INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C1','soc',5,2,'u1',1,'유적과 유물·선사 시대 — 유적은 옛 사람들이 남긴 건물터·무덤 같은 자리, 유물은 옛 사람들이 쓰던 도구·그릇 같은 물건 · 문자를 쓰기 전이라 글로 남은 기록이 없는 때를 선사 시대라 하고, 유적과 유물을 보고 생활 모습을 짐작함 · 기준은 「얼마나 오래됐나」가 아니라 「기록이 있나」',ARRAY['[6사04-01] 선사 시대와 고조선의 유적과 유물을 활용하여 당시 사람들의 생활을 추론한다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C2','soc',5,2,'u1',1,'구석기 시대 사람들의 생활 — 돌을 깨뜨리거나 떼어 내 만든 뗀석기를 씀(주먹 도끼 하나로 자르기·두들기기·땅파기를 하는 만능 도구) · 열매·풀뿌리를 채집하고 사냥함 · 머물던 곳의 먹을 것이 떨어지면 옮겨 다녀야 해서 막집이나 동굴·바위 그늘에서 지냄 · 불로 추위와 사나운 짐승을 막고 고기를 익혀 먹음 · 짐승 가죽이나 풀로 몸을 덮음',ARRAY['[6사04-01] 선사 시대와 고조선의 유적과 유물을 활용하여 당시 사람들의 생활을 추론한다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C3','soc',5,2,'u1',2,'신석기 시대의 도구와 의식주 — 돌을 갈고 다듬어 쓰임에 맞게 만든 간석기를 씀 · 사냥·채집에 더해 강과 바다에서 물고기잡이를 하고 점차 농사도 지음 · 빗살무늬 토기에 먹을 것을 보관하고 조리함 · 가락바퀴로 실을 뽑고 뼈바늘로 옷과 그물을 지음 · 조개껍데기로 장신구를 만들어 꾸밈',ARRAY['[6사04-01] 선사 시대와 고조선의 유적과 유물을 활용하여 당시 사람들의 생활을 추론한다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C4','soc',5,2,'u1',2,'정착 생활과 움집 — 물고기잡이·사냥·채집으로 먹을 것을 꾸준히 구하고 토기에 남겨 둘 수 있게 되자 먹을 것이 많은 강가나 바닷가에 움집을 짓고 마을을 이루어 한곳에 머물러 삶(정착 생활) · 농사는 그 위에 조금씩 더해짐 · 서울 암사동처럼 신석기 마을 유적이 남아 있음',ARRAY['[6사04-01] 선사 시대와 고조선의 유적과 유물을 활용하여 당시 사람들의 생활을 추론한다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C5','soc',5,2,'u1',3,'청동기와 벼농사 — 구리에 주석을 섞어 녹인 청동으로 검·거울·방울을 만듦 · 청동은 재료가 귀하고 만들기 어려워 지배자가 무기와 제사 도구로 주로 씀 · 늘 쓰는 도구는 여전히 돌과 나무(반달 돌칼로 벼 이삭을 거둠, 간 돌검·돌화살촉) · 벼농사가 곳곳에서 이루어지고 민무늬 토기를 씀 · 네모난 움집도 생김',ARRAY['[6사04-01] 선사 시대와 고조선의 유적과 유물을 활용하여 당시 사람들의 생활을 추론한다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C6','soc',5,2,'u1',3,'빈부의 차이와 지배자·고인돌 — 농사 기술이 나아져 곡식이 남자 많이 가진 사람과 적게 가진 사람이 생김(빈부의 차이) · 재산과 힘을 모은 사람이 지배자가 되어 마을을 다스리고 하늘에 제사를 이끎 · 곡식과 재산을 두고 다툼이 생겨 마을 둘레에 도랑·울타리·망루를 세움 · 지배자의 무덤 고인돌은 거대한 덮개돌을 옮길 많은 사람을 모을 힘이 있었음을 알려 줌 · 고창·화순·강화 고인돌 유적은 세계유산',ARRAY['[6사04-01] 선사 시대와 고조선의 유적과 유물을 활용하여 당시 사람들의 생활을 추론한다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C7','soc',5,2,'u1',4,'고조선의 건국 이야기 — 청동기 문화를 바탕으로 우리 역사의 첫 나라 고조선이 세워짐(한반도 북부와 중국 동북쪽 중심) · 이야기는 고려 승려 일연의 「삼국유사」에 전해짐 · 하늘의 자손이라 내세운 환웅 부족이 바람·비·구름을 다스리는 신하(앞선 농사 기술)를 가지고 왔고, 곰을 받드는 부족이 환웅 부족과 힘을 합쳐 단군왕검이 나라를 세웠다고 짐작 · 이야기를 그대로 믿거나 거짓으로 버리지 않고 담긴 뜻을 읽음',ARRAY['[6사04-01] 선사 시대와 고조선의 유적과 유물을 활용하여 당시 사람들의 생활을 추론한다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C8','soc',5,2,'u1',4,'8조법과 고조선의 문화 범위 — 사회 질서를 지키려고 만든 8조법은 세 조항만 전함(사람을 죽이면 사형, 다치게 하면 곡식으로 갚음, 훔치면 노비로 삼되 돈을 내면 면함) → 생명과 재산을 중히 여기고 노비가 있는 신분 사회였으며 화폐를 썼다고 짐작 · 비파형 동검과 탁자식 고인돌이 발견되는 곳을 이어 문화 범위를 짐작함(영토 기록은 없음 — 짐작이며 연구가 이어짐)',ARRAY['[6사04-01] 선사 시대와 고조선의 유적과 유물을 활용하여 당시 사람들의 생활을 추론한다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C9','soc',5,2,'u1',5,'철기 문화와 삼국·가야의 성립 — 고조선이 무너질 무렵 철로 만든 농기구와 무기를 쓰는 철기 문화를 바탕으로 여러 나라가 세워짐 · 고구려·백제·신라(삼국)는 왕을 중심으로 나라의 틀을 갖추며 커 갔고, 낙동강 가에서는 여러 나라가 모인 가야 연맹이 자람 · 건국 이야기(알에서 태어남)는 나라를 세운 사람이 특별하다는 것을 알리려는 뜻',ARRAY['[6사04-02] 역사 기록이나 유적과 유물에 나타난 고대 사람들의 생각과 생활을 추론한다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C10','soc',5,2,'u1',5,'삼국의 발전과 한강 유역 — 고구려: 광개토대왕이 영토를 넓히고 장수왕이 수도를 평양으로 옮긴 뒤 한강 유역을 차지 · 백제: 한강 유역에서 일어나 근초고왕 때 크게 발전, 중국·왜와 교류(칠지도) · 신라: 진흥왕 때 화랑으로 인재를 기르고 한강 유역을 차지해 중국과 바로 오감 · 한강 유역은 넓은 평야로 농사짓기 좋고 바다로 나가 다른 나라와 오가기 편해 서로 차지하려 함 · 가야는 금관가야에서 대가야로 중심이 옮겨 갔다가 신라에 합쳐짐',ARRAY['[6사04-02] 역사 기록이나 유적과 유물에 나타난 고대 사람들의 생각과 생활을 추론한다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C11','soc',5,2,'u1',6,'삼국 시대의 신분과 의식주 — 귀족·평민·천민으로 신분이 나뉨(귀족은 토지·노비가 많고 나라의 중요한 일을 정함, 평민은 농사짓고 세금을 냄, 천민은 대부분 노비) · 신분에 따라 옷(비단↔삼베)·음식(쌀↔보리·조 같은 잡곡)·집(기와집↔초가집)이 달랐음 · 고분 벽화에 신분이 높은 사람을 크게 그림 · 고구려의 맥적, 콩으로 만든 장',ARRAY['[6사04-02] 역사 기록이나 유적과 유물에 나타난 고대 사람들의 생각과 생활을 추론한다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C12','soc',5,2,'u1',6,'불교의 수용과 가야의 철 문화 — 삼국은 백성의 마음을 하나로 모으고 왕의 힘을 키우려고 불교를 받아들여 절·탑·불상을 만듦(귀족의 반대도 있었음) · 철이 많이 나는 가야는 철을 다루는 기술이 뛰어나 무기와 갑옷을 만들어 팔고 덩이쇠를 화폐처럼 씀 · 집·배·말 탄 무사 모양 토기로 가야 사람들의 생활을 짐작',ARRAY['[6사04-02] 역사 기록이나 유적과 유물에 나타난 고대 사람들의 생각과 생활을 추론한다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C13','soc',5,2,'u1',7,'신라의 삼국 통일과 제도 정비 — 신라는 당과 손잡고 백제와 고구려를 무너뜨린 뒤, 당이 한반도 전체를 차지하려 하자 옛 백제·고구려 사람들과 힘을 모아 당을 물리치고 삼국 통일을 이룸(고구려 북쪽 땅은 되찾지 못함) · 넓어진 땅과 늘어난 사람을 다스리려고 제도를 정비 · 신라 촌락 문서(사람·말·논·뽕나무 수)는 마을을 관리하고 세금을 걷으려는 기록',ARRAY['[6사04-02] 역사 기록이나 유적과 유물에 나타난 고대 사람들의 생각과 생활을 추론한다.']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C14','soc',5,2,'u1',7,'통일신라의 교류와 불교문화 — 승려와 유학생이 당으로 가 공부하고, 일본과는 주로 무역으로 오가며, 멀리 서역 상인도 찾아옴(왕릉을 지키는 돌사람의 서역인 모습, 인도·서역을 다녀온 혜초) · 불교가 백성에게까지 퍼져 부처의 나라를 바라는 마음을 담은 불국사, 화강암을 쌓아 만든 석굴암을 세움(세계유산)',ARRAY['[6사04-02] 역사 기록이나 유적과 유물에 나타난 고대 사람들의 생각과 생활을 추론한다.']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C15','soc',5,2,'u1',8,'발해의 건국과 고구려 계승 — 고구려가 무너진 뒤 고구려 출신 대조영이 고구려 유민과 말갈 사람 일부를 이끌고 동모산에서 발해를 세움 · 고구려 옛 땅을 대부분 되찾아 당에서 해동성국(바다 동쪽의 번성한 나라)이라 부름 · 스스로 고구려를 계승했다고 밝혔고 일본 기록도 발해 사신을 고려(고구려) 사신이라 적음 · 기와 꽃잎 무늬와 온돌이 고구려와 닮음',ARRAY['[6사04-02] 역사 기록이나 유적과 유물에 나타난 고대 사람들의 생각과 생활을 추론한다.']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C16','soc',5,2,'u1',8,'발해의 교류와 생활 — 당·일본 등과 활발히 교류(당의 세 빛깔 도자기를 닮은 삼채 향로, 말·짐승 가죽·인삼을 팖) · 신분 제도가 있어 귀족은 기와집, 평민은 주로 초가집 · 불교가 널리 퍼져 수도 상경성에 절터·불상·큰 석등이 남음',ARRAY['[6사04-02] 역사 기록이나 유적과 유물에 나타난 고대 사람들의 생각과 생활을 추론한다.']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C17','soc',5,2,'u1',9,'후삼국과 고려의 건국 — 통일신라 말 귀족들의 다툼으로 나라가 어지러워지자 지방의 힘센 세력 호족이 자람 · 견훤은 후백제, 궁예는 후고구려를 세워 신라와 함께 후삼국 · 궁예의 부하 왕건이 궁예를 몰아내고 고구려를 계승한다는 뜻으로 고려를 세움 · 신라의 항복을 받고 후백제를 물리쳐 후삼국을 통일 · 거란에 무너진 발해의 유민을 친척처럼 받아들임 · 세금을 줄이고 훈요 10조(서경 중시 등)를 남김 · 고려가 바깥에 알려져 COREA·KOREA로 이어짐',ARRAY['[6사04-03] 다양한 역사 자료를 활용하여 고려 시대 사회 모습과 사람들의 생활을 추론한다.']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C18','soc',5,2,'u1',10,'고려의 정책과 신분 — 억울하게 노비가 된 백성을 풀어 주고, 시험으로 관리를 뽑는 과거제를 열고(합격증 홍패), 주요 지방에 관리를 보냄 → 호족의 힘이 약해지고 나라를 더 잘 다스림 · 신분은 크게 양인(왕족·관리·농사짓는 백성)과 천인(노비가 많음)으로 나뉨 · 전쟁에서 공을 세우면 신분이 오르기도 함',ARRAY['[6사04-03] 다양한 역사 자료를 활용하여 고려 시대 사회 모습과 사람들의 생활을 추론한다.']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C19','soc',5,2,'u1',10,'고려 여성의 지위와 불교 행사 — 관리가 되는 것 같은 사회 활동은 자유롭지 않았지만 집안에서는 남성과 같은 지위(아들딸이 유산을 똑같이 받고 돌아가며 제사, 여성이 집안의 가장이 되기도 함) · 불교가 나라의 도움으로 크게 자라 등불을 밝혀 소원을 비는 연등회, 11월에 온 세상의 평안을 비는 팔관회가 크게 열림 · 연등회는 오늘날 연등 행렬로 이어져 인류 무형 문화유산',ARRAY['[6사04-03] 다양한 역사 자료를 활용하여 고려 시대 사회 모습과 사람들의 생활을 추론한다.']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C20','soc',5,2,'u1',11,'거란·송과의 관계와 벽란도 — 발해를 무너뜨린 거란과는 거리를 두고 송과는 좋은 사이를 이어 감 · 거란의 침입에 서희가 외교 담판으로 싸우지 않고 강동 6주를 얻고(거란이 바란 것은 고려와 송의 사이를 끊는 것), 끈질기게 맞섰으며, 강감찬이 귀주에서 크게 이김 · 개경 가까운 예성강의 벽란도에 송·거란·여진·일본·아라비아 상인이 오갔고 고려는 인삼·삼베·도자기를 팖',ARRAY['[6사04-03] 다양한 역사 자료를 활용하여 고려 시대 사회 모습과 사람들의 생활을 추론한다.']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C21','soc',5,2,'u1',11,'몽골의 침입과 고려의 대응 — 몽골이 쳐들어오자 바다로 둘러싸여 몽골군이 건너기 어려운 강화도로 수도를 옮겨 맞섬 · 승려 김윤후가 노비 문서를 불태우고 신분에 상관없이 벼슬을 약속하자 모두 힘을 합쳐 성을 지킴(신분을 넘은 저항) · 전쟁이 길어져 땅이 황폐해지고 백성이 끌려가는 고통 · 전쟁 뒤 서로의 풍습을 주고받음(만두·설렁탕·족두리, 고려의 상추쌈)',ARRAY['[6사04-03] 다양한 역사 자료를 활용하여 고려 시대 사회 모습과 사람들의 생활을 추론한다.']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C22','soc',5,2,'u1',12,'고려청자 — 처음엔 중국 기술을 받아들였지만 무늬를 파내고 다른 색 흙으로 메워 굽는 상감 기법으로 고려만의 청자를 만듦 · 주전자·베개·연적 같은 생활용품이었고 비싸고 귀해 주로 지배층이 씀 · 태안 앞바다에서 청자를 가득 실은 고려 배(보물선)가 발견됨',ARRAY['[6사04-03] 다양한 역사 자료를 활용하여 고려 시대 사회 모습과 사람들의 생활을 추론한다.']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C23','soc',5,2,'u1',12,'팔만대장경·금속 활자·목화 — 몽골 침입으로 처음 만든 대장경판이 불타자 불교의 힘으로 몽골을 물리치기를 바라며 마음을 모아 팔만대장경을 다시 만듦(틀린 글자가 거의 없음, 해인사) · 목판은 새긴 내용만 찍지만 금속 활자는 다시 짜서 여러 책을 찍을 수 있음 — 고려는 세계 최초로 금속 활자를 만들었고 「직지」가 남아 있는 가장 오래된 금속 활자 책 · 문익점이 목화씨를 가져와 길러 백성이 따뜻한 무명옷과 솜이불로 겨울을 남',ARRAY['[6사04-03] 다양한 역사 자료를 활용하여 고려 시대 사회 모습과 사람들의 생활을 추론한다.']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u1-C24','soc',5,2,'u1',13,'역사 신문 만들기 — 시대를 골라 사회 모습이나 사람들의 생활이 드러나는 주제를 정하고 유물 사진·역사 기록 같은 자료를 모음 → 사건·인터뷰·광고·만화 같은 기사를 씀 → 기사를 배치하고 신문 이름·날짜를 써서 전시 · 꾸미는 형식은 상상해도 내용은 유적·유물·기록으로 확인한 사실에 맞아야 함(그 시대에 없던 물건을 넣지 않음)',ARRAY['[6사04-03] 다양한 역사 자료를 활용하여 고려 시대 사회 모습과 사람들의 생활을 추론한다.']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X01','soc',5,'u1',ARRAY['SO5-2-u1-C1']::text[],'유적과 유물을 바꾸어 안다(무덤·집터를 유물로, 토기·도끼를 유적으로)','자리 = 유적 · 물건 = 유물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X02','soc',5,'u1',ARRAY['SO5-2-u1-C1']::text[],'선사 시대의 기준을 「아주 오래된 때」로만 알거나, 선사 시대도 글로 남은 기록으로 생활을 안다고 여긴다','문자 기록이 없는 때 · 유적과 유물로 짐작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X03','soc',5,'u1',ARRAY['SO5-2-u1-C2','SO5-2-u1-C3']::text[],'뗀석기와 간석기를 바꾸어 안다','깨뜨려 떼어 냄 = 뗀석기 · 갈아 다듬음 = 간석기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X04','soc',5,'u1',ARRAY['SO5-2-u1-C2']::text[],'구석기 사람들이 옮겨 다닌 까닭을 놓친다(농사지을 땅을 찾으려고, 집 짓는 법을 몰라서만이라고 여긴다)','먹을 것이 떨어지면 옮겨 감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X05','soc',5,'u1',ARRAY['SO5-2-u1-C2']::text[],'구석기 사람들의 불의 쓰임을 음식 익히기로만 안다','추위·짐승 막기 + 익혀 먹기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X06','soc',5,'u1',ARRAY['SO5-2-u1-C3']::text[],'신석기 도구의 쓰임을 바꾸어 안다(가락바퀴로 곡식을 거두고, 토기로 사냥한다고)','가락바퀴 실 · 뼈바늘 옷 · 토기 보관·조리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X07','soc',5,'u1',ARRAY['SO5-2-u1-C4']::text[],'신석기 정착 생활의 바탕과 자리를 잘못 안다(처음부터 농사만으로 정착했다고, 산꼭대기에 마을을 이뤘다고)','먹을 것을 꾸준히 · 강가나 바닷가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X08','soc',5,'u1',ARRAY['SO5-2-u1-C2','SO5-2-u1-C3','SO5-2-u1-C5']::text[],'시대와 도구·유물을 섞는다(구석기에 토기, 신석기에 청동 검, 고조선에 철기)','뗀석기 → 간석기·토기 → 청동기 → 철기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X09','soc',5,'u1',ARRAY['SO5-2-u1-C5']::text[],'청동기를 누구나 썼다고, 농기구까지 모두 청동으로 만들었다고 여긴다','귀해서 지배자가 · 늘 쓰는 건 돌과 나무') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X10','soc',5,'u1',ARRAY['SO5-2-u1-C6']::text[],'빈부의 차이와 지배자가 처음부터 있었다고 여기거나, 생긴 까닭(남는 곡식)을 놓친다','곡식이 남자 → 빈부 차이 → 지배자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X11','soc',5,'u1',ARRAY['SO5-2-u1-C6']::text[],'고인돌을 집이나 놀이 시설로 알거나, 고인돌과 지배자의 힘을 잇지 못한다','지배자의 무덤 · 많은 사람을 모은 힘') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X12','soc',5,'u1',ARRAY['SO5-2-u1-C7','SO5-2-u1-C9']::text[],'건국 이야기를 사실 그대로 믿거나 쓸모없는 거짓으로만 여겨 담긴 뜻을 놓친다','이야기 속 뜻을 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X13','soc',5,'u1',ARRAY['SO5-2-u1-C8']::text[],'8조법에서 고조선 사회를 잘못 짐작한다(노비가 없었다고, 재산을 가볍게 여겼다고, 모두 평등했다고)','생명·재산 중시 · 노비 · 화폐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X14','soc',5,'u1',ARRAY['SO5-2-u1-C8']::text[],'고조선의 문화 범위를 기록된 국경으로 여기거나, 유물이 발견된 곳으로 짐작한다는 것을 놓친다','비파형 동검·탁자식 고인돌이 나온 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X15','soc',5,'u1',ARRAY['SO5-2-u1-C7','SO5-2-u1-C9']::text[],'고조선과 삼국·가야의 바탕 문화를 바꾸어 안다(고조선은 철기, 삼국은 청동기로)','고조선 청동기 · 삼국과 가야 철기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X16','soc',5,'u1',ARRAY['SO5-2-u1-C10']::text[],'나라와 왕·한 일을 바꾸어 짝짓는다(진흥왕이 평양으로 옮겼다고, 근초고왕이 화랑을 만들었다고)','고구려 광개토·장수 · 백제 근초고 · 신라 진흥') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X17','soc',5,'u1',ARRAY['SO5-2-u1-C10']::text[],'한강 유역이 중요한 까닭을 놓친다(땅이 좁고 쓸모없었다고, 우연히 다투었다고)','넓은 평야 · 바다로 나가 중국과 오감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X18','soc',5,'u1',ARRAY['SO5-2-u1-C9','SO5-2-u1-C10']::text[],'가야를 하나의 큰 왕국으로 여기거나 삼국에 넣고, 고구려에 합쳐졌다고 안다','여러 나라의 연맹 · 신라에 합쳐짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X19','soc',5,'u1',ARRAY['SO5-2-u1-C11']::text[],'신분과 옷·음식·집을 바꾸어 짝짓는다(평민이 비단옷·기와집, 귀족이 잡곡·초가집)','귀족 비단·쌀·기와 · 평민 삼베·잡곡·초가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X20','soc',5,'u1',ARRAY['SO5-2-u1-C11','SO5-2-u1-C18']::text[],'옛날에도 신분 차이 없이 모두 같은 생활을 했다고 여기거나, 벽화의 크기 차이를 원근으로만 읽는다','신분에 따라 생활이 달랐어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X21','soc',5,'u1',ARRAY['SO5-2-u1-C12']::text[],'삼국이 불교를 받아들인 까닭을 오해한다(놀이로, 외국 흉내로, 백성을 갈라놓으려고)','마음을 하나로 · 왕의 힘') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X22','soc',5,'u1',ARRAY['SO5-2-u1-C12']::text[],'가야의 철 문화와 토기가 알려 주는 생활을 놓친다(가야는 철이 없었다고, 덩이쇠를 그냥 장식으로)','철 기술 · 덩이쇠는 화폐처럼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X23','soc',5,'u1',ARRAY['SO5-2-u1-C13']::text[],'삼국 통일 과정을 잘못 안다(신라 혼자 했다고, 끝까지 당과 한편이었다고, 고구려가 통일했다고)','당과 손잡음 → 당을 물리침') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X24','soc',5,'u1',ARRAY['SO5-2-u1-C13']::text[],'신라 촌락 문서를 놀이 기록이나 일기로 여겨, 마을 관리·세금이라는 목적을 놓친다','사람·말·논·뽕나무 → 세금') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X25','soc',5,'u1',ARRAY['SO5-2-u1-C14','SO5-2-u1-C16']::text[],'통일신라·발해의 교류 범위를 좁게 알거나 유물이 알려 주는 교류를 놓친다(서역 사람은 올 수 없었다고)','당·일본·서역까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X26','soc',5,'u1',ARRAY['SO5-2-u1-C14','SO5-2-u1-C22','SO5-2-u1-C23']::text[],'문화유산과 시대를 바꾸어 짝짓는다(불국사를 고려, 팔만대장경을 통일신라로)','불국사·석굴암 통일신라 · 대장경·청자 고려') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X27','soc',5,'u1',ARRAY['SO5-2-u1-C15']::text[],'발해를 세운 사람과 이어받은 나라를 잘못 안다(신라를 계승했다고, 당 사람이 세웠다고)','고구려 출신 대조영 · 고구려 계승') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X28','soc',5,'u1',ARRAY['SO5-2-u1-C15']::text[],'해동성국의 뜻을 오해하거나, 발해가 고구려를 계승한 증거(기록·기와·온돌)를 잇지 못한다','바다 동쪽의 번성한 나라 · 닮은 문화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X29','soc',5,'u1',ARRAY['SO5-2-u1-C17']::text[],'후삼국의 나라와 세운 사람, 호족의 뜻을 바꾸어 안다','견훤 후백제 · 궁예 후고구려 · 지방 세력 호족') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X30','soc',5,'u1',ARRAY['SO5-2-u1-C17']::text[],'고려라는 이름의 뜻이나 왕건이 발해 유민을 대한 방법을 잘못 안다(신라를 잇는다고, 유민을 내쫓았다고)','고구려 계승 · 친척처럼 받아들임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X31','soc',5,'u1',ARRAY['SO5-2-u1-C18']::text[],'고려 초 정책의 목적을 거꾸로 안다(호족의 힘을 키우려고, 과거제를 돈으로 관리 사는 제도로)','호족 힘 약하게 · 시험으로 관리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X32','soc',5,'u1',ARRAY['SO5-2-u1-C19']::text[],'고려 여성의 지위를 잘못 안다(집안에서 아무 권리가 없었다고, 또는 관리도 자유롭게 되었다고)','집안에서는 같은 지위 · 사회 활동은 자유롭지 않음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X33','soc',5,'u1',ARRAY['SO5-2-u1-C19']::text[],'연등회와 팔관회를 바꾸어 알거나 불교와 상관없는 행사로 여긴다','연등회 등불 · 팔관회 11월 평안') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X34','soc',5,'u1',ARRAY['SO5-2-u1-C20']::text[],'고려와 거란·송의 관계를 거꾸로 알거나 서희가 싸워서 땅을 얻었다고 여긴다','거란 멀리·송 가까이 · 말로 강동 6주') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X35','soc',5,'u1',ARRAY['SO5-2-u1-C20']::text[],'벽란도의 자리와 교류를 잘못 안다(외국과 오가지 않았다고, 고려가 물건을 사기만 했다고)','개경 가까운 국제 항구 · 인삼·삼베·도자기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X36','soc',5,'u1',ARRAY['SO5-2-u1-C21']::text[],'몽골의 침입과 대응을 잘못 안다(강화도로 옮긴 까닭을 놓치거나, 높은 신분만 싸웠다고, 전쟁에 고통이 없었다고)','바다로 둘러싸인 섬 · 신분을 넘어 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X37','soc',5,'u1',ARRAY['SO5-2-u1-C22']::text[],'고려청자의 상감 기법이나 쓰임·쓴 사람을 잘못 안다(그림을 물감으로 그렸다고, 백성 누구나 흔히 썼다고)','파내고 다른 색 흙으로 메움 · 귀해서 지배층') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X38','soc',5,'u1',ARRAY['SO5-2-u1-C23']::text[],'팔만대장경을 만든 까닭이나 금속 활자의 좋은 점을 잘못 안다(장식용으로, 한 가지 책만 찍는다고)','몽골을 물리치기를 바람 · 다시 짜서 여러 책') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X39','soc',5,'u1',ARRAY['SO5-2-u1-C23']::text[],'목화와 무명옷이 백성의 생활에 준 변화를 놓친다(목화가 처음부터 있었다고, 지배층만 입었다고)','문익점 · 백성의 따뜻한 겨울') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X40','soc',5,'u1',ARRAY['SO5-2-u1-C24']::text[],'역사 신문을 근거 없이 지어낸 이야기로 쓰거나 그 시대에 없던 물건·사건을 넣는다','형식은 상상 · 내용은 유적·유물·기록의 사실') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X41','soc',5,'u1',ARRAY['SO5-2-u1-C24']::text[],'역사 신문 기사의 갈래(사건·인터뷰·광고·만화)와 만드는 차례를 헷갈린다','주제·자료 → 기사 → 배치·전시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u1-X42','soc',5,'u1',ARRAY['SO5-2-u1-C1','SO5-2-u1-C8','SO5-2-u1-C15','SO5-2-u1-C22']::text[],'역사 공부를 이름과 연도를 외우는 것으로만 여겨 유적·유물·기록에서 생활과 생각을 짐작하는 것을 놓친다','외우기보다 자료로 짐작하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_basic#1','soc',5,2,'u1','L01','g5_2_soc_u1_L01_basic','lesson_basic','SO5-2-u1-C1',1,'mc','auto','옛 사람들이 남긴 건물터나 무덤처럼 생활의 흔적이 남아 있는 자리를 무엇이라고 하나요?',ARRAY['SO5-2-u1-X01','SO5-2-u1-X42','SO5-2-u1-X02']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C1","difficulty":1,"kind":"mc","stem":"옛 사람들이 남긴 건물터나 무덤처럼 생활의 흔적이 남아 있는 자리를 무엇이라고 하나요?","options":[{"t":"유적","correct":true},{"t":"유물","mis":"SO5-2-u1-X01"},{"t":"지도","mis":"SO5-2-u1-X42"},{"t":"기록","mis":"SO5-2-u1-X02"}],"explanation":["땅 위나 땅속에 남은 자리예요.","옮길 수 없는 흔적이에요.","유적이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_basic#2','soc',5,2,'u1','L01','g5_2_soc_u1_L01_basic','lesson_basic','SO5-2-u1-C1',1,'mc','auto','문자를 쓰기 전이라 글로 남은 기록이 없는 시대를 무엇이라고 하나요?',ARRAY['SO5-2-u1-X02']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C1","difficulty":1,"kind":"mc","stem":"문자를 쓰기 전이라 글로 남은 기록이 없는 시대를 무엇이라고 하나요?","options":[{"t":"선사 시대","correct":true},{"t":"고려 시대","mis":"SO5-2-u1-X02"},{"t":"삼국 시대","mis":"SO5-2-u1-X02"},{"t":"오늘날","mis":"SO5-2-u1-X02"}],"explanation":["기록이 없어요.","유적과 유물로 짐작해요.","선사 시대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_basic#3','soc',5,2,'u1','L01','g5_2_soc_u1_L01_basic','lesson_basic','SO5-2-u1-C2',1,'sa','auto','구석기 시대 사람들이 돌을 깨뜨리거나 떼어 내서 만든 도구를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u1-C2","difficulty":1,"kind":"sa","stem":"구석기 시대 사람들이 돌을 깨뜨리거나 떼어 내서 만든 도구를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["뗀석기"],"explanation":["돌을 깨뜨려요.","떼어 내어 날을 세워요.","뗀석기예요."],"mis":"SO5-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_basic#4','soc',5,2,'u1','L01','g5_2_soc_u1_L01_basic','lesson_basic','SO5-2-u1-C2',1,'ox','auto','구석기 시대 사람들은 불을 피워 추위와 사나운 짐승을 막고 고기를 익혀 먹었어요.',ARRAY['SO5-2-u1-X05']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C2","difficulty":1,"kind":"ox","stem":"구석기 시대 사람들은 불을 피워 추위와 사나운 짐승을 막고 고기를 익혀 먹었어요.","answer":"O","reason_options":[{"t":"불은 몸을 지키고 음식을 익히는 데 함께 쓰였기 때문에","correct":true},{"t":"불은 음식을 익히는 데에만 썼기 때문에","mis":"SO5-2-u1-X05"}],"mis":"SO5-2-u1-X05","explanation":["불은 따뜻해요.","짐승은 불을 무서워해요.","고기도 익혀 먹었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_basic#5','soc',5,2,'u1','L01','g5_2_soc_u1_L01_basic','lesson_basic','SO5-2-u1-C1',2,'mc','auto','발굴 현장 기록 카드 가운데 유물이 아닌 것끼리 바르게 묶은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X01']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C1","difficulty":2,"kind":"mc","stem":"발굴 현장 기록 카드 가운데 유물이 아닌 것끼리 바르게 묶은 것은 어느 것인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉡, ㉣","mis":"SO5-2-u1-X01"},{"t":"㉠, ㉡","mis":"SO5-2-u1-X01"},{"t":"㉢, ㉣","mis":"SO5-2-u1-X01"}],"explanation":["무덤 자리와 집터는 자리예요.","그릇 조각과 돌도끼는 물건이에요.","㉠·㉢은 유적이에요."],"asset":{"type":"passage","lines":["㉠ 돌을 쌓아 만든 무덤 자리","㉡ 흙으로 빚은 그릇 조각","㉢ 기둥 구멍이 남은 집터","㉣ 날을 세운 돌도끼"],"title":"발굴 현장 기록 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_basic#6','soc',5,2,'u1','L01','g5_2_soc_u1_L01_basic','lesson_basic','SO5-2-u1-C2',2,'mc','auto','주먹 도끼를 「만능 도구」라고 부르는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X08','SO5-2-u1-X06','SO5-2-u1-X09']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C2","difficulty":2,"kind":"mc","stem":"주먹 도끼를 「만능 도구」라고 부르는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하나로 자르기·두들기기·땅파기 같은 여러 일을 할 수 있어서","correct":true},{"t":"청동으로 만들어 반짝여서","mis":"SO5-2-u1-X08"},{"t":"곡식을 거두는 데에만 써서","mis":"SO5-2-u1-X06"},{"t":"지배자만 가질 수 있어서","mis":"SO5-2-u1-X09"}],"explanation":["한쪽은 둥글고 한쪽은 뾰족해요.","여러 일에 두루 썼어요.","그래서 만능 도구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_basic#7','soc',5,2,'u1','L01','g5_2_soc_u1_L01_basic','lesson_basic','SO5-2-u1-C2',2,'mc','auto','구석기 시대 사람들이 막집이나 동굴, 바위 그늘에서 지낸 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X04','SO5-2-u1-X10']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C2","difficulty":2,"kind":"mc","stem":"구석기 시대 사람들이 막집이나 동굴, 바위 그늘에서 지낸 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"먹을 것을 찾아 옮겨 다녀서 잠깐 머물 곳이면 충분했기 때문에","correct":true},{"t":"농사지을 넓은 땅을 지키려고","mis":"SO5-2-u1-X04"},{"t":"튼튼한 집을 짓는 것이 법으로 금지되어서","mis":"SO5-2-u1-X04"},{"t":"마을 둘레에 울타리를 세우려고","mis":"SO5-2-u1-X10"}],"explanation":["먹을 것이 떨어지면 떠나요.","오래 살 집이 필요 없었어요.","잠깐 머물 곳이면 됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_basic#8','soc',5,2,'u1','L01','g5_2_soc_u1_L01_basic','lesson_basic','SO5-2-u1-C2',2,'mc','auto','세 사람의 말로 보아 구석기 사람들이 옮겨 다닌 까닭은 어느 것인가요?',ARRAY['SO5-2-u1-X07','SO5-2-u1-X04','SO5-2-u1-X08']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C2","difficulty":2,"kind":"mc","stem":"세 사람의 말로 보아 구석기 사람들이 옮겨 다닌 까닭은 어느 것인가요?","options":[{"t":"머물던 곳의 먹을 것이 떨어져서","correct":true},{"t":"새로 지은 움집이 무너져서","mis":"SO5-2-u1-X07"},{"t":"씨앗을 심을 땅을 찾으려고","mis":"SO5-2-u1-X04"},{"t":"청동을 구하려고","mis":"SO5-2-u1-X08"}],"explanation":["열매도 짐승도 없어요.","먹을 것이 있는 곳으로 가요.","먹을 것 때문에 옮겨요."],"asset":{"type":"speech","turns":[{"who":"하윤","text":"이 골짜기엔 이제 열매도 짐승도 거의 없어."},{"who":"도겸","text":"그럼 먹을 것이 있는 곳으로 옮겨 가자."},{"who":"하윤","text":"짐은 가볍게, 주먹 도끼 하나면 여러 일을 할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_basic#9','soc',5,2,'u1','L01','g5_2_soc_u1_L01_basic','lesson_basic','SO5-2-u1-C1',2,'ox','auto','선사 시대 사람들의 생활은 그들이 남긴 일기와 책으로 알아내요.',ARRAY['SO5-2-u1-X02']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C1","difficulty":2,"kind":"ox","stem":"선사 시대 사람들의 생활은 그들이 남긴 일기와 책으로 알아내요.","answer":"X","reason_options":[{"t":"선사 시대에는 글로 남은 기록이 없어 유적과 유물로 짐작하기 때문에","correct":true},{"t":"선사 시대 사람들도 글을 써서 남겼기 때문에","mis":"SO5-2-u1-X02"}],"mis":"SO5-2-u1-X02","explanation":["선사 시대는 문자 이전이에요.","기록이 없어요.","유적과 유물로 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_basic#10','soc',5,2,'u1','L01','g5_2_soc_u1_L01_basic','lesson_basic','SO5-2-u1-C2',3,'error','auto','구석기 시대 사람들의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X07','SO5-2-u1-X05','SO5-2-u1-X04']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C2","difficulty":3,"kind":"error","stem":"구석기 시대 사람들의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「구석기 사람들은 강가에 움집을 짓고 한곳에 머물러 살았어.」","correct":true,"mis_target":"SO5-2-u1-X07"},{"t":"유나 — 「짐승 가죽이나 풀로 몸을 덮었어.」","mis":"SO5-2-u1-X05"},{"t":"지호 — 「열매를 따고 짐승을 사냥해서 먹을 것을 구했어.」","mis":"SO5-2-u1-X04"}],"explanation":["움집과 정착은 다음 시대 이야기예요.","구석기 사람들은 옮겨 다녔어요.","서준의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_challenge#1','soc',5,2,'u1','L01','g5_2_soc_u1_L01_challenge','lesson_challenge','SO5-2-u1-C1',2,'mc','auto','유적과 유물로 옛 사람들의 생활을 알아보는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X02','SO5-2-u1-X01','SO5-2-u1-X42']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C1","difficulty":2,"kind":"mc","stem":"유적과 유물로 옛 사람들의 생활을 알아보는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"글로 된 기록이 없는 때도 남긴 흔적으로 생활을 짐작할 수 있어서","correct":true},{"t":"유적과 유물에는 그때 사람들의 이름이 모두 적혀 있어서","mis":"SO5-2-u1-X02"},{"t":"유적과 유물은 오늘날 사람들이 새로 만든 것이라서","mis":"SO5-2-u1-X01"},{"t":"연도만 알면 생활은 알 필요가 없어서","mis":"SO5-2-u1-X42"}],"explanation":["기록이 없을 때가 있어요.","흔적은 남아요.","흔적으로 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_challenge#2','soc',5,2,'u1','L01','g5_2_soc_u1_L01_challenge','lesson_challenge','SO5-2-u1-C1',2,'match','auto','발굴 현장 기록 카드를 보고 카드와 알맞은 말을 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u1-C1","difficulty":2,"kind":"match","stem":"발굴 현장 기록 카드를 보고 카드와 알맞은 말을 이으세요.","pairs":[{"l":"㉠ 무덤 자리","r":"유적"},{"l":"㉡ 그릇 조각","r":"유물"},{"l":"㉢ 집터","r":"유적인 집 자리"},{"l":"㉣ 돌도끼","r":"유물인 도구"}],"mis":"SO5-2-u1-X01","explanation":["자리는 유적이에요.","물건은 유물이에요.","무덤·집터는 유적, 그릇·도끼는 유물이에요."],"asset":{"type":"passage","lines":["㉠ 돌을 쌓아 만든 무덤 자리","㉡ 흙으로 빚은 그릇 조각","㉢ 기둥 구멍이 남은 집터","㉣ 날을 세운 돌도끼"],"title":"발굴 현장 기록 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_challenge#3','soc',5,2,'u1','L01','g5_2_soc_u1_L01_challenge','lesson_challenge','SO5-2-u1-C2',3,'mc','auto','세 사람의 말에서 「짐은 가볍게」라고 한 까닭을 생활과 이어 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X07','SO5-2-u1-X09','SO5-2-u1-X04']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C2","difficulty":3,"kind":"mc","stem":"세 사람의 말에서 「짐은 가볍게」라고 한 까닭을 생활과 이어 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"자주 옮겨 다녀야 해서 하나로 여러 일을 하는 도구를 들고 다녔다","correct":true},{"t":"마을 창고에 짐을 쌓아 둘 곳이 있었다","mis":"SO5-2-u1-X07"},{"t":"청동 도구가 무거워 버리고 갔다","mis":"SO5-2-u1-X09"},{"t":"농사를 지어 짐이 필요 없었다","mis":"SO5-2-u1-X04"}],"explanation":["옮겨 다니는 생활이에요.","짐이 많으면 힘들어요.","만능 도구 하나를 들고 다녀요."],"asset":{"type":"speech","turns":[{"who":"하윤","text":"이 골짜기엔 이제 열매도 짐승도 거의 없어."},{"who":"도겸","text":"그럼 먹을 것이 있는 곳으로 옮겨 가자."},{"who":"하윤","text":"짐은 가볍게, 주먹 도끼 하나면 여러 일을 할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_challenge#4','soc',5,2,'u1','L01','g5_2_soc_u1_L01_challenge','lesson_challenge','SO5-2-u1-C2',3,'mc','auto','구석기 사람들이 불을 쓰게 되면서 달라진 점으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X05']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C2","difficulty":3,"kind":"mc","stem":"구석기 사람들이 불을 쓰게 되면서 달라진 점으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"곡식을 거두어 토기에 오래 보관하게 되었다","correct":true},{"t":"밤에도 사나운 짐승을 쫓을 수 있었다","mis":"SO5-2-u1-X05"},{"t":"추운 날에도 몸을 따뜻하게 할 수 있었다","mis":"SO5-2-u1-X05"},{"t":"고기를 익혀 먹을 수 있었다","mis":"SO5-2-u1-X05"}],"explanation":["불은 따뜻함과 안전을 줬어요.","익혀 먹게 했어요.","토기 보관은 신석기 이야기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_challenge#5','soc',5,2,'u1','L01','g5_2_soc_u1_L01_challenge','lesson_challenge','SO5-2-u1-C1',3,'mc','auto','경기도 연천 한탄강 가에서 주먹 도끼가 발견된 일이 알려 주는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X42','SO5-2-u1-X08','SO5-2-u1-X01']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C1","difficulty":3,"kind":"mc","stem":"경기도 연천 한탄강 가에서 주먹 도끼가 발견된 일이 알려 주는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"유물 하나가 옛 사람들의 생활에 대한 생각을 바꾸는 증거가 될 수 있다","correct":true},{"t":"유물은 박물관을 꾸미는 장식일 뿐이다","mis":"SO5-2-u1-X42"},{"t":"주먹 도끼는 고려 사람들이 쓰던 도구다","mis":"SO5-2-u1-X08"},{"t":"돌은 어디서나 흔해 역사와 관계없다","mis":"SO5-2-u1-X01"}],"explanation":["돌 하나가 발견됐어요.","학자들의 생각이 바뀌었어요.","유물은 증거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_challenge#6','soc',5,2,'u1','L01','g5_2_soc_u1_L01_challenge','lesson_challenge','SO5-2-u1-C2',3,'ox','auto','구석기 사람들이 튼튼한 집을 짓지 않은 것은 옮겨 다니는 생활과 관계가 있어요.',ARRAY['SO5-2-u1-X04']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C2","difficulty":3,"kind":"ox","stem":"구석기 사람들이 튼튼한 집을 짓지 않은 것은 옮겨 다니는 생활과 관계가 있어요.","answer":"O","reason_options":[{"t":"먹을 것을 찾아 자주 떠나야 해서 잠깐 머물 집이면 충분했기 때문에","correct":true},{"t":"구석기 사람들은 아무 집도 짓지 않고 늘 들판에서만 잤기 때문에","mis":"SO5-2-u1-X04"}],"mis":"SO5-2-u1-X04","explanation":["막집은 잠깐 머무는 집이에요.","자주 옮겨 다녔어요.","생활에 맞는 집이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_challenge#7','soc',5,2,'u1','L01','g5_2_soc_u1_L01_challenge','lesson_challenge','SO5-2-u1-C1',3,'error','auto','선사 시대를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X02','SO5-2-u1-X01']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C1","difficulty":3,"kind":"error","stem":"선사 시대를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은호 — 「선사 시대는 그냥 아주아주 오래된 때를 말하는 거야.」","correct":true,"mis_target":"SO5-2-u1-X02"},{"t":"라희 — 「선사 시대는 기록이 없어서 유물과 유적으로 생활을 짐작해.」","mis":"SO5-2-u1-X02"},{"t":"태민 — 「땅속에서 나온 도구로도 생활을 알 수 있어.」","mis":"SO5-2-u1-X01"}],"explanation":["오래됐다는 것만이 기준이 아니에요.","문자 기록이 없는 때예요.","은호의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_challenge#8','soc',5,2,'u1','L01','g5_2_soc_u1_L01_challenge','lesson_challenge','SO5-2-u1-C2',4,'mc','auto','구석기 사람들의 생활을 원인과 결과로 가장 잘 이은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X07','SO5-2-u1-X10','SO5-2-u1-X08']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C2","difficulty":4,"kind":"mc","stem":"구석기 사람들의 생활을 원인과 결과로 가장 잘 이은 것은 어느 것인가요?","options":[{"t":"먹을 것이 떨어지면 옮겨 감 → 막집·동굴에서 지냄 → 하나로 여러 일을 하는 주먹 도끼를 씀","correct":true},{"t":"농사를 지음 → 움집을 지음 → 토기에 곡식을 보관함","mis":"SO5-2-u1-X07"},{"t":"곡식이 남음 → 지배자가 생김 → 고인돌을 만듦","mis":"SO5-2-u1-X10"},{"t":"청동을 씀 → 무기를 만듦 → 다른 마을과 싸움","mis":"SO5-2-u1-X08"}],"explanation":["먹을 것이 떨어져요.","옮겨 다녀요.","집과 도구가 그 생활에 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_challenge#9','soc',5,2,'u1','L01','g5_2_soc_u1_L01_challenge','lesson_challenge','SO5-2-u1-C1',4,'mc','auto','선사 시대를 공부하는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X42','SO5-2-u1-X04','SO5-2-u1-X02']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C1","difficulty":4,"kind":"mc","stem":"선사 시대를 공부하는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"유물의 생김새와 쓰임을 살펴 그때 사람들이 어떻게 살았는지 짐작해 본다","correct":true},{"t":"도구 이름만 빠르게 외우고 넘어간다","mis":"SO5-2-u1-X42"},{"t":"옛 사람들은 미개했다고 보고 깊이 살피지 않는다","mis":"SO5-2-u1-X04"},{"t":"선사 시대 사람들이 쓴 책을 찾아 읽는다","mis":"SO5-2-u1-X02"}],"explanation":["생김새를 살펴요.","쓰임을 생각해요.","생활을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L01_challenge#10','soc',5,2,'u1','L01','g5_2_soc_u1_L01_challenge','lesson_challenge','SO5-2-u1-C2',4,'essay','teacher','구석기 시대 어린이가 되었다고 생각하고, 옷·먹을 것·사는 곳·불이 모두 드러나게 하루 일기를 두세 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C2","difficulty":4,"kind":"essay","stem":"구석기 시대 어린이가 되었다고 생각하고, 옷·먹을 것·사는 곳·불이 모두 드러나게 하루 일기를 두세 문장으로 쓰세요.","answer_guide":{"answer":"예: 오늘 아침 짐승 가죽을 두르고 어른들과 산에 가서 열매를 따고 사슴을 사냥했다. 이 골짜기에는 먹을 것이 줄어 며칠 뒤 다른 곳으로 옮겨 가기로 해서 지금은 바위 그늘에서 지낸다. 저녁에는 불을 피워 고기를 익혀 먹고, 불 덕분에 짐승이 다가오지 못해 안심하고 잤다.","scoring_points":["옷과 먹을 것을 구하는 방법을 썼는가","옮겨 다니는 생활과 사는 곳을 이어 썼는가","불의 쓰임을 썼는가"]},"explanation":["가죽·풀로 몸을 덮어요.","채집·사냥하고 옮겨 다녀요.","불로 지키고 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_basic#1','soc',5,2,'u1','L02','g5_2_soc_u1_L02_basic','lesson_basic','SO5-2-u1-C3',1,'mc','auto','신석기 시대 사람들이 돌을 갈고 다듬어 쓰임에 맞게 만든 도구를 무엇이라고 하나요?',ARRAY['SO5-2-u1-X03','SO5-2-u1-X08']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C3","difficulty":1,"kind":"mc","stem":"신석기 시대 사람들이 돌을 갈고 다듬어 쓰임에 맞게 만든 도구를 무엇이라고 하나요?","options":[{"t":"간석기","correct":true},{"t":"뗀석기","mis":"SO5-2-u1-X03"},{"t":"청동기","mis":"SO5-2-u1-X08"},{"t":"철기","mis":"SO5-2-u1-X08"}],"explanation":["돌을 갈아요.","매끄럽게 다듬어요.","간석기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_basic#2','soc',5,2,'u1','L02','g5_2_soc_u1_L02_basic','lesson_basic','SO5-2-u1-C3',1,'mc','auto','신석기 시대 사람들이 먹을 것을 담아 보관하고 조리할 때 쓴 그릇은 어느 것인가요?',ARRAY['SO5-2-u1-X08','SO5-2-u1-X26']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C3","difficulty":1,"kind":"mc","stem":"신석기 시대 사람들이 먹을 것을 담아 보관하고 조리할 때 쓴 그릇은 어느 것인가요?","options":[{"t":"빗살무늬 토기","correct":true},{"t":"민무늬 토기","mis":"SO5-2-u1-X08"},{"t":"고려청자","mis":"SO5-2-u1-X26"},{"t":"청동 거울","mis":"SO5-2-u1-X08"}],"explanation":["겉에 빗으로 그은 듯한 무늬가 있어요.","흙으로 빚어 구웠어요.","빗살무늬 토기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_basic#3','soc',5,2,'u1','L02','g5_2_soc_u1_L02_basic','lesson_basic','SO5-2-u1-C4',1,'sa','auto','신석기 시대 사람들이 땅을 파고 기둥을 세워 지은 집을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u1-C4","difficulty":1,"kind":"sa","stem":"신석기 시대 사람들이 땅을 파고 기둥을 세워 지은 집을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["움집"],"explanation":["땅을 파요.","기둥과 지붕을 얹어요.","움집이에요."],"mis":"SO5-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_basic#4','soc',5,2,'u1','L02','g5_2_soc_u1_L02_basic','lesson_basic','SO5-2-u1-C3',1,'ox','auto','신석기 시대 사람들은 가락바퀴로 실을 뽑고 뼈바늘로 옷을 지었어요.',ARRAY['SO5-2-u1-X06']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C3","difficulty":1,"kind":"ox","stem":"신석기 시대 사람들은 가락바퀴로 실을 뽑고 뼈바늘로 옷을 지었어요.","answer":"O","reason_options":[{"t":"가락바퀴는 실을 뽑는 도구이고 뼈바늘로 그 실을 꿰어 옷을 지었기 때문에","correct":true},{"t":"가락바퀴는 곡식을 거두는 도구였기 때문에","mis":"SO5-2-u1-X06"}],"mis":"SO5-2-u1-X06","explanation":["가락바퀴는 돌려서 써요.","실을 뽑아요.","뼈바늘로 옷을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_basic#5','soc',5,2,'u1','L02','g5_2_soc_u1_L02_basic','lesson_basic','SO5-2-u1-C4',2,'mc','auto','신석기 시대 사람들이 마을을 이룬 곳으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X07']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C4","difficulty":2,"kind":"mc","stem":"신석기 시대 사람들이 마을을 이룬 곳으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"먹을 것을 구하기 좋은 강가나 바닷가","correct":true},{"t":"물이 없는 높은 산꼭대기","mis":"SO5-2-u1-X07"},{"t":"사람이 들어갈 수 없는 깊은 동굴 속","mis":"SO5-2-u1-X07"},{"t":"바다 한가운데 배 위","mis":"SO5-2-u1-X07"}],"explanation":["물고기를 잡을 수 있어요.","물을 구하기 쉬워요.","강가나 바닷가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_basic#6','soc',5,2,'u1','L02','g5_2_soc_u1_L02_basic','lesson_basic','SO5-2-u1-C4',2,'mc','auto','신석기 시대 사람들이 한곳에 머물러 살게 된 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X08','SO5-2-u1-X13','SO5-2-u1-X05']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C4","difficulty":2,"kind":"mc","stem":"신석기 시대 사람들이 한곳에 머물러 살게 된 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물고기잡이·사냥·채집으로 먹을 것을 꾸준히 구하고 남은 것을 토기에 보관할 수 있어서","correct":true},{"t":"청동 무기로 마을을 지킬 수 있어서","mis":"SO5-2-u1-X08"},{"t":"왕이 옮겨 다니지 못하게 법을 만들어서","mis":"SO5-2-u1-X13"},{"t":"불을 처음 쓰게 되어서","mis":"SO5-2-u1-X05"}],"explanation":["먹을 것을 꾸준히 구해요.","남은 것은 토기에 담아요.","그래서 머물러 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_basic#7','soc',5,2,'u1','L02','g5_2_soc_u1_L02_basic','lesson_basic','SO5-2-u1-C3',2,'mc','auto','어느 강가 유적 발굴 메모 ③의 둥근 돌 조각은 무엇에 쓰였을까요?',ARRAY['SO5-2-u1-X06','SO5-2-u1-X09']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C3","difficulty":2,"kind":"mc","stem":"어느 강가 유적 발굴 메모 ③의 둥근 돌 조각은 무엇에 쓰였을까요?","options":[{"t":"실을 뽑을 때","correct":true},{"t":"곡식 이삭을 자를 때","mis":"SO5-2-u1-X06"},{"t":"물고기를 굽는 그릇으로","mis":"SO5-2-u1-X06"},{"t":"지배자가 제사를 지낼 때","mis":"SO5-2-u1-X09"}],"explanation":["가운데 구멍이 뚫려 있어요.","막대를 끼워 돌려요.","가락바퀴로 실을 뽑았어요."],"asset":{"type":"passage","lines":["① 강가 모래밭에서 바닥이 뾰족한 그릇이 나왔다.","② 그릇 겉에 빗으로 그은 듯한 무늬가 가득하다.","③ 가운데 구멍이 뚫린 둥근 돌 조각이 함께 나왔다.","④ 짐승 뼈를 갈아 만든 가늘고 뾰족한 도구도 있다.","⑤ 땅을 둥글게 파고 기둥을 세운 집터가 여러 개 모여 있다."],"title":"어느 강가 유적 발굴 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_basic#8','soc',5,2,'u1','L02','g5_2_soc_u1_L02_basic','lesson_basic','SO5-2-u1-C3',2,'mc','auto','신석기 시대 사람들의 먹을거리 구하기에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X07','SO5-2-u1-X08','SO5-2-u1-X04']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C3","difficulty":2,"kind":"mc","stem":"신석기 시대 사람들의 먹을거리 구하기에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"사냥과 채집에 더해 물고기잡이를 하고 점차 농사도 지었다","correct":true},{"t":"처음부터 넓은 논에서 벼농사만 지었다","mis":"SO5-2-u1-X07"},{"t":"사냥을 하지 않고 시장에서 사 먹었다","mis":"SO5-2-u1-X08"},{"t":"먹을 것이 떨어지면 늘 옮겨 다녔다","mis":"SO5-2-u1-X04"}],"explanation":["물고기잡이가 더해졌어요.","농사도 조금씩 시작했어요.","먹을 것을 꾸준히 구했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_basic#9','soc',5,2,'u1','L02','g5_2_soc_u1_L02_basic','lesson_basic','SO5-2-u1-C4',2,'ox','auto','서울 암사동 유적은 신석기 사람들이 마을을 이루어 살았다는 것을 알려 주어요.',ARRAY['SO5-2-u1-X08']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C4","difficulty":2,"kind":"ox","stem":"서울 암사동 유적은 신석기 사람들이 마을을 이루어 살았다는 것을 알려 주어요.","answer":"O","reason_options":[{"t":"여러 집터와 신석기 유물이 함께 발견되었기 때문에","correct":true},{"t":"그곳에서 청동 검과 고인돌이 나왔기 때문에","mis":"SO5-2-u1-X08"}],"mis":"SO5-2-u1-X08","explanation":["한강 가에서 집터가 드러났어요.","신석기 유물이 많이 나왔어요.","신석기 마을이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_basic#10','soc',5,2,'u1','L02','g5_2_soc_u1_L02_basic','lesson_basic','SO5-2-u1-C3',3,'error','auto','신석기 시대를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X08','SO5-2-u1-X06','SO5-2-u1-X03']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C3","difficulty":3,"kind":"error","stem":"신석기 시대를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「신석기 사람들은 청동으로 만든 거울로 몸을 꾸몄어.」","correct":true,"mis_target":"SO5-2-u1-X08"},{"t":"주원 — 「조개껍데기로 장신구를 만들어 꾸몄어.」","mis":"SO5-2-u1-X06"},{"t":"세빈 — 「돌을 갈아 만든 간석기를 썼어.」","mis":"SO5-2-u1-X03"}],"explanation":["청동은 다음 시대에 나와요.","신석기 사람들은 조개껍데기로 꾸몄어요.","하린의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_challenge#1','soc',5,2,'u1','L02','g5_2_soc_u1_L02_challenge','lesson_challenge','SO5-2-u1-C3',2,'match','auto','신석기 시대 유물과 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C3","difficulty":2,"kind":"match","stem":"신석기 시대 유물과 쓰임을 알맞게 이으세요.","pairs":[{"l":"빗살무늬 토기","r":"먹을 것 보관·조리"},{"l":"가락바퀴","r":"실 뽑기"},{"l":"뼈바늘","r":"옷·그물 짓기"},{"l":"조개껍데기 장신구","r":"몸 꾸미기"}],"mis":"SO5-2-u1-X06","explanation":["토기는 담는 그릇이에요.","가락바퀴와 뼈바늘은 옷을 짓는 데 썼어요.","조개껍데기로 꾸몄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_challenge#2','soc',5,2,'u1','L02','g5_2_soc_u1_L02_challenge','lesson_challenge','SO5-2-u1-C3',2,'mc','auto','박물관 진열장 설명 셋 가운데 신석기 시대에 처음 널리 쓴 도구를 설명한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X03','SO5-2-u1-X08']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C3","difficulty":2,"kind":"mc","stem":"박물관 진열장 설명 셋 가운데 신석기 시대에 처음 널리 쓴 도구를 설명한 것은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"SO5-2-u1-X03"},{"t":"다","mis":"SO5-2-u1-X08"},{"t":"가와 다 모두","mis":"SO5-2-u1-X08"}],"explanation":["가는 깨뜨려 만든 돌이에요.","나는 갈아서 만든 돌이에요.","다는 청동이에요."],"asset":{"type":"passage","lines":["가 — 한쪽은 둥글고 다른 쪽은 뾰족하게 깨뜨려 날을 세웠다.","나 — 돌을 갈아서 표면이 매끄럽고 날이 고르다.","다 — 구리에 주석을 섞어 녹여 만든 검으로 반짝인다."],"title":"박물관 진열장 설명 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_challenge#3','soc',5,2,'u1','L02','g5_2_soc_u1_L02_challenge','lesson_challenge','SO5-2-u1-C3',3,'mc','auto','빗살무늬 토기의 바닥이 뾰족한 까닭을 짐작한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X11','SO5-2-u1-X04','SO5-2-u1-X08']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C3","difficulty":3,"kind":"mc","stem":"빗살무늬 토기의 바닥이 뾰족한 까닭을 짐작한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"강가 모래밭에 꽂아 세워 두기 좋았을 것이다","correct":true},{"t":"지배자의 무덤에 장식으로 넣으려고","mis":"SO5-2-u1-X11"},{"t":"들고 다니며 옮겨 다니기 좋게","mis":"SO5-2-u1-X04"},{"t":"쇠를 녹이는 데 쓰려고","mis":"SO5-2-u1-X08"}],"explanation":["발견된 곳은 강가 모래밭이에요.","모래에 꽂으면 서요.","생김새와 쓰임을 이어 짐작해요."],"asset":{"type":"passage","lines":["① 강가 모래밭에서 바닥이 뾰족한 그릇이 나왔다.","② 그릇 겉에 빗으로 그은 듯한 무늬가 가득하다.","③ 가운데 구멍이 뚫린 둥근 돌 조각이 함께 나왔다.","④ 짐승 뼈를 갈아 만든 가늘고 뾰족한 도구도 있다.","⑤ 땅을 둥글게 파고 기둥을 세운 집터가 여러 개 모여 있다."],"title":"어느 강가 유적 발굴 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_challenge#4','soc',5,2,'u1','L02','g5_2_soc_u1_L02_challenge','lesson_challenge','SO5-2-u1-C4',3,'mc','auto','어느 강가 유적 발굴 메모 ⑤에서 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X04','SO5-2-u1-X10']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C4","difficulty":3,"kind":"mc","stem":"어느 강가 유적 발굴 메모 ⑤에서 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 집이 모여 마을을 이루고 한곳에 머물러 살았다","correct":true},{"t":"먹을 것을 찾아 날마다 옮겨 다녔다","mis":"SO5-2-u1-X04"},{"t":"지배자 한 사람만 집에서 살았다","mis":"SO5-2-u1-X10"},{"t":"사람들이 동굴에서만 지냈다","mis":"SO5-2-u1-X04"}],"explanation":["집터가 여러 개예요.","한곳에 모여 있어요.","정착해 마을을 이뤘어요."],"asset":{"type":"passage","lines":["① 강가 모래밭에서 바닥이 뾰족한 그릇이 나왔다.","② 그릇 겉에 빗으로 그은 듯한 무늬가 가득하다.","③ 가운데 구멍이 뚫린 둥근 돌 조각이 함께 나왔다.","④ 짐승 뼈를 갈아 만든 가늘고 뾰족한 도구도 있다.","⑤ 땅을 둥글게 파고 기둥을 세운 집터가 여러 개 모여 있다."],"title":"어느 강가 유적 발굴 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_challenge#5','soc',5,2,'u1','L02','g5_2_soc_u1_L02_challenge','lesson_challenge','SO5-2-u1-C3',3,'mc','auto','신석기 사람들이 가죽 대신 실로 지은 옷을 입게 되면서 좋아진 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X06','SO5-2-u1-X19','SO5-2-u1-X08']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C3","difficulty":3,"kind":"mc","stem":"신석기 사람들이 가죽 대신 실로 지은 옷을 입게 되면서 좋아진 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"몸을 더 잘 보호하고 활동하기 편해졌다","correct":true},{"t":"옷을 입지 않아도 되었다","mis":"SO5-2-u1-X06"},{"t":"신분에 따라 비단옷을 입게 되었다","mis":"SO5-2-u1-X19"},{"t":"옷감을 다른 나라에 팔게 되었다","mis":"SO5-2-u1-X08"}],"explanation":["가락바퀴로 실을 뽑아요.","뼈바늘로 꿰매요.","몸을 더 잘 보호해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_challenge#6','soc',5,2,'u1','L02','g5_2_soc_u1_L02_challenge','lesson_challenge','SO5-2-u1-C4',3,'ox','auto','신석기 사람들은 처음부터 넓은 논에서 벼농사를 지어 먹을 것을 모두 해결했어요.',ARRAY['SO5-2-u1-X07']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C4","difficulty":3,"kind":"ox","stem":"신석기 사람들은 처음부터 넓은 논에서 벼농사를 지어 먹을 것을 모두 해결했어요.","answer":"X","reason_options":[{"t":"물고기잡이·사냥·채집이 바탕이었고 농사는 조금씩 더해졌기 때문에","correct":true},{"t":"신석기 사람들은 먹을 것을 모두 벼농사로만 얻었기 때문에","mis":"SO5-2-u1-X07"}],"mis":"SO5-2-u1-X07","explanation":["바탕은 물고기잡이·사냥·채집이에요.","농사는 조금씩 시작했어요.","벼농사가 널리 퍼진 것은 다음 시대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_challenge#7','soc',5,2,'u1','L02','g5_2_soc_u1_L02_challenge','lesson_challenge','SO5-2-u1-C4',3,'error','auto','구석기와 신석기를 견주어 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X04','SO5-2-u1-X03','SO5-2-u1-X07']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C4","difficulty":3,"kind":"error","stem":"구석기와 신석기를 견주어 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「신석기 사람들도 먹을 것이 떨어지면 계속 옮겨 다녀서 집을 짓지 않았어.」","correct":true,"mis_target":"SO5-2-u1-X04"},{"t":"가은 — 「구석기는 뗀석기, 신석기는 간석기를 썼어.」","mis":"SO5-2-u1-X03"},{"t":"민혁 — 「신석기 사람들은 강가에 움집을 짓고 머물렀어.」","mis":"SO5-2-u1-X07"}],"explanation":["신석기에는 먹을 것을 꾸준히 구했어요.","움집을 짓고 머물렀어요.","도윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_challenge#8','soc',5,2,'u1','L02','g5_2_soc_u1_L02_challenge','lesson_challenge','SO5-2-u1-C4',4,'mc','auto','신석기 시대의 생활 변화를 원인과 결과로 가장 잘 이은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X15','SO5-2-u1-X04','SO5-2-u1-X10']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C4","difficulty":4,"kind":"mc","stem":"신석기 시대의 생활 변화를 원인과 결과로 가장 잘 이은 것은 어느 것인가요?","options":[{"t":"먹을 것을 꾸준히 구하고 토기에 보관함 → 옮겨 다니지 않아도 됨 → 강가에 움집을 짓고 마을을 이룸","correct":true},{"t":"청동 무기를 만듦 → 다른 마을을 정복함 → 나라를 세움","mis":"SO5-2-u1-X15"},{"t":"먹을 것이 떨어짐 → 옮겨 다님 → 막집에서 지냄","mis":"SO5-2-u1-X04"},{"t":"곡식이 남음 → 빈부의 차이가 생김 → 고인돌을 만듦","mis":"SO5-2-u1-X10"}],"explanation":["먹을 것을 꾸준히 구해요.","보관도 할 수 있어요.","그래서 머물러 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_challenge#9','soc',5,2,'u1','L02','g5_2_soc_u1_L02_challenge','lesson_challenge','SO5-2-u1-C3',4,'mc','auto','구석기와 신석기를 견준 표에서 알맞지 않은 줄은 어느 것인가요?',ARRAY['SO5-2-u1-X03','SO5-2-u1-X07','SO5-2-u1-X04']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C3","difficulty":4,"kind":"mc","stem":"구석기와 신석기를 견준 표에서 알맞지 않은 줄은 어느 것인가요?","options":[{"t":"사는 곳 — 구석기 움집 / 신석기 동굴","correct":true},{"t":"도구 — 구석기 뗀석기 / 신석기 간석기","mis":"SO5-2-u1-X03"},{"t":"먹을거리 — 구석기 사냥·채집 / 신석기 물고기잡이·농사가 더해짐","mis":"SO5-2-u1-X07"},{"t":"생활 — 구석기 옮겨 다님 / 신석기 한곳에 머묾","mis":"SO5-2-u1-X04"}],"explanation":["구석기는 막집·동굴이에요.","신석기는 움집이에요.","사는 곳 줄이 거꾸로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L02_challenge#10','soc',5,2,'u1','L02','g5_2_soc_u1_L02_challenge','lesson_challenge','SO5-2-u1-C4',4,'essay','teacher','어느 강가 유적 발굴 메모 ①~⑤를 증거로 삼아 신석기 사람들의 생활 모습을 짐작해 두 가지 이상 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C4","difficulty":4,"kind":"essay","stem":"어느 강가 유적 발굴 메모 ①~⑤를 증거로 삼아 신석기 사람들의 생활 모습을 짐작해 두 가지 이상 쓰세요.","answer_guide":{"answer":"예: ①·②의 빗살무늬 토기로 먹을 것을 담아 보관하고 조리했다는 것을 알 수 있다. ③의 가락바퀴와 ④의 뼈바늘로 실을 뽑아 옷을 지어 입었다고 짐작한다. ⑤처럼 집터가 여러 개 모여 있어 강가에 움집을 짓고 마을을 이루어 머물러 살았다고 짐작한다.","scoring_points":["메모의 유물을 증거로 들었는가","유물과 생활 모습을 바르게 이었는가","두 가지 이상 썼는가"]},"explanation":["토기는 보관이에요.","가락바퀴·뼈바늘은 옷이에요.","집터가 모이면 마을이에요."],"asset":{"type":"passage","lines":["① 강가 모래밭에서 바닥이 뾰족한 그릇이 나왔다.","② 그릇 겉에 빗으로 그은 듯한 무늬가 가득하다.","③ 가운데 구멍이 뚫린 둥근 돌 조각이 함께 나왔다.","④ 짐승 뼈를 갈아 만든 가늘고 뾰족한 도구도 있다.","⑤ 땅을 둥글게 파고 기둥을 세운 집터가 여러 개 모여 있다."],"title":"어느 강가 유적 발굴 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_basic#1','soc',5,2,'u1','L03','g5_2_soc_u1_L03_basic','lesson_basic','SO5-2-u1-C5',1,'mc','auto','청동은 무엇과 무엇을 섞어 녹여 만든 금속인가요?',ARRAY['SO5-2-u1-X08','SO5-2-u1-X15']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C5","difficulty":1,"kind":"mc","stem":"청동은 무엇과 무엇을 섞어 녹여 만든 금속인가요?","options":[{"t":"구리와 주석","correct":true},{"t":"흙과 모래","mis":"SO5-2-u1-X08"},{"t":"철과 돌","mis":"SO5-2-u1-X15"},{"t":"금과 조개껍데기","mis":"SO5-2-u1-X08"}],"explanation":["반짝이는 금속이에요.","구리에 섞었어요.","구리와 주석이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_basic#2','soc',5,2,'u1','L03','g5_2_soc_u1_L03_basic','lesson_basic','SO5-2-u1-C5',1,'mc','auto','청동기 시대 사람들이 벼 이삭을 거둘 때 쓴 도구는 어느 것인가요?',ARRAY['SO5-2-u1-X08','SO5-2-u1-X06','SO5-2-u1-X09']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C5","difficulty":1,"kind":"mc","stem":"청동기 시대 사람들이 벼 이삭을 거둘 때 쓴 도구는 어느 것인가요?","options":[{"t":"반달 돌칼","correct":true},{"t":"주먹 도끼","mis":"SO5-2-u1-X08"},{"t":"가락바퀴","mis":"SO5-2-u1-X06"},{"t":"비파형 동검","mis":"SO5-2-u1-X09"}],"explanation":["반달처럼 생겼어요.","돌로 만들었어요.","이삭을 땄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_basic#3','soc',5,2,'u1','L03','g5_2_soc_u1_L03_basic','lesson_basic','SO5-2-u1-C6',1,'sa','auto','받침돌 위에 커다란 덮개돌을 얹어 만든 청동기 시대의 무덤을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u1-C6","difficulty":1,"kind":"sa","stem":"받침돌 위에 커다란 덮개돌을 얹어 만든 청동기 시대의 무덤을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["고인돌"],"explanation":["돌로 만든 무덤이에요.","덮개돌이 커요.","고인돌이에요."],"mis":"SO5-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_basic#4','soc',5,2,'u1','L03','g5_2_soc_u1_L03_basic','lesson_basic','SO5-2-u1-C6',1,'ox','auto','청동기 시대에는 곡식이 남으면서 많이 가진 사람과 적게 가진 사람이 생겼어요.',ARRAY['SO5-2-u1-X10']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C6","difficulty":1,"kind":"ox","stem":"청동기 시대에는 곡식이 남으면서 많이 가진 사람과 적게 가진 사람이 생겼어요.","answer":"O","reason_options":[{"t":"남은 곡식을 더 많이 가진 사람이 생겨 빈부의 차이가 나타났기 때문에","correct":true},{"t":"처음부터 모든 사람이 똑같이 나누어 가졌기 때문에","mis":"SO5-2-u1-X10"}],"mis":"SO5-2-u1-X10","explanation":["농사 기술이 나아졌어요.","곡식이 남았어요.","빈부의 차이가 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_basic#5','soc',5,2,'u1','L03','g5_2_soc_u1_L03_basic','lesson_basic','SO5-2-u1-C5',2,'mc','auto','청동기가 귀해 주로 지배자가 쓴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X09','SO5-2-u1-X08']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C5","difficulty":2,"kind":"mc","stem":"청동기가 귀해 주로 지배자가 쓴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"재료가 귀하고 만들기 어려웠기 때문에","correct":true},{"t":"누구나 쉽게 주울 수 있었기 때문에","mis":"SO5-2-u1-X09"},{"t":"돌보다 약해 쓸모가 없었기 때문에","mis":"SO5-2-u1-X09"},{"t":"신석기 사람들이 이미 다 써 버렸기 때문에","mis":"SO5-2-u1-X08"}],"explanation":["구리와 주석이 필요해요.","녹여 만들기 어려워요.","귀해서 지배자가 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_basic#6','soc',5,2,'u1','L03','g5_2_soc_u1_L03_basic','lesson_basic','SO5-2-u1-C6',2,'mc','auto','청동기 시대 지배자가 한 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X31','SO5-2-u1-X26','SO5-2-u1-X04']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C6","difficulty":2,"kind":"mc","stem":"청동기 시대 지배자가 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"마을을 다스리고 하늘에 제사를 이끌었다","correct":true},{"t":"과거 시험으로 관리를 뽑았다","mis":"SO5-2-u1-X31"},{"t":"팔만대장경을 새겼다","mis":"SO5-2-u1-X26"},{"t":"먹을 것을 찾아 혼자 옮겨 다녔다","mis":"SO5-2-u1-X04"}],"explanation":["재산과 힘을 모았어요.","마을을 다스렸어요.","제사도 이끌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_basic#7','soc',5,2,'u1','L03','g5_2_soc_u1_L03_basic','lesson_basic','SO5-2-u1-C6',2,'mc','auto','어느 청동기 마을 유적 메모 ①·②처럼 도랑·울타리·망루를 세운 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X07','SO5-2-u1-X04','SO5-2-u1-X10']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C6","difficulty":2,"kind":"mc","stem":"어느 청동기 마을 유적 메모 ①·②처럼 도랑·울타리·망루를 세운 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쌓인 곡식과 재산을 두고 다툼이 생겨 마을을 지키려고","correct":true},{"t":"물고기를 잡으려고","mis":"SO5-2-u1-X07"},{"t":"먹을 것이 떨어져 옮겨 가려고","mis":"SO5-2-u1-X04"},{"t":"지배자를 없애려고","mis":"SO5-2-u1-X10"}],"explanation":["곡식이 쌓였어요.","빼앗으려는 다툼이 생겼어요.","마을을 지켜야 했어요."],"asset":{"type":"passage","lines":["① 마을 둘레에 깊은 도랑을 파고 나무 울타리를 둘렀다.","② 울타리 곁에 높은 망루를 세웠다.","③ 마을 안 창고에 곡식이 가득 쌓여 있다.","④ 한 무덤에서만 청동 검과 청동 거울이 나왔다.","⑤ 다른 무덤들에서는 돌화살촉만 나왔다."],"title":"어느 청동기 마을 유적 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_basic#8','soc',5,2,'u1','L03','g5_2_soc_u1_L03_basic','lesson_basic','SO5-2-u1-C5',2,'mc','auto','청동기 시대 사람들이 늘 쓰는 도구를 만든 재료로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X09','SO5-2-u1-X15']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C5","difficulty":2,"kind":"mc","stem":"청동기 시대 사람들이 늘 쓰는 도구를 만든 재료로 알맞은 것은 어느 것인가요?","options":[{"t":"돌과 나무","correct":true},{"t":"모두 청동","mis":"SO5-2-u1-X09"},{"t":"모두 철","mis":"SO5-2-u1-X15"},{"t":"금과 은","mis":"SO5-2-u1-X09"}],"explanation":["청동은 귀했어요.","늘 쓰는 도구는 흔한 재료로 만들어요.","돌과 나무예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_basic#9','soc',5,2,'u1','L03','g5_2_soc_u1_L03_basic','lesson_basic','SO5-2-u1-C5',2,'ox','auto','청동기 시대에는 무늬 없는 민무늬 토기를 썼어요.',ARRAY['SO5-2-u1-X08']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C5","difficulty":2,"kind":"ox","stem":"청동기 시대에는 무늬 없는 민무늬 토기를 썼어요.","answer":"O","reason_options":[{"t":"빗살무늬 토기와 달리 겉에 무늬가 없는 토기를 썼기 때문에","correct":true},{"t":"토기는 구석기 시대에만 썼기 때문에","mis":"SO5-2-u1-X08"}],"mis":"SO5-2-u1-X08","explanation":["신석기는 빗살무늬예요.","청동기는 무늬가 없어요.","민무늬 토기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_basic#10','soc',5,2,'u1','L03','g5_2_soc_u1_L03_basic','lesson_basic','SO5-2-u1-C6',3,'error','auto','고인돌을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X11']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C6","difficulty":3,"kind":"error","stem":"고인돌을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「고인돌은 마을 사람들이 비를 피하려고 만든 집이야.」","correct":true,"mis_target":"SO5-2-u1-X11"},{"t":"예준 — 「덮개돌을 옮기려면 많은 사람이 필요했을 거야.」","mis":"SO5-2-u1-X11"},{"t":"소율 — 「고인돌은 지배자의 힘을 보여 주는 무덤이야.」","mis":"SO5-2-u1-X11"}],"explanation":["고인돌은 무덤이에요.","집이 아니에요.","지안의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_challenge#1','soc',5,2,'u1','L03','g5_2_soc_u1_L03_challenge','lesson_challenge','SO5-2-u1-C5',2,'match','auto','신석기 시대와 청동기 시대를 견주어 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C5","difficulty":2,"kind":"match","stem":"신석기 시대와 청동기 시대를 견주어 알맞게 이으세요.","pairs":[{"l":"신석기의 토기","r":"빗살무늬 토기"},{"l":"청동기의 토기","r":"민무늬 토기"},{"l":"청동기의 곡식 거두는 도구","r":"반달 돌칼"},{"l":"청동기의 지배자 무기","r":"청동 검"}],"mis":"SO5-2-u1-X08","explanation":["토기 무늬가 달라졌어요.","반달 돌칼로 거두었어요.","청동 검은 지배자의 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_challenge#2','soc',5,2,'u1','L03','g5_2_soc_u1_L03_challenge','lesson_challenge','SO5-2-u1-C6',2,'mc','auto','고인돌 유적 안내판을 보고 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X04','SO5-2-u1-X10','SO5-2-u1-X02']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C6","difficulty":2,"kind":"mc","stem":"고인돌 유적 안내판을 보고 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"많은 사람을 모아 일을 시킬 수 있는 힘센 지배자가 있었다","correct":true},{"t":"사람들이 옮겨 다니며 살았다","mis":"SO5-2-u1-X04"},{"t":"모든 사람이 똑같은 재산을 가졌다","mis":"SO5-2-u1-X10"},{"t":"사람들이 글로 기록을 남겼다","mis":"SO5-2-u1-X02"}],"explanation":["덮개돌이 아주 무거워요.","많은 사람이 필요해요.","사람을 모을 지배자가 있었어요."],"asset":{"type":"passage","lines":["큰 받침돌 위에 집채만 한 덮개돌이 얹혀 있다.","덮개돌 하나의 무게가 수십 톤에 이른다고 한다.","둘레에 이런 무덤이 수백 기나 모여 있다.","근처에 돌을 떠낸 채석장 흔적도 남아 있다."],"title":"고인돌 유적 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_challenge#3','soc',5,2,'u1','L03','g5_2_soc_u1_L03_challenge','lesson_challenge','SO5-2-u1-C6',3,'mc','auto','어느 청동기 마을 유적 메모 ④·⑤를 함께 볼 때 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X09','SO5-2-u1-X11']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C6","difficulty":3,"kind":"mc","stem":"어느 청동기 마을 유적 메모 ④·⑤를 함께 볼 때 알 수 있는 것은 어느 것인가요?","options":[{"t":"무덤에 묻힌 사람들 사이에 재산과 힘의 차이가 있었다","correct":true},{"t":"마을 사람 모두가 청동 검을 가졌다","mis":"SO5-2-u1-X09"},{"t":"청동 검은 물고기를 잡는 도구였다","mis":"SO5-2-u1-X09"},{"t":"이 마을에는 무덤이 하나뿐이었다","mis":"SO5-2-u1-X11"}],"explanation":["한 무덤에만 청동 검이 있어요.","다른 무덤엔 돌화살촉뿐이에요.","차이가 있었어요."],"asset":{"type":"passage","lines":["① 마을 둘레에 깊은 도랑을 파고 나무 울타리를 둘렀다.","② 울타리 곁에 높은 망루를 세웠다.","③ 마을 안 창고에 곡식이 가득 쌓여 있다.","④ 한 무덤에서만 청동 검과 청동 거울이 나왔다.","⑤ 다른 무덤들에서는 돌화살촉만 나왔다."],"title":"어느 청동기 마을 유적 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_challenge#4','soc',5,2,'u1','L03','g5_2_soc_u1_L03_challenge','lesson_challenge','SO5-2-u1-C6',3,'mc','auto','청동기 시대에 빈부의 차이가 생기고 지배자가 나타난 과정을 차례로 바르게 이은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X10','SO5-2-u1-X04']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C6","difficulty":3,"kind":"mc","stem":"청동기 시대에 빈부의 차이가 생기고 지배자가 나타난 과정을 차례로 바르게 이은 것은 어느 것인가요?","options":[{"t":"농사 기술이 나아짐 → 곡식이 남음 → 많이 가진 사람이 생김 → 지배자가 마을을 다스림","correct":true},{"t":"지배자가 나타남 → 곡식이 남음 → 농사를 시작함 → 빈부가 사라짐","mis":"SO5-2-u1-X10"},{"t":"곡식이 모자람 → 옮겨 다님 → 지배자가 생김 → 고인돌을 만듦","mis":"SO5-2-u1-X04"},{"t":"불을 씀 → 고기를 익힘 → 지배자가 생김 → 움집을 지음","mis":"SO5-2-u1-X10"}],"explanation":["먼저 곡식이 남아요.","가진 것이 달라져요.","힘을 모은 사람이 지배자가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_challenge#5','soc',5,2,'u1','L03','g5_2_soc_u1_L03_challenge','lesson_challenge','SO5-2-u1-C5',3,'ox','auto','청동기 시대가 되자 사람들은 돌 도구를 모두 버리고 청동 도구만 썼어요.',ARRAY['SO5-2-u1-X09']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C5","difficulty":3,"kind":"ox","stem":"청동기 시대가 되자 사람들은 돌 도구를 모두 버리고 청동 도구만 썼어요.","answer":"X","reason_options":[{"t":"청동은 귀해 지배자가 주로 썼고 늘 쓰는 도구는 여전히 돌과 나무로 만들었기 때문에","correct":true},{"t":"청동이 흔해져 누구나 청동 농기구를 썼기 때문에","mis":"SO5-2-u1-X09"}],"mis":"SO5-2-u1-X09","explanation":["반달 돌칼은 돌이에요.","고인돌에서 돌화살촉도 나와요.","돌 도구를 계속 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_challenge#6','soc',5,2,'u1','L03','g5_2_soc_u1_L03_challenge','lesson_challenge','SO5-2-u1-C6',3,'mc','auto','전라북도 고창 고인돌 유적에 돌을 떠낸 채석장까지 남아 있는 것이 알려 주는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X11','SO5-2-u1-X15']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C6","difficulty":3,"kind":"mc","stem":"전라북도 고창 고인돌 유적에 돌을 떠낸 채석장까지 남아 있는 것이 알려 주는 것은 어느 것인가요?","options":[{"t":"사람들이 근처에서 돌을 떠내 옮겨 고인돌을 만들었다","correct":true},{"t":"고인돌은 저절로 생긴 바위다","mis":"SO5-2-u1-X11"},{"t":"고인돌은 오늘날 만든 놀이 시설이다","mis":"SO5-2-u1-X11"},{"t":"고인돌은 철로 만든 무덤이다","mis":"SO5-2-u1-X15"}],"explanation":["돌을 떠낸 흔적이 있어요.","사람이 일부러 옮겼어요.","고인돌을 만든 과정을 짐작해요."],"asset":{"type":"passage","lines":["큰 받침돌 위에 집채만 한 덮개돌이 얹혀 있다.","덮개돌 하나의 무게가 수십 톤에 이른다고 한다.","둘레에 이런 무덤이 수백 기나 모여 있다.","근처에 돌을 떠낸 채석장 흔적도 남아 있다."],"title":"고인돌 유적 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_challenge#7','soc',5,2,'u1','L03','g5_2_soc_u1_L03_challenge','lesson_challenge','SO5-2-u1-C5',3,'error','auto','청동기 시대 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X09','SO5-2-u1-X05']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C5","difficulty":3,"kind":"error","stem":"청동기 시대 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「청동기 시대 농부들은 청동 괭이로 밭을 갈았어.」","correct":true,"mis_target":"SO5-2-u1-X09"},{"t":"나윤 — 「곳곳에서 벼농사를 지었어.」","mis":"SO5-2-u1-X05"},{"t":"시우 — 「네모난 모양의 움집도 생겼어.」","mis":"SO5-2-u1-X05"}],"explanation":["청동은 귀했어요.","농기구는 돌과 나무였어요.","준서의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_challenge#8','soc',5,2,'u1','L03','g5_2_soc_u1_L03_challenge','lesson_challenge','SO5-2-u1-C6',4,'mc','auto','청동기 시대 유적을 보고 친구가 「옛날 사람들은 다 평화롭게 똑같이 살았구나」라고 했어요. 알맞게 고쳐 준 말은 어느 것인가요?',ARRAY['SO5-2-u1-X11','SO5-2-u1-X09','SO5-2-u1-X42']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C6","difficulty":4,"kind":"mc","stem":"청동기 시대 유적을 보고 친구가 「옛날 사람들은 다 평화롭게 똑같이 살았구나」라고 했어요. 알맞게 고쳐 준 말은 어느 것인가요?","options":[{"t":"울타리·망루와 무덤 속 유물의 차이를 보면 다툼과 빈부의 차이가 있었다고 짐작할 수 있어","correct":true},{"t":"맞아, 고인돌은 모두가 함께 쉬던 쉼터였어","mis":"SO5-2-u1-X11"},{"t":"맞아, 청동 검은 모든 집에 하나씩 있었어","mis":"SO5-2-u1-X09"},{"t":"유물로는 아무것도 짐작할 수 없으니 말할 수 없어","mis":"SO5-2-u1-X42"}],"explanation":["울타리와 망루는 지키려는 것이에요.","무덤 속 유물이 달라요.","다툼과 차이가 있었어요."],"asset":{"type":"passage","lines":["① 마을 둘레에 깊은 도랑을 파고 나무 울타리를 둘렀다.","② 울타리 곁에 높은 망루를 세웠다.","③ 마을 안 창고에 곡식이 가득 쌓여 있다.","④ 한 무덤에서만 청동 검과 청동 거울이 나왔다.","⑤ 다른 무덤들에서는 돌화살촉만 나왔다."],"title":"어느 청동기 마을 유적 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_challenge#9','soc',5,2,'u1','L03','g5_2_soc_u1_L03_challenge','lesson_challenge','SO5-2-u1-C5',4,'mc','auto','청동기 시대 사람들의 생활을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X09','SO5-2-u1-X04','SO5-2-u1-X15']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C5","difficulty":4,"kind":"mc","stem":"청동기 시대 사람들의 생활을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"벼농사로 곡식이 남자 빈부의 차이와 지배자가 생겼고, 귀한 청동기는 지배자가, 늘 쓰는 도구는 돌로 썼다","correct":true},{"t":"모두 청동 농기구를 쓰며 똑같이 나누어 살았다","mis":"SO5-2-u1-X09"},{"t":"먹을 것을 찾아 옮겨 다니며 뗀석기를 썼다","mis":"SO5-2-u1-X04"},{"t":"철로 만든 무기로 삼국을 세웠다","mis":"SO5-2-u1-X15"}],"explanation":["벼농사로 곡식이 남았어요.","지배자가 생겼어요.","청동은 지배자, 돌은 늘 쓰는 도구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L03_challenge#10','soc',5,2,'u1','L03','g5_2_soc_u1_L03_challenge','lesson_challenge','SO5-2-u1-C6',4,'essay','teacher','고인돌 유적 안내판을 보고, 고인돌로 짐작할 수 있는 청동기 시대 사회의 모습을 덮개돌의 무게와 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C6","difficulty":4,"kind":"essay","stem":"고인돌 유적 안내판을 보고, 고인돌로 짐작할 수 있는 청동기 시대 사회의 모습을 덮개돌의 무게와 이어 쓰세요.","answer_guide":{"answer":"예: 덮개돌 하나가 수십 톤이나 되어 옮기려면 아주 많은 사람이 힘을 모아야 했을 것이다. 그렇게 많은 사람을 모아 일을 시킬 수 있었다는 것은 재산과 힘을 가진 지배자가 있었다는 뜻이다. 그래서 청동기 시대에는 빈부의 차이가 있고 지배자가 마을을 다스렸다고 짐작할 수 있다.","scoring_points":["덮개돌의 무게와 많은 사람을 이었는가","지배자가 있었다고 짐작했는가","빈부의 차이나 다스림을 썼는가"]},"explanation":["덮개돌이 아주 무거워요.","많은 사람이 필요해요.","사람을 모은 지배자가 있었어요."],"asset":{"type":"passage","lines":["큰 받침돌 위에 집채만 한 덮개돌이 얹혀 있다.","덮개돌 하나의 무게가 수십 톤에 이른다고 한다.","둘레에 이런 무덤이 수백 기나 모여 있다.","근처에 돌을 떠낸 채석장 흔적도 남아 있다."],"title":"고인돌 유적 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_basic#1','soc',5,2,'u1','L04','g5_2_soc_u1_L04_basic','lesson_basic','SO5-2-u1-C7',1,'mc','auto','우리 역사에서 처음으로 세워진 나라는 어느 것인가요?',ARRAY['SO5-2-u1-X15','SO5-2-u1-X30','SO5-2-u1-X27']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C7","difficulty":1,"kind":"mc","stem":"우리 역사에서 처음으로 세워진 나라는 어느 것인가요?","options":[{"t":"고조선","correct":true},{"t":"고구려","mis":"SO5-2-u1-X15"},{"t":"고려","mis":"SO5-2-u1-X30"},{"t":"발해","mis":"SO5-2-u1-X27"}],"explanation":["청동기 문화를 바탕으로 세워졌어요.","단군왕검이 세웠어요.","고조선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_basic#2','soc',5,2,'u1','L04','g5_2_soc_u1_L04_basic','lesson_basic','SO5-2-u1-C7',1,'sa','auto','고조선을 세운 사람은 누구인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u1-C7","difficulty":1,"kind":"sa","stem":"고조선을 세운 사람은 누구인가요? 네 글자로 쓰세요.","answer":["단군왕검"],"explanation":["환웅의 아들이에요.","건국 이야기에 나와요.","단군왕검이에요."],"mis":"SO5-2-u1-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_basic#3','soc',5,2,'u1','L04','g5_2_soc_u1_L04_basic','lesson_basic','SO5-2-u1-C8',1,'mc','auto','고조선을 대표하는 유물로, 칼날 아래가 악기 비파처럼 둥근 검은 어느 것인가요?',ARRAY['SO5-2-u1-X08','SO5-2-u1-X16']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C8","difficulty":1,"kind":"mc","stem":"고조선을 대표하는 유물로, 칼날 아래가 악기 비파처럼 둥근 검은 어느 것인가요?","options":[{"t":"비파형 동검","correct":true},{"t":"주먹 도끼","mis":"SO5-2-u1-X08"},{"t":"반달 돌칼","mis":"SO5-2-u1-X08"},{"t":"칠지도","mis":"SO5-2-u1-X16"}],"explanation":["청동으로 만든 검이에요.","모양이 비파를 닮았어요.","비파형 동검이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_basic#4','soc',5,2,'u1','L04','g5_2_soc_u1_L04_basic','lesson_basic','SO5-2-u1-C8',1,'ox','auto','고조선은 사회 질서를 지키려고 8조법을 만들었어요.',ARRAY['SO5-2-u1-X13']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C8","difficulty":1,"kind":"ox","stem":"고조선은 사회 질서를 지키려고 8조법을 만들었어요.","answer":"O","reason_options":[{"t":"사람들이 지켜야 할 규칙을 정해 사회를 다스렸기 때문에","correct":true},{"t":"고조선에는 아무 규칙도 없었기 때문에","mis":"SO5-2-u1-X13"}],"mis":"SO5-2-u1-X13","explanation":["여덟 조항이 있었대요.","지금은 세 조항이 전해요.","질서를 지키려고 만들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_basic#5','soc',5,2,'u1','L04','g5_2_soc_u1_L04_basic','lesson_basic','SO5-2-u1-C7',2,'mc','auto','고조선의 건국 이야기에서 환웅이 바람·비·구름을 다스리는 신하를 데려왔다는 것으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X12','SO5-2-u1-X15']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C7","difficulty":2,"kind":"mc","stem":"고조선의 건국 이야기에서 환웅이 바람·비·구름을 다스리는 신하를 데려왔다는 것으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"농사를 중요하게 여겼고 앞선 농사 기술을 가졌다","correct":true},{"t":"바다에서 물고기만 잡았다","mis":"SO5-2-u1-X12"},{"t":"날씨와 아무 관계없이 살았다","mis":"SO5-2-u1-X12"},{"t":"철로 만든 무기를 썼다","mis":"SO5-2-u1-X15"}],"explanation":["바람·비·구름은 날씨예요.","날씨는 농사에 중요해요.","농사를 중히 여겼어요."],"asset":{"type":"passage","lines":["① 하늘의 자손 환웅이 무리를 이끌고 땅으로 내려왔다.","② 바람·비·구름을 다스리는 신하들을 데려왔다.","③ 곰과 호랑이가 사람이 되게 해 달라고 빌었다.","④ 쑥과 마늘을 먹고 견딘 곰만 여인이 되었다.","⑤ 환웅과 그 여인 사이에서 단군왕검이 태어나 나라를 세웠다."],"title":"고조선 건국 이야기 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_basic#6','soc',5,2,'u1','L04','g5_2_soc_u1_L04_basic','lesson_basic','SO5-2-u1-C7',2,'mc','auto','고조선 건국 이야기에서 곰과 호랑이가 나오는 까닭을 짐작한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X12']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C7","difficulty":2,"kind":"mc","stem":"고조선 건국 이야기에서 곰과 호랑이가 나오는 까닭을 짐작한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"곰과 호랑이를 받드는 부족이 있었고 곰을 받드는 부족이 환웅 부족과 힘을 합쳤다","correct":true},{"t":"곰이 정말로 사람이 되었다","mis":"SO5-2-u1-X12"},{"t":"이야기는 다 거짓이라 뜻이 없다","mis":"SO5-2-u1-X12"},{"t":"고조선 사람들은 동물을 기르지 않았다","mis":"SO5-2-u1-X12"}],"explanation":["동물은 부족을 나타내요.","곰 부족이 힘을 합쳤어요.","이야기 속 뜻을 읽어요."],"asset":{"type":"passage","lines":["① 하늘의 자손 환웅이 무리를 이끌고 땅으로 내려왔다.","② 바람·비·구름을 다스리는 신하들을 데려왔다.","③ 곰과 호랑이가 사람이 되게 해 달라고 빌었다.","④ 쑥과 마늘을 먹고 견딘 곰만 여인이 되었다.","⑤ 환웅과 그 여인 사이에서 단군왕검이 태어나 나라를 세웠다."],"title":"고조선 건국 이야기 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_basic#7','soc',5,2,'u1','L04','g5_2_soc_u1_L04_basic','lesson_basic','SO5-2-u1-C8',2,'mc','auto','전해 오는 8조법 ㄴ 조항으로 짐작할 수 있는 고조선 사회의 모습은 어느 것인가요?',ARRAY['SO5-2-u1-X13','SO5-2-u1-X15']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C8","difficulty":2,"kind":"mc","stem":"전해 오는 8조법 ㄴ 조항으로 짐작할 수 있는 고조선 사회의 모습은 어느 것인가요?","options":[{"t":"농사를 지어 곡식을 귀하게 여겼다","correct":true},{"t":"곡식이 전혀 없었다","mis":"SO5-2-u1-X13"},{"t":"다쳐도 아무 벌이 없었다","mis":"SO5-2-u1-X13"},{"t":"철기로 농사를 지었다","mis":"SO5-2-u1-X15"}],"explanation":["곡식으로 갚게 했어요.","곡식이 값어치가 있었어요.","농사를 지었어요."],"asset":{"type":"passage","lines":["ㄱ — 사람을 죽인 사람은 사형에 처한다.","ㄴ — 남을 다치게 한 사람은 곡식으로 갚는다.","ㄷ — 남의 물건을 훔친 사람은 노비로 삼는다.","ㄷ의 덧붙임 — 벌을 면하려면 돈을 내야 한다."],"title":"전해 오는 8조법의 세 조항"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_basic#8','soc',5,2,'u1','L04','g5_2_soc_u1_L04_basic','lesson_basic','SO5-2-u1-C8',2,'mc','auto','고조선의 문화 범위를 짐작할 때 살펴보는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X14']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C8","difficulty":2,"kind":"mc","stem":"고조선의 문화 범위를 짐작할 때 살펴보는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"비파형 동검과 탁자식 고인돌이 발견된 곳","correct":true},{"t":"고조선 사람들이 남긴 국경 기록","mis":"SO5-2-u1-X14"},{"t":"오늘날 도시의 크기","mis":"SO5-2-u1-X14"},{"t":"고려 사람들이 그린 지도","mis":"SO5-2-u1-X14"}],"explanation":["국경 기록은 없어요.","대표 유물·유적을 찾아요.","발견된 곳을 이어 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_basic#9','soc',5,2,'u1','L04','g5_2_soc_u1_L04_basic','lesson_basic','SO5-2-u1-C7',2,'ox','auto','고조선의 건국 이야기는 고려의 승려 일연이 쓴 「삼국유사」에 전해져요.',ARRAY['SO5-2-u1-X02']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C7","difficulty":2,"kind":"ox","stem":"고조선의 건국 이야기는 고려의 승려 일연이 쓴 「삼국유사」에 전해져요.","answer":"O","reason_options":[{"t":"오래 전해 오던 이야기가 고려 때 쓴 역사책에 실렸기 때문에","correct":true},{"t":"고조선 사람들이 직접 쓴 일기에 남았기 때문에","mis":"SO5-2-u1-X02"}],"mis":"SO5-2-u1-X02","explanation":["이야기는 오래 전해 왔어요.","고려 때 책에 실렸어요.","「삼국유사」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_basic#10','soc',5,2,'u1','L04','g5_2_soc_u1_L04_basic','lesson_basic','SO5-2-u1-C8',3,'error','auto','8조법을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X13']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C8","difficulty":3,"kind":"error","stem":"8조법을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「고조선에는 노비가 없고 모두 평등했어.」","correct":true,"mis_target":"SO5-2-u1-X13"},{"t":"하은 — 「사람을 죽이면 사형이니 생명을 귀하게 여겼어.」","mis":"SO5-2-u1-X13"},{"t":"재민 — 「돈을 내면 벌을 면했으니 화폐를 썼다고 짐작해.」","mis":"SO5-2-u1-X13"}],"explanation":["훔치면 노비로 삼았어요.","노비가 있는 신분 사회였어요.","태윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_challenge#1','soc',5,2,'u1','L04','g5_2_soc_u1_L04_challenge','lesson_challenge','SO5-2-u1-C8',2,'match','auto','전해 오는 8조법의 조항과 짐작할 수 있는 고조선 사회의 모습을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C8","difficulty":2,"kind":"match","stem":"전해 오는 8조법의 조항과 짐작할 수 있는 고조선 사회의 모습을 이으세요.","pairs":[{"l":"ㄱ 사형","r":"생명을 귀하게 여김"},{"l":"ㄴ 곡식으로 갚음","r":"농사짓고 곡식이 귀함"},{"l":"ㄷ 노비로 삼음","r":"신분 차이가 있음"},{"l":"ㄷ의 덧붙임 돈","r":"화폐를 씀"}],"mis":"SO5-2-u1-X13","explanation":["생명과 재산을 지켰어요.","노비가 있었어요.","화폐도 썼어요."],"asset":{"type":"passage","lines":["ㄱ — 사람을 죽인 사람은 사형에 처한다.","ㄴ — 남을 다치게 한 사람은 곡식으로 갚는다.","ㄷ — 남의 물건을 훔친 사람은 노비로 삼는다.","ㄷ의 덧붙임 — 벌을 면하려면 돈을 내야 한다."],"title":"전해 오는 8조법의 세 조항"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_challenge#2','soc',5,2,'u1','L04','g5_2_soc_u1_L04_challenge','lesson_challenge','SO5-2-u1-C7',2,'mc','auto','고조선이 세워진 바탕이 된 문화는 어느 것인가요?',ARRAY['SO5-2-u1-X15','SO5-2-u1-X08','SO5-2-u1-X21']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C7","difficulty":2,"kind":"mc","stem":"고조선이 세워진 바탕이 된 문화는 어느 것인가요?","options":[{"t":"청동기 문화","correct":true},{"t":"철기 문화","mis":"SO5-2-u1-X15"},{"t":"구석기 문화","mis":"SO5-2-u1-X08"},{"t":"불교문화","mis":"SO5-2-u1-X21"}],"explanation":["고인돌과 비파형 동검이 나와요.","모두 청동기 시대 것이에요.","청동기 문화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_challenge#3','soc',5,2,'u1','L04','g5_2_soc_u1_L04_challenge','lesson_challenge','SO5-2-u1-C8',3,'mc','auto','고조선 문화 범위 탐구 메모로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X14','SO5-2-u1-X26']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C8","difficulty":3,"kind":"mc","stem":"고조선 문화 범위 탐구 메모로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"고조선의 문화는 한반도 남부 일부까지 넓게 퍼졌다고 짐작한다","correct":true},{"t":"고조선의 국경이 정확히 기록되어 있다","mis":"SO5-2-u1-X14"},{"t":"고조선은 한반도 남쪽 끝에만 있었다","mis":"SO5-2-u1-X14"},{"t":"비파형 동검은 고려 때 유물이다","mis":"SO5-2-u1-X26"}],"explanation":["두 유물·유적이 넓게 나와요.","국경 기록은 없어요.","문화 범위를 짐작해요."],"asset":{"type":"passage","lines":["비파형 동검 — 칼날 아래가 악기 비파처럼 둥글다.","탁자식 고인돌 — 받침돌 위에 넓은 덮개돌이 탁자처럼 놓였다.","두 가지가 나온 곳 — 중국 동북쪽, 한반도 북부, 한반도 남부 일부","고조선의 국경을 적은 기록은 남아 있지 않다."],"title":"고조선 문화 범위 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_challenge#4','soc',5,2,'u1','L04','g5_2_soc_u1_L04_challenge','lesson_challenge','SO5-2-u1-C7',3,'mc','auto','고조선 건국 이야기 줄거리 ①~⑤에서 「여러 부족이 힘을 합쳐 나라를 세웠다」는 뜻을 가장 잘 보여 주는 부분은 어느 것인가요?',ARRAY['SO5-2-u1-X12']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C7","difficulty":3,"kind":"mc","stem":"고조선 건국 이야기 줄거리 ①~⑤에서 「여러 부족이 힘을 합쳐 나라를 세웠다」는 뜻을 가장 잘 보여 주는 부분은 어느 것인가요?","options":[{"t":"⑤","correct":true},{"t":"①","mis":"SO5-2-u1-X12"},{"t":"②","mis":"SO5-2-u1-X12"},{"t":"③","mis":"SO5-2-u1-X12"}],"explanation":["①은 환웅 무리가 온 것이에요.","③은 곰과 호랑이가 빈 것이에요.","⑤에서 두 무리가 하나가 돼요."],"asset":{"type":"passage","lines":["① 하늘의 자손 환웅이 무리를 이끌고 땅으로 내려왔다.","② 바람·비·구름을 다스리는 신하들을 데려왔다.","③ 곰과 호랑이가 사람이 되게 해 달라고 빌었다.","④ 쑥과 마늘을 먹고 견딘 곰만 여인이 되었다.","⑤ 환웅과 그 여인 사이에서 단군왕검이 태어나 나라를 세웠다."],"title":"고조선 건국 이야기 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_challenge#5','soc',5,2,'u1','L04','g5_2_soc_u1_L04_challenge','lesson_challenge','SO5-2-u1-C8',3,'ox','auto','고조선의 문화 범위를 나타낸 지도는 오늘날 연구로 짐작한 것이어서 새 유물이 나오면 바뀔 수 있어요.',ARRAY['SO5-2-u1-X14']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C8","difficulty":3,"kind":"ox","stem":"고조선의 문화 범위를 나타낸 지도는 오늘날 연구로 짐작한 것이어서 새 유물이 나오면 바뀔 수 있어요.","answer":"O","reason_options":[{"t":"영토 기록이 없어 대표 유물·유적이 나온 곳을 이어 짐작한 것이기 때문에","correct":true},{"t":"고조선 사람들이 직접 그린 지도를 그대로 옮긴 것이기 때문에","mis":"SO5-2-u1-X14"}],"mis":"SO5-2-u1-X14","explanation":["국경 기록이 없어요.","유물로 짐작해요.","연구가 이어지고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_challenge#6','soc',5,2,'u1','L04','g5_2_soc_u1_L04_challenge','lesson_challenge','SO5-2-u1-C7',3,'error','auto','고조선 건국 이야기를 두고 친구들이 말했어요. 가장 알맞지 않게 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X12']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C7","difficulty":3,"kind":"error","stem":"고조선 건국 이야기를 두고 친구들이 말했어요. 가장 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"윤재 — 「곰이 사람이 되는 건 말이 안 되니까 이 이야기에선 알 게 없어.」","correct":true,"mis_target":"SO5-2-u1-X12"},{"t":"수아 — 「바람·비·구름을 다스리는 신하가 나오니 농사가 중요했나 봐.」","mis":"SO5-2-u1-X12"},{"t":"건우 — 「곰을 받드는 부족이 힘을 합쳤다고 짐작해.」","mis":"SO5-2-u1-X12"}],"explanation":["이야기에도 뜻이 담겨 있어요.","그 뜻을 읽어 짐작해요.","윤재의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_challenge#7','soc',5,2,'u1','L04','g5_2_soc_u1_L04_challenge','lesson_challenge','SO5-2-u1-C8',3,'mc','auto','강화 부근리 고인돌처럼 탁자식 고인돌이 고조선과 관련된 유적으로 여겨지는 까닭은 어느 것인가요?',ARRAY['SO5-2-u1-X02','SO5-2-u1-X26','SO5-2-u1-X15']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C8","difficulty":3,"kind":"mc","stem":"강화 부근리 고인돌처럼 탁자식 고인돌이 고조선과 관련된 유적으로 여겨지는 까닭은 어느 것인가요?","options":[{"t":"비파형 동검과 함께 고조선 문화가 퍼진 곳에서 많이 발견되기 때문에","correct":true},{"t":"고조선 사람들이 고인돌에 나라 이름을 새겼기 때문에","mis":"SO5-2-u1-X02"},{"t":"고려 때 새로 만든 무덤이기 때문에","mis":"SO5-2-u1-X26"},{"t":"철기 문화를 보여 주기 때문에","mis":"SO5-2-u1-X15"}],"explanation":["탁자 모양 고인돌이에요.","고조선 문화 범위에서 많이 나와요.","대표 유적으로 여겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_challenge#8','soc',5,2,'u1','L04','g5_2_soc_u1_L04_challenge','lesson_challenge','SO5-2-u1-C8',4,'mc','auto','전해 오는 8조법의 세 조항을 함께 볼 때 고조선 사회를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X13','SO5-2-u1-X15']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C8","difficulty":4,"kind":"mc","stem":"전해 오는 8조법의 세 조항을 함께 볼 때 고조선 사회를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"생명과 재산을 중히 여기고, 노비가 있는 신분 사회였으며, 화폐를 썼다","correct":true},{"t":"재산이 없어 모두 똑같이 살았다","mis":"SO5-2-u1-X13"},{"t":"법이 없어 다툼이 생기면 그냥 두었다","mis":"SO5-2-u1-X13"},{"t":"철로 만든 농기구로 농사를 지었다","mis":"SO5-2-u1-X15"}],"explanation":["사형·곡식·노비·돈이 나와요.","생명과 재산을 지켰어요.","신분과 화폐가 있었어요."],"asset":{"type":"passage","lines":["ㄱ — 사람을 죽인 사람은 사형에 처한다.","ㄴ — 남을 다치게 한 사람은 곡식으로 갚는다.","ㄷ — 남의 물건을 훔친 사람은 노비로 삼는다.","ㄷ의 덧붙임 — 벌을 면하려면 돈을 내야 한다."],"title":"전해 오는 8조법의 세 조항"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_challenge#9','soc',5,2,'u1','L04','g5_2_soc_u1_L04_challenge','lesson_challenge','SO5-2-u1-C7',4,'mc','auto','청동기 시대에서 고조선으로 이어지는 흐름을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X04','SO5-2-u1-X15','SO5-2-u1-X10']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C7","difficulty":4,"kind":"mc","stem":"청동기 시대에서 고조선으로 이어지는 흐름을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"지배자가 이끄는 부족들이 힘을 합치거나 정복되며 하나로 모여 첫 나라가 세워졌다","correct":true},{"t":"먹을 것을 찾아 옮겨 다니던 무리가 곧바로 나라를 세웠다","mis":"SO5-2-u1-X04"},{"t":"철기를 쓰는 삼국이 힘을 합쳐 고조선을 세웠다","mis":"SO5-2-u1-X15"},{"t":"부족들이 모두 흩어져 나라가 사라졌다","mis":"SO5-2-u1-X10"}],"explanation":["청동기 시대에 지배자가 생겼어요.","부족들이 모였어요.","고조선이 세워졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L04_challenge#10','soc',5,2,'u1','L04','g5_2_soc_u1_L04_challenge','lesson_challenge','SO5-2-u1-C8',4,'essay','teacher','고조선 문화 범위 탐구 메모를 보고, 기록이 없는데도 고조선의 문화 범위를 짐작할 수 있는 까닭과 그렇게 짐작한 범위를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C8","difficulty":4,"kind":"essay","stem":"고조선 문화 범위 탐구 메모를 보고, 기록이 없는데도 고조선의 문화 범위를 짐작할 수 있는 까닭과 그렇게 짐작한 범위를 쓰세요.","answer_guide":{"answer":"예: 고조선의 국경을 적은 기록은 없지만 고조선을 대표하는 비파형 동검과 탁자식 고인돌이 나온 곳을 이어 보면 문화가 퍼진 범위를 짐작할 수 있다. 두 가지가 중국 동북쪽과 한반도 북부, 한반도 남부 일부에서 나와 고조선의 문화가 이 넓은 지역에 퍼졌다고 짐작한다.","scoring_points":["기록 대신 대표 유물·유적을 쓴다고 썼는가","비파형 동검과 탁자식 고인돌을 들었는가","짐작한 범위를 썼는가"]},"explanation":["기록은 없어요.","대표 유물·유적을 봐요.","나온 곳을 이어 짐작해요."],"asset":{"type":"passage","lines":["비파형 동검 — 칼날 아래가 악기 비파처럼 둥글다.","탁자식 고인돌 — 받침돌 위에 넓은 덮개돌이 탁자처럼 놓였다.","두 가지가 나온 곳 — 중국 동북쪽, 한반도 북부, 한반도 남부 일부","고조선의 국경을 적은 기록은 남아 있지 않다."],"title":"고조선 문화 범위 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_basic#1','soc',5,2,'u1','L05','g5_2_soc_u1_L05_basic','lesson_basic','SO5-2-u1-C9',1,'mc','auto','고조선이 무너질 무렵 여러 나라가 세워지는 바탕이 된 문화는 어느 것인가요?',ARRAY['SO5-2-u1-X15','SO5-2-u1-X08']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C9","difficulty":1,"kind":"mc","stem":"고조선이 무너질 무렵 여러 나라가 세워지는 바탕이 된 문화는 어느 것인가요?","options":[{"t":"철기 문화","correct":true},{"t":"청동기 문화","mis":"SO5-2-u1-X15"},{"t":"구석기 문화","mis":"SO5-2-u1-X08"},{"t":"신석기 문화","mis":"SO5-2-u1-X08"}],"explanation":["철로 농기구와 무기를 만들었어요.","농사와 전쟁에 힘이 됐어요.","철기 문화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_basic#2','soc',5,2,'u1','L05','g5_2_soc_u1_L05_basic','lesson_basic','SO5-2-u1-C9',1,'mc','auto','고구려·백제·신라를 함께 부르는 말은 어느 것인가요?',ARRAY['SO5-2-u1-X29','SO5-2-u1-X18','SO5-2-u1-X15']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C9","difficulty":1,"kind":"mc","stem":"고구려·백제·신라를 함께 부르는 말은 어느 것인가요?","options":[{"t":"삼국","correct":true},{"t":"후삼국","mis":"SO5-2-u1-X29"},{"t":"가야 연맹","mis":"SO5-2-u1-X18"},{"t":"고조선","mis":"SO5-2-u1-X15"}],"explanation":["세 나라예요.","왕을 중심으로 커 갔어요.","삼국이라 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_basic#3','soc',5,2,'u1','L05','g5_2_soc_u1_L05_basic','lesson_basic','SO5-2-u1-C9',1,'sa','auto','낙동강 가의 여러 나라가 모여 이룬 연맹을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u1-C9","difficulty":1,"kind":"sa","stem":"낙동강 가의 여러 나라가 모여 이룬 연맹을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["가야"],"explanation":["낙동강 가에 있었어요.","여러 나라가 모였어요.","가야예요."],"mis":"SO5-2-u1-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_basic#4','soc',5,2,'u1','L05','g5_2_soc_u1_L05_basic','lesson_basic','SO5-2-u1-C10',1,'ox','auto','신라는 진흥왕 때 화랑으로 인재를 기르고 한강 유역을 차지했어요.',ARRAY['SO5-2-u1-X16']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C10","difficulty":1,"kind":"ox","stem":"신라는 진흥왕 때 화랑으로 인재를 기르고 한강 유역을 차지했어요.","answer":"O","reason_options":[{"t":"진흥왕이 인재를 길러 영토를 넓히고 한강 유역을 차지했기 때문에","correct":true},{"t":"화랑은 백제 근초고왕이 만든 무리이기 때문에","mis":"SO5-2-u1-X16"}],"mis":"SO5-2-u1-X16","explanation":["진흥왕은 신라의 왕이에요.","화랑으로 인재를 길렀어요.","한강 유역을 차지했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_basic#5','soc',5,2,'u1','L05','g5_2_soc_u1_L05_basic','lesson_basic','SO5-2-u1-C10',2,'mc','auto','삼국을 크게 키운 왕 카드 ㉯는 어느 왕의 업적인가요?',ARRAY['SO5-2-u1-X16']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C10","difficulty":2,"kind":"mc","stem":"삼국을 크게 키운 왕 카드 ㉯는 어느 왕의 업적인가요?","options":[{"t":"장수왕","correct":true},{"t":"광개토대왕","mis":"SO5-2-u1-X16"},{"t":"근초고왕","mis":"SO5-2-u1-X16"},{"t":"진흥왕","mis":"SO5-2-u1-X16"}],"explanation":["수도를 평양으로 옮겼어요.","한강 유역을 모두 차지했어요.","고구려 장수왕이에요."],"asset":{"type":"passage","lines":["㉮ 북쪽으로 영토를 크게 넓혔고, 그 업적이 큰 비석에 새겨졌다.","㉯ 수도를 평양으로 옮기고 한강 유역을 모두 차지했다.","㉰ 남북으로 영토를 넓히고 왜에 칼을 보내며 교류했다.","㉱ 화랑으로 인재를 기르고 한강 유역을 차지했다."],"title":"삼국을 크게 키운 왕 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_basic#6','soc',5,2,'u1','L05','g5_2_soc_u1_L05_basic','lesson_basic','SO5-2-u1-C10',2,'mc','auto','삼국을 크게 키운 왕 카드 ㉰의 왕이 다스린 나라는 어느 것인가요?',ARRAY['SO5-2-u1-X16','SO5-2-u1-X18']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C10","difficulty":2,"kind":"mc","stem":"삼국을 크게 키운 왕 카드 ㉰의 왕이 다스린 나라는 어느 것인가요?","options":[{"t":"백제","correct":true},{"t":"고구려","mis":"SO5-2-u1-X16"},{"t":"신라","mis":"SO5-2-u1-X16"},{"t":"가야","mis":"SO5-2-u1-X18"}],"explanation":["왜에 칼을 보냈어요.","칠지도가 그 흔적이에요.","백제 근초고왕이에요."],"asset":{"type":"passage","lines":["㉮ 북쪽으로 영토를 크게 넓혔고, 그 업적이 큰 비석에 새겨졌다.","㉯ 수도를 평양으로 옮기고 한강 유역을 모두 차지했다.","㉰ 남북으로 영토를 넓히고 왜에 칼을 보내며 교류했다.","㉱ 화랑으로 인재를 기르고 한강 유역을 차지했다."],"title":"삼국을 크게 키운 왕 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_basic#7','soc',5,2,'u1','L05','g5_2_soc_u1_L05_basic','lesson_basic','SO5-2-u1-C10',2,'mc','auto','한강 유역 탐구 메모로 보아 삼국이 한강 유역을 차지하려 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X17']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C10","difficulty":2,"kind":"mc","stem":"한강 유역 탐구 메모로 보아 삼국이 한강 유역을 차지하려 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"넓은 평야로 농사짓기 좋고 서해로 나가 중국과 바로 오갈 수 있어서","correct":true},{"t":"땅이 좁아 지키기 쉬워서","mis":"SO5-2-u1-X17"},{"t":"높은 산이 많아 숨기 좋아서","mis":"SO5-2-u1-X17"},{"t":"철이 전혀 나지 않아서","mis":"SO5-2-u1-X17"}],"explanation":["넓은 평야가 있어요.","서해로 나갈 수 있어요.","농사와 교류에 좋았어요."],"asset":{"type":"passage","lines":["한강 둘레에는 넓은 평야가 있어 농사짓기 좋다.","강을 따라 내려가면 서해로 나갈 수 있다.","서해를 건너면 중국과 바로 오갈 수 있다.","삼국은 이곳을 두고 번갈아 다투었다."],"title":"한강 유역 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_basic#8','soc',5,2,'u1','L05','g5_2_soc_u1_L05_basic','lesson_basic','SO5-2-u1-C9',2,'mc','auto','가야 안내판으로 보아 가야에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X18','SO5-2-u1-X15']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C9","difficulty":2,"kind":"mc","stem":"가야 안내판으로 보아 가야에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"여러 작은 나라가 모인 연맹으로, 끝내 신라에 합쳐졌다","correct":true},{"t":"하나의 큰 왕국으로 고구려에 합쳐졌다","mis":"SO5-2-u1-X18"},{"t":"삼국 가운데 하나로 한강 유역을 차지했다","mis":"SO5-2-u1-X18"},{"t":"청동기 문화를 바탕으로 처음 세워진 나라다","mis":"SO5-2-u1-X15"}],"explanation":["여러 나라가 모였어요.","금관가야, 대가야가 이끌었어요.","신라에 합쳐졌어요."],"asset":{"type":"passage","lines":["낙동강 가의 여러 작은 나라가 모여 하나의 무리를 이루었다.","처음엔 김해의 금관가야가, 나중엔 고령의 대가야가 이끌었다.","백제와 신라 사이에서 눌리다가 끝내 신라에 합쳐졌다."],"title":"가야 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_basic#9','soc',5,2,'u1','L05','g5_2_soc_u1_L05_basic','lesson_basic','SO5-2-u1-C9',2,'ox','auto','주몽·박혁거세·김수로가 알에서 태어났다는 이야기는 나라를 세운 사람이 특별하다는 것을 알리려는 뜻을 담고 있어요.',ARRAY['SO5-2-u1-X12']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C9","difficulty":2,"kind":"ox","stem":"주몽·박혁거세·김수로가 알에서 태어났다는 이야기는 나라를 세운 사람이 특별하다는 것을 알리려는 뜻을 담고 있어요.","answer":"O","reason_options":[{"t":"건국 이야기는 세운 사람을 하늘이 내린 특별한 사람으로 그려 나라를 높이기 때문에","correct":true},{"t":"그때 사람들은 정말 알에서 태어났기 때문에","mis":"SO5-2-u1-X12"}],"mis":"SO5-2-u1-X12","explanation":["알은 특별한 탄생이에요.","세운 사람을 높여요.","이야기의 뜻을 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_basic#10','soc',5,2,'u1','L05','g5_2_soc_u1_L05_basic','lesson_basic','SO5-2-u1-C10',3,'error','auto','삼국의 발전을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X16']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C10","difficulty":3,"kind":"error","stem":"삼국의 발전을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「진흥왕은 수도를 평양으로 옮기고 한강 유역을 차지했어.」","correct":true,"mis_target":"SO5-2-u1-X16"},{"t":"채원 — 「광개토대왕은 북쪽으로 영토를 크게 넓혔어.」","mis":"SO5-2-u1-X16"},{"t":"지율 — 「근초고왕 때 백제는 중국·왜와 활발히 교류했어.」","mis":"SO5-2-u1-X16"}],"explanation":["평양으로 옮긴 왕은 장수왕이에요.","진흥왕은 신라의 왕이에요.","하준의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_challenge#1','soc',5,2,'u1','L05','g5_2_soc_u1_L05_challenge','lesson_challenge','SO5-2-u1-C10',2,'match','auto','삼국을 크게 키운 왕 카드와 나라를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C10","difficulty":2,"kind":"match","stem":"삼국을 크게 키운 왕 카드와 나라를 알맞게 이으세요.","pairs":[{"l":"㉮ 비석에 새겨진 업적","r":"고구려 광개토대왕"},{"l":"㉯ 평양으로 옮김","r":"고구려 장수왕"},{"l":"㉰ 왜에 칼을 보냄","r":"백제 근초고왕"},{"l":"㉱ 화랑으로 인재를 기름","r":"신라 진흥왕"}],"mis":"SO5-2-u1-X16","explanation":["㉮·㉯는 고구려예요.","㉰는 백제예요.","㉱는 신라예요."],"asset":{"type":"passage","lines":["㉮ 북쪽으로 영토를 크게 넓혔고, 그 업적이 큰 비석에 새겨졌다.","㉯ 수도를 평양으로 옮기고 한강 유역을 모두 차지했다.","㉰ 남북으로 영토를 넓히고 왜에 칼을 보내며 교류했다.","㉱ 화랑으로 인재를 기르고 한강 유역을 차지했다."],"title":"삼국을 크게 키운 왕 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_challenge#2','soc',5,2,'u1','L05','g5_2_soc_u1_L05_challenge','lesson_challenge','SO5-2-u1-C9',2,'mc','auto','삼국과 가야가 자라는 데 철기가 도움이 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X09','SO5-2-u1-X06','SO5-2-u1-X04']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C9","difficulty":2,"kind":"mc","stem":"삼국과 가야가 자라는 데 철기가 도움이 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"철로 만든 농기구로 농사가 늘고 철 무기로 세력을 넓힐 수 있어서","correct":true},{"t":"철은 귀해서 지배자의 장신구로만 썼기 때문에","mis":"SO5-2-u1-X09"},{"t":"철로 토기를 만들어 곡식을 보관했기 때문에","mis":"SO5-2-u1-X06"},{"t":"철을 쓰자 옮겨 다니게 되었기 때문에","mis":"SO5-2-u1-X04"}],"explanation":["농기구가 튼튼해졌어요.","무기도 강해졌어요.","나라가 커졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_challenge#3','soc',5,2,'u1','L05','g5_2_soc_u1_L05_challenge','lesson_challenge','SO5-2-u1-C10',3,'mc','auto','한강 유역을 차지한 나라가 바뀌어 온 흐름으로 보아 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X17','SO5-2-u1-X15']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C10","difficulty":3,"kind":"mc","stem":"한강 유역을 차지한 나라가 바뀌어 온 흐름으로 보아 알 수 있는 것은 어느 것인가요?","options":[{"t":"한강 유역을 차지한 나라가 그때 가장 크게 발전했다","correct":true},{"t":"한강 유역은 아무 나라도 원하지 않았다","mis":"SO5-2-u1-X17"},{"t":"한강 유역은 처음부터 끝까지 한 나라만 가졌다","mis":"SO5-2-u1-X17"},{"t":"한강 유역을 차지하면 철기를 버렸다","mis":"SO5-2-u1-X15"}],"explanation":["백제, 고구려, 신라 차례로 차지했어요.","차지할 때 크게 발전했어요.","그만큼 중요한 곳이었어요."],"asset":{"type":"passage","lines":["한강 둘레에는 넓은 평야가 있어 농사짓기 좋다.","강을 따라 내려가면 서해로 나갈 수 있다.","서해를 건너면 중국과 바로 오갈 수 있다.","삼국은 이곳을 두고 번갈아 다투었다."],"title":"한강 유역 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_challenge#4','soc',5,2,'u1','L05','g5_2_soc_u1_L05_challenge','lesson_challenge','SO5-2-u1-C10',3,'mc','auto','신라가 한강 유역을 차지한 뒤 달라진 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X16','SO5-2-u1-X18','SO5-2-u1-X15']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C10","difficulty":3,"kind":"mc","stem":"신라가 한강 유역을 차지한 뒤 달라진 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서해로 나가 중국과 바로 오갈 수 있게 되었다","correct":true},{"t":"수도를 평양으로 옮겼다","mis":"SO5-2-u1-X16"},{"t":"가야에 합쳐졌다","mis":"SO5-2-u1-X18"},{"t":"철기를 처음 쓰게 되었다","mis":"SO5-2-u1-X15"}],"explanation":["신라는 동남쪽 끝에 있었어요.","한강 유역은 서해와 닿아요.","중국과 바로 오갔어요."],"asset":{"type":"passage","lines":["한강 둘레에는 넓은 평야가 있어 농사짓기 좋다.","강을 따라 내려가면 서해로 나갈 수 있다.","서해를 건너면 중국과 바로 오갈 수 있다.","삼국은 이곳을 두고 번갈아 다투었다."],"title":"한강 유역 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_challenge#5','soc',5,2,'u1','L05','g5_2_soc_u1_L05_challenge','lesson_challenge','SO5-2-u1-C10',3,'ox','auto','먼 나라에서 만든 물건이 다른 나라 무덤에서 나오면 두 나라가 서로 오갔다고 짐작할 수 있어요.',ARRAY['SO5-2-u1-X42']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C10","difficulty":3,"kind":"ox","stem":"먼 나라에서 만든 물건이 다른 나라 무덤에서 나오면 두 나라가 서로 오갔다고 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"물건이 오갔다는 것은 사람과 나라가 교류했다는 증거가 되기 때문에","correct":true},{"t":"물건은 바람에 실려 저절로 옮겨 가기 때문에","mis":"SO5-2-u1-X42"}],"mis":"SO5-2-u1-X42","explanation":["만든 곳과 나온 곳이 달라요.","누군가 가져갔어요.","교류를 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_challenge#6','soc',5,2,'u1','L05','g5_2_soc_u1_L05_challenge','lesson_challenge','SO5-2-u1-C9',3,'error','auto','가야를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X18']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C9","difficulty":3,"kind":"error","stem":"가야를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수호 — 「가야는 고구려·백제와 함께 삼국을 이룬 큰 왕국이야.」","correct":true,"mis_target":"SO5-2-u1-X18"},{"t":"다인 — 「처음엔 금관가야가, 나중엔 대가야가 이끌었어.」","mis":"SO5-2-u1-X18"},{"t":"로운 — 「가야는 낙동강 가의 여러 나라가 모인 연맹이야.」","mis":"SO5-2-u1-X18"}],"explanation":["삼국은 고구려·백제·신라예요.","가야는 여러 나라의 연맹이에요.","수호의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_challenge#7','soc',5,2,'u1','L05','g5_2_soc_u1_L05_challenge','lesson_challenge','SO5-2-u1-C10',3,'mc','auto','서울 송파구 풍납동 토성에서 도로·우물 자리와 중국에서 온 그릇이 나온 것으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X42','SO5-2-u1-X25','SO5-2-u1-X26']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C10","difficulty":3,"kind":"mc","stem":"서울 송파구 풍납동 토성에서 도로·우물 자리와 중국에서 온 그릇이 나온 것으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"백제의 중심지에 많은 사람이 모여 살았고 중국과도 활발히 오갔다","correct":true},{"t":"그곳은 사람이 살지 않은 빈 땅이었다","mis":"SO5-2-u1-X42"},{"t":"백제는 다른 나라와 전혀 오가지 않았다","mis":"SO5-2-u1-X25"},{"t":"그곳은 고려의 수도였다","mis":"SO5-2-u1-X26"}],"explanation":["도로와 우물이 있어요.","사람이 많이 살았어요.","중국 물건은 교류의 증거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_challenge#8','soc',5,2,'u1','L05','g5_2_soc_u1_L05_challenge','lesson_challenge','SO5-2-u1-C10',4,'mc','auto','삼국과 가야의 발전 과정을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X15','SO5-2-u1-X18','SO5-2-u1-X42']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C10","difficulty":4,"kind":"mc","stem":"삼국과 가야의 발전 과정을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"철기 문화를 바탕으로 세워진 삼국과 가야는 서로 겨루고 교류하며 커 갔고, 한강 유역을 차지한 나라가 크게 발전했다","correct":true},{"t":"청동기 문화를 바탕으로 세워진 삼국은 다투지 않고 지냈다","mis":"SO5-2-u1-X15"},{"t":"가야가 삼국을 하나로 합쳤다","mis":"SO5-2-u1-X18"},{"t":"왕과 업적은 순서만 외우면 된다","mis":"SO5-2-u1-X42"}],"explanation":["철기가 바탕이에요.","겨루고 오갔어요.","한강 유역이 열쇠였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_challenge#9','soc',5,2,'u1','L05','g5_2_soc_u1_L05_challenge','lesson_challenge','SO5-2-u1-C9',4,'mc','auto','삼국을 크게 키운 왕 카드 ㉮의 비석처럼 왕의 업적을 크게 새겨 남긴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X12','SO5-2-u1-X17','SO5-2-u1-X04']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C9","difficulty":4,"kind":"mc","stem":"삼국을 크게 키운 왕 카드 ㉮의 비석처럼 왕의 업적을 크게 새겨 남긴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라와 왕의 힘이 크다는 것을 널리 알리고 자랑하려고","correct":true},{"t":"업적을 숨기려고","mis":"SO5-2-u1-X12"},{"t":"다른 나라에 땅을 넘겨주려고","mis":"SO5-2-u1-X17"},{"t":"옮겨 다닐 때 길을 찾으려고","mis":"SO5-2-u1-X04"}],"explanation":["업적을 크게 새겼어요.","모두가 보게 했어요.","나라의 힘을 알렸어요."],"asset":{"type":"passage","lines":["㉮ 북쪽으로 영토를 크게 넓혔고, 그 업적이 큰 비석에 새겨졌다.","㉯ 수도를 평양으로 옮기고 한강 유역을 모두 차지했다.","㉰ 남북으로 영토를 넓히고 왜에 칼을 보내며 교류했다.","㉱ 화랑으로 인재를 기르고 한강 유역을 차지했다."],"title":"삼국을 크게 키운 왕 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L05_challenge#10','soc',5,2,'u1','L05','g5_2_soc_u1_L05_challenge','lesson_challenge','SO5-2-u1-C10',4,'essay','teacher','한강 유역 탐구 메모를 보고, 삼국이 한강 유역을 두고 다툰 까닭을 두 가지 쓰고, 한강 유역을 차지한 신라에 어떤 변화가 있었는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C10","difficulty":4,"kind":"essay","stem":"한강 유역 탐구 메모를 보고, 삼국이 한강 유역을 두고 다툰 까닭을 두 가지 쓰고, 한강 유역을 차지한 신라에 어떤 변화가 있었는지 쓰세요.","answer_guide":{"answer":"예: 한강 둘레에는 넓은 평야가 있어 농사짓기 좋았고, 강을 따라 서해로 나가 중국과 바로 오갈 수 있었다. 그래서 삼국은 이곳을 차지하려고 다투었다. 신라는 한강 유역을 차지한 뒤 중국과 바로 오가며 크게 자랄 수 있었다.","scoring_points":["농사와 관련된 까닭을 썼는가","바다·교류와 관련된 까닭을 썼는가","신라의 변화를 썼는가"]},"explanation":["넓은 평야가 있어요.","서해로 나가요.","신라는 중국과 바로 오갔어요."],"asset":{"type":"passage","lines":["한강 둘레에는 넓은 평야가 있어 농사짓기 좋다.","강을 따라 내려가면 서해로 나갈 수 있다.","서해를 건너면 중국과 바로 오갈 수 있다.","삼국은 이곳을 두고 번갈아 다투었다."],"title":"한강 유역 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_basic#1','soc',5,2,'u1','L06','g5_2_soc_u1_L06_basic','lesson_basic','SO5-2-u1-C11',1,'mc','auto','삼국 시대의 신분을 바르게 묶은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X20']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C11","difficulty":1,"kind":"mc","stem":"삼국 시대의 신분을 바르게 묶은 것은 어느 것인가요?","options":[{"t":"귀족·평민·천민","correct":true},{"t":"양인·천인·호족","mis":"SO5-2-u1-X20"},{"t":"왕·지배자·부족","mis":"SO5-2-u1-X20"},{"t":"어른·어린이·노인","mis":"SO5-2-u1-X20"}],"explanation":["신분이 셋으로 나뉘었어요.","귀족이 가장 높았어요.","귀족·평민·천민이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_basic#2','soc',5,2,'u1','L06','g5_2_soc_u1_L06_basic','lesson_basic','SO5-2-u1-C11',1,'mc','auto','삼국 시대 귀족이 주로 입은 옷은 어느 것인가요?',ARRAY['SO5-2-u1-X19','SO5-2-u1-X08','SO5-2-u1-X39']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C11","difficulty":1,"kind":"mc","stem":"삼국 시대 귀족이 주로 입은 옷은 어느 것인가요?","options":[{"t":"화려한 비단옷","correct":true},{"t":"거친 삼베옷","mis":"SO5-2-u1-X19"},{"t":"짐승 가죽","mis":"SO5-2-u1-X08"},{"t":"목화솜으로 짠 무명옷","mis":"SO5-2-u1-X39"}],"explanation":["귀족은 부유했어요.","비단은 귀했어요.","비단옷을 입었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_basic#3','soc',5,2,'u1','L06','g5_2_soc_u1_L06_basic','lesson_basic','SO5-2-u1-C12',1,'sa','auto','가야에서 철을 납작하게 펴 만들어 화폐처럼 쓴 것을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u1-C12","difficulty":1,"kind":"sa","stem":"가야에서 철을 납작하게 펴 만들어 화폐처럼 쓴 것을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["덩이쇠"],"explanation":["철 덩어리예요.","화폐처럼 썼어요.","덩이쇠예요."],"mis":"SO5-2-u1-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_basic#4','soc',5,2,'u1','L06','g5_2_soc_u1_L06_basic','lesson_basic','SO5-2-u1-C12',1,'ox','auto','삼국은 백성의 마음을 하나로 모으려고 불교를 받아들였어요.',ARRAY['SO5-2-u1-X21']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C12","difficulty":1,"kind":"ox","stem":"삼국은 백성의 마음을 하나로 모으려고 불교를 받아들였어요.","answer":"O","reason_options":[{"t":"같은 믿음으로 마음을 모으고 왕의 힘을 키울 수 있었기 때문에","correct":true},{"t":"불교는 놀이를 즐기려고 받아들였기 때문에","mis":"SO5-2-u1-X21"}],"mis":"SO5-2-u1-X21","explanation":["여러 믿음이 있었어요.","불교로 마음을 모았어요.","왕의 힘이 커졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_basic#5','soc',5,2,'u1','L06','g5_2_soc_u1_L06_basic','lesson_basic','SO5-2-u1-C11',2,'mc','auto','고분 벽화 관찰 메모 ①·②에서 사람을 다르게 그린 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X20']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C11","difficulty":2,"kind":"mc","stem":"고분 벽화 관찰 메모 ①·②에서 사람을 다르게 그린 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"신분이 높은 사람을 크게, 낮은 사람을 작게 그렸기 때문에","correct":true},{"t":"가까운 사람을 크게 그렸기 때문에","mis":"SO5-2-u1-X20"},{"t":"어른은 크게, 어린이는 작게 그렸기 때문에","mis":"SO5-2-u1-X20"},{"t":"물감이 모자라서","mis":"SO5-2-u1-X20"}],"explanation":["구경하는 사람은 주인이에요.","시중드는 사람은 작아요.","신분 차이를 크기로 나타냈어요."],"asset":{"type":"passage","lines":["① 고구려 무덤 벽에 구경하는 사람이 아주 크게 그려져 있다.","② 그 앞의 재주꾼과 시중드는 사람은 아주 작게 그려져 있다.","③ 다른 벽에는 부엌에서 음식을 하는 사람과 고기를 건 창고가 있다."],"title":"고분 벽화 관찰 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_basic#6','soc',5,2,'u1','L06','g5_2_soc_u1_L06_basic','lesson_basic','SO5-2-u1-C11',2,'mc','auto','삼국 시대 세 사람의 생활 카드 가운데 평민의 생활은 어느 것인가요?',ARRAY['SO5-2-u1-X19']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C11","difficulty":2,"kind":"mc","stem":"삼국 시대 세 사람의 생활 카드 가운데 평민의 생활은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"SO5-2-u1-X19"},{"t":"다","mis":"SO5-2-u1-X19"},{"t":"가와 다","mis":"SO5-2-u1-X19"}],"explanation":["가는 귀족이에요.","다는 천민이에요.","나는 농사짓고 세금을 낸 평민이에요."],"asset":{"type":"passage","lines":["가 — 비단옷 · 쌀밥 · 기와집 · 많은 토지와 노비","나 — 삼베옷 · 보리·조로 지은 밥 · 초가집 · 농사짓고 세금을 냄","다 — 주인집 일을 함 · 대부분 노비"],"title":"삼국 시대 세 사람의 생활 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_basic#7','soc',5,2,'u1','L06','g5_2_soc_u1_L06_basic','lesson_basic','SO5-2-u1-C12',2,'mc','auto','가야가 철을 다루는 기술로 한 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X22','SO5-2-u1-X11','SO5-2-u1-X26']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C12","difficulty":2,"kind":"mc","stem":"가야가 철을 다루는 기술로 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"무기와 갑옷을 만들어 다른 나라에 팔았다","correct":true},{"t":"철을 모두 땅에 묻어 버렸다","mis":"SO5-2-u1-X22"},{"t":"철로 고인돌을 만들었다","mis":"SO5-2-u1-X11"},{"t":"철로 불국사를 지었다","mis":"SO5-2-u1-X26"}],"explanation":["가야에는 철이 많이 났어요.","기술이 뛰어났어요.","무기와 갑옷을 팔았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_basic#8','soc',5,2,'u1','L06','g5_2_soc_u1_L06_basic','lesson_basic','SO5-2-u1-C12',2,'mc','auto','삼국이 불교를 받아들인 뒤 많이 만들어진 것은 어느 것인가요?',ARRAY['SO5-2-u1-X11','SO5-2-u1-X14','SO5-2-u1-X26']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C12","difficulty":2,"kind":"mc","stem":"삼국이 불교를 받아들인 뒤 많이 만들어진 것은 어느 것인가요?","options":[{"t":"절과 탑, 불상","correct":true},{"t":"고인돌과 움집","mis":"SO5-2-u1-X11"},{"t":"비파형 동검","mis":"SO5-2-u1-X14"},{"t":"금속 활자","mis":"SO5-2-u1-X26"}],"explanation":["불교를 믿게 되었어요.","부처를 모실 곳이 필요했어요.","절·탑·불상이 많아졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_basic#9','soc',5,2,'u1','L06','g5_2_soc_u1_L06_basic','lesson_basic','SO5-2-u1-C11',2,'ox','auto','삼국 시대 평민은 주로 쌀밥을 먹고 기와집에서 살았어요.',ARRAY['SO5-2-u1-X19']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C11","difficulty":2,"kind":"ox","stem":"삼국 시대 평민은 주로 쌀밥을 먹고 기와집에서 살았어요.","answer":"X","reason_options":[{"t":"쌀과 기와집은 주로 지배층의 것이고 평민은 잡곡을 먹고 초가집에서 살았기 때문에","correct":true},{"t":"삼국 시대에는 신분과 상관없이 모두 같은 집에 살았기 때문에","mis":"SO5-2-u1-X19"}],"mis":"SO5-2-u1-X19","explanation":["쌀은 귀했어요.","평민은 보리·조를 먹었어요.","초가집에 살았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_basic#10','soc',5,2,'u1','L06','g5_2_soc_u1_L06_basic','lesson_basic','SO5-2-u1-C12',3,'error','auto','가야 무덤 출토품 메모를 보고 친구들이 짐작했어요. 알맞지 않게 짐작한 친구는 누구인가요?',ARRAY['SO5-2-u1-X22']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C12","difficulty":3,"kind":"error","stem":"가야 무덤 출토품 메모를 보고 친구들이 짐작했어요. 알맞지 않게 짐작한 친구는 누구인가요?","options":[{"t":"서아 — 「덩이쇠가 많은 걸 보니 가야에는 철이 거의 없었나 봐.」","correct":true,"mis_target":"SO5-2-u1-X22"},{"t":"이안 — 「집 모양 토기의 고양이는 곡식을 지키려고 길렀나 봐.」","mis":"SO5-2-u1-X22"},{"t":"하람 — 「말 탄 무사 토기를 보니 말을 타고 싸웠나 봐.」","mis":"SO5-2-u1-X22"}],"explanation":["덩이쇠는 철이에요.","철이 많았다는 뜻이에요.","서아의 짐작이 알맞지 않아요."],"asset":{"type":"passage","lines":["① 지붕 위에 고양이가, 사다리에 쥐 두 마리가 붙은 집 모양 토기","② 배 모양 토기","③ 말을 탄 무사 모양 토기","④ 철을 납작하게 펴 만든 덩이쇠가 무덤에 가득 쌓여 있다."],"title":"가야 무덤 출토품 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_challenge#1','soc',5,2,'u1','L06','g5_2_soc_u1_L06_challenge','lesson_challenge','SO5-2-u1-C11',2,'match','auto','삼국 시대 신분과 생활 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C11","difficulty":2,"kind":"match","stem":"삼국 시대 신분과 생활 모습을 알맞게 이으세요.","pairs":[{"l":"귀족","r":"토지·노비가 많고 나라의 중요한 일을 정함"},{"l":"평민","r":"농사짓고 세금을 냄"},{"l":"천민","r":"대부분 노비로 주인집 일을 함"}],"mis":"SO5-2-u1-X19","explanation":["귀족은 나라 일을 정했어요.","평민은 세금을 냈어요.","천민은 노비가 많았어요."],"asset":{"type":"passage","lines":["가 — 비단옷 · 쌀밥 · 기와집 · 많은 토지와 노비","나 — 삼베옷 · 보리·조로 지은 밥 · 초가집 · 농사짓고 세금을 냄","다 — 주인집 일을 함 · 대부분 노비"],"title":"삼국 시대 세 사람의 생활 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_challenge#2','soc',5,2,'u1','L06','g5_2_soc_u1_L06_challenge','lesson_challenge','SO5-2-u1-C12',2,'mc','auto','가야 무덤 출토품 메모 ①의 집 모양 토기로 짐작할 수 있는 가야 사람들의 생활은 어느 것인가요?',ARRAY['SO5-2-u1-X22']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C12","difficulty":2,"kind":"mc","stem":"가야 무덤 출토품 메모 ①의 집 모양 토기로 짐작할 수 있는 가야 사람들의 생활은 어느 것인가요?","options":[{"t":"집 안에 곡식을 두었고 쥐를 막으려고 고양이를 길렀다","correct":true},{"t":"사람들이 동굴에서만 살았다","mis":"SO5-2-u1-X22"},{"t":"쥐를 기르며 놀았다","mis":"SO5-2-u1-X22"},{"t":"집 없이 배에서만 살았다","mis":"SO5-2-u1-X22"}],"explanation":["지붕 위에 고양이가 있어요.","사다리에 쥐가 있어요.","곡식을 지키려 했어요."],"asset":{"type":"passage","lines":["① 지붕 위에 고양이가, 사다리에 쥐 두 마리가 붙은 집 모양 토기","② 배 모양 토기","③ 말을 탄 무사 모양 토기","④ 철을 납작하게 펴 만든 덩이쇠가 무덤에 가득 쌓여 있다."],"title":"가야 무덤 출토품 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_challenge#3','soc',5,2,'u1','L06','g5_2_soc_u1_L06_challenge','lesson_challenge','SO5-2-u1-C11',3,'mc','auto','고분 벽화 관찰 메모 ③으로 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X05','SO5-2-u1-X19','SO5-2-u1-X04']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C11","difficulty":3,"kind":"mc","stem":"고분 벽화 관찰 메모 ③으로 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"고구려 귀족의 집에는 부엌과 고기를 걸어 둔 창고가 있었다","correct":true},{"t":"고구려 사람들은 불을 쓰지 않았다","mis":"SO5-2-u1-X05"},{"t":"모든 백성이 고기를 마음껏 먹었다","mis":"SO5-2-u1-X19"},{"t":"고구려 사람들은 옮겨 다니며 살았다","mis":"SO5-2-u1-X04"}],"explanation":["부엌에서 음식을 해요.","고기를 건 창고가 있어요.","무덤 주인의 넉넉한 생활이에요."],"asset":{"type":"passage","lines":["① 고구려 무덤 벽에 구경하는 사람이 아주 크게 그려져 있다.","② 그 앞의 재주꾼과 시중드는 사람은 아주 작게 그려져 있다.","③ 다른 벽에는 부엌에서 음식을 하는 사람과 고기를 건 창고가 있다."],"title":"고분 벽화 관찰 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_challenge#4','soc',5,2,'u1','L06','g5_2_soc_u1_L06_challenge','lesson_challenge','SO5-2-u1-C11',3,'mc','auto','고구려 귀족이 돼지고기를 콩으로 만든 장에 절여 구운 맥적을 먹었다는 기록으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X19','SO5-2-u1-X05']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C11","difficulty":3,"kind":"mc","stem":"고구려 귀족이 돼지고기를 콩으로 만든 장에 절여 구운 맥적을 먹었다는 기록으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"콩으로 장을 담그는 음식 문화가 아주 오래전부터 있었다","correct":true},{"t":"고구려에는 콩이 없었다","mis":"SO5-2-u1-X19"},{"t":"평민도 날마다 고기를 먹었다","mis":"SO5-2-u1-X19"},{"t":"고구려 사람들은 음식을 익히지 않았다","mis":"SO5-2-u1-X05"}],"explanation":["콩으로 장을 만들었어요.","고기를 절여 구웠어요.","장 문화가 오래됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_challenge#5','soc',5,2,'u1','L06','g5_2_soc_u1_L06_challenge','lesson_challenge','SO5-2-u1-C12',3,'ox','auto','신라에서는 귀족들의 반대가 있었지만 결국 불교를 받아들여 왕의 힘이 세졌어요.',ARRAY['SO5-2-u1-X21']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C12","difficulty":3,"kind":"ox","stem":"신라에서는 귀족들의 반대가 있었지만 결국 불교를 받아들여 왕의 힘이 세졌어요.","answer":"O","reason_options":[{"t":"불교로 백성의 마음이 모이며 왕을 중심으로 나라가 하나가 되었기 때문에","correct":true},{"t":"불교를 받아들이자 왕의 힘이 사라졌기 때문에","mis":"SO5-2-u1-X21"}],"mis":"SO5-2-u1-X21","explanation":["처음에는 반대가 컸어요.","마침내 받아들였어요.","왕의 힘이 세졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_challenge#6','soc',5,2,'u1','L06','g5_2_soc_u1_L06_challenge','lesson_challenge','SO5-2-u1-C11',3,'error','auto','삼국 시대 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X19']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C11","difficulty":3,"kind":"error","stem":"삼국 시대 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나은 — 「삼국 시대 사람들은 신분과 상관없이 모두 비단옷을 입었어.」","correct":true,"mis_target":"SO5-2-u1-X19"},{"t":"준혁 — 「사람들은 대체로 저고리와 바지를 입었어.」","mis":"SO5-2-u1-X19"},{"t":"예린 — 「평민은 보리·조 같은 잡곡을 먹었어.」","mis":"SO5-2-u1-X19"}],"explanation":["비단은 귀했어요.","평민은 삼베옷을 입었어요.","나은의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_challenge#7','soc',5,2,'u1','L06','g5_2_soc_u1_L06_challenge','lesson_challenge','SO5-2-u1-C12',3,'mc','auto','부여 정림사지 오층 석탑, 고구려의 작은 금동 불상 같은 유물이 알려 주는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X21','SO5-2-u1-X26']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C12","difficulty":3,"kind":"mc","stem":"부여 정림사지 오층 석탑, 고구려의 작은 금동 불상 같은 유물이 알려 주는 것은 어느 것인가요?","options":[{"t":"삼국에 불교가 받아들여져 탑과 불상이 만들어졌다","correct":true},{"t":"삼국 사람들은 아무것도 믿지 않았다","mis":"SO5-2-u1-X21"},{"t":"불교는 고려 때 처음 들어왔다","mis":"SO5-2-u1-X26"},{"t":"탑과 불상은 놀이 기구였다","mis":"SO5-2-u1-X21"}],"explanation":["탑과 불상은 불교 유물이에요.","삼국 때 만들어졌어요.","불교를 받아들였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_challenge#8','soc',5,2,'u1','L06','g5_2_soc_u1_L06_challenge','lesson_challenge','SO5-2-u1-C11',4,'mc','auto','삼국 시대 세 사람의 생활 카드를 보고 친구가 「옛날엔 다 같은 밥을 먹고 같은 집에 살았구나」라고 했어요. 알맞게 고쳐 준 말은 어느 것인가요?',ARRAY['SO5-2-u1-X19','SO5-2-u1-X42']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C11","difficulty":4,"kind":"mc","stem":"삼국 시대 세 사람의 생활 카드를 보고 친구가 「옛날엔 다 같은 밥을 먹고 같은 집에 살았구나」라고 했어요. 알맞게 고쳐 준 말은 어느 것인가요?","options":[{"t":"신분에 따라 하는 일, 옷, 음식, 집이 달랐어","correct":true},{"t":"맞아, 신분은 옷 색깔만 달랐어","mis":"SO5-2-u1-X19"},{"t":"맞아, 천민이 가장 큰 집에 살았어","mis":"SO5-2-u1-X19"},{"t":"카드로는 생활을 짐작할 수 없어","mis":"SO5-2-u1-X42"}],"explanation":["가·나·다 카드가 달라요.","신분이 달랐어요.","생활 모습도 달랐어요."],"asset":{"type":"passage","lines":["가 — 비단옷 · 쌀밥 · 기와집 · 많은 토지와 노비","나 — 삼베옷 · 보리·조로 지은 밥 · 초가집 · 농사짓고 세금을 냄","다 — 주인집 일을 함 · 대부분 노비"],"title":"삼국 시대 세 사람의 생활 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_challenge#9','soc',5,2,'u1','L06','g5_2_soc_u1_L06_challenge','lesson_challenge','SO5-2-u1-C12',4,'mc','auto','가야가 철로 무기와 갑옷을 만들어 팔고 덩이쇠를 화폐처럼 쓴 것을 함께 볼 때 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X22','SO5-2-u1-X25','SO5-2-u1-X15']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C12","difficulty":4,"kind":"mc","stem":"가야가 철로 무기와 갑옷을 만들어 팔고 덩이쇠를 화폐처럼 쓴 것을 함께 볼 때 알 수 있는 것은 어느 것인가요?","options":[{"t":"철이 가야의 힘이자 다른 나라와 물건을 주고받는 바탕이었다","correct":true},{"t":"가야는 철을 쓸 줄 몰랐다","mis":"SO5-2-u1-X22"},{"t":"가야는 다른 나라와 오가지 않았다","mis":"SO5-2-u1-X25"},{"t":"가야는 청동기만 썼다","mis":"SO5-2-u1-X15"}],"explanation":["철로 무기를 만들어 팔았어요.","덩이쇠는 화폐처럼 썼어요.","철이 가야의 힘이었어요."],"asset":{"type":"passage","lines":["① 지붕 위에 고양이가, 사다리에 쥐 두 마리가 붙은 집 모양 토기","② 배 모양 토기","③ 말을 탄 무사 모양 토기","④ 철을 납작하게 펴 만든 덩이쇠가 무덤에 가득 쌓여 있다."],"title":"가야 무덤 출토품 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L06_challenge#10','soc',5,2,'u1','L06','g5_2_soc_u1_L06_challenge','lesson_challenge','SO5-2-u1-C11',4,'essay','teacher','삼국 시대 세 사람의 생활 카드와 고분 벽화 관찰 메모를 보고, 신분에 따라 생활이 어떻게 달랐는지 옷·음식·집 가운데 두 가지를 들어 쓰고, 벽화에 그 차이가 어떻게 나타나는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C11","difficulty":4,"kind":"essay","stem":"삼국 시대 세 사람의 생활 카드와 고분 벽화 관찰 메모를 보고, 신분에 따라 생활이 어떻게 달랐는지 옷·음식·집 가운데 두 가지를 들어 쓰고, 벽화에 그 차이가 어떻게 나타나는지 쓰세요.","answer_guide":{"answer":"예: 귀족은 비단옷을 입고 쌀밥을 먹었지만 평민은 삼베옷을 입고 보리·조 같은 잡곡을 먹었다. 귀족은 기와집, 평민은 초가집에 살았다. 고분 벽화에서는 신분이 높은 주인을 아주 크게, 재주꾼과 시중드는 사람을 작게 그려 신분의 차이를 나타냈다.","scoring_points":["신분에 따른 생활 차이를 두 가지 썼는가","귀족과 평민을 견주었는가","벽화 속 크기 차이를 신분과 이었는가"]},"explanation":["옷과 음식이 달라요.","집도 달라요.","벽화는 크기로 신분을 나타내요."],"asset":{"type":"passage","lines":["① 고구려 무덤 벽에 구경하는 사람이 아주 크게 그려져 있다.","② 그 앞의 재주꾼과 시중드는 사람은 아주 작게 그려져 있다.","③ 다른 벽에는 부엌에서 음식을 하는 사람과 고기를 건 창고가 있다."],"title":"고분 벽화 관찰 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_basic#1','soc',5,2,'u1','L07','g5_2_soc_u1_L07_basic','lesson_basic','SO5-2-u1-C13',1,'mc','auto','신라가 백제와 고구려를 무너뜨릴 때 손잡은 중국의 나라는 어느 것인가요?',ARRAY['SO5-2-u1-X34','SO5-2-u1-X36']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C13","difficulty":1,"kind":"mc","stem":"신라가 백제와 고구려를 무너뜨릴 때 손잡은 중국의 나라는 어느 것인가요?","options":[{"t":"당","correct":true},{"t":"송","mis":"SO5-2-u1-X34"},{"t":"거란","mis":"SO5-2-u1-X34"},{"t":"몽골","mis":"SO5-2-u1-X36"}],"explanation":["신라는 도움을 청했어요.","중국의 큰 나라였어요.","당이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_basic#2','soc',5,2,'u1','L07','g5_2_soc_u1_L07_basic','lesson_basic','SO5-2-u1-C14',1,'mc','auto','통일신라 때 부처의 나라를 이 땅에 만들고 싶은 마음을 담아 세운 절은 어느 것인가요?',ARRAY['SO5-2-u1-X26']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C14","difficulty":1,"kind":"mc","stem":"통일신라 때 부처의 나라를 이 땅에 만들고 싶은 마음을 담아 세운 절은 어느 것인가요?","options":[{"t":"불국사","correct":true},{"t":"해인사","mis":"SO5-2-u1-X26"},{"t":"정림사","mis":"SO5-2-u1-X26"},{"t":"상경성","mis":"SO5-2-u1-X26"}],"explanation":["경주에 있어요.","부처의 나라를 바랐어요.","불국사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_basic#3','soc',5,2,'u1','L07','g5_2_soc_u1_L07_basic','lesson_basic','SO5-2-u1-C13',1,'sa','auto','마을의 사람·말·논·뽕나무 수를 적은 통일신라의 문서를 무엇이라고 하나요? (○○ ○○ 문서)','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u1-C13","difficulty":1,"kind":"sa","stem":"마을의 사람·말·논·뽕나무 수를 적은 통일신라의 문서를 무엇이라고 하나요? (○○ ○○ 문서)","answer":["신라 촌락 문서","촌락 문서","신라촌락문서"],"explanation":["마을을 촌락이라고 해요.","신라 때 만들었어요.","신라 촌락 문서예요."],"mis":"SO5-2-u1-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_basic#4','soc',5,2,'u1','L07','g5_2_soc_u1_L07_basic','lesson_basic','SO5-2-u1-C14',1,'ox','auto','통일신라에는 서역의 상인들도 찾아왔어요.',ARRAY['SO5-2-u1-X25']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C14","difficulty":1,"kind":"ox","stem":"통일신라에는 서역의 상인들도 찾아왔어요.","answer":"O","reason_options":[{"t":"서역 사람의 모습을 한 돌사람 같은 유물이 남아 있기 때문에","correct":true},{"t":"통일신라는 다른 나라와 전혀 오가지 않았기 때문에","mis":"SO5-2-u1-X25"}],"mis":"SO5-2-u1-X25","explanation":["서역은 먼 서쪽 지역이에요.","서역 상인들이 왔어요.","유물이 증거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_basic#5','soc',5,2,'u1','L07','g5_2_soc_u1_L07_basic','lesson_basic','SO5-2-u1-C13',2,'mc','auto','삼국 통일 과정을 차례로 바르게 이은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X23']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C13","difficulty":2,"kind":"mc","stem":"삼국 통일 과정을 차례로 바르게 이은 것은 어느 것인가요?","options":[{"t":"신라가 당과 손잡음 → 백제와 고구려가 무너짐 → 신라가 당을 물리침","correct":true},{"t":"신라가 당을 물리침 → 당과 손잡음 → 백제가 무너짐","mis":"SO5-2-u1-X23"},{"t":"고구려가 당과 손잡음 → 신라가 무너짐 → 고구려가 통일함","mis":"SO5-2-u1-X23"},{"t":"신라 혼자 싸움 → 당이 도와줌 → 당이 한반도를 다스림","mis":"SO5-2-u1-X23"}],"explanation":["먼저 당과 손잡았어요.","두 나라가 무너졌어요.","마지막에 당을 물리쳤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_basic#6','soc',5,2,'u1','L07','g5_2_soc_u1_L07_basic','lesson_basic','SO5-2-u1-C13',2,'mc','auto','신라 촌락 문서를 만든 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X24']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C13","difficulty":2,"kind":"mc","stem":"신라 촌락 문서를 만든 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마을을 잘 관리하고 세금을 걷으려고","correct":true},{"t":"마을 아이들의 놀이를 기록하려고","mis":"SO5-2-u1-X24"},{"t":"다른 나라에 팔려고","mis":"SO5-2-u1-X24"},{"t":"왕의 일기를 쓰려고","mis":"SO5-2-u1-X24"}],"explanation":["사람과 땅을 셌어요.","말과 나무도 셌어요.","세금을 걷으려 했어요."],"asset":{"type":"passage","lines":["어느 마을 — 집 11채 · 사람 147명(다른 마을에서 온 사람 포함)","말 25마리 · 소 22마리","논과 밭의 넓이","뽕나무 1,004그루 · 잣나무 120그루"],"title":"신라 촌락 문서에 적힌 것(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_basic#7','soc',5,2,'u1','L07','g5_2_soc_u1_L07_basic','lesson_basic','SO5-2-u1-C14',2,'mc','auto','통일신라 교류 카드 ④가 알려 주는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X25','SO5-2-u1-X26']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C14","difficulty":2,"kind":"mc","stem":"통일신라 교류 카드 ④가 알려 주는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"먼 서역 사람들이 신라를 오가며 활동했다","correct":true},{"t":"신라 사람들은 모두 턱수염을 길렀다","mis":"SO5-2-u1-X25"},{"t":"돌사람은 고려 때 만든 것이다","mis":"SO5-2-u1-X26"},{"t":"신라는 서역과 전쟁만 했다","mis":"SO5-2-u1-X25"}],"explanation":["턱수염과 큰 코예요.","서역 사람의 모습이에요.","서역과 오갔어요."],"asset":{"type":"passage","lines":["① 승려와 유학생이 바다를 건너 당에서 공부했다.","② 당에는 신라 사람들이 모여 사는 곳이 생겼다.","③ 일본과는 주로 물건을 사고팔며 오갔다.","④ 왕릉을 지키는 돌사람에 턱수염 짙고 코 큰 얼굴이 새겨졌다.","⑤ 한 승려가 인도와 서역을 여행하고 책을 남겼다."],"title":"통일신라 교류 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_basic#8','soc',5,2,'u1','L07','g5_2_soc_u1_L07_basic','lesson_basic','SO5-2-u1-C14',2,'mc','auto','석굴암에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X26','SO5-2-u1-X11']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C14","difficulty":2,"kind":"mc","stem":"석굴암에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"화강암을 쌓아 동굴처럼 만든 통일신라의 절이다","correct":true},{"t":"나무로 지은 고려의 궁궐이다","mis":"SO5-2-u1-X26"},{"t":"청동기 시대 지배자의 무덤이다","mis":"SO5-2-u1-X11"},{"t":"발해의 수도에 있는 석등이다","mis":"SO5-2-u1-X26"}],"explanation":["돌을 쌓았어요.","동굴처럼 만들었어요.","통일신라의 절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_basic#9','soc',5,2,'u1','L07','g5_2_soc_u1_L07_basic','lesson_basic','SO5-2-u1-C13',2,'ox','auto','신라는 삼국을 통일하면서 고구려의 북쪽 넓은 땅까지 모두 차지했어요.',ARRAY['SO5-2-u1-X23']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C13","difficulty":2,"kind":"ox","stem":"신라는 삼국을 통일하면서 고구려의 북쪽 넓은 땅까지 모두 차지했어요.","answer":"X","reason_options":[{"t":"당을 물리쳤지만 고구려의 북쪽 땅은 되찾지 못했기 때문에","correct":true},{"t":"고구려 땅은 처음부터 신라 땅이었기 때문에","mis":"SO5-2-u1-X23"}],"mis":"SO5-2-u1-X23","explanation":["당을 물리쳤어요.","북쪽 땅은 되찾지 못했어요.","그곳에 뒤에 발해가 섰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_basic#10','soc',5,2,'u1','L07','g5_2_soc_u1_L07_basic','lesson_basic','SO5-2-u1-C13',3,'error','auto','삼국 통일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X23']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C13","difficulty":3,"kind":"error","stem":"삼국 통일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「신라는 끝까지 당과 한편이 되어 당이 한반도를 함께 다스렸어.」","correct":true,"mis_target":"SO5-2-u1-X23"},{"t":"도하 — 「당이 한반도 전체를 차지하려 하자 신라가 맞서 싸웠어.」","mis":"SO5-2-u1-X23"},{"t":"유찬 — 「신라는 옛 백제·고구려 사람들과 힘을 모아 당을 물리쳤어.」","mis":"SO5-2-u1-X23"}],"explanation":["당은 한반도를 차지하려 했어요.","신라는 당을 물리쳤어요.","서윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_challenge#1','soc',5,2,'u1','L07','g5_2_soc_u1_L07_challenge','lesson_challenge','SO5-2-u1-C14',2,'match','auto','통일신라 교류 카드와 교류한 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C14","difficulty":2,"kind":"match","stem":"통일신라 교류 카드와 교류한 곳을 알맞게 이으세요.","pairs":[{"l":"① 승려·유학생의 공부","r":"당"},{"l":"③ 물건을 사고팔며 오감","r":"일본"},{"l":"④ 턱수염 짙은 돌사람","r":"서역"},{"l":"⑤ 여행하고 책을 남김","r":"인도와 서역"}],"mis":"SO5-2-u1-X25","explanation":["당으로 공부하러 갔어요.","일본과는 무역이에요.","서역 사람도 오갔어요."],"asset":{"type":"passage","lines":["① 승려와 유학생이 바다를 건너 당에서 공부했다.","② 당에는 신라 사람들이 모여 사는 곳이 생겼다.","③ 일본과는 주로 물건을 사고팔며 오갔다.","④ 왕릉을 지키는 돌사람에 턱수염 짙고 코 큰 얼굴이 새겨졌다.","⑤ 한 승려가 인도와 서역을 여행하고 책을 남겼다."],"title":"통일신라 교류 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_challenge#2','soc',5,2,'u1','L07','g5_2_soc_u1_L07_challenge','lesson_challenge','SO5-2-u1-C13',2,'mc','auto','통일 뒤 신라가 나라의 제도를 정비한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X23','SO5-2-u1-X24']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C13","difficulty":2,"kind":"mc","stem":"통일 뒤 신라가 나라의 제도를 정비한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"넓어진 땅과 늘어난 사람을 다스리려고","correct":true},{"t":"나라를 다시 셋으로 나누려고","mis":"SO5-2-u1-X23"},{"t":"당에 땅을 넘겨주려고","mis":"SO5-2-u1-X23"},{"t":"세금을 모두 없애려고","mis":"SO5-2-u1-X24"}],"explanation":["땅이 넓어졌어요.","사람이 늘었어요.","다스릴 틀이 필요했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_challenge#3','soc',5,2,'u1','L07','g5_2_soc_u1_L07_challenge','lesson_challenge','SO5-2-u1-C13',3,'mc','auto','신라 촌락 문서에 뽕나무 수까지 적은 까닭을 짐작한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X24']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C13","difficulty":3,"kind":"mc","stem":"신라 촌락 문서에 뽕나무 수까지 적은 까닭을 짐작한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뽕잎으로 누에를 쳐 비단을 만들 수 있어 나라가 살필 재산이었다","correct":true},{"t":"뽕나무로 집을 지었기 때문에","mis":"SO5-2-u1-X24"},{"t":"뽕나무 수를 세는 놀이가 있었기 때문에","mis":"SO5-2-u1-X24"},{"t":"뽕나무는 아무 쓸모가 없었기 때문에","mis":"SO5-2-u1-X24"}],"explanation":["뽕잎은 누에가 먹어요.","누에고치로 비단을 짜요.","재산이라 세금과 이어져요."],"asset":{"type":"passage","lines":["어느 마을 — 집 11채 · 사람 147명(다른 마을에서 온 사람 포함)","말 25마리 · 소 22마리","논과 밭의 넓이","뽕나무 1,004그루 · 잣나무 120그루"],"title":"신라 촌락 문서에 적힌 것(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_challenge#4','soc',5,2,'u1','L07','g5_2_soc_u1_L07_challenge','lesson_challenge','SO5-2-u1-C14',3,'mc','auto','경주의 두 문화유산 메모 ㉰로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X26','SO5-2-u1-X42']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C14","difficulty":3,"kind":"mc","stem":"경주의 두 문화유산 메모 ㉰로 알 수 있는 것은 어느 것인가요?","options":[{"t":"석굴암을 지을 때 습기를 막는 지혜를 썼다","correct":true},{"t":"불국사는 물 위에 지었다","mis":"SO5-2-u1-X26"},{"t":"석굴암은 나무로 지어 물에 약했다","mis":"SO5-2-u1-X26"},{"t":"샘물은 마시려고 끌어왔다","mis":"SO5-2-u1-X42"}],"explanation":["돌로 만든 굴엔 습기가 차요.","샘물로 바닥을 차갑게 했어요.","습기를 막는 지혜예요."],"asset":{"type":"passage","lines":["㉮ 부처의 나라를 이 땅에 만들고 싶은 마음을 담은 절","㉯ 화강암을 쌓아 동굴처럼 만든 절","㉰ 바닥 아래로 샘물이 흐르게 해 습기를 막았다."],"title":"경주의 두 문화유산 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_challenge#5','soc',5,2,'u1','L07','g5_2_soc_u1_L07_challenge','lesson_challenge','SO5-2-u1-C14',3,'ox','auto','통일신라 때 불교는 왕과 귀족뿐 아니라 백성에게까지 널리 퍼졌어요.',ARRAY['SO5-2-u1-X21']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C14","difficulty":3,"kind":"ox","stem":"통일신라 때 불교는 왕과 귀족뿐 아니라 백성에게까지 널리 퍼졌어요.","answer":"O","reason_options":[{"t":"불교가 널리 퍼져 불국사·석굴암 같은 절이 세워졌기 때문에","correct":true},{"t":"불교는 왕 한 사람만 믿었기 때문에","mis":"SO5-2-u1-X21"}],"mis":"SO5-2-u1-X21","explanation":["백성도 불교를 믿었어요.","큰 절이 세워졌어요.","불교문화가 꽃피었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_challenge#6','soc',5,2,'u1','L07','g5_2_soc_u1_L07_challenge','lesson_challenge','SO5-2-u1-C14',3,'error','auto','경주의 두 문화유산을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X26']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C14","difficulty":3,"kind":"error","stem":"경주의 두 문화유산을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은채 — 「불국사와 석굴암은 고려 사람들이 지은 절이야.」","correct":true,"mis_target":"SO5-2-u1-X26"},{"t":"주안 — 「불국사에는 부처의 나라를 바라는 마음이 담겼어.」","mis":"SO5-2-u1-X26"},{"t":"시아 — 「석굴암은 화강암을 쌓아 만들었어.」","mis":"SO5-2-u1-X26"}],"explanation":["둘 다 통일신라 때 지었어요.","고려가 아니에요.","은채의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉮ 부처의 나라를 이 땅에 만들고 싶은 마음을 담은 절","㉯ 화강암을 쌓아 동굴처럼 만든 절","㉰ 바닥 아래로 샘물이 흐르게 해 습기를 막았다."],"title":"경주의 두 문화유산 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_challenge#7','soc',5,2,'u1','L07','g5_2_soc_u1_L07_challenge','lesson_challenge','SO5-2-u1-C14',3,'mc','auto','통일신라 교류 카드 ②처럼 당에 신라 사람들이 모여 사는 곳이 생긴 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X25']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C14","difficulty":3,"kind":"mc","stem":"통일신라 교류 카드 ②처럼 당에 신라 사람들이 모여 사는 곳이 생긴 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"신라와 당 사이에 사람의 오고 감이 아주 활발했다","correct":true},{"t":"신라 사람들은 바다를 건너지 못했다","mis":"SO5-2-u1-X25"},{"t":"당과 신라는 늘 전쟁만 했다","mis":"SO5-2-u1-X25"},{"t":"신라 사람들은 당에서 모두 쫓겨났다","mis":"SO5-2-u1-X25"}],"explanation":["많은 사람이 당에 갔어요.","모여 살 만큼이에요.","교류가 활발했어요."],"asset":{"type":"passage","lines":["① 승려와 유학생이 바다를 건너 당에서 공부했다.","② 당에는 신라 사람들이 모여 사는 곳이 생겼다.","③ 일본과는 주로 물건을 사고팔며 오갔다.","④ 왕릉을 지키는 돌사람에 턱수염 짙고 코 큰 얼굴이 새겨졌다.","⑤ 한 승려가 인도와 서역을 여행하고 책을 남겼다."],"title":"통일신라 교류 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_challenge#8','soc',5,2,'u1','L07','g5_2_soc_u1_L07_challenge','lesson_challenge','SO5-2-u1-C13',4,'mc','auto','신라가 당과 맞서 싸워 삼국 통일을 이룬 것에 대해 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X23']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C13","difficulty":4,"kind":"mc","stem":"신라가 당과 맞서 싸워 삼국 통일을 이룬 것에 대해 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"큰 나라 당을 물리쳐 스스로 통일을 지켰지만, 고구려의 북쪽 땅은 되찾지 못한 아쉬움이 있다","correct":true},{"t":"당과 끝까지 한편이었기 때문에 쉽게 통일했다","mis":"SO5-2-u1-X23"},{"t":"고구려 땅까지 모두 차지해 아쉬움이 전혀 없다","mis":"SO5-2-u1-X23"},{"t":"통일은 고구려가 이룬 일이다","mis":"SO5-2-u1-X23"}],"explanation":["당을 물리쳤어요.","스스로 지킨 통일이에요.","북쪽 땅은 되찾지 못했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_challenge#9','soc',5,2,'u1','L07','g5_2_soc_u1_L07_challenge','lesson_challenge','SO5-2-u1-C14',4,'mc','auto','통일신라 교류 카드 ①~⑤를 함께 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO5-2-u1-X25','SO5-2-u1-X42']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C14","difficulty":4,"kind":"mc","stem":"통일신라 교류 카드 ①~⑤를 함께 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"통일신라는 당·일본은 물론 먼 서역까지 활발히 교류했다","correct":true},{"t":"통일신라는 당하고만 오갔다","mis":"SO5-2-u1-X25"},{"t":"통일신라는 다른 나라와 오가지 않았다","mis":"SO5-2-u1-X25"},{"t":"교류 카드는 연도만 외우면 된다","mis":"SO5-2-u1-X42"}],"explanation":["당·일본이 나와요.","서역·인도도 나와요.","넓게 교류했어요."],"asset":{"type":"passage","lines":["① 승려와 유학생이 바다를 건너 당에서 공부했다.","② 당에는 신라 사람들이 모여 사는 곳이 생겼다.","③ 일본과는 주로 물건을 사고팔며 오갔다.","④ 왕릉을 지키는 돌사람에 턱수염 짙고 코 큰 얼굴이 새겨졌다.","⑤ 한 승려가 인도와 서역을 여행하고 책을 남겼다."],"title":"통일신라 교류 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L07_challenge#10','soc',5,2,'u1','L07','g5_2_soc_u1_L07_challenge','lesson_challenge','SO5-2-u1-C13',4,'essay','teacher','신라 촌락 문서에 적힌 것을 보고, 통일신라가 이 문서를 만든 까닭을 통일 뒤 상황과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C13","difficulty":4,"kind":"essay","stem":"신라 촌락 문서에 적힌 것을 보고, 통일신라가 이 문서를 만든 까닭을 통일 뒤 상황과 이어 쓰세요.","answer_guide":{"answer":"예: 통일 뒤 신라는 땅이 넓어지고 다스릴 사람이 늘어 나라의 제도를 정비해야 했다. 그래서 마을마다 집과 사람 수, 말과 소, 논밭 넓이, 뽕나무 수를 꼼꼼히 적어 마을을 잘 관리하고 세금을 걷으려고 이 문서를 만들었다.","scoring_points":["통일 뒤 넓어진 땅·늘어난 사람을 썼는가","문서에 적힌 것을 들었는가","마을 관리와 세금이라는 목적을 썼는가"]},"explanation":["통일로 땅이 넓어졌어요.","마을을 꼼꼼히 셌어요.","관리하고 세금을 걷으려고요."],"asset":{"type":"passage","lines":["어느 마을 — 집 11채 · 사람 147명(다른 마을에서 온 사람 포함)","말 25마리 · 소 22마리","논과 밭의 넓이","뽕나무 1,004그루 · 잣나무 120그루"],"title":"신라 촌락 문서에 적힌 것(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_basic#1','soc',5,2,'u1','L08','g5_2_soc_u1_L08_basic','lesson_basic','SO5-2-u1-C15',1,'sa','auto','고구려가 무너진 뒤 고구려 유민을 이끌고 발해를 세운 사람은 누구인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C15","difficulty":1,"kind":"sa","stem":"고구려가 무너진 뒤 고구려 유민을 이끌고 발해를 세운 사람은 누구인가요? 세 글자로 쓰세요.","answer":["대조영"],"explanation":["고구려 출신이에요.","유민을 이끌었어요.","대조영이에요."],"mis":"SO5-2-u1-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_basic#2','soc',5,2,'u1','L08','g5_2_soc_u1_L08_basic','lesson_basic','SO5-2-u1-C15',1,'mc','auto','당에서 발해를 「바다 동쪽의 번성한 나라」라는 뜻으로 부른 이름은 어느 것인가요?',ARRAY['SO5-2-u1-X28','SO5-2-u1-X29','SO5-2-u1-X18']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C15","difficulty":1,"kind":"mc","stem":"당에서 발해를 「바다 동쪽의 번성한 나라」라는 뜻으로 부른 이름은 어느 것인가요?","options":[{"t":"해동성국","correct":true},{"t":"삼국 통일","mis":"SO5-2-u1-X28"},{"t":"후삼국","mis":"SO5-2-u1-X29"},{"t":"가야 연맹","mis":"SO5-2-u1-X18"}],"explanation":["바다 동쪽이에요.","번성한 나라예요.","해동성국이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_basic#3','soc',5,2,'u1','L08','g5_2_soc_u1_L08_basic','lesson_basic','SO5-2-u1-C15',1,'mc','auto','발해가 스스로 이어받았다고 밝힌 나라는 어느 것인가요?',ARRAY['SO5-2-u1-X27']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C15","difficulty":1,"kind":"mc","stem":"발해가 스스로 이어받았다고 밝힌 나라는 어느 것인가요?","options":[{"t":"고구려","correct":true},{"t":"신라","mis":"SO5-2-u1-X27"},{"t":"백제","mis":"SO5-2-u1-X27"},{"t":"당","mis":"SO5-2-u1-X27"}],"explanation":["대조영은 고구려 출신이에요.","고구려 옛 땅을 되찾았어요.","고구려를 계승했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_basic#4','soc',5,2,'u1','L08','g5_2_soc_u1_L08_basic','lesson_basic','SO5-2-u1-C16',1,'ox','auto','발해는 당·일본 등 주변 나라와 활발히 교류했어요.',ARRAY['SO5-2-u1-X25']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C16","difficulty":1,"kind":"ox","stem":"발해는 당·일본 등 주변 나라와 활발히 교류했어요.","answer":"O","reason_options":[{"t":"당의 도자기를 닮은 향로가 나오고 이웃 나라에 물건을 팔았기 때문에","correct":true},{"t":"발해는 바깥과 문을 닫고 살았기 때문에","mis":"SO5-2-u1-X25"}],"mis":"SO5-2-u1-X25","explanation":["당과 오갔어요.","일본과도 오갔어요.","활발히 교류했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_basic#5','soc',5,2,'u1','L08','g5_2_soc_u1_L08_basic','lesson_basic','SO5-2-u1-C15',2,'mc','auto','어느 나라의 건국 기록 메모 ①~④가 설명하는 나라는 어느 것인가요?',ARRAY['SO5-2-u1-X30','SO5-2-u1-X15','SO5-2-u1-X23']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C15","difficulty":2,"kind":"mc","stem":"어느 나라의 건국 기록 메모 ①~④가 설명하는 나라는 어느 것인가요?","options":[{"t":"발해","correct":true},{"t":"고려","mis":"SO5-2-u1-X30"},{"t":"고조선","mis":"SO5-2-u1-X15"},{"t":"통일신라","mis":"SO5-2-u1-X23"}],"explanation":["고구려 출신 장수예요.","고구려 옛 땅을 되찾았어요.","해동성국 발해예요."],"asset":{"type":"passage","lines":["① 고구려 출신 장수가 남은 고구려 사람들을 이끌었다.","② 동쪽으로 가서 산에 성을 쌓고 나라를 세웠다.","③ 고구려의 옛 땅을 대부분 되찾았다.","④ 당에서는 이 나라를 바다 동쪽의 번성한 나라라 불렀다."],"title":"어느 나라의 건국 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_basic#6','soc',5,2,'u1','L08','g5_2_soc_u1_L08_basic','lesson_basic','SO5-2-u1-C15',2,'mc','auto','고구려와 발해를 견준 탐구 카드 가·나로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X28','SO5-2-u1-X27']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C15","difficulty":2,"kind":"mc","stem":"고구려와 발해를 견준 탐구 카드 가·나로 알 수 있는 것은 어느 것인가요?","options":[{"t":"발해의 문화가 고구려와 닮았다","correct":true},{"t":"발해는 고구려와 아무 관계가 없다","mis":"SO5-2-u1-X28"},{"t":"발해의 문화는 신라에서만 왔다","mis":"SO5-2-u1-X27"},{"t":"두 나라는 서로 전쟁만 했다","mis":"SO5-2-u1-X28"}],"explanation":["같은 꽃잎 무늬예요.","같은 온돌이에요.","고구려를 이었어요."],"asset":{"type":"passage","lines":["가 — 고구려 기와와 이 나라 기와에 모두 꽃잎 무늬가 있다.","나 — 두 나라 집터 모두 방 한쪽 바닥을 데우는 시설이 있다.","다 — 일본 기록에 이 나라 사신을 「고려 사신」이라 적었다.","라 — 이 나라 왕이 스스로 고구려를 이었다고 밝혔다."],"title":"고구려와 발해를 견준 탐구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_basic#7','soc',5,2,'u1','L08','g5_2_soc_u1_L08_basic','lesson_basic','SO5-2-u1-C16',2,'mc','auto','발해 생활 탐구 메모 ①의 세 빛깔 향로로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X25','SO5-2-u1-X26']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C16","difficulty":2,"kind":"mc","stem":"발해 생활 탐구 메모 ①의 세 빛깔 향로로 알 수 있는 것은 어느 것인가요?","options":[{"t":"발해가 당과 교류해 도자기 만드는 법이 전해졌다","correct":true},{"t":"발해는 도자기를 전혀 쓰지 않았다","mis":"SO5-2-u1-X25"},{"t":"향로는 고려 청자다","mis":"SO5-2-u1-X26"},{"t":"발해는 당과 교류하지 않았다","mis":"SO5-2-u1-X25"}],"explanation":["당에서 유행한 도자기와 닮았어요.","만드는 법이 전해졌어요.","당과 교류했어요."],"asset":{"type":"passage","lines":["① 초록·노랑·갈색 세 빛깔의 향로가 나왔다.","② 말과 짐승 가죽, 인삼을 이웃 나라에 팔았다.","③ 귀족은 넓은 땅과 기와집, 평민은 주로 초가집이었다.","④ 수도 자리에 절터와 불상, 어른 키 세 배의 석등이 남았다."],"title":"발해 생활 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_basic#8','soc',5,2,'u1','L08','g5_2_soc_u1_L08_basic','lesson_basic','SO5-2-u1-C16',2,'mc','auto','발해 사람들의 생활 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X20','SO5-2-u1-X19']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C16","difficulty":2,"kind":"mc","stem":"발해 사람들의 생활 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"귀족은 기와집에, 평민은 주로 초가집에 살았다","correct":true},{"t":"모든 사람이 같은 집에 살았다","mis":"SO5-2-u1-X20"},{"t":"평민이 가장 넓은 땅을 가졌다","mis":"SO5-2-u1-X19"},{"t":"신분 제도가 없었다","mis":"SO5-2-u1-X20"}],"explanation":["발해에도 신분 제도가 있었어요.","집이 달랐어요.","귀족 기와집, 평민 초가집이에요."],"asset":{"type":"passage","lines":["① 초록·노랑·갈색 세 빛깔의 향로가 나왔다.","② 말과 짐승 가죽, 인삼을 이웃 나라에 팔았다.","③ 귀족은 넓은 땅과 기와집, 평민은 주로 초가집이었다.","④ 수도 자리에 절터와 불상, 어른 키 세 배의 석등이 남았다."],"title":"발해 생활 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_basic#9','soc',5,2,'u1','L08','g5_2_soc_u1_L08_basic','lesson_basic','SO5-2-u1-C15',2,'ox','auto','방바닥을 데우는 온돌은 고구려와 발해 집터에서 모두 보여요.',ARRAY['SO5-2-u1-X28']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C15","difficulty":2,"kind":"ox","stem":"방바닥을 데우는 온돌은 고구려와 발해 집터에서 모두 보여요.","answer":"O","reason_options":[{"t":"추운 북쪽에서 겨울을 나는 방법이 고구려에서 발해로 이어졌기 때문에","correct":true},{"t":"온돌은 오늘날 처음 만든 것이기 때문에","mis":"SO5-2-u1-X28"}],"mis":"SO5-2-u1-X28","explanation":["아궁이에 불을 지펴요.","방바닥이 따뜻해져요.","고구려와 발해가 닮았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_basic#10','soc',5,2,'u1','L08','g5_2_soc_u1_L08_basic','lesson_basic','SO5-2-u1-C15',3,'error','auto','발해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X27','SO5-2-u1-X28']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C15","difficulty":3,"kind":"error","stem":"발해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"승우 — 「발해는 신라 사람들이 세운 나라라서 신라를 이었어.」","correct":true,"mis_target":"SO5-2-u1-X27"},{"t":"라온 — 「발해는 고구려의 옛 땅을 대부분 되찾았어.」","mis":"SO5-2-u1-X27"},{"t":"다은 — 「일본 기록에는 발해 사신을 고려 사신이라 적었어.」","mis":"SO5-2-u1-X28"}],"explanation":["발해는 고구려 출신 대조영이 세웠어요.","고구려를 이었어요.","승우의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_challenge#1','soc',5,2,'u1','L08','g5_2_soc_u1_L08_challenge','lesson_challenge','SO5-2-u1-C15',2,'match','auto','고구려와 발해를 견준 탐구 카드와 그것이 무엇을 보여 주는지 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C15","difficulty":2,"kind":"match","stem":"고구려와 발해를 견준 탐구 카드와 그것이 무엇을 보여 주는지 알맞게 이으세요.","pairs":[{"l":"가 꽃잎 무늬 기와","r":"건축 문화가 닮음"},{"l":"나 바닥을 데우는 시설","r":"생활 방식이 닮음"},{"l":"다 「고려 사신」 기록","r":"이웃 나라도 고구려를 이었다고 봄"},{"l":"라 왕이 밝힌 말","r":"스스로 고구려를 이었다고 밝힘"}],"mis":"SO5-2-u1-X28","explanation":["가·나는 유물·유적이에요.","다는 다른 나라 기록이에요.","라는 스스로 밝힌 말이에요."],"asset":{"type":"passage","lines":["가 — 고구려 기와와 이 나라 기와에 모두 꽃잎 무늬가 있다.","나 — 두 나라 집터 모두 방 한쪽 바닥을 데우는 시설이 있다.","다 — 일본 기록에 이 나라 사신을 「고려 사신」이라 적었다.","라 — 이 나라 왕이 스스로 고구려를 이었다고 밝혔다."],"title":"고구려와 발해를 견준 탐구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_challenge#2','soc',5,2,'u1','L08','g5_2_soc_u1_L08_challenge','lesson_challenge','SO5-2-u1-C16',2,'mc','auto','발해 생활 탐구 메모 ④로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X21','SO5-2-u1-X11']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C16","difficulty":2,"kind":"mc","stem":"발해 생활 탐구 메모 ④로 알 수 있는 것은 어느 것인가요?","options":[{"t":"발해에 불교가 널리 퍼졌다","correct":true},{"t":"발해 사람들은 아무것도 믿지 않았다","mis":"SO5-2-u1-X21"},{"t":"석등은 고인돌의 한 종류다","mis":"SO5-2-u1-X11"},{"t":"발해의 수도에는 절이 없었다","mis":"SO5-2-u1-X21"}],"explanation":["절터와 불상이 있어요.","큰 석등도 있어요.","불교가 퍼졌어요."],"asset":{"type":"passage","lines":["① 초록·노랑·갈색 세 빛깔의 향로가 나왔다.","② 말과 짐승 가죽, 인삼을 이웃 나라에 팔았다.","③ 귀족은 넓은 땅과 기와집, 평민은 주로 초가집이었다.","④ 수도 자리에 절터와 불상, 어른 키 세 배의 석등이 남았다."],"title":"발해 생활 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_challenge#3','soc',5,2,'u1','L08','g5_2_soc_u1_L08_challenge','lesson_challenge','SO5-2-u1-C15',3,'mc','auto','발해가 고구려를 계승했다는 증거로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X28']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C15","difficulty":3,"kind":"mc","stem":"발해가 고구려를 계승했다는 증거로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"당의 세 빛깔 도자기를 닮은 향로를 만들었다","correct":true},{"t":"고구려와 같은 꽃잎 무늬 기와를 썼다","mis":"SO5-2-u1-X28"},{"t":"고구려처럼 방 한쪽에 온돌을 놓았다","mis":"SO5-2-u1-X28"},{"t":"일본이 발해 사신을 고려 사신이라 적었다","mis":"SO5-2-u1-X28"}],"explanation":["기와와 온돌은 고구려와 닮았어요.","일본 기록도 증거예요.","삼채 향로는 당과의 교류를 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_challenge#4','soc',5,2,'u1','L08','g5_2_soc_u1_L08_challenge','lesson_challenge','SO5-2-u1-C15',3,'mc','auto','어느 나라의 건국 기록 메모 ④처럼 당이 발해를 해동성국이라 부른 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X28','SO5-2-u1-X27']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C15","difficulty":3,"kind":"mc","stem":"어느 나라의 건국 기록 메모 ④처럼 당이 발해를 해동성국이라 부른 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"발해가 이웃 나라도 인정할 만큼 크게 번성했다","correct":true},{"t":"발해는 아주 작은 마을이었다","mis":"SO5-2-u1-X28"},{"t":"발해는 당의 일부였다","mis":"SO5-2-u1-X27"},{"t":"발해는 바다 한가운데 있었다","mis":"SO5-2-u1-X28"}],"explanation":["번성한 나라라는 뜻이에요.","당이 그렇게 불렀어요.","크게 발전했어요."],"asset":{"type":"passage","lines":["① 고구려 출신 장수가 남은 고구려 사람들을 이끌었다.","② 동쪽으로 가서 산에 성을 쌓고 나라를 세웠다.","③ 고구려의 옛 땅을 대부분 되찾았다.","④ 당에서는 이 나라를 바다 동쪽의 번성한 나라라 불렀다."],"title":"어느 나라의 건국 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_challenge#5','soc',5,2,'u1','L08','g5_2_soc_u1_L08_challenge','lesson_challenge','SO5-2-u1-C16',3,'ox','auto','발해가 말과 짐승 가죽, 인삼을 이웃 나라에 판 것은 발해 땅에서 나는 것을 바탕으로 교류했다는 뜻이에요.',ARRAY['SO5-2-u1-X25']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C16","difficulty":3,"kind":"ox","stem":"발해가 말과 짐승 가죽, 인삼을 이웃 나라에 판 것은 발해 땅에서 나는 것을 바탕으로 교류했다는 뜻이에요.","answer":"O","reason_options":[{"t":"넓은 북쪽 땅에서 기른 말과 사냥한 짐승 가죽, 인삼을 내다 팔았기 때문에","correct":true},{"t":"발해는 물건을 사기만 하고 팔지 않았기 때문에","mis":"SO5-2-u1-X25"}],"mis":"SO5-2-u1-X25","explanation":["북쪽 땅에서 나는 것이에요.","이웃 나라에 팔았어요.","교류의 바탕이에요."],"asset":{"type":"passage","lines":["① 초록·노랑·갈색 세 빛깔의 향로가 나왔다.","② 말과 짐승 가죽, 인삼을 이웃 나라에 팔았다.","③ 귀족은 넓은 땅과 기와집, 평민은 주로 초가집이었다.","④ 수도 자리에 절터와 불상, 어른 키 세 배의 석등이 남았다."],"title":"발해 생활 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_challenge#6','soc',5,2,'u1','L08','g5_2_soc_u1_L08_challenge','lesson_challenge','SO5-2-u1-C16',3,'error','auto','발해 생활 탐구 메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X20','SO5-2-u1-X21','SO5-2-u1-X25']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C16","difficulty":3,"kind":"error","stem":"발해 생활 탐구 메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「발해에는 신분 차이가 없어서 모두 기와집에 살았어.」","correct":true,"mis_target":"SO5-2-u1-X20"},{"t":"윤우 — 「수도 자리에 남은 절터를 보면 불교가 퍼졌어.」","mis":"SO5-2-u1-X21"},{"t":"채이 — 「세 빛깔 향로를 보면 당과 교류했어.」","mis":"SO5-2-u1-X25"}],"explanation":["귀족은 기와집, 평민은 초가집이에요.","신분 차이가 있었어요.","하율의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["① 초록·노랑·갈색 세 빛깔의 향로가 나왔다.","② 말과 짐승 가죽, 인삼을 이웃 나라에 팔았다.","③ 귀족은 넓은 땅과 기와집, 평민은 주로 초가집이었다.","④ 수도 자리에 절터와 불상, 어른 키 세 배의 석등이 남았다."],"title":"발해 생활 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_challenge#7','soc',5,2,'u1','L08','g5_2_soc_u1_L08_challenge','lesson_challenge','SO5-2-u1-C15',3,'mc','auto','발해가 세워진 곳과 신라의 삼국 통일을 함께 볼 때 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X27','SO5-2-u1-X23']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C15","difficulty":3,"kind":"mc","stem":"발해가 세워진 곳과 신라의 삼국 통일을 함께 볼 때 알 수 있는 것은 어느 것인가요?","options":[{"t":"신라가 되찾지 못한 고구려 북쪽 땅에 발해가 세워져 남쪽의 신라와 북쪽의 발해가 함께 있었다","correct":true},{"t":"발해는 신라 땅 한가운데 세워졌다","mis":"SO5-2-u1-X27"},{"t":"발해가 세워지자 신라는 사라졌다","mis":"SO5-2-u1-X23"},{"t":"발해와 신라는 같은 나라다","mis":"SO5-2-u1-X27"}],"explanation":["신라는 북쪽 땅을 되찾지 못했어요.","그곳에 발해가 섰어요.","남과 북에 두 나라가 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_challenge#8','soc',5,2,'u1','L08','g5_2_soc_u1_L08_challenge','lesson_challenge','SO5-2-u1-C15',4,'mc','auto','「발해는 고구려를 이은 나라다」라는 주장을 가장 탄탄하게 뒷받침하는 묶음은 어느 것인가요?',ARRAY['SO5-2-u1-X25','SO5-2-u1-X28','SO5-2-u1-X20']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C15","difficulty":4,"kind":"mc","stem":"「발해는 고구려를 이은 나라다」라는 주장을 가장 탄탄하게 뒷받침하는 묶음은 어느 것인가요?","options":[{"t":"세운 사람이 고구려 출신이고, 기와·온돌이 닮았으며, 스스로 밝히고 이웃 나라 기록도 그렇게 적었다","correct":true},{"t":"당의 도자기를 닮은 향로를 만들었다","mis":"SO5-2-u1-X25"},{"t":"해동성국이라고 불렸다","mis":"SO5-2-u1-X28"},{"t":"귀족이 기와집에 살았다","mis":"SO5-2-u1-X20"}],"explanation":["사람·유물·기록이 모두 있어요.","여러 증거가 한쪽을 가리켜요.","탄탄한 뒷받침이에요."],"asset":{"type":"passage","lines":["가 — 고구려 기와와 이 나라 기와에 모두 꽃잎 무늬가 있다.","나 — 두 나라 집터 모두 방 한쪽 바닥을 데우는 시설이 있다.","다 — 일본 기록에 이 나라 사신을 「고려 사신」이라 적었다.","라 — 이 나라 왕이 스스로 고구려를 이었다고 밝혔다."],"title":"고구려와 발해를 견준 탐구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_challenge#9','soc',5,2,'u1','L08','g5_2_soc_u1_L08_challenge','lesson_challenge','SO5-2-u1-C16',4,'mc','auto','발해 생활 탐구 메모 ①~④를 함께 볼 때 발해를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X25','SO5-2-u1-X21','SO5-2-u1-X42']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C16","difficulty":4,"kind":"mc","stem":"발해 생활 탐구 메모 ①~④를 함께 볼 때 발해를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"주변 나라와 교류하고 불교를 믿었으며, 신분에 따라 생활이 달랐던 나라","correct":true},{"t":"바깥과 오가지 않고 신분 차이도 없던 나라","mis":"SO5-2-u1-X25"},{"t":"불교를 막고 청동기만 쓰던 나라","mis":"SO5-2-u1-X21"},{"t":"연도와 왕 이름만 남은 나라","mis":"SO5-2-u1-X42"}],"explanation":["향로와 물건 팔기는 교류예요.","절터는 불교예요.","집은 신분에 따라 달랐어요."],"asset":{"type":"passage","lines":["① 초록·노랑·갈색 세 빛깔의 향로가 나왔다.","② 말과 짐승 가죽, 인삼을 이웃 나라에 팔았다.","③ 귀족은 넓은 땅과 기와집, 평민은 주로 초가집이었다.","④ 수도 자리에 절터와 불상, 어른 키 세 배의 석등이 남았다."],"title":"발해 생활 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L08_challenge#10','soc',5,2,'u1','L08','g5_2_soc_u1_L08_challenge','lesson_challenge','SO5-2-u1-C15',4,'essay','teacher','고구려와 발해를 견준 탐구 카드 가~라 가운데 두 가지를 골라, 발해가 고구려를 계승한 나라라고 말할 수 있는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C15","difficulty":4,"kind":"essay","stem":"고구려와 발해를 견준 탐구 카드 가~라 가운데 두 가지를 골라, 발해가 고구려를 계승한 나라라고 말할 수 있는 까닭을 쓰세요.","answer_guide":{"answer":"예: 가에서 고구려와 발해의 기와에 같은 꽃잎 무늬가 있어 건축 문화가 이어졌다고 볼 수 있다. 다에서 일본은 발해에서 온 사신을 고려(고구려) 사신이라 적어, 이웃 나라도 발해를 고구려를 이은 나라로 여겼다. 그래서 발해는 고구려를 계승한 나라라고 말할 수 있다.","scoring_points":["카드 두 가지를 골랐는가","카드마다 무엇이 이어졌는지 썼는가","고구려 계승이라는 결론을 썼는가"]},"explanation":["두 카드를 골라요.","닮은 점을 써요.","계승을 결론으로 써요."],"asset":{"type":"passage","lines":["가 — 고구려 기와와 이 나라 기와에 모두 꽃잎 무늬가 있다.","나 — 두 나라 집터 모두 방 한쪽 바닥을 데우는 시설이 있다.","다 — 일본 기록에 이 나라 사신을 「고려 사신」이라 적었다.","라 — 이 나라 왕이 스스로 고구려를 이었다고 밝혔다."],"title":"고구려와 발해를 견준 탐구 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_basic#1','soc',5,2,'u1','L09','g5_2_soc_u1_L09_basic','lesson_basic','SO5-2-u1-C17',1,'mc','auto','통일신라 말 지방에서 자라난 힘센 세력을 무엇이라고 하나요?',ARRAY['SO5-2-u1-X29']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C17","difficulty":1,"kind":"mc","stem":"통일신라 말 지방에서 자라난 힘센 세력을 무엇이라고 하나요?","options":[{"t":"호족","correct":true},{"t":"화랑","mis":"SO5-2-u1-X29"},{"t":"귀족","mis":"SO5-2-u1-X29"},{"t":"유민","mis":"SO5-2-u1-X29"}],"explanation":["지방의 세력이에요.","힘이 셌어요.","호족이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_basic#2','soc',5,2,'u1','L09','g5_2_soc_u1_L09_basic','lesson_basic','SO5-2-u1-C17',1,'sa','auto','궁예를 몰아내고 고려를 세운 사람은 누구인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u1-C17","difficulty":1,"kind":"sa","stem":"궁예를 몰아내고 고려를 세운 사람은 누구인가요? 두 글자로 쓰세요.","answer":["왕건"],"explanation":["궁예의 부하였어요.","후삼국을 통일했어요.","왕건이에요."],"mis":"SO5-2-u1-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_basic#3','soc',5,2,'u1','L09','g5_2_soc_u1_L09_basic','lesson_basic','SO5-2-u1-C17',1,'mc','auto','견훤이 세운 나라는 어느 것인가요?',ARRAY['SO5-2-u1-X29','SO5-2-u1-X27']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C17","difficulty":1,"kind":"mc","stem":"견훤이 세운 나라는 어느 것인가요?","options":[{"t":"후백제","correct":true},{"t":"후고구려","mis":"SO5-2-u1-X29"},{"t":"고려","mis":"SO5-2-u1-X29"},{"t":"발해","mis":"SO5-2-u1-X27"}],"explanation":["견훤은 호족이에요.","백제를 이었다고 내세웠어요.","후백제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_basic#4','soc',5,2,'u1','L09','g5_2_soc_u1_L09_basic','lesson_basic','SO5-2-u1-C17',1,'ox','auto','「고려」라는 나라 이름에는 고구려를 계승한다는 뜻이 담겨 있어요.',ARRAY['SO5-2-u1-X30']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C17","difficulty":1,"kind":"ox","stem":"「고려」라는 나라 이름에는 고구려를 계승한다는 뜻이 담겨 있어요.","answer":"O","reason_options":[{"t":"왕건이 고구려를 잇는다는 뜻으로 나라 이름을 정했기 때문에","correct":true},{"t":"고려는 신라를 잇는다는 뜻이기 때문에","mis":"SO5-2-u1-X30"}],"mis":"SO5-2-u1-X30","explanation":["고구려를 줄여 고려라고도 불렀어요.","그 뜻을 담았어요.","고구려 계승이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_basic#5','soc',5,2,'u1','L09','g5_2_soc_u1_L09_basic','lesson_basic','SO5-2-u1-C17',2,'mc','auto','후삼국에서 통일까지 기록 메모 ④의 「궁예의 부하」는 누구인가요?',ARRAY['SO5-2-u1-X29','SO5-2-u1-X27','SO5-2-u1-X12']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C17","difficulty":2,"kind":"mc","stem":"후삼국에서 통일까지 기록 메모 ④의 「궁예의 부하」는 누구인가요?","options":[{"t":"왕건","correct":true},{"t":"견훤","mis":"SO5-2-u1-X29"},{"t":"대조영","mis":"SO5-2-u1-X27"},{"t":"단군왕검","mis":"SO5-2-u1-X12"}],"explanation":["궁예를 몰아냈어요.","새 나라를 세웠어요.","왕건이에요."],"asset":{"type":"passage","lines":["① 통일신라 말 귀족들의 다툼으로 나라가 어지러워졌다.","② 지방에서 힘센 세력들이 자라났다.","③ 견훤이 후백제를, 궁예가 후고구려를 세웠다.","④ 궁예의 부하가 궁예를 몰아내고 새 나라를 세웠다.","⑤ 새 나라가 신라의 항복을 받고 후백제를 물리쳤다."],"title":"후삼국에서 통일까지 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_basic#6','soc',5,2,'u1','L09','g5_2_soc_u1_L09_basic','lesson_basic','SO5-2-u1-C17',2,'mc','auto','어느 역사 기록으로 알 수 있는 왕건이 발해 유민을 대한 방법은 어느 것인가요?',ARRAY['SO5-2-u1-X30']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C17","difficulty":2,"kind":"mc","stem":"어느 역사 기록으로 알 수 있는 왕건이 발해 유민을 대한 방법은 어느 것인가요?","options":[{"t":"친척처럼 받아들여 벼슬과 땅, 집을 주었다","correct":true},{"t":"나라 밖으로 내쫓았다","mis":"SO5-2-u1-X30"},{"t":"모두 노비로 삼았다","mis":"SO5-2-u1-X30"},{"t":"발해로 돌려보냈다","mis":"SO5-2-u1-X30"}],"explanation":["왕 씨 성을 주었어요.","관직과 땅을 주었어요.","친척처럼 받아들였어요."],"asset":{"type":"passage","lines":["거란에 나라를 잃은 발해의 세자가 많은 백성을 이끌고 왔다.","왕은 세자에게 왕 씨 성과 벼슬을 주었다.","따라온 사람들에게도 관직과 땅, 집을 나누어 주었다."],"title":"어느 역사 기록(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_basic#7','soc',5,2,'u1','L09','g5_2_soc_u1_L09_basic','lesson_basic','SO5-2-u1-C17',2,'mc','auto','왕건이 백성을 위해 한 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X31']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C17","difficulty":2,"kind":"mc","stem":"왕건이 백성을 위해 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"세금을 줄여 백성의 생활을 안정시켰다","correct":true},{"t":"세금을 크게 올렸다","mis":"SO5-2-u1-X31"},{"t":"백성을 모두 노비로 삼았다","mis":"SO5-2-u1-X31"},{"t":"농사를 금지했다","mis":"SO5-2-u1-X31"}],"explanation":["백성이 힘들었어요.","세금을 줄였어요.","생활이 안정됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_basic#8','soc',5,2,'u1','L09','g5_2_soc_u1_L09_basic','lesson_basic','SO5-2-u1-C17',2,'mc','auto','서양에서 만든 옛 지도에 우리나라가 「COREA」로 적힌 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X42','SO5-2-u1-X27']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C17","difficulty":2,"kind":"mc","stem":"서양에서 만든 옛 지도에 우리나라가 「COREA」로 적힌 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"고려와 교류한 상인들이 「고려」라는 이름을 바깥 세상에 전해서","correct":true},{"t":"고조선 사람들이 서양에 이름을 알려서","mis":"SO5-2-u1-X42"},{"t":"발해가 서양과 전쟁을 해서","mis":"SO5-2-u1-X27"},{"t":"오늘날 새로 지은 이름이라서","mis":"SO5-2-u1-X42"}],"explanation":["아라비아 상인도 왔어요.","고려라는 이름을 전했어요.","COREA가 되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_basic#9','soc',5,2,'u1','L09','g5_2_soc_u1_L09_basic','lesson_basic','SO5-2-u1-C17',2,'ox','auto','고려는 신라의 항복을 받고 후백제를 물리쳐 후삼국을 통일했어요.',ARRAY['SO5-2-u1-X29']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C17","difficulty":2,"kind":"ox","stem":"고려는 신라의 항복을 받고 후백제를 물리쳐 후삼국을 통일했어요.","answer":"O","reason_options":[{"t":"신라가 스스로 고려에 들어오고 후백제는 싸워 이겼기 때문에","correct":true},{"t":"고려는 후삼국과 싸우지 않고 사라졌기 때문에","mis":"SO5-2-u1-X29"}],"mis":"SO5-2-u1-X29","explanation":["신라가 항복했어요.","후백제를 물리쳤어요.","후삼국이 하나가 됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_basic#10','soc',5,2,'u1','L09','g5_2_soc_u1_L09_basic','lesson_basic','SO5-2-u1-C17',3,'error','auto','후삼국을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X29']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C17","difficulty":3,"kind":"error","stem":"후삼국을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「궁예는 후백제를, 견훤은 후고구려를 세웠어.」","correct":true,"mis_target":"SO5-2-u1-X29"},{"t":"태호 — 「후삼국은 후백제·후고구려·신라야.」","mis":"SO5-2-u1-X29"},{"t":"나래 — 「지방의 호족이 자라 새 나라를 세웠어.」","mis":"SO5-2-u1-X29"}],"explanation":["견훤은 후백제예요.","궁예는 후고구려예요.","지민이 거꾸로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_challenge#1','soc',5,2,'u1','L09','g5_2_soc_u1_L09_challenge','lesson_challenge','SO5-2-u1-C17',2,'mc','auto','후삼국에서 통일까지 기록 메모 ①~⑤를 차례로 볼 때 ②의 세력이 ③에서 한 일은 어느 것인가요?',ARRAY['SO5-2-u1-X29','SO5-2-u1-X27','SO5-2-u1-X23']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C17","difficulty":2,"kind":"mc","stem":"후삼국에서 통일까지 기록 메모 ①~⑤를 차례로 볼 때 ②의 세력이 ③에서 한 일은 어느 것인가요?","options":[{"t":"새 나라를 세웠다","correct":true},{"t":"신라를 통일했다","mis":"SO5-2-u1-X29"},{"t":"발해를 세웠다","mis":"SO5-2-u1-X27"},{"t":"당과 손잡았다","mis":"SO5-2-u1-X23"}],"explanation":["②는 호족이에요.","견훤과 궁예도 호족이에요.","새 나라를 세웠어요."],"asset":{"type":"passage","lines":["① 통일신라 말 귀족들의 다툼으로 나라가 어지러워졌다.","② 지방에서 힘센 세력들이 자라났다.","③ 견훤이 후백제를, 궁예가 후고구려를 세웠다.","④ 궁예의 부하가 궁예를 몰아내고 새 나라를 세웠다.","⑤ 새 나라가 신라의 항복을 받고 후백제를 물리쳤다."],"title":"후삼국에서 통일까지 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_challenge#2','soc',5,2,'u1','L09','g5_2_soc_u1_L09_challenge','lesson_challenge','SO5-2-u1-C17',2,'match','auto','인물과 한 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u1-C17","difficulty":2,"kind":"match","stem":"인물과 한 일을 알맞게 이으세요.","pairs":[{"l":"견훤","r":"후백제를 세움"},{"l":"궁예","r":"후고구려를 세움"},{"l":"왕건","r":"고려를 세우고 후삼국을 통일함"}],"mis":"SO5-2-u1-X29","explanation":["견훤은 후백제예요.","궁예는 후고구려예요.","왕건은 고려예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_challenge#3','soc',5,2,'u1','L09','g5_2_soc_u1_L09_challenge','lesson_challenge','SO5-2-u1-C17',3,'mc','auto','훈요 10조 가운데 「서경(평양)을 중요하게 여길 것」으로 짐작할 수 있는 왕건의 생각은 어느 것인가요?',ARRAY['SO5-2-u1-X30','SO5-2-u1-X34','SO5-2-u1-X33']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C17","difficulty":3,"kind":"mc","stem":"훈요 10조 가운데 「서경(평양)을 중요하게 여길 것」으로 짐작할 수 있는 왕건의 생각은 어느 것인가요?","options":[{"t":"고구려를 잇고 북쪽의 옛 땅을 되찾고 싶었다","correct":true},{"t":"수도를 신라 땅으로 옮기고 싶었다","mis":"SO5-2-u1-X30"},{"t":"거란과 가깝게 지내고 싶었다","mis":"SO5-2-u1-X34"},{"t":"불교를 없애고 싶었다","mis":"SO5-2-u1-X33"}],"explanation":["평양은 고구려의 옛 수도예요.","그곳을 중히 여기라 했어요.","고구려 계승과 북쪽 땅이에요."],"asset":{"type":"passage","lines":["하나 — 불교를 잘 받들 것","둘 — 서경(평양)을 중요하게 여길 것","셋 — 백성의 세금을 가볍게 할 것","넷 — 거란의 풍속과 말을 본받지 말 것"],"title":"훈요 10조 가운데 일부(쉬운 말)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_challenge#4','soc',5,2,'u1','L09','g5_2_soc_u1_L09_challenge','lesson_challenge','SO5-2-u1-C17',3,'mc','auto','훈요 10조 가운데 「넷」으로 보아 고려가 거란을 어떻게 여겼는지 가장 알맞게 짐작한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X34']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C17","difficulty":3,"kind":"mc","stem":"훈요 10조 가운데 「넷」으로 보아 고려가 거란을 어떻게 여겼는지 가장 알맞게 짐작한 것은 어느 것인가요?","options":[{"t":"발해를 무너뜨린 거란을 경계하고 멀리했다","correct":true},{"t":"거란을 가장 가까운 친구로 여겼다","mis":"SO5-2-u1-X34"},{"t":"거란의 풍속을 모두 따르려 했다","mis":"SO5-2-u1-X34"},{"t":"거란과 하나의 나라가 되려 했다","mis":"SO5-2-u1-X34"}],"explanation":["거란을 본받지 말라 했어요.","거란은 발해를 무너뜨렸어요.","경계하고 멀리했어요."],"asset":{"type":"passage","lines":["하나 — 불교를 잘 받들 것","둘 — 서경(평양)을 중요하게 여길 것","셋 — 백성의 세금을 가볍게 할 것","넷 — 거란의 풍속과 말을 본받지 말 것"],"title":"훈요 10조 가운데 일부(쉬운 말)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_challenge#5','soc',5,2,'u1','L09','g5_2_soc_u1_L09_challenge','lesson_challenge','SO5-2-u1-C17',3,'ox','auto','왕건이 발해 유민을 받아들인 것은 고려가 고구려를 계승한 나라라는 생각과 이어져요.',ARRAY['SO5-2-u1-X30']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C17","difficulty":3,"kind":"ox","stem":"왕건이 발해 유민을 받아들인 것은 고려가 고구려를 계승한 나라라는 생각과 이어져요.","answer":"O","reason_options":[{"t":"발해도 고구려를 이은 나라라서 그 백성을 같은 뿌리로 여겼기 때문에","correct":true},{"t":"발해 유민은 신라 사람이었기 때문에","mis":"SO5-2-u1-X30"}],"mis":"SO5-2-u1-X30","explanation":["발해는 고구려를 이었어요.","고려도 고구려를 이었어요.","같은 뿌리로 여겼어요."],"asset":{"type":"passage","lines":["거란에 나라를 잃은 발해의 세자가 많은 백성을 이끌고 왔다.","왕은 세자에게 왕 씨 성과 벼슬을 주었다.","따라온 사람들에게도 관직과 땅, 집을 나누어 주었다."],"title":"어느 역사 기록(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_challenge#6','soc',5,2,'u1','L09','g5_2_soc_u1_L09_challenge','lesson_challenge','SO5-2-u1-C17',3,'error','auto','고려의 건국을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X30','SO5-2-u1-X31']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C17","difficulty":3,"kind":"error","stem":"고려의 건국을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 「왕건은 발해 유민이 오자 나라 밖으로 돌려보냈어.」","correct":true,"mis_target":"SO5-2-u1-X30"},{"t":"현우 — 「왕건은 세금을 줄여 백성의 생활을 안정시켰어.」","mis":"SO5-2-u1-X31"},{"t":"소이 — 「왕건은 뒤의 왕들에게 훈요 10조를 남겼어.」","mis":"SO5-2-u1-X30"}],"explanation":["왕건은 유민을 받아들였어요.","친척처럼 대했어요.","은솔의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["거란에 나라를 잃은 발해의 세자가 많은 백성을 이끌고 왔다.","왕은 세자에게 왕 씨 성과 벼슬을 주었다.","따라온 사람들에게도 관직과 땅, 집을 나누어 주었다."],"title":"어느 역사 기록(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_challenge#7','soc',5,2,'u1','L09','g5_2_soc_u1_L09_challenge','lesson_challenge','SO5-2-u1-C17',3,'mc','auto','통일신라 말 호족이 자라난 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X29','SO5-2-u1-X23','SO5-2-u1-X15']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C17","difficulty":3,"kind":"mc","stem":"통일신라 말 호족이 자라난 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"귀족들의 다툼으로 나라가 어지러워져 나라의 힘이 지방까지 미치지 못해서","correct":true},{"t":"나라가 아주 튼튼해져서","mis":"SO5-2-u1-X29"},{"t":"당이 지방을 다스려서","mis":"SO5-2-u1-X23"},{"t":"고조선이 다시 세워져서","mis":"SO5-2-u1-X15"}],"explanation":["귀족들이 다투었어요.","나라가 어지러워졌어요.","지방 세력이 자랐어요."],"asset":{"type":"passage","lines":["① 통일신라 말 귀족들의 다툼으로 나라가 어지러워졌다.","② 지방에서 힘센 세력들이 자라났다.","③ 견훤이 후백제를, 궁예가 후고구려를 세웠다.","④ 궁예의 부하가 궁예를 몰아내고 새 나라를 세웠다.","⑤ 새 나라가 신라의 항복을 받고 후백제를 물리쳤다."],"title":"후삼국에서 통일까지 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_challenge#8','soc',5,2,'u1','L09','g5_2_soc_u1_L09_challenge','lesson_challenge','SO5-2-u1-C17',4,'mc','auto','고려가 후삼국을 통일한 과정에서 신라 왕을 정중히 맞아 높은 자리를 준 것이 통일에 도움이 된 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X29','SO5-2-u1-X30']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C17","difficulty":4,"kind":"mc","stem":"고려가 후삼국을 통일한 과정에서 신라 왕을 정중히 맞아 높은 자리를 준 것이 통일에 도움이 된 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이를 본 호족과 신라 사람들이 고려 편에 서서 힘이 모였기 때문에","correct":true},{"t":"신라 왕이 혼자 후백제를 무찔렀기 때문에","mis":"SO5-2-u1-X29"},{"t":"신라 사람들이 모두 발해로 떠났기 때문에","mis":"SO5-2-u1-X30"},{"t":"고려가 신라 땅을 버렸기 때문에","mis":"SO5-2-u1-X29"}],"explanation":["신라 왕을 존중했어요.","사람들 마음이 고려로 모였어요.","통일에 힘이 됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_challenge#9','soc',5,2,'u1','L09','g5_2_soc_u1_L09_challenge','lesson_challenge','SO5-2-u1-C17',4,'mc','auto','고려의 건국 과정을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X29','SO5-2-u1-X30']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C17","difficulty":4,"kind":"mc","stem":"고려의 건국 과정을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"통일신라 말 호족이 자라 후삼국이 되었고, 왕건이 고구려를 잇는 고려를 세워 후삼국을 통일하고 발해 유민까지 받아들였다","correct":true},{"t":"견훤이 고려를 세워 발해를 무너뜨렸다","mis":"SO5-2-u1-X29"},{"t":"신라가 후백제와 손잡아 고려를 무너뜨렸다","mis":"SO5-2-u1-X29"},{"t":"고려는 신라를 잇는다는 뜻으로 세운 나라다","mis":"SO5-2-u1-X30"}],"explanation":["호족과 후삼국이에요.","왕건이 통일했어요.","발해 유민까지 품었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L09_challenge#10','soc',5,2,'u1','L09','g5_2_soc_u1_L09_challenge','lesson_challenge','SO5-2-u1-C17',4,'essay','teacher','어느 역사 기록과 훈요 10조 가운데 일부를 함께 보고, 왕건이 만들고 싶었던 고려의 모습을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C17","difficulty":4,"kind":"essay","stem":"어느 역사 기록과 훈요 10조 가운데 일부를 함께 보고, 왕건이 만들고 싶었던 고려의 모습을 두 가지 쓰세요.","answer_guide":{"answer":"예: 왕건은 발해의 세자와 백성을 친척처럼 받아들이고 서경(평양)을 중요하게 여기라고 해, 고구려를 잇고 북쪽 옛 땅을 되찾는 나라를 만들고 싶었다. 또 백성의 세금을 가볍게 하라고 해, 백성의 생활이 안정된 나라를 만들고 싶었다.","scoring_points":["고구려 계승·북쪽 땅과 관련된 모습을 썼는가","백성·세금과 관련된 모습을 썼는가","자료를 근거로 들었는가"]},"explanation":["발해 유민을 받아들였어요.","서경을 중히 여겼어요.","세금을 가볍게 했어요."],"asset":{"type":"passage","lines":["하나 — 불교를 잘 받들 것","둘 — 서경(평양)을 중요하게 여길 것","셋 — 백성의 세금을 가볍게 할 것","넷 — 거란의 풍속과 말을 본받지 말 것"],"title":"훈요 10조 가운데 일부(쉬운 말)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_basic#1','soc',5,2,'u1','L10','g5_2_soc_u1_L10_basic','lesson_basic','SO5-2-u1-C18',1,'mc','auto','시험을 보아 실력 있는 사람을 관리로 뽑은 고려의 제도는 어느 것인가요?',ARRAY['SO5-2-u1-X31']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C18","difficulty":1,"kind":"mc","stem":"시험을 보아 실력 있는 사람을 관리로 뽑은 고려의 제도는 어느 것인가요?","options":[{"t":"과거제","correct":true},{"t":"8조법","mis":"SO5-2-u1-X31"},{"t":"화랑","mis":"SO5-2-u1-X31"},{"t":"훈요 10조","mis":"SO5-2-u1-X31"}],"explanation":["시험을 봐요.","관리를 뽑아요.","과거제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_basic#2','soc',5,2,'u1','L10','g5_2_soc_u1_L10_basic','lesson_basic','SO5-2-u1-C18',1,'mc','auto','고려의 신분을 크게 나눈 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X20','SO5-2-u1-X29']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C18","difficulty":1,"kind":"mc","stem":"고려의 신분을 크게 나눈 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"양인과 천인","correct":true},{"t":"귀족·평민·천민","mis":"SO5-2-u1-X20"},{"t":"호족과 화랑","mis":"SO5-2-u1-X29"},{"t":"왕과 지배자","mis":"SO5-2-u1-X20"}],"explanation":["크게 둘로 나뉘었어요.","양인 안에 관리와 백성이 있어요.","양인과 천인이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_basic#3','soc',5,2,'u1','L10','g5_2_soc_u1_L10_basic','lesson_basic','SO5-2-u1-C19',1,'sa','auto','고려 때 등불을 밝히고 소원을 빈 불교 행사를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u1-C19","difficulty":1,"kind":"sa","stem":"고려 때 등불을 밝히고 소원을 빈 불교 행사를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["연등회"],"explanation":["등불을 밝혀요.","소원을 빌어요.","연등회예요."],"mis":"SO5-2-u1-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_basic#4','soc',5,2,'u1','L10','g5_2_soc_u1_L10_basic','lesson_basic','SO5-2-u1-C19',1,'ox','auto','고려 때에는 아들과 딸이 부모의 재산을 똑같이 나누어 받았어요.',ARRAY['SO5-2-u1-X32']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C19","difficulty":1,"kind":"ox","stem":"고려 때에는 아들과 딸이 부모의 재산을 똑같이 나누어 받았어요.","answer":"O","reason_options":[{"t":"고려 여성은 집안에서 남성과 같은 지위를 가졌기 때문에","correct":true},{"t":"고려 여성은 재산을 전혀 받을 수 없었기 때문에","mis":"SO5-2-u1-X32"}],"mis":"SO5-2-u1-X32","explanation":["유산을 똑같이 받았어요.","제사도 돌아가며 지냈어요.","집안에서 같은 지위였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_basic#5','soc',5,2,'u1','L10','g5_2_soc_u1_L10_basic','lesson_basic','SO5-2-u1-C18',2,'mc','auto','고려 초 왕들의 새 정책 ㉮~㉰를 펼친 결과로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X31','SO5-2-u1-X29']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C18","difficulty":2,"kind":"mc","stem":"고려 초 왕들의 새 정책 ㉮~㉰를 펼친 결과로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"호족의 힘이 약해지고 나라를 더 잘 다스리게 되었다","correct":true},{"t":"호족의 힘이 더 세졌다","mis":"SO5-2-u1-X31"},{"t":"나라가 다시 셋으로 나뉘었다","mis":"SO5-2-u1-X29"},{"t":"노비가 더 많아졌다","mis":"SO5-2-u1-X31"}],"explanation":["노비를 풀어 주었어요.","관리를 시험으로 뽑고 지방에 보냈어요.","호족의 힘이 약해졌어요."],"asset":{"type":"passage","lines":["㉮ 억울하게 노비가 된 사람을 풀어 주었다.","㉯ 시험을 보아 실력 있는 사람을 관리로 뽑았다.","㉰ 주요 지방에 나라의 관리를 보냈다."],"title":"고려 초 왕들의 새 정책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_basic#6','soc',5,2,'u1','L10','g5_2_soc_u1_L10_basic','lesson_basic','SO5-2-u1-C18',2,'mc','auto','고려 때 과거에 붙은 사람이 받은, 붉은 종이에 왕의 도장이 찍힌 합격증은 어느 것인가요?',ARRAY['SO5-2-u1-X24','SO5-2-u1-X31','SO5-2-u1-X38']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C18","difficulty":2,"kind":"mc","stem":"고려 때 과거에 붙은 사람이 받은, 붉은 종이에 왕의 도장이 찍힌 합격증은 어느 것인가요?","options":[{"t":"홍패","correct":true},{"t":"촌락 문서","mis":"SO5-2-u1-X24"},{"t":"훈요 10조","mis":"SO5-2-u1-X31"},{"t":"직지","mis":"SO5-2-u1-X38"}],"explanation":["붉은 종이예요.","왕의 도장이 찍혔어요.","홍패예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_basic#7','soc',5,2,'u1','L10','g5_2_soc_u1_L10_basic','lesson_basic','SO5-2-u1-C19',2,'mc','auto','고려의 큰 행사 메모 나는 어느 행사인가요?',ARRAY['SO5-2-u1-X33']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C19","difficulty":2,"kind":"mc","stem":"고려의 큰 행사 메모 나는 어느 행사인가요?","options":[{"t":"팔관회","correct":true},{"t":"연등회","mis":"SO5-2-u1-X33"},{"t":"제천 행사","mis":"SO5-2-u1-X33"},{"t":"8조법","mis":"SO5-2-u1-X33"}],"explanation":["11월에 열렸어요.","온 세상의 평안을 빌었어요.","팔관회예요."],"asset":{"type":"passage","lines":["가 — 해마다 초에 등불을 밝히고 소원을 빌었다.","나 — 11월에 춤·노래·놀이로 온 세상의 평안을 빌었다.","다 — 오늘날 부처님 오신 날 무렵 거리에 등 행렬이 이어진다."],"title":"고려의 큰 행사 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_basic#8','soc',5,2,'u1','L10','g5_2_soc_u1_L10_basic','lesson_basic','SO5-2-u1-C19',2,'mc','auto','고려 여성의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X32']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C19","difficulty":2,"kind":"mc","stem":"고려 여성의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"사회 활동은 자유롭지 않았지만 집안에서는 남성과 같은 지위였다","correct":true},{"t":"관리가 되어 나라 일을 마음껏 했다","mis":"SO5-2-u1-X32"},{"t":"집안에서도 아무 권리가 없었다","mis":"SO5-2-u1-X32"},{"t":"재산은 아들만 받았다","mis":"SO5-2-u1-X32"}],"explanation":["나라 일은 어려웠어요.","집안에서는 같은 지위였어요.","둘을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_basic#9','soc',5,2,'u1','L10','g5_2_soc_u1_L10_basic','lesson_basic','SO5-2-u1-C18',2,'ox','auto','고려 때에도 전쟁에서 공을 세우면 신분이 오르기도 했어요.',ARRAY['SO5-2-u1-X20']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C18","difficulty":2,"kind":"ox","stem":"고려 때에도 전쟁에서 공을 세우면 신분이 오르기도 했어요.","answer":"O","reason_options":[{"t":"공을 세운 사람에게 벼슬을 주어 신분이 바뀌기도 했기 때문에","correct":true},{"t":"고려의 신분은 어떤 일이 있어도 절대 바뀌지 않았기 때문에","mis":"SO5-2-u1-X20"}],"mis":"SO5-2-u1-X20","explanation":["신분은 나뉘었어요.","공을 세우면 오르기도 했어요.","바뀔 길이 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_basic#10','soc',5,2,'u1','L10','g5_2_soc_u1_L10_basic','lesson_basic','SO5-2-u1-C19',3,'error','auto','고려 사회를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X32']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C19","difficulty":3,"kind":"error","stem":"고려 사회를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하진 — 「고려 여성은 관리가 되어 나라 일을 자유롭게 했어.」","correct":true,"mis_target":"SO5-2-u1-X32"},{"t":"수빈 — 「아들딸이 돌아가며 제사를 지냈어.」","mis":"SO5-2-u1-X32"},{"t":"도원 — 「여성이 집안의 가장이 되기도 했어.」","mis":"SO5-2-u1-X32"}],"explanation":["집안에서는 같은 지위였어요.","사회 활동은 자유롭지 않았어요.","하진의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_challenge#1','soc',5,2,'u1','L10','g5_2_soc_u1_L10_challenge','lesson_challenge','SO5-2-u1-C18',2,'match','auto','고려 초 왕들의 새 정책과 그 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C18","difficulty":2,"kind":"match","stem":"고려 초 왕들의 새 정책과 그 결과를 알맞게 이으세요.","pairs":[{"l":"㉮ 노비를 풀어 줌","r":"호족이 거느린 사람이 줄어듦"},{"l":"㉯ 시험으로 관리를 뽑음","r":"실력 있는 관리가 나라 일을 맡음"},{"l":"㉰ 지방에 관리를 보냄","r":"나라의 힘이 지방까지 미침"}],"mis":"SO5-2-u1-X31","explanation":["호족의 노비가 줄었어요.","관리를 실력으로 뽑았어요.","지방도 나라가 다스렸어요."],"asset":{"type":"passage","lines":["㉮ 억울하게 노비가 된 사람을 풀어 주었다.","㉯ 시험을 보아 실력 있는 사람을 관리로 뽑았다.","㉰ 주요 지방에 나라의 관리를 보냈다."],"title":"고려 초 왕들의 새 정책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_challenge#2','soc',5,2,'u1','L10','g5_2_soc_u1_L10_challenge','lesson_challenge','SO5-2-u1-C19',2,'mc','auto','고려의 큰 행사 메모 다로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X33']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C19","difficulty":2,"kind":"mc","stem":"고려의 큰 행사 메모 다로 알 수 있는 것은 어느 것인가요?","options":[{"t":"고려 때 연등회의 전통이 오늘날까지 이어지고 있다","correct":true},{"t":"연등회는 오늘날 처음 생겼다","mis":"SO5-2-u1-X33"},{"t":"팔관회가 오늘날 등 행렬이 되었다","mis":"SO5-2-u1-X33"},{"t":"고려의 행사는 모두 사라졌다","mis":"SO5-2-u1-X33"}],"explanation":["등을 밝혀요.","가와 같은 행사예요.","연등회가 이어졌어요."],"asset":{"type":"passage","lines":["가 — 해마다 초에 등불을 밝히고 소원을 빌었다.","나 — 11월에 춤·노래·놀이로 온 세상의 평안을 빌었다.","다 — 오늘날 부처님 오신 날 무렵 거리에 등 행렬이 이어진다."],"title":"고려의 큰 행사 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_challenge#3','soc',5,2,'u1','L10','g5_2_soc_u1_L10_challenge','lesson_challenge','SO5-2-u1-C18',3,'mc','auto','과거제를 연 것이 호족의 힘을 약하게 한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X31']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C18","difficulty":3,"kind":"mc","stem":"과거제를 연 것이 호족의 힘을 약하게 한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"집안의 힘이 아니라 시험 실력으로 관리를 뽑아 나라가 관리를 직접 정했기 때문에","correct":true},{"t":"호족만 시험을 볼 수 있었기 때문에","mis":"SO5-2-u1-X31"},{"t":"돈을 내면 관리가 되었기 때문에","mis":"SO5-2-u1-X31"},{"t":"시험을 보면 노비가 되었기 때문에","mis":"SO5-2-u1-X31"}],"explanation":["실력으로 뽑았어요.","나라가 관리를 정했어요.","호족의 손이 줄었어요."],"asset":{"type":"passage","lines":["㉮ 억울하게 노비가 된 사람을 풀어 주었다.","㉯ 시험을 보아 실력 있는 사람을 관리로 뽑았다.","㉰ 주요 지방에 나라의 관리를 보냈다."],"title":"고려 초 왕들의 새 정책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_challenge#4','soc',5,2,'u1','L10','g5_2_soc_u1_L10_challenge','lesson_challenge','SO5-2-u1-C19',3,'mc','auto','고려 때 남매의 재산 다툼 이야기에서 손변이 재산을 반씩 나누게 한 것으로 알 수 있는 고려 사회의 모습은 어느 것인가요?',ARRAY['SO5-2-u1-X32']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C19","difficulty":3,"kind":"mc","stem":"고려 때 남매의 재산 다툼 이야기에서 손변이 재산을 반씩 나누게 한 것으로 알 수 있는 고려 사회의 모습은 어느 것인가요?","options":[{"t":"아들과 딸이 재산을 똑같이 나누어 받는 것이 마땅하다고 여겼다","correct":true},{"t":"재산은 딸만 받는 것이 법이었다","mis":"SO5-2-u1-X32"},{"t":"재산은 아들만 받아야 했다","mis":"SO5-2-u1-X32"},{"t":"관청은 집안일에 관심이 없었다","mis":"SO5-2-u1-X32"}],"explanation":["반씩 나누게 했어요.","아들딸이 똑같아요.","고려의 생각이 보여요."],"asset":{"type":"passage","lines":["아버지가 죽으며 재산을 모두 누나에게 주었다.","어린 남동생에게는 옷·모자·신발 한 벌과 종이 한 장만 남겼다.","자란 남동생이 억울하다며 관청에 따졌다.","관리 손변은 아버지의 뜻을 짚어 재산을 반씩 나누게 했다."],"title":"고려 때 남매의 재산 다툼 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_challenge#5','soc',5,2,'u1','L10','g5_2_soc_u1_L10_challenge','lesson_challenge','SO5-2-u1-C19',3,'ox','auto','연등회와 팔관회가 크게 열린 것은 고려에서 불교가 나라의 도움으로 크게 자랐기 때문이에요.',ARRAY['SO5-2-u1-X33']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C19","difficulty":3,"kind":"ox","stem":"연등회와 팔관회가 크게 열린 것은 고려에서 불교가 나라의 도움으로 크게 자랐기 때문이에요.","answer":"O","reason_options":[{"t":"나라가 불교를 받들어 전국에 절과 탑이 세워지고 큰 행사가 열렸기 때문에","correct":true},{"t":"고려는 불교를 금지했기 때문에","mis":"SO5-2-u1-X33"}],"mis":"SO5-2-u1-X33","explanation":["나라가 불교를 도왔어요.","절과 탑이 많아졌어요.","큰 행사가 열렸어요."],"asset":{"type":"passage","lines":["가 — 해마다 초에 등불을 밝히고 소원을 빌었다.","나 — 11월에 춤·노래·놀이로 온 세상의 평안을 빌었다.","다 — 오늘날 부처님 오신 날 무렵 거리에 등 행렬이 이어진다."],"title":"고려의 큰 행사 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_challenge#6','soc',5,2,'u1','L10','g5_2_soc_u1_L10_challenge','lesson_challenge','SO5-2-u1-C18',3,'error','auto','고려의 신분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X20']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C18","difficulty":3,"kind":"error","stem":"고려의 신분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「고려에는 노비가 하나도 없었어.」","correct":true,"mis_target":"SO5-2-u1-X20"},{"t":"주하 — 「천인에는 지배층을 위해 일한 노비가 많았어.」","mis":"SO5-2-u1-X20"},{"t":"세윤 — 「양인에는 관리와 농사짓는 백성이 있었어.」","mis":"SO5-2-u1-X20"}],"explanation":["노비를 풀어 주기도 했지만","천인에 노비가 많았어요.","라온의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_challenge#7','soc',5,2,'u1','L10','g5_2_soc_u1_L10_challenge','lesson_challenge','SO5-2-u1-C19',3,'mc','auto','고려 때 남매의 재산 다툼 이야기에서 아버지가 어린 남동생에게 옷·모자·신발과 종이를 남긴 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X32']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C19","difficulty":3,"kind":"mc","stem":"고려 때 남매의 재산 다툼 이야기에서 아버지가 어린 남동생에게 옷·모자·신발과 종이를 남긴 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다 크면 그것을 입고 관청에 와서 바로잡으라는 뜻","correct":true},{"t":"남동생을 미워했다는 뜻","mis":"SO5-2-u1-X32"},{"t":"딸만 자식으로 여겼다는 뜻","mis":"SO5-2-u1-X32"},{"t":"재산은 모두 나라에 주라는 뜻","mis":"SO5-2-u1-X32"}],"explanation":["누나가 동생을 돌보게 했어요.","자라면 관청에 가라 했어요.","나중에 바로잡으라는 뜻이에요."],"asset":{"type":"passage","lines":["아버지가 죽으며 재산을 모두 누나에게 주었다.","어린 남동생에게는 옷·모자·신발 한 벌과 종이 한 장만 남겼다.","자란 남동생이 억울하다며 관청에 따졌다.","관리 손변은 아버지의 뜻을 짚어 재산을 반씩 나누게 했다."],"title":"고려 때 남매의 재산 다툼 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_challenge#8','soc',5,2,'u1','L10','g5_2_soc_u1_L10_challenge','lesson_challenge','SO5-2-u1-C18',4,'mc','auto','고려 초 정책과 신분 제도를 함께 볼 때 고려 사회를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X31','SO5-2-u1-X20']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C18","difficulty":4,"kind":"mc","stem":"고려 초 정책과 신분 제도를 함께 볼 때 고려 사회를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"왕이 호족의 힘을 줄여 나라의 틀을 다졌고, 양인과 천인으로 신분이 나뉘었지만 신분이 오르는 길도 있었다","correct":true},{"t":"호족이 왕보다 힘이 세서 나라를 다스렸다","mis":"SO5-2-u1-X31"},{"t":"신분 차이가 전혀 없는 사회였다","mis":"SO5-2-u1-X20"},{"t":"과거제로 노비만 관리가 되었다","mis":"SO5-2-u1-X31"}],"explanation":["호족의 힘을 줄였어요.","신분은 둘로 나뉘었어요.","오르는 길도 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_challenge#9','soc',5,2,'u1','L10','g5_2_soc_u1_L10_challenge','lesson_challenge','SO5-2-u1-C19',4,'mc','auto','「고려 여성은 집안에서 아무 권리가 없었다」는 주장을 바로잡는 근거로 가장 알맞은 묶음은 어느 것인가요?',ARRAY['SO5-2-u1-X32','SO5-2-u1-X19','SO5-2-u1-X33']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C19","difficulty":4,"kind":"mc","stem":"「고려 여성은 집안에서 아무 권리가 없었다」는 주장을 바로잡는 근거로 가장 알맞은 묶음은 어느 것인가요?","options":[{"t":"유산을 똑같이 받고, 돌아가며 제사를 지내고, 집안의 가장이 되기도 했다","correct":true},{"t":"관리가 되어 나라 일을 했다","mis":"SO5-2-u1-X32"},{"t":"비단옷을 입고 기와집에 살았다","mis":"SO5-2-u1-X19"},{"t":"연등회에서 등불을 밝혔다","mis":"SO5-2-u1-X33"}],"explanation":["유산을 똑같이 받았어요.","제사도 맡았어요.","가장도 되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L10_challenge#10','soc',5,2,'u1','L10','g5_2_soc_u1_L10_challenge','lesson_challenge','SO5-2-u1-C19',4,'essay','teacher','고려의 큰 행사 메모를 보고 연등회와 팔관회를 각각 설명하고, 이 행사들로 알 수 있는 고려 사람들의 생각과 오늘날 우리 생활과의 관계를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C19","difficulty":4,"kind":"essay","stem":"고려의 큰 행사 메모를 보고 연등회와 팔관회를 각각 설명하고, 이 행사들로 알 수 있는 고려 사람들의 생각과 오늘날 우리 생활과의 관계를 쓰세요.","answer_guide":{"answer":"예: 연등회는 해마다 초에 등불을 밝히고 소원을 빈 행사이고, 팔관회는 11월에 춤·노래·놀이로 온 세상의 평안을 빈 행사이다. 고려 사람들이 불교를 믿으며 가족과 나라의 평안을 바랐다는 것을 알 수 있다. 연등회는 오늘날 부처님 오신 날 무렵의 연등 행렬로 이어져 지금도 볼 수 있다.","scoring_points":["연등회와 팔관회를 바르게 설명했는가","불교·평안을 바란 생각을 썼는가","오늘날 연등 행렬과 이었는가"]},"explanation":["연등회는 등불이에요.","팔관회는 11월 평안이에요.","오늘날 연등 행렬로 이어져요."],"asset":{"type":"passage","lines":["가 — 해마다 초에 등불을 밝히고 소원을 빌었다.","나 — 11월에 춤·노래·놀이로 온 세상의 평안을 빌었다.","다 — 오늘날 부처님 오신 날 무렵 거리에 등 행렬이 이어진다."],"title":"고려의 큰 행사 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_basic#1','soc',5,2,'u1','L11','g5_2_soc_u1_L11_basic','lesson_basic','SO5-2-u1-C20',1,'mc','auto','거란이 쳐들어왔을 때 외교 담판으로 싸우지 않고 강동 6주를 얻은 사람은 누구인가요?',ARRAY['SO5-2-u1-X34','SO5-2-u1-X36','SO5-2-u1-X39']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C20","difficulty":1,"kind":"mc","stem":"거란이 쳐들어왔을 때 외교 담판으로 싸우지 않고 강동 6주를 얻은 사람은 누구인가요?","options":[{"t":"서희","correct":true},{"t":"강감찬","mis":"SO5-2-u1-X34"},{"t":"김윤후","mis":"SO5-2-u1-X36"},{"t":"문익점","mis":"SO5-2-u1-X39"}],"explanation":["말로 맞섰어요.","거란 장수와 담판했어요.","서희예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_basic#2','soc',5,2,'u1','L11','g5_2_soc_u1_L11_basic','lesson_basic','SO5-2-u1-C20',1,'mc','auto','개경 가까운 예성강에 있던 고려의 국제 항구는 어느 것인가요?',ARRAY['SO5-2-u1-X36','SO5-2-u1-X26','SO5-2-u1-X17']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C20","difficulty":1,"kind":"mc","stem":"개경 가까운 예성강에 있던 고려의 국제 항구는 어느 것인가요?","options":[{"t":"벽란도","correct":true},{"t":"강화도","mis":"SO5-2-u1-X36"},{"t":"상경성","mis":"SO5-2-u1-X26"},{"t":"한강 유역","mis":"SO5-2-u1-X17"}],"explanation":["예성강 물이 깊어요.","큰 배가 드나들었어요.","벽란도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_basic#3','soc',5,2,'u1','L11','g5_2_soc_u1_L11_basic','lesson_basic','SO5-2-u1-C21',1,'sa','auto','몽골이 쳐들어오자 고려가 수도를 옮긴 섬은 어디인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u1-C21","difficulty":1,"kind":"sa","stem":"몽골이 쳐들어오자 고려가 수도를 옮긴 섬은 어디인가요? 세 글자로 쓰세요.","answer":["강화도"],"explanation":["바다로 둘러싸인 섬이에요.","개경 가까이에 있어요.","강화도예요."],"mis":"SO5-2-u1-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_basic#4','soc',5,2,'u1','L11','g5_2_soc_u1_L11_basic','lesson_basic','SO5-2-u1-C20',1,'ox','auto','강감찬은 귀주에서 거란군을 크게 물리쳤어요.',ARRAY['SO5-2-u1-X34']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C20","difficulty":1,"kind":"ox","stem":"강감찬은 귀주에서 거란군을 크게 물리쳤어요.","answer":"O","reason_options":[{"t":"세 번째로 쳐들어온 거란을 귀주에서 크게 이겼기 때문에","correct":true},{"t":"강감찬은 몽골과 싸운 사람이기 때문에","mis":"SO5-2-u1-X34"}],"mis":"SO5-2-u1-X34","explanation":["거란이 세 번째로 왔어요.","귀주에서 싸웠어요.","귀주 대첩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_basic#5','soc',5,2,'u1','L11','g5_2_soc_u1_L11_basic','lesson_basic','SO5-2-u1-C20',2,'mc','auto','고려가 거란과 거리를 둔 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X34']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C20","difficulty":2,"kind":"mc","stem":"고려가 거란과 거리를 둔 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"고려가 친척처럼 여긴 발해를 거란이 무너뜨렸기 때문에","correct":true},{"t":"거란이 고려에 비단을 너무 많이 주어서","mis":"SO5-2-u1-X34"},{"t":"거란이 송을 무너뜨려서","mis":"SO5-2-u1-X34"},{"t":"거란이 고구려를 세운 나라라서","mis":"SO5-2-u1-X34"}],"explanation":["거란은 발해를 무너뜨렸어요.","고려는 발해를 친척처럼 여겼어요.","그래서 멀리했어요."],"asset":{"type":"passage","lines":["① 거란이 사신과 낙타 쉰 마리를 보내 친하게 지내자고 했다.","② 고려는 사신을 섬으로 보내고 낙타는 다리 아래 묶어 두었다.","③ 거란 장수 — 「고려는 신라 땅에서 일어났으니 고구려 땅은 우리 것이다.」","④ 서희 — 「우리는 고구려를 이어 이름도 고려라 했다.」","⑤ 서희 — 「길을 막은 여진을 몰아내면 거란과 오가겠다.」","⑥ 고려는 싸우지 않고 강동 6주를 얻었다."],"title":"고려와 거란 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_basic#6','soc',5,2,'u1','L11','g5_2_soc_u1_L11_basic','lesson_basic','SO5-2-u1-C20',2,'mc','auto','고려와 거란 기록 메모 ②에서 고려가 낙타를 다리 아래 묶어 둔 것으로 알 수 있는 고려의 생각은 어느 것인가요?',ARRAY['SO5-2-u1-X34']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C20","difficulty":2,"kind":"mc","stem":"고려와 거란 기록 메모 ②에서 고려가 낙타를 다리 아래 묶어 둔 것으로 알 수 있는 고려의 생각은 어느 것인가요?","options":[{"t":"거란과 친하게 지낼 뜻이 없다","correct":true},{"t":"거란과 가장 친하게 지내고 싶다","mis":"SO5-2-u1-X34"},{"t":"낙타를 아주 귀하게 여긴다","mis":"SO5-2-u1-X34"},{"t":"송과 사이를 끊고 싶다","mis":"SO5-2-u1-X34"}],"explanation":["선물을 받아들이지 않았어요.","사신도 섬으로 보냈어요.","친할 뜻이 없었어요."],"asset":{"type":"passage","lines":["① 거란이 사신과 낙타 쉰 마리를 보내 친하게 지내자고 했다.","② 고려는 사신을 섬으로 보내고 낙타는 다리 아래 묶어 두었다.","③ 거란 장수 — 「고려는 신라 땅에서 일어났으니 고구려 땅은 우리 것이다.」","④ 서희 — 「우리는 고구려를 이어 이름도 고려라 했다.」","⑤ 서희 — 「길을 막은 여진을 몰아내면 거란과 오가겠다.」","⑥ 고려는 싸우지 않고 강동 6주를 얻었다."],"title":"고려와 거란 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_basic#7','soc',5,2,'u1','L11','g5_2_soc_u1_L11_basic','lesson_basic','SO5-2-u1-C20',2,'mc','auto','벽란도에서 고려가 다른 나라에 판 물건으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X35']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C20","difficulty":2,"kind":"mc","stem":"벽란도에서 고려가 다른 나라에 판 물건으로 알맞은 것은 어느 것인가요?","options":[{"t":"인삼·삼베·도자기","correct":true},{"t":"청동 검·민무늬 토기","mis":"SO5-2-u1-X35"},{"t":"덩이쇠·가야 토기","mis":"SO5-2-u1-X35"},{"t":"뗀석기·주먹 도끼","mis":"SO5-2-u1-X35"}],"explanation":["고려에서 나는 것이에요.","인삼은 이름났어요.","도자기도 팔았어요."],"asset":{"type":"passage","lines":["개경 가까운 예성강은 물이 깊어 큰 배가 드나들기 좋았다.","송·거란·여진·일본, 멀리 아라비아 상인까지 찾아왔다.","고려는 인삼·삼베·도자기를 팔고 비단·책·향료를 샀다.","이곳을 거쳐 고려라는 이름이 바깥 세상에 알려졌다."],"title":"어느 항구 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_basic#8','soc',5,2,'u1','L11','g5_2_soc_u1_L11_basic','lesson_basic','SO5-2-u1-C21',2,'mc','auto','몽골과의 전쟁 기록 메모 ②로 보아 고려가 수도를 섬으로 옮긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X36']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C21","difficulty":2,"kind":"mc","stem":"몽골과의 전쟁 기록 메모 ②로 보아 고려가 수도를 섬으로 옮긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"말 탄 몽골군이 바다를 건너기 어려웠기 때문에","correct":true},{"t":"섬에 먹을 것이 가장 많아서","mis":"SO5-2-u1-X36"},{"t":"몽골과 친하게 지내려고","mis":"SO5-2-u1-X36"},{"t":"섬에 금속 활자가 있어서","mis":"SO5-2-u1-X36"}],"explanation":["바다로 둘러싸였어요.","몽골군은 말을 타요.","바다를 건너기 어려웠어요."],"asset":{"type":"passage","lines":["① 몽골이 쳐들어오자 고려는 수도를 섬으로 옮겼다.","② 그 섬은 바다로 둘러싸여 말 탄 군대가 건너기 어려웠다.","③ 한 승려가 노비 문서를 불태우며 함께 싸우면 벼슬을 주겠다고 했다.","④ 승려와 노비, 백성이 힘을 합쳐 성을 지켰다.","⑤ 전쟁이 길어져 땅이 황폐해지고 많은 백성이 끌려갔다."],"title":"몽골과의 전쟁 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_basic#9','soc',5,2,'u1','L11','g5_2_soc_u1_L11_basic','lesson_basic','SO5-2-u1-C21',2,'ox','auto','몽골과 싸울 때 높은 신분의 사람들만 나서서 싸웠어요.',ARRAY['SO5-2-u1-X36']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C21","difficulty":2,"kind":"ox","stem":"몽골과 싸울 때 높은 신분의 사람들만 나서서 싸웠어요.","answer":"X","reason_options":[{"t":"승려와 노비, 백성까지 신분을 넘어 함께 싸웠기 때문에","correct":true},{"t":"노비와 백성은 전쟁과 아무 관계가 없었기 때문에","mis":"SO5-2-u1-X36"}],"mis":"SO5-2-u1-X36","explanation":["노비 문서를 불태웠어요.","모두 힘을 합쳤어요.","신분을 넘어 싸웠어요."],"asset":{"type":"passage","lines":["① 몽골이 쳐들어오자 고려는 수도를 섬으로 옮겼다.","② 그 섬은 바다로 둘러싸여 말 탄 군대가 건너기 어려웠다.","③ 한 승려가 노비 문서를 불태우며 함께 싸우면 벼슬을 주겠다고 했다.","④ 승려와 노비, 백성이 힘을 합쳐 성을 지켰다.","⑤ 전쟁이 길어져 땅이 황폐해지고 많은 백성이 끌려갔다."],"title":"몽골과의 전쟁 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_basic#10','soc',5,2,'u1','L11','g5_2_soc_u1_L11_basic','lesson_basic','SO5-2-u1-C20',3,'error','auto','서희의 외교 담판을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X34']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C20","difficulty":3,"kind":"error","stem":"서희의 외교 담판을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예서 — 「서희는 거란군과 크게 싸워 이겨서 강동 6주를 빼앗았어.」","correct":true,"mis_target":"SO5-2-u1-X34"},{"t":"민재 — 「서희는 거란이 바라는 것이 송과의 사이를 끊는 것임을 알아챘어.」","mis":"SO5-2-u1-X34"},{"t":"가윤 — 「서희는 고려가 고구려를 이은 나라라고 맞섰어.」","mis":"SO5-2-u1-X34"}],"explanation":["서희는 말로 맞섰어요.","싸우지 않고 얻었어요.","예서의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["① 거란이 사신과 낙타 쉰 마리를 보내 친하게 지내자고 했다.","② 고려는 사신을 섬으로 보내고 낙타는 다리 아래 묶어 두었다.","③ 거란 장수 — 「고려는 신라 땅에서 일어났으니 고구려 땅은 우리 것이다.」","④ 서희 — 「우리는 고구려를 이어 이름도 고려라 했다.」","⑤ 서희 — 「길을 막은 여진을 몰아내면 거란과 오가겠다.」","⑥ 고려는 싸우지 않고 강동 6주를 얻었다."],"title":"고려와 거란 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_challenge#1','soc',5,2,'u1','L11','g5_2_soc_u1_L11_challenge','lesson_challenge','SO5-2-u1-C20',2,'match','auto','거란의 세 차례 침입과 고려의 대응을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C20","difficulty":2,"kind":"match","stem":"거란의 세 차례 침입과 고려의 대응을 알맞게 이으세요.","pairs":[{"l":"첫 번째 침입","r":"서희의 외교 담판"},{"l":"두 번째 침입","r":"끈질긴 저항"},{"l":"세 번째 침입","r":"강감찬의 귀주 대첩"}],"mis":"SO5-2-u1-X34","explanation":["첫 번째는 말로 맞섰어요.","두 번째는 끈질기게 버텼어요.","세 번째는 귀주에서 이겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_challenge#2','soc',5,2,'u1','L11','g5_2_soc_u1_L11_challenge','lesson_challenge','SO5-2-u1-C20',2,'mc','auto','어느 항구 이야기에서 이 항구가 국제 항구가 될 수 있었던 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X35']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C20","difficulty":2,"kind":"mc","stem":"어느 항구 이야기에서 이 항구가 국제 항구가 될 수 있었던 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"수도 개경과 가깝고 물이 깊어 큰 배가 드나들기 좋아서","correct":true},{"t":"바다에서 아주 멀리 떨어져 있어서","mis":"SO5-2-u1-X35"},{"t":"외국 배가 들어오지 못하게 막아서","mis":"SO5-2-u1-X35"},{"t":"물이 얕아 배가 쉬기 좋아서","mis":"SO5-2-u1-X35"}],"explanation":["개경과 가까워요.","예성강 물이 깊어요.","큰 배가 드나들었어요."],"asset":{"type":"passage","lines":["개경 가까운 예성강은 물이 깊어 큰 배가 드나들기 좋았다.","송·거란·여진·일본, 멀리 아라비아 상인까지 찾아왔다.","고려는 인삼·삼베·도자기를 팔고 비단·책·향료를 샀다.","이곳을 거쳐 고려라는 이름이 바깥 세상에 알려졌다."],"title":"어느 항구 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_challenge#3','soc',5,2,'u1','L11','g5_2_soc_u1_L11_challenge','lesson_challenge','SO5-2-u1-C20',3,'mc','auto','고려와 거란 기록 메모 ④·⑤에서 서희가 말한 것을 바탕으로 담판이 성공한 까닭을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X34']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C20","difficulty":3,"kind":"mc","stem":"고려와 거란 기록 메모 ④·⑤에서 서희가 말한 것을 바탕으로 담판이 성공한 까닭을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"고구려 땅에 대한 거란의 주장을 맞받고, 거란이 바라는 교류를 들어주는 대신 길목 땅을 얻어 냈다","correct":true},{"t":"거란 장수에게 많은 선물을 주어서","mis":"SO5-2-u1-X34"},{"t":"송과 손잡고 거란을 위협해서","mis":"SO5-2-u1-X34"},{"t":"거란군을 싸워서 모두 물리쳐서","mis":"SO5-2-u1-X34"}],"explanation":["④는 고구려 계승을 내세웠어요.","⑤는 거란과 오가겠다는 약속이에요.","그 대신 강동 6주를 얻었어요."],"asset":{"type":"passage","lines":["① 거란이 사신과 낙타 쉰 마리를 보내 친하게 지내자고 했다.","② 고려는 사신을 섬으로 보내고 낙타는 다리 아래 묶어 두었다.","③ 거란 장수 — 「고려는 신라 땅에서 일어났으니 고구려 땅은 우리 것이다.」","④ 서희 — 「우리는 고구려를 이어 이름도 고려라 했다.」","⑤ 서희 — 「길을 막은 여진을 몰아내면 거란과 오가겠다.」","⑥ 고려는 싸우지 않고 강동 6주를 얻었다."],"title":"고려와 거란 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_challenge#4','soc',5,2,'u1','L11','g5_2_soc_u1_L11_challenge','lesson_challenge','SO5-2-u1-C21',3,'mc','auto','몽골과의 전쟁 기록 메모 ③·④로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X36']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C21","difficulty":3,"kind":"mc","stem":"몽골과의 전쟁 기록 메모 ③·④로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"신분의 벽을 넘어 모두가 힘을 합쳐 나라를 지켰다","correct":true},{"t":"노비는 싸움에 나갈 수 없었다","mis":"SO5-2-u1-X36"},{"t":"승려는 전쟁을 막으려 몽골 편에 섰다","mis":"SO5-2-u1-X36"},{"t":"벼슬은 높은 신분만 받을 수 있었다","mis":"SO5-2-u1-X36"}],"explanation":["노비 문서를 불태웠어요.","벼슬을 약속했어요.","모두 함께 싸웠어요."],"asset":{"type":"passage","lines":["① 몽골이 쳐들어오자 고려는 수도를 섬으로 옮겼다.","② 그 섬은 바다로 둘러싸여 말 탄 군대가 건너기 어려웠다.","③ 한 승려가 노비 문서를 불태우며 함께 싸우면 벼슬을 주겠다고 했다.","④ 승려와 노비, 백성이 힘을 합쳐 성을 지켰다.","⑤ 전쟁이 길어져 땅이 황폐해지고 많은 백성이 끌려갔다."],"title":"몽골과의 전쟁 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_challenge#5','soc',5,2,'u1','L11','g5_2_soc_u1_L11_challenge','lesson_challenge','SO5-2-u1-C21',3,'ox','auto','몽골과의 전쟁이 길어지면서 고려 백성은 큰 고통을 겪었어요.',ARRAY['SO5-2-u1-X36']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C21","difficulty":3,"kind":"ox","stem":"몽골과의 전쟁이 길어지면서 고려 백성은 큰 고통을 겪었어요.","answer":"O","reason_options":[{"t":"땅이 황폐해지고 많은 백성이 끌려갔기 때문에","correct":true},{"t":"전쟁 중에도 백성의 생활은 하나도 달라지지 않았기 때문에","mis":"SO5-2-u1-X36"}],"mis":"SO5-2-u1-X36","explanation":["전쟁이 오래 이어졌어요.","땅이 황폐해졌어요.","백성이 끌려갔어요."],"asset":{"type":"passage","lines":["① 몽골이 쳐들어오자 고려는 수도를 섬으로 옮겼다.","② 그 섬은 바다로 둘러싸여 말 탄 군대가 건너기 어려웠다.","③ 한 승려가 노비 문서를 불태우며 함께 싸우면 벼슬을 주겠다고 했다.","④ 승려와 노비, 백성이 힘을 합쳐 성을 지켰다.","⑤ 전쟁이 길어져 땅이 황폐해지고 많은 백성이 끌려갔다."],"title":"몽골과의 전쟁 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_challenge#6','soc',5,2,'u1','L11','g5_2_soc_u1_L11_challenge','lesson_challenge','SO5-2-u1-C20',3,'error','auto','벽란도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X35']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C20","difficulty":3,"kind":"error","stem":"벽란도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도아 — 「고려는 벽란도에서 물건을 사기만 하고 팔지는 않았어.」","correct":true,"mis_target":"SO5-2-u1-X35"},{"t":"준우 — 「아라비아 상인까지 벽란도를 찾아왔어.」","mis":"SO5-2-u1-X35"},{"t":"이수 — 「이곳을 거쳐 고려라는 이름이 바깥에 알려졌어.」","mis":"SO5-2-u1-X35"}],"explanation":["고려도 물건을 팔았어요.","인삼·삼베·도자기예요.","도아의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["개경 가까운 예성강은 물이 깊어 큰 배가 드나들기 좋았다.","송·거란·여진·일본, 멀리 아라비아 상인까지 찾아왔다.","고려는 인삼·삼베·도자기를 팔고 비단·책·향료를 샀다.","이곳을 거쳐 고려라는 이름이 바깥 세상에 알려졌다."],"title":"어느 항구 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_challenge#7','soc',5,2,'u1','L11','g5_2_soc_u1_L11_challenge','lesson_challenge','SO5-2-u1-C21',3,'mc','auto','몽골과의 전쟁 뒤 두 나라 사이에 생긴 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X36']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C21","difficulty":3,"kind":"mc","stem":"몽골과의 전쟁 뒤 두 나라 사이에 생긴 일로 알맞은 것은 어느 것인가요?","options":[{"t":"서로 오가며 음식과 풍습을 주고받았다","correct":true},{"t":"두 나라는 다시는 오가지 않았다","mis":"SO5-2-u1-X36"},{"t":"고려의 풍습이 모두 사라졌다","mis":"SO5-2-u1-X36"},{"t":"몽골 사람들이 고려 말을 처음 만들었다","mis":"SO5-2-u1-X36"}],"explanation":["사람과 물건이 오갔어요.","설렁탕·족두리가 전해졌대요.","고려의 상추쌈도 인기였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_challenge#8','soc',5,2,'u1','L11','g5_2_soc_u1_L11_challenge','lesson_challenge','SO5-2-u1-C20',4,'mc','auto','고려가 송과는 가깝게, 거란과는 멀리 지낸 것과 서희의 담판을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO5-2-u1-X34']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C20","difficulty":4,"kind":"mc","stem":"고려가 송과는 가깝게, 거란과는 멀리 지낸 것과 서희의 담판을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"고려는 주변 나라의 사정을 살피며 상황에 맞게 외교를 펼쳐 나라를 지켰다","correct":true},{"t":"고려는 주변 나라와 늘 싸우기만 했다","mis":"SO5-2-u1-X34"},{"t":"고려는 주변 나라에 아무 관심이 없었다","mis":"SO5-2-u1-X34"},{"t":"고려는 거란과 가장 친한 나라였다","mis":"SO5-2-u1-X34"}],"explanation":["송과 거란을 다르게 대했어요.","말로 땅을 얻었어요.","사정에 맞게 외교했어요."],"asset":{"type":"passage","lines":["① 거란이 사신과 낙타 쉰 마리를 보내 친하게 지내자고 했다.","② 고려는 사신을 섬으로 보내고 낙타는 다리 아래 묶어 두었다.","③ 거란 장수 — 「고려는 신라 땅에서 일어났으니 고구려 땅은 우리 것이다.」","④ 서희 — 「우리는 고구려를 이어 이름도 고려라 했다.」","⑤ 서희 — 「길을 막은 여진을 몰아내면 거란과 오가겠다.」","⑥ 고려는 싸우지 않고 강동 6주를 얻었다."],"title":"고려와 거란 기록 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_challenge#9','soc',5,2,'u1','L11','g5_2_soc_u1_L11_challenge','lesson_challenge','SO5-2-u1-C21',4,'mc','auto','고려가 거란과 몽골의 침입을 겪은 일을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X36','SO5-2-u1-X34']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C21","difficulty":4,"kind":"mc","stem":"고려가 거란과 몽골의 침입을 겪은 일을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"외교와 끈질긴 싸움으로 거란을 막았고, 몽골에는 강화도로 옮겨 신분을 넘어 맞섰지만 큰 고통도 겪었다","correct":true},{"t":"두 나라 모두 싸우지 않고 물러갔다","mis":"SO5-2-u1-X36"},{"t":"몽골은 서희의 담판으로 물러갔다","mis":"SO5-2-u1-X34"},{"t":"거란에 맞서 수도를 강화도로 옮겼다","mis":"SO5-2-u1-X36"}],"explanation":["거란은 담판과 귀주 대첩이에요.","몽골은 강화도예요.","고통도 컸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L11_challenge#10','soc',5,2,'u1','L11','g5_2_soc_u1_L11_challenge','lesson_challenge','SO5-2-u1-C20',4,'essay','teacher','어느 항구 이야기를 보고, 벽란도가 국제 항구가 된 까닭과 이곳에서 이루어진 교류의 모습을 쓰고, 이것이 오늘날 우리나라의 영어 이름과 어떻게 이어지는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C20","difficulty":4,"kind":"essay","stem":"어느 항구 이야기를 보고, 벽란도가 국제 항구가 된 까닭과 이곳에서 이루어진 교류의 모습을 쓰고, 이것이 오늘날 우리나라의 영어 이름과 어떻게 이어지는지 쓰세요.","answer_guide":{"answer":"예: 벽란도는 수도 개경과 가깝고 예성강 물이 깊어 큰 배가 드나들기 좋아 국제 항구가 되었다. 송·거란·여진·일본, 멀리 아라비아 상인까지 찾아와 고려는 인삼·삼베·도자기를 팔고 비단·책·향료를 샀다. 이곳을 거쳐 고려라는 이름이 바깥에 알려져 오늘날 KOREA라는 이름으로 이어졌다.","scoring_points":["국제 항구가 된 까닭을 썼는가","오간 나라와 물건을 썼는가","KOREA와 이었는가"]},"explanation":["개경과 가깝고 물이 깊어요.","여러 나라 상인이 왔어요.","고려가 KOREA로 이어져요."],"asset":{"type":"passage","lines":["개경 가까운 예성강은 물이 깊어 큰 배가 드나들기 좋았다.","송·거란·여진·일본, 멀리 아라비아 상인까지 찾아왔다.","고려는 인삼·삼베·도자기를 팔고 비단·책·향료를 샀다.","이곳을 거쳐 고려라는 이름이 바깥 세상에 알려졌다."],"title":"어느 항구 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_basic#1','soc',5,2,'u1','L12','g5_2_soc_u1_L12_basic','lesson_basic','SO5-2-u1-C22',1,'mc','auto','무늬를 파내고 다른 색 흙으로 메워 구운 고려청자의 기법을 무엇이라고 하나요?',ARRAY['SO5-2-u1-X37']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C22","difficulty":1,"kind":"mc","stem":"무늬를 파내고 다른 색 흙으로 메워 구운 고려청자의 기법을 무엇이라고 하나요?","options":[{"t":"상감 기법","correct":true},{"t":"빗살무늬 기법","mis":"SO5-2-u1-X37"},{"t":"뗀석기 기법","mis":"SO5-2-u1-X37"},{"t":"금속 활자 기법","mis":"SO5-2-u1-X37"}],"explanation":["무늬를 파내요.","다른 색 흙을 메워요.","상감 기법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_basic#2','soc',5,2,'u1','L12','g5_2_soc_u1_L12_basic','lesson_basic','SO5-2-u1-C23',1,'sa','auto','오늘날 남아 있는 세계에서 가장 오래된 금속 활자 책은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u1-C23","difficulty":1,"kind":"sa","stem":"오늘날 남아 있는 세계에서 가장 오래된 금속 활자 책은 무엇인가요? 두 글자로 쓰세요.","answer":["직지"],"explanation":["고려 때 찍었어요.","프랑스 도서관에서 발견됐어요.","「직지」예요."],"mis":"SO5-2-u1-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_basic#3','soc',5,2,'u1','L12','g5_2_soc_u1_L12_basic','lesson_basic','SO5-2-u1-C23',1,'mc','auto','몽골에 사신으로 갔다가 목화씨를 가져온 사람은 누구인가요?',ARRAY['SO5-2-u1-X39']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C23","difficulty":1,"kind":"mc","stem":"몽골에 사신으로 갔다가 목화씨를 가져온 사람은 누구인가요?","options":[{"t":"문익점","correct":true},{"t":"서희","mis":"SO5-2-u1-X39"},{"t":"강감찬","mis":"SO5-2-u1-X39"},{"t":"왕건","mis":"SO5-2-u1-X39"}],"explanation":["사신으로 다녀왔어요.","목화씨를 가져왔어요.","문익점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_basic#4','soc',5,2,'u1','L12','g5_2_soc_u1_L12_basic','lesson_basic','SO5-2-u1-C23',1,'ox','auto','팔만대장경은 지금도 해인사에 남아 있어요.',ARRAY['SO5-2-u1-X38']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C23","difficulty":1,"kind":"ox","stem":"팔만대장경은 지금도 해인사에 남아 있어요.","answer":"O","reason_options":[{"t":"오랫동안 잘 보관되어 지금도 해인사에서 볼 수 있기 때문에","correct":true},{"t":"팔만대장경은 몽골군이 모두 불태웠기 때문에","mis":"SO5-2-u1-X38"}],"mis":"SO5-2-u1-X38","explanation":["다시 만든 대장경이에요.","틀린 글자가 거의 없어요.","해인사에 남아 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_basic#5','soc',5,2,'u1','L12','g5_2_soc_u1_L12_basic','lesson_basic','SO5-2-u1-C22',2,'mc','auto','고려청자를 주로 쓴 사람들은 누구인가요?',ARRAY['SO5-2-u1-X37','SO5-2-u1-X08']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C22","difficulty":2,"kind":"mc","stem":"고려청자를 주로 쓴 사람들은 누구인가요?","options":[{"t":"지배층","correct":true},{"t":"모든 백성","mis":"SO5-2-u1-X37"},{"t":"구석기 사람들","mis":"SO5-2-u1-X08"},{"t":"천민","mis":"SO5-2-u1-X37"}],"explanation":["청자는 비싸고 귀했어요.","생활용품이었지만","주로 지배층이 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_basic#6','soc',5,2,'u1','L12','g5_2_soc_u1_L12_basic','lesson_basic','SO5-2-u1-C23',2,'mc','auto','고려 사람들이 팔만대장경을 다시 만든 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X38']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C23","difficulty":2,"kind":"mc","stem":"고려 사람들이 팔만대장경을 다시 만든 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"불교의 힘으로 몽골군을 물리치기를 바라서","correct":true},{"t":"목판 인쇄를 연습하려고","mis":"SO5-2-u1-X38"},{"t":"송나라에 팔려고","mis":"SO5-2-u1-X38"},{"t":"거란과 친해지려고","mis":"SO5-2-u1-X38"}],"explanation":["처음 만든 대장경판이 불탔어요.","몽골이 쳐들어왔어요.","부처의 힘을 빌렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_basic#7','soc',5,2,'u1','L12','g5_2_soc_u1_L12_basic','lesson_basic','SO5-2-u1-C23',2,'mc','auto','두 가지 인쇄 방법 메모 가와 견주어 나의 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X38']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C23","difficulty":2,"kind":"mc","stem":"두 가지 인쇄 방법 메모 가와 견주어 나의 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"글자를 다시 짜서 여러 책을 찍을 수 있다","correct":true},{"t":"한 가지 책만 찍을 수 있다","mis":"SO5-2-u1-X38"},{"t":"나무판이 휘고 갈라진다","mis":"SO5-2-u1-X38"},{"t":"글자를 새로 만들 필요가 전혀 없다","mis":"SO5-2-u1-X38"}],"explanation":["가는 한 쪽을 통째로 새겨요.","나는 글자를 하나씩 만들어요.","다시 짜면 다른 책도 찍어요."],"asset":{"type":"passage","lines":["가 — 나무판 한 장에 한 쪽을 통째로 새겨 찍는다.","나 — 금속으로 글자를 하나씩 만들어 판에 짜서 찍는다.","다 — 찍고 나면 글자를 다시 짜서 다른 책도 찍을 수 있다."],"title":"두 가지 인쇄 방법 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_basic#8','soc',5,2,'u1','L12','g5_2_soc_u1_L12_basic','lesson_basic','SO5-2-u1-C23',2,'mc','auto','문익점이 가져온 목화로 백성의 생활에 생긴 변화는 어느 것인가요?',ARRAY['SO5-2-u1-X39']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C23","difficulty":2,"kind":"mc","stem":"문익점이 가져온 목화로 백성의 생활에 생긴 변화는 어느 것인가요?","options":[{"t":"따뜻한 무명옷과 솜이불로 겨울을 나게 되었다","correct":true},{"t":"비단옷을 처음 입게 되었다","mis":"SO5-2-u1-X39"},{"t":"삼베옷을 처음 입게 되었다","mis":"SO5-2-u1-X39"},{"t":"옷을 입지 않게 되었다","mis":"SO5-2-u1-X39"}],"explanation":["목화솜으로 실을 뽑아요.","무명을 짜요.","겨울이 따뜻해졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_basic#9','soc',5,2,'u1','L12','g5_2_soc_u1_L12_basic','lesson_basic','SO5-2-u1-C22',2,'ox','auto','고려청자는 처음부터 끝까지 중국의 기술만 그대로 따라 만들었어요.',ARRAY['SO5-2-u1-X37']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C22","difficulty":2,"kind":"ox","stem":"고려청자는 처음부터 끝까지 중국의 기술만 그대로 따라 만들었어요.","answer":"X","reason_options":[{"t":"처음엔 중국 기술을 받아들였지만 상감 기법으로 고려만의 청자를 만들었기 때문에","correct":true},{"t":"고려청자는 중국에서 사 온 것이기 때문에","mis":"SO5-2-u1-X37"}],"mis":"SO5-2-u1-X37","explanation":["처음엔 중국 기술을 받아들였어요.","상감 기법을 더했어요.","고려만의 청자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_basic#10','soc',5,2,'u1','L12','g5_2_soc_u1_L12_basic','lesson_basic','SO5-2-u1-C23',3,'error','auto','고려의 문화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X26','SO5-2-u1-X38','SO5-2-u1-X37']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C23","difficulty":3,"kind":"error","stem":"고려의 문화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「팔만대장경은 통일신라 사람들이 만든 거야.」","correct":true,"mis_target":"SO5-2-u1-X26"},{"t":"지성 — 「고려는 세계 최초로 금속 활자를 만들었어.」","mis":"SO5-2-u1-X38"},{"t":"보민 — 「상감 청자는 고려만의 청자야.」","mis":"SO5-2-u1-X37"}],"explanation":["팔만대장경은 고려 때 만들었어요.","몽골 침입 때예요.","하랑의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_challenge#1','soc',5,2,'u1','L12','g5_2_soc_u1_L12_challenge','lesson_challenge','SO5-2-u1-C23',2,'match','auto','고려의 문화유산과 그것에 담긴 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C23","difficulty":2,"kind":"match","stem":"고려의 문화유산과 그것에 담긴 것을 알맞게 이으세요.","pairs":[{"l":"상감 청자","r":"고려만의 도자기 기술"},{"l":"팔만대장경","r":"몽골을 물리치려는 바람"},{"l":"금속 활자","r":"여러 책을 찍는 기술"},{"l":"목화","r":"백성의 따뜻한 겨울"}],"mis":"SO5-2-u1-X26","explanation":["청자는 기술이에요.","대장경은 바람이에요.","활자와 목화는 생활을 바꿨어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_challenge#2','soc',5,2,'u1','L12','g5_2_soc_u1_L12_challenge','lesson_challenge','SO5-2-u1-C22',2,'mc','auto','고려 보물선 조사 메모 ③으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X37']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C22","difficulty":2,"kind":"mc","stem":"고려 보물선 조사 메모 ③으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"청자는 주전자·베개·연적처럼 생활 속에서 쓰는 물건이었다","correct":true},{"t":"청자는 무기로 썼다","mis":"SO5-2-u1-X37"},{"t":"청자는 장식으로만 땅에 묻었다","mis":"SO5-2-u1-X37"},{"t":"청자는 농기구였다","mis":"SO5-2-u1-X37"}],"explanation":["주전자와 베개예요.","먹물 담는 연적도 있어요.","생활용품이었어요."],"asset":{"type":"passage","lines":["① 태안 앞바다 진흙 속에서 푸른빛 그릇을 가득 실은 고려 배가 나왔다.","② 그릇에 무늬를 파내고 흰 흙·붉은 흙을 메운 흔적이 있다.","③ 주전자·베개·먹물 담는 연적 모양이 많다.","④ 배에서 나온 나무 꼬리표에 높은 벼슬아치에게 보낸다고 적혀 있다."],"title":"고려 보물선 조사 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_challenge#3','soc',5,2,'u1','L12','g5_2_soc_u1_L12_challenge','lesson_challenge','SO5-2-u1-C22',3,'mc','auto','고려 보물선 조사 메모 ④로 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X37']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C22","difficulty":3,"kind":"mc","stem":"고려 보물선 조사 메모 ④로 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"귀한 청자를 높은 벼슬아치 같은 지배층에게 보냈다","correct":true},{"t":"청자는 백성 누구나 흔히 쓰던 그릇이었다","mis":"SO5-2-u1-X37"},{"t":"배는 청자를 외국으로 버리러 가던 길이었다","mis":"SO5-2-u1-X37"},{"t":"청자는 바다 밑에서 만들었다","mis":"SO5-2-u1-X37"}],"explanation":["꼬리표에 받는 사람이 적혔어요.","높은 벼슬아치예요.","지배층이 썼어요."],"asset":{"type":"passage","lines":["① 태안 앞바다 진흙 속에서 푸른빛 그릇을 가득 실은 고려 배가 나왔다.","② 그릇에 무늬를 파내고 흰 흙·붉은 흙을 메운 흔적이 있다.","③ 주전자·베개·먹물 담는 연적 모양이 많다.","④ 배에서 나온 나무 꼬리표에 높은 벼슬아치에게 보낸다고 적혀 있다."],"title":"고려 보물선 조사 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_challenge#4','soc',5,2,'u1','L12','g5_2_soc_u1_L12_challenge','lesson_challenge','SO5-2-u1-C23',3,'mc','auto','목화 이야기 메모 ③·④에서 알 수 있는 문익점과 장인의 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X39']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C23","difficulty":3,"kind":"mc","stem":"목화 이야기 메모 ③·④에서 알 수 있는 문익점과 장인의 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실패해도 포기하지 않고 남은 한 그루로 다시 길러 냈다","correct":true},{"t":"한 그루만 남자 바로 포기했다","mis":"SO5-2-u1-X39"},{"t":"목화를 혼자만 가졌다","mis":"SO5-2-u1-X39"},{"t":"목화 대신 삼베만 길렀다","mis":"SO5-2-u1-X39"}],"explanation":["거의 다 말라 죽었어요.","한 그루에서 씨를 받았어요.","다시 심어 늘렸어요."],"asset":{"type":"passage","lines":["① 백성은 겨울에도 바람이 잘 통하는 삼베·모시옷을 입었다.","② 한 사신이 목화씨를 가져와 장인과 함께 심었다.","③ 거의 다 말라 죽고 한 그루만 살아남았다.","④ 그 한 그루에서 씨를 받아 몇 해 동안 다시 심었다.","⑤ 씨와 실 뽑는 법이 퍼져 따뜻한 무명옷과 솜이불이 생겼다."],"title":"목화 이야기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_challenge#5','soc',5,2,'u1','L12','g5_2_soc_u1_L12_challenge','lesson_challenge','SO5-2-u1-C23',3,'ox','auto','목판 인쇄는 나무판에 새긴 내용만 찍을 수 있지만 금속 활자는 글자를 다시 짜서 다른 책도 찍을 수 있어요.',ARRAY['SO5-2-u1-X38']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C23","difficulty":3,"kind":"ox","stem":"목판 인쇄는 나무판에 새긴 내용만 찍을 수 있지만 금속 활자는 글자를 다시 짜서 다른 책도 찍을 수 있어요.","answer":"O","reason_options":[{"t":"금속 활자는 글자를 하나씩 만들어 판에 짜 넣기 때문에","correct":true},{"t":"금속 활자는 한 번 쓰면 녹아 없어지기 때문에","mis":"SO5-2-u1-X38"}],"mis":"SO5-2-u1-X38","explanation":["목판은 통째로 새겨요.","활자는 하나씩이에요.","다시 짤 수 있어요."],"asset":{"type":"passage","lines":["가 — 나무판 한 장에 한 쪽을 통째로 새겨 찍는다.","나 — 금속으로 글자를 하나씩 만들어 판에 짜서 찍는다.","다 — 찍고 나면 글자를 다시 짜서 다른 책도 찍을 수 있다."],"title":"두 가지 인쇄 방법 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_challenge#6','soc',5,2,'u1','L12','g5_2_soc_u1_L12_challenge','lesson_challenge','SO5-2-u1-C22',3,'error','auto','고려청자를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X37']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C22","difficulty":3,"kind":"error","stem":"고려청자를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「상감 청자의 무늬는 붓으로 물감을 칠해 그린 거야.」","correct":true,"mis_target":"SO5-2-u1-X37"},{"t":"찬희 — 「무늬를 파내고 다른 색 흙으로 메워 구웠어.」","mis":"SO5-2-u1-X37"},{"t":"소담 — 「청자는 비싸서 주로 지배층이 썼어.」","mis":"SO5-2-u1-X37"}],"explanation":["물감이 아니에요.","흙을 메워 구웠어요.","태린의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["① 태안 앞바다 진흙 속에서 푸른빛 그릇을 가득 실은 고려 배가 나왔다.","② 그릇에 무늬를 파내고 흰 흙·붉은 흙을 메운 흔적이 있다.","③ 주전자·베개·먹물 담는 연적 모양이 많다.","④ 배에서 나온 나무 꼬리표에 높은 벼슬아치에게 보낸다고 적혀 있다."],"title":"고려 보물선 조사 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_challenge#7','soc',5,2,'u1','L12','g5_2_soc_u1_L12_challenge','lesson_challenge','SO5-2-u1-C23',3,'mc','auto','팔만대장경을 만들 때 많은 사람이 오랫동안 정성을 모은 것으로 알 수 있는 고려 사람들의 생각은 어느 것인가요?',ARRAY['SO5-2-u1-X38','SO5-2-u1-X36']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C23","difficulty":3,"kind":"mc","stem":"팔만대장경을 만들 때 많은 사람이 오랫동안 정성을 모은 것으로 알 수 있는 고려 사람들의 생각은 어느 것인가요?","options":[{"t":"어려울 때 불교의 힘에 기대어 마음을 하나로 모으려 했다","correct":true},{"t":"불교를 믿지 않아 대장경을 장식으로 썼다","mis":"SO5-2-u1-X38"},{"t":"전쟁에는 관심이 없었다","mis":"SO5-2-u1-X36"},{"t":"대장경은 왕 혼자 만들었다","mis":"SO5-2-u1-X38"}],"explanation":["몽골이 쳐들어왔어요.","많은 사람이 정성을 모았어요.","불교로 마음을 모았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_challenge#8','soc',5,2,'u1','L12','g5_2_soc_u1_L12_challenge','lesson_challenge','SO5-2-u1-C23',4,'mc','auto','목화 이야기 메모 ①과 ⑤를 견주어 목화가 고려 백성의 생활을 어떻게 바꾸었는지 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X39']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C23","difficulty":4,"kind":"mc","stem":"목화 이야기 메모 ①과 ⑤를 견주어 목화가 고려 백성의 생활을 어떻게 바꾸었는지 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"바람이 잘 통하는 삼베옷으로 춥게 나던 겨울을 무명옷과 솜이불로 따뜻하게 나게 되었다","correct":true},{"t":"비단옷을 입던 백성이 삼베옷을 입게 되었다","mis":"SO5-2-u1-X39"},{"t":"옷감이 줄어 더 춥게 지내게 되었다","mis":"SO5-2-u1-X39"},{"t":"목화는 지배층만 써서 백성은 달라진 것이 없다","mis":"SO5-2-u1-X39"}],"explanation":["①은 삼베·모시옷이에요.","⑤는 무명옷과 솜이불이에요.","겨울이 따뜻해졌어요."],"asset":{"type":"passage","lines":["① 백성은 겨울에도 바람이 잘 통하는 삼베·모시옷을 입었다.","② 한 사신이 목화씨를 가져와 장인과 함께 심었다.","③ 거의 다 말라 죽고 한 그루만 살아남았다.","④ 그 한 그루에서 씨를 받아 몇 해 동안 다시 심었다.","⑤ 씨와 실 뽑는 법이 퍼져 따뜻한 무명옷과 솜이불이 생겼다."],"title":"목화 이야기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_challenge#9','soc',5,2,'u1','L12','g5_2_soc_u1_L12_challenge','lesson_challenge','SO5-2-u1-C22',4,'mc','auto','고려의 문화유산으로 고려 사람들의 생활을 짐작하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X42']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C22","difficulty":4,"kind":"mc","stem":"고려의 문화유산으로 고려 사람들의 생활을 짐작하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"청자·대장경·활자·목화를 살펴 그것을 만든 까닭과 쓴 사람, 바뀐 생활을 함께 생각한다","correct":true},{"t":"문화유산의 이름만 차례로 외운다","mis":"SO5-2-u1-X42"},{"t":"만든 연도만 찾아 적는다","mis":"SO5-2-u1-X42"},{"t":"오늘날과 관계없으니 살피지 않는다","mis":"SO5-2-u1-X42"}],"explanation":["만든 까닭을 생각해요.","쓴 사람을 살펴요.","바뀐 생활을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L12_challenge#10','soc',5,2,'u1','L12','g5_2_soc_u1_L12_challenge','lesson_challenge','SO5-2-u1-C23',4,'essay','teacher','팔만대장경과 금속 활자 가운데 하나를 골라, 그것을 만든 까닭이나 좋은 점을 쓰고, 그로써 알 수 있는 고려 사람들의 생각이나 생활을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C23","difficulty":4,"kind":"essay","stem":"팔만대장경과 금속 활자 가운데 하나를 골라, 그것을 만든 까닭이나 좋은 점을 쓰고, 그로써 알 수 있는 고려 사람들의 생각이나 생활을 쓰세요.","answer_guide":{"answer":"예: 팔만대장경은 몽골 침입으로 처음 만든 대장경판이 불타자 불교의 힘으로 몽골군을 물리치기를 바라며 다시 만들었다. 많은 사람이 오랫동안 정성을 모아 틀린 글자가 거의 없을 만큼 정확하게 새겼다. 이로써 고려 사람들이 어려운 때에 불교에 기대어 마음을 하나로 모았다는 것을 알 수 있다.","scoring_points":["하나를 골라 만든 까닭이나 좋은 점을 썼는가","바르게 설명했는가","고려 사람들의 생각이나 생활과 이었는가"]},"explanation":["하나를 골라요.","까닭이나 좋은 점을 써요.","고려 사람들의 생각과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_basic#1','soc',5,2,'u1','L13','g5_2_soc_u1_L13_basic','lesson_basic','SO5-2-u1-C24',1,'mc','auto','옛 사람들의 생활을 기사로 전하는 신문을 무엇이라고 하나요?',ARRAY['SO5-2-u1-X41']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C24","difficulty":1,"kind":"mc","stem":"옛 사람들의 생활을 기사로 전하는 신문을 무엇이라고 하나요?","options":[{"t":"역사 신문","correct":true},{"t":"학급 일기","mis":"SO5-2-u1-X41"},{"t":"광고지","mis":"SO5-2-u1-X41"},{"t":"달력","mis":"SO5-2-u1-X41"}],"explanation":["옛날 이야기를 다뤄요.","기사로 전해요.","역사 신문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_basic#2','soc',5,2,'u1','L13','g5_2_soc_u1_L13_basic','lesson_basic','SO5-2-u1-C24',1,'mc','auto','역사 신문에서 기자가 묻고 옛사람이 답하는 꼴의 기사를 무엇이라고 하나요?',ARRAY['SO5-2-u1-X41']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C24","difficulty":1,"kind":"mc","stem":"역사 신문에서 기자가 묻고 옛사람이 답하는 꼴의 기사를 무엇이라고 하나요?","options":[{"t":"인터뷰","correct":true},{"t":"광고","mis":"SO5-2-u1-X41"},{"t":"만화","mis":"SO5-2-u1-X41"},{"t":"사건 기사","mis":"SO5-2-u1-X41"}],"explanation":["묻고 답해요.","옛사람의 생각이 드러나요.","인터뷰예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_basic#3','soc',5,2,'u1','L13','g5_2_soc_u1_L13_basic','lesson_basic','SO5-2-u1-C24',1,'sa','auto','역사 신문 기사의 내용은 무엇으로 확인한 사실을 바탕으로 써야 하나요? 「유적·유물·○○」의 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u1-C24","difficulty":1,"kind":"sa","stem":"역사 신문 기사의 내용은 무엇으로 확인한 사실을 바탕으로 써야 하나요? 「유적·유물·○○」의 ○○에 알맞은 두 글자를 쓰세요.","answer":["기록"],"explanation":["유적과 유물이 있어요.","글로 남은 것도 있어요.","역사 기록이에요."],"mis":"SO5-2-u1-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_basic#4','soc',5,2,'u1','L13','g5_2_soc_u1_L13_basic','lesson_basic','SO5-2-u1-C24',1,'ox','auto','역사 신문의 광고 기사로 그 시대에 쓰던 물건을 소개할 수 있어요.',ARRAY['SO5-2-u1-X41']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C24","difficulty":1,"kind":"ox","stem":"역사 신문의 광고 기사로 그 시대에 쓰던 물건을 소개할 수 있어요.","answer":"O","reason_options":[{"t":"광고는 그때 쓰던 물건을 보여 주기 좋은 기사 갈래이기 때문에","correct":true},{"t":"역사 신문에는 광고를 실을 수 없기 때문에","mis":"SO5-2-u1-X41"}],"mis":"SO5-2-u1-X41","explanation":["기사 갈래가 여럿이에요.","광고는 물건을 보여 줘요.","그 시대 물건을 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_basic#5','soc',5,2,'u1','L13','g5_2_soc_u1_L13_basic','lesson_basic','SO5-2-u1-C24',2,'mc','auto','우리 반 역사 신문 기사 목록 가운데 사실과 어긋나는 기사는 어느 것인가요?',ARRAY['SO5-2-u1-X40']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C24","difficulty":2,"kind":"mc","stem":"우리 반 역사 신문 기사 목록 가운데 사실과 어긋나는 기사는 어느 것인가요?","options":[{"t":"㉲","correct":true},{"t":"㉮","mis":"SO5-2-u1-X40"},{"t":"㉯","mis":"SO5-2-u1-X40"},{"t":"㉰","mis":"SO5-2-u1-X40"}],"explanation":["신석기에는 청동이 없었어요.","청동 검은 청동기 시대 것이에요.","㉲가 어긋나요."],"asset":{"type":"passage","lines":["㉮ 사건 — 「서희, 말 한마디로 강동 6주를 얻다」","㉯ 인터뷰 — 「신석기인에게 묻다, 왜 강가에 집을 지었나요?」","㉰ 광고 — 「상감 청자 주전자 들어왔습니다」","㉱ 만화 — 「구석기 어린이의 하루」","㉲ 광고 — 「신석기 마을에 청동 검 팝니다」"],"title":"우리 반 역사 신문 기사 목록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_basic#6','soc',5,2,'u1','L13','g5_2_soc_u1_L13_basic','lesson_basic','SO5-2-u1-C24',2,'mc','auto','우리 반 역사 신문 기사 목록 ㉱의 기사 갈래로 사람들의 생활 모습을 보여 주기 좋은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X41']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C24","difficulty":2,"kind":"mc","stem":"우리 반 역사 신문 기사 목록 ㉱의 기사 갈래로 사람들의 생활 모습을 보여 주기 좋은 것은 어느 것인가요?","options":[{"t":"만화","correct":true},{"t":"인터뷰","mis":"SO5-2-u1-X41"},{"t":"광고","mis":"SO5-2-u1-X41"},{"t":"사건","mis":"SO5-2-u1-X41"}],"explanation":["그림으로 보여 줘요.","하루를 장면으로 나타내요.","만화예요."],"asset":{"type":"passage","lines":["㉮ 사건 — 「서희, 말 한마디로 강동 6주를 얻다」","㉯ 인터뷰 — 「신석기인에게 묻다, 왜 강가에 집을 지었나요?」","㉰ 광고 — 「상감 청자 주전자 들어왔습니다」","㉱ 만화 — 「구석기 어린이의 하루」","㉲ 광고 — 「신석기 마을에 청동 검 팝니다」"],"title":"우리 반 역사 신문 기사 목록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_basic#7','soc',5,2,'u1','L13','g5_2_soc_u1_L13_basic','lesson_basic','SO5-2-u1-C24',2,'mc','auto','역사 신문 만들기 순서 카드에서 가장 먼저 할 일은 어느 것인가요?',ARRAY['SO5-2-u1-X41']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C24","difficulty":2,"kind":"mc","stem":"역사 신문 만들기 순서 카드에서 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"ㄴ","correct":true},{"t":"ㄱ","mis":"SO5-2-u1-X41"},{"t":"ㄷ","mis":"SO5-2-u1-X41"},{"t":"ㄹ","mis":"SO5-2-u1-X41"}],"explanation":["먼저 이름과 주제를 정해요.","자료를 모아요.","ㄴ이 처음이에요."],"asset":{"type":"passage","lines":["ㄱ 기사를 모아 배치하고 신문 이름과 날짜를 쓴다.","ㄴ 신문 이름과 기사 주제를 정하고 자료를 모은다.","ㄷ 모은 자료로 알맞은 기사를 쓴다.","ㄹ 완성한 신문을 전시하고 함께 읽는다."],"title":"역사 신문 만들기 순서 카드(섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_basic#8','soc',5,2,'u1','L13','g5_2_soc_u1_L13_basic','lesson_basic','SO5-2-u1-C24',2,'mc','auto','역사 신문의 기사 자료를 모으기에 알맞은 곳으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X40']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C24","difficulty":2,"kind":"mc","stem":"역사 신문의 기사 자료를 모으기에 알맞은 곳으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"교과서와 박물관 누리집","correct":true},{"t":"친구가 지어낸 이야기","mis":"SO5-2-u1-X40"},{"t":"오늘 날씨 예보","mis":"SO5-2-u1-X40"},{"t":"만화 영화 속 장면","mis":"SO5-2-u1-X40"}],"explanation":["사실을 확인할 수 있어야 해요.","교과서와 박물관이 좋아요.","유물 사진과 기록을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_basic#9','soc',5,2,'u1','L13','g5_2_soc_u1_L13_basic','lesson_basic','SO5-2-u1-C24',2,'ox','auto','「신석기인 인터뷰」처럼 꾸민 형식을 쓰더라도 내용은 유적과 유물로 확인한 사실에 맞아야 해요.',ARRAY['SO5-2-u1-X40']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C24","difficulty":2,"kind":"ox","stem":"「신석기인 인터뷰」처럼 꾸민 형식을 쓰더라도 내용은 유적과 유물로 확인한 사실에 맞아야 해요.","answer":"O","reason_options":[{"t":"형식은 상상해도 되지만 내용은 사실이어야 역사 신문이 되기 때문에","correct":true},{"t":"역사 신문은 모두 지어낸 이야기여야 하기 때문에","mis":"SO5-2-u1-X40"}],"mis":"SO5-2-u1-X40","explanation":["형식은 꾸밀 수 있어요.","내용은 사실이어야 해요.","유적과 유물로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_basic#10','soc',5,2,'u1','L13','g5_2_soc_u1_L13_basic','lesson_basic','SO5-2-u1-C24',3,'error','auto','역사 신문을 만들며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X40','SO5-2-u1-X41']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C24","difficulty":3,"kind":"error","stem":"역사 신문을 만들며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"세라 — 「재미있으면 되니까 고려 신문에 휴대 전화 광고를 넣자.」","correct":true,"mis_target":"SO5-2-u1-X40"},{"t":"윤호 — 「고려 신문엔 서희의 담판을 사건 기사로 쓰자.」","mis":"SO5-2-u1-X41"},{"t":"지유 — 「상감 청자는 광고 기사로 소개하면 좋겠어.」","mis":"SO5-2-u1-X41"}],"explanation":["고려에는 휴대 전화가 없었어요.","사실과 어긋나요.","세라의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_challenge#1','soc',5,2,'u1','L13','g5_2_soc_u1_L13_challenge','lesson_challenge','SO5-2-u1-C24',2,'match','auto','역사 신문 기사 갈래와 보여 주기 좋은 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C24","difficulty":2,"kind":"match","stem":"역사 신문 기사 갈래와 보여 주기 좋은 것을 알맞게 이으세요.","pairs":[{"l":"사건","r":"무슨 일이 왜 일어났는지"},{"l":"인터뷰","r":"옛사람의 생각"},{"l":"광고","r":"그때 쓰던 물건"},{"l":"만화","r":"사람들의 생활 모습"}],"mis":"SO5-2-u1-X41","explanation":["사건은 일어난 일이에요.","인터뷰는 생각이에요.","광고는 물건, 만화는 생활이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_challenge#2','soc',5,2,'u1','L13','g5_2_soc_u1_L13_challenge','lesson_challenge','SO5-2-u1-C24',2,'mc','auto','역사 신문 만들기 순서 카드를 차례로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X41']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C24","difficulty":2,"kind":"mc","stem":"역사 신문 만들기 순서 카드를 차례로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"ㄴ → ㄷ → ㄱ → ㄹ","correct":true},{"t":"ㄱ → ㄴ → ㄷ → ㄹ","mis":"SO5-2-u1-X41"},{"t":"ㄷ → ㄴ → ㄹ → ㄱ","mis":"SO5-2-u1-X41"},{"t":"ㄹ → ㄷ → ㄴ → ㄱ","mis":"SO5-2-u1-X41"}],"explanation":["주제와 자료가 먼저예요.","기사를 쓰고 배치해요.","마지막에 전시해요."],"asset":{"type":"passage","lines":["ㄱ 기사를 모아 배치하고 신문 이름과 날짜를 쓴다.","ㄴ 신문 이름과 기사 주제를 정하고 자료를 모은다.","ㄷ 모은 자료로 알맞은 기사를 쓴다.","ㄹ 완성한 신문을 전시하고 함께 읽는다."],"title":"역사 신문 만들기 순서 카드(섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_challenge#3','soc',5,2,'u1','L13','g5_2_soc_u1_L13_challenge','lesson_challenge','SO5-2-u1-C24',3,'mc','auto','「신석기 신문」을 만들 때 실을 기사로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X08']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C24","difficulty":3,"kind":"mc","stem":"「신석기 신문」을 만들 때 실을 기사로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「강가에 움집 마을 생겼다」 — 빗살무늬 토기에 먹을 것을 보관해","correct":true},{"t":"「고인돌 세우는 날」 — 지배자의 무덤","mis":"SO5-2-u1-X08"},{"t":"「비파형 동검 새로 나왔다」","mis":"SO5-2-u1-X08"},{"t":"「주먹 도끼 들고 이사 가요」 — 먹을 것을 찾아","mis":"SO5-2-u1-X08"}],"explanation":["신석기는 움집과 토기예요.","고인돌·동검은 청동기예요.","주먹 도끼 이사는 구석기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_challenge#4','soc',5,2,'u1','L13','g5_2_soc_u1_L13_challenge','lesson_challenge','SO5-2-u1-C24',3,'mc','auto','「고려 신문」의 머리기사로 쓸 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X26']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C24","difficulty":3,"kind":"mc","stem":"「고려 신문」의 머리기사로 쓸 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서희, 말 한마디로 강동 6주를 얻다","correct":true},{"t":"대조영, 동모산에 나라를 세우다","mis":"SO5-2-u1-X26"},{"t":"신라와 당, 백제를 무너뜨리다","mis":"SO5-2-u1-X26"},{"t":"단군왕검, 아사달에 도읍하다","mis":"SO5-2-u1-X26"}],"explanation":["대조영은 발해예요.","신라와 당은 통일신라 이야기예요.","서희의 담판이 고려예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_challenge#5','soc',5,2,'u1','L13','g5_2_soc_u1_L13_challenge','lesson_challenge','SO5-2-u1-C24',3,'ox','auto','우리 반 소식을 신문으로 남기면 훗날 지금 우리의 생활을 짐작하는 역사 기록이 될 수 있어요.',ARRAY['SO5-2-u1-X42']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C24","difficulty":3,"kind":"ox","stem":"우리 반 소식을 신문으로 남기면 훗날 지금 우리의 생활을 짐작하는 역사 기록이 될 수 있어요.","answer":"O","reason_options":[{"t":"오늘의 기록도 시간이 흐르면 그때 사람들의 생활을 알려 주는 자료가 되기 때문에","correct":true},{"t":"역사 기록은 아주 먼 옛날 사람만 남길 수 있기 때문에","mis":"SO5-2-u1-X42"}],"mis":"SO5-2-u1-X42","explanation":["오늘도 시간이 흘러요.","기록은 남아요.","훗날 역사 기록이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_challenge#6','soc',5,2,'u1','L13','g5_2_soc_u1_L13_challenge','lesson_challenge','SO5-2-u1-C24',3,'error','auto','「구석기 신문」 기사를 고치며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X08','SO5-2-u1-X40']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C24","difficulty":3,"kind":"error","stem":"「구석기 신문」 기사를 고치며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"한결 — 「구석기 사람들이 토기에 곡식을 보관했다는 기사를 넣자.」","correct":true,"mis_target":"SO5-2-u1-X08"},{"t":"예솔 — 「불을 피워 짐승을 막았다는 기사를 넣자.」","mis":"SO5-2-u1-X40"},{"t":"도유 — 「주먹 도끼 광고를 넣자.」","mis":"SO5-2-u1-X40"}],"explanation":["토기와 곡식 보관은 신석기 이야기예요.","구석기와 맞지 않아요.","한결의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_challenge#7','soc',5,2,'u1','L13','g5_2_soc_u1_L13_challenge','lesson_challenge','SO5-2-u1-C24',3,'mc','auto','역사 신문 기사를 쓸 때 가장 먼저 확인해야 할 것은 어느 것인가요?',ARRAY['SO5-2-u1-X40']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C24","difficulty":3,"kind":"mc","stem":"역사 신문 기사를 쓸 때 가장 먼저 확인해야 할 것은 어느 것인가요?","options":[{"t":"기사 내용이 그 시대의 유적·유물·기록과 맞는지","correct":true},{"t":"기사가 얼마나 길게 쓰였는지","mis":"SO5-2-u1-X40"},{"t":"글씨 색이 얼마나 화려한지","mis":"SO5-2-u1-X40"},{"t":"친구들이 지어낸 이야기인지","mis":"SO5-2-u1-X40"}],"explanation":["사실이 가장 중요해요.","그 시대 자료와 맞춰 봐요.","그다음에 꾸며요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_challenge#8','soc',5,2,'u1','L13','g5_2_soc_u1_L13_challenge','lesson_challenge','SO5-2-u1-C24',4,'mc','auto','「고조선 신문」 기사 가운데 사실과 어긋나는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X40']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C24","difficulty":4,"kind":"mc","stem":"「고조선 신문」 기사 가운데 사실과 어긋나는 것은 어느 것인가요?","options":[{"t":"「철로 만든 괭이 날개 돋친 듯 팔려」","correct":true},{"t":"「8조법, 남을 다치게 하면 곡식으로 갚아야」","mis":"SO5-2-u1-X40"},{"t":"「단군왕검, 나라를 세우다」","mis":"SO5-2-u1-X40"},{"t":"「비파형 동검, 지배자의 상징」","mis":"SO5-2-u1-X40"}],"explanation":["고조선은 청동기 문화예요.","8조법·단군왕검·비파형 동검은 맞아요.","철 괭이 기사가 어긋나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_challenge#9','soc',5,2,'u1','L13','g5_2_soc_u1_L13_challenge','lesson_challenge','SO5-2-u1-C24',4,'mc','auto','단원에서 공부한 시대 가운데 하나를 골라 역사 신문을 만드는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X42','SO5-2-u1-X40','SO5-2-u1-X41']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C24","difficulty":4,"kind":"mc","stem":"단원에서 공부한 시대 가운데 하나를 골라 역사 신문을 만드는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"공부한 내용을 사실에 맞게 골라 정리하고, 옛 사람들의 생활을 다른 사람에게 알기 쉽게 전하려고","correct":true},{"t":"시대마다 왕 이름과 연도를 외우려고","mis":"SO5-2-u1-X42"},{"t":"지어낸 이야기를 쓰는 연습을 하려고","mis":"SO5-2-u1-X40"},{"t":"신문 꾸미기 솜씨만 겨루려고","mis":"SO5-2-u1-X41"}],"explanation":["공부한 내용을 골라요.","사실에 맞게 정리해요.","알기 쉽게 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_L13_challenge#10','soc',5,2,'u1','L13','g5_2_soc_u1_L13_challenge','lesson_challenge','SO5-2-u1-C24',4,'essay','teacher','단원에서 공부한 시대 하나를 골라 역사 신문의 이름과 기사 두 개(갈래와 제목, 한 줄 내용)를 쓰고, 기사가 사실에 맞는지 어떤 자료로 확인했는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u1-C24","difficulty":4,"kind":"essay","stem":"단원에서 공부한 시대 하나를 골라 역사 신문의 이름과 기사 두 개(갈래와 제목, 한 줄 내용)를 쓰고, 기사가 사실에 맞는지 어떤 자료로 확인했는지 쓰세요.","answer_guide":{"answer":"예: 신문 이름 — 「통일신라 소식」. 사건 기사 — 「신라, 당을 물리치고 삼국 통일 이뤄」: 당과 손잡았다가 한반도를 차지하려는 당을 몰아냈다. 인터뷰 — 「불국사를 지은 장인에게 묻다」: 부처의 나라를 이 땅에 만들고 싶었다고 답했다. 교과서의 역사 기록과 불국사 사진으로 확인했다.","scoring_points":["한 시대를 골라 신문 이름을 썼는가","기사 두 개를 갈래와 함께 썼는가","확인한 자료를 썼는가"]},"explanation":["시대를 골라요.","갈래를 정해 기사를 써요.","자료로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#1','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C1',1,'mc','auto','누리 수첩 ③의 「땅을 파고 지은 집이 모인 자리」는 유적과 유물 가운데 무엇인가요?',ARRAY['SO5-2-u1-X01','SO5-2-u1-X02','SO5-2-u1-X42']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C1","difficulty":1,"kind":"mc","stem":"누리 수첩 ③의 「땅을 파고 지은 집이 모인 자리」는 유적과 유물 가운데 무엇인가요?","options":[{"t":"유적","correct":true},{"t":"유물","mis":"SO5-2-u1-X01"},{"t":"기록","mis":"SO5-2-u1-X02"},{"t":"지도","mis":"SO5-2-u1-X42"}],"explanation":["집터는 자리예요.","옮길 수 없어요.","유적이에요."],"asset":{"type":"passage","lines":["① 첫 전시실 — 깨뜨려 만든 돌도끼 옆에 동굴 속 불 피운 자리 사진이 있었다.","② 다음 진열장 — 바닥이 뾰족한 무늬 그릇과 가운데 구멍 난 둥근 돌이 있었다.","③ 강가 마을 모형 — 땅을 파고 지은 집이 여러 채 모여 있었다."],"title":"누리의 박물관 견학 수첩 ①(선사실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#2','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C2',1,'mc','auto','누리 수첩 ①의 「깨뜨려 만든 돌도끼」를 쓴 시대는 어느 것인가요?',ARRAY['SO5-2-u1-X03','SO5-2-u1-X08']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C2","difficulty":1,"kind":"mc","stem":"누리 수첩 ①의 「깨뜨려 만든 돌도끼」를 쓴 시대는 어느 것인가요?","options":[{"t":"구석기 시대","correct":true},{"t":"신석기 시대","mis":"SO5-2-u1-X03"},{"t":"청동기 시대","mis":"SO5-2-u1-X08"},{"t":"고려 시대","mis":"SO5-2-u1-X08"}],"explanation":["깨뜨려 만들었어요.","뗀석기예요.","구석기 시대예요."],"asset":{"type":"passage","lines":["① 첫 전시실 — 깨뜨려 만든 돌도끼 옆에 동굴 속 불 피운 자리 사진이 있었다.","② 다음 진열장 — 바닥이 뾰족한 무늬 그릇과 가운데 구멍 난 둥근 돌이 있었다.","③ 강가 마을 모형 — 땅을 파고 지은 집이 여러 채 모여 있었다."],"title":"누리의 박물관 견학 수첩 ①(선사실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#3','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C6',1,'mc','auto','누리 수첩 ⑥의 「탁자처럼 생긴 거대한 돌무덤」은 무엇인가요?',ARRAY['SO5-2-u1-X11','SO5-2-u1-X26']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C6","difficulty":1,"kind":"mc","stem":"누리 수첩 ⑥의 「탁자처럼 생긴 거대한 돌무덤」은 무엇인가요?","options":[{"t":"고인돌","correct":true},{"t":"움집","mis":"SO5-2-u1-X11"},{"t":"석굴암","mis":"SO5-2-u1-X26"},{"t":"막집","mis":"SO5-2-u1-X11"}],"explanation":["돌로 만든 무덤이에요.","탁자처럼 생겼어요.","고인돌이에요."],"asset":{"type":"passage","lines":["④ 청동기실 — 반짝이는 검과 거울은 한 무덤에서만 나왔다고 한다.","⑤ 그 옆에는 반달 모양 돌칼과 무늬 없는 토기가 가득했다.","⑥ 바깥 마당 — 탁자처럼 생긴 거대한 돌무덤을 본떠 세워 두었다.","⑦ 벽 안내문 — 「사람을 다치게 하면 곡식으로 갚는다.」"],"title":"누리의 박물관 견학 수첩 ②(청동기·고조선실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#4','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C7',1,'mc','auto','고조선을 세운 사람은 누구인가요?',ARRAY['SO5-2-u1-X27','SO5-2-u1-X29','SO5-2-u1-X15']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C7","difficulty":1,"kind":"mc","stem":"고조선을 세운 사람은 누구인가요?","options":[{"t":"단군왕검","correct":true},{"t":"대조영","mis":"SO5-2-u1-X27"},{"t":"왕건","mis":"SO5-2-u1-X29"},{"t":"주몽","mis":"SO5-2-u1-X15"}],"explanation":["우리 역사의 첫 나라예요.","건국 이야기에 나와요.","단군왕검이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#5','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C9',1,'mc','auto','삼국과 가야가 세워지는 바탕이 된 문화는 어느 것인가요?',ARRAY['SO5-2-u1-X15']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C9","difficulty":1,"kind":"mc","stem":"삼국과 가야가 세워지는 바탕이 된 문화는 어느 것인가요?","options":[{"t":"철기 문화","correct":true},{"t":"청동기 문화","mis":"SO5-2-u1-X15"},{"t":"신석기 문화","mis":"SO5-2-u1-X15"},{"t":"구석기 문화","mis":"SO5-2-u1-X15"}],"explanation":["철로 농기구를 만들었어요.","철 무기도 만들었어요.","철기 문화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#6','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C13',1,'mc','auto','누리 수첩 ⑪의 마을 문서를 무엇이라고 하나요?',ARRAY['SO5-2-u1-X24']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C13","difficulty":1,"kind":"mc","stem":"누리 수첩 ⑪의 마을 문서를 무엇이라고 하나요?","options":[{"t":"신라 촌락 문서","correct":true},{"t":"훈요 10조","mis":"SO5-2-u1-X24"},{"t":"8조법","mis":"SO5-2-u1-X24"},{"t":"직지","mis":"SO5-2-u1-X24"}],"explanation":["마을의 사람과 말을 셌어요.","통일신라 때예요.","신라 촌락 문서예요."],"asset":{"type":"passage","lines":["⑪ 통일신라실 — 사람·말·뽕나무 수를 적은 마을 문서를 보았다.","⑫ 턱수염 짙은 돌사람 사진 — 먼 서쪽 사람의 얼굴이라 한다.","⑬ 북쪽 나라 코너 — 고구려와 꼭 닮은 꽃잎 무늬 기와와 온돌 집터 모형","⑭ 세 빛깔 향로 — 당의 도자기를 닮았다는 설명이 붙어 있었다."],"title":"누리의 박물관 견학 수첩 ④(통일신라·발해실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#7','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C15',1,'mc','auto','고구려 출신 대조영이 세운 나라는 어느 것인가요?',ARRAY['SO5-2-u1-X27']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C15","difficulty":1,"kind":"mc","stem":"고구려 출신 대조영이 세운 나라는 어느 것인가요?","options":[{"t":"발해","correct":true},{"t":"고려","mis":"SO5-2-u1-X27"},{"t":"후고구려","mis":"SO5-2-u1-X27"},{"t":"가야","mis":"SO5-2-u1-X27"}],"explanation":["고구려 유민을 이끌었어요.","동모산에 세웠어요.","발해예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#8','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C17',1,'mc','auto','누리 수첩 ⑮의 「궁예를 몰아낸 왕」은 누구인가요?',ARRAY['SO5-2-u1-X29']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C17","difficulty":1,"kind":"mc","stem":"누리 수첩 ⑮의 「궁예를 몰아낸 왕」은 누구인가요?","options":[{"t":"왕건","correct":true},{"t":"견훤","mis":"SO5-2-u1-X29"},{"t":"서희","mis":"SO5-2-u1-X29"},{"t":"대조영","mis":"SO5-2-u1-X29"}],"explanation":["궁예의 부하였어요.","고려를 세웠어요.","왕건이에요."],"asset":{"type":"passage","lines":["⑮ 고려실 — 궁예를 몰아낸 왕이 고구려를 잇겠다며 나라 이름을 정했다.","⑯ 붉은 종이 합격증 — 시험을 보아 관리를 뽑았다는 증거라고 한다.","⑰ 남매가 재산을 반씩 나눈 이야기 그림이 걸려 있었다.","⑱ 등불 행렬 그림 — 오늘날 거리의 연등 행렬과 닮았다."],"title":"누리의 박물관 견학 수첩 ⑤(고려 사회실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#9','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C4',2,'mc','auto','누리 수첩 ③의 강가 마을 모형으로 알 수 있는 신석기 사람들의 생활은 어느 것인가요?',ARRAY['SO5-2-u1-X04','SO5-2-u1-X07','SO5-2-u1-X10']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C4","difficulty":2,"kind":"mc","stem":"누리 수첩 ③의 강가 마을 모형으로 알 수 있는 신석기 사람들의 생활은 어느 것인가요?","options":[{"t":"움집을 짓고 마을을 이루어 한곳에 머물러 살았다","correct":true},{"t":"먹을 것을 찾아 늘 옮겨 다녔다","mis":"SO5-2-u1-X04"},{"t":"높은 산꼭대기에 성을 쌓았다","mis":"SO5-2-u1-X07"},{"t":"지배자의 고인돌 둘레에 살았다","mis":"SO5-2-u1-X10"}],"explanation":["집이 여러 채예요.","강가에 모였어요.","정착 생활이에요."],"asset":{"type":"passage","lines":["① 첫 전시실 — 깨뜨려 만든 돌도끼 옆에 동굴 속 불 피운 자리 사진이 있었다.","② 다음 진열장 — 바닥이 뾰족한 무늬 그릇과 가운데 구멍 난 둥근 돌이 있었다.","③ 강가 마을 모형 — 땅을 파고 지은 집이 여러 채 모여 있었다."],"title":"누리의 박물관 견학 수첩 ①(선사실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#10','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C11',2,'mc','auto','누리 수첩 ⑧의 벽화에서 주인을 크게 그린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X20']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C11","difficulty":2,"kind":"mc","stem":"누리 수첩 ⑧의 벽화에서 주인을 크게 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"신분이 높은 사람을 크게 나타냈기 때문에","correct":true},{"t":"가까이 있는 사람이라서","mis":"SO5-2-u1-X20"},{"t":"나이가 가장 많아서","mis":"SO5-2-u1-X20"},{"t":"그림을 잘못 그려서","mis":"SO5-2-u1-X20"}],"explanation":["주인은 귀족이에요.","시중드는 사람은 작아요.","신분 차이를 나타냈어요."],"asset":{"type":"passage","lines":["⑧ 고대실 — 무덤 벽화 사진 속 주인은 크고 시중드는 사람은 작았다.","⑨ 철을 납작하게 편 덩이쇠와 말 탄 무사 모양 토기가 있었다.","⑩ 한강 지도 — 세 나라가 번갈아 차지한 땅에 색이 칠해져 있었다."],"title":"누리의 박물관 견학 수첩 ③(삼국·가야실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#11','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C12',2,'mc','auto','삼국이 불교를 받아들인 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X21']::text[],false,'{"seq":11,"concept":"SO5-2-u1-C12","difficulty":2,"kind":"mc","stem":"삼국이 불교를 받아들인 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"백성의 마음을 하나로 모으고 왕의 힘을 키우려고","correct":true},{"t":"외국 옷을 따라 입으려고","mis":"SO5-2-u1-X21"},{"t":"귀족들의 힘을 키워 주려고","mis":"SO5-2-u1-X21"},{"t":"농사를 그만두려고","mis":"SO5-2-u1-X21"}],"explanation":["여러 믿음이 있었어요.","마음을 모았어요.","왕의 힘이 커졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#12','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C16',2,'mc','auto','누리 수첩 ⑭의 세 빛깔 향로로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X25','SO5-2-u1-X26','SO5-2-u1-X21']::text[],false,'{"seq":12,"concept":"SO5-2-u1-C16","difficulty":2,"kind":"mc","stem":"누리 수첩 ⑭의 세 빛깔 향로로 알 수 있는 것은 어느 것인가요?","options":[{"t":"발해가 당과 교류했다","correct":true},{"t":"발해가 당과 전혀 오가지 않았다","mis":"SO5-2-u1-X25"},{"t":"향로는 고려 청자다","mis":"SO5-2-u1-X26"},{"t":"발해에는 불교가 없었다","mis":"SO5-2-u1-X21"}],"explanation":["당의 도자기를 닮았어요.","만드는 법이 전해졌어요.","당과 교류했어요."],"asset":{"type":"passage","lines":["⑪ 통일신라실 — 사람·말·뽕나무 수를 적은 마을 문서를 보았다.","⑫ 턱수염 짙은 돌사람 사진 — 먼 서쪽 사람의 얼굴이라 한다.","⑬ 북쪽 나라 코너 — 고구려와 꼭 닮은 꽃잎 무늬 기와와 온돌 집터 모형","⑭ 세 빛깔 향로 — 당의 도자기를 닮았다는 설명이 붙어 있었다."],"title":"누리의 박물관 견학 수첩 ④(통일신라·발해실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#13','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C19',2,'mc','auto','누리 수첩 ⑰의 남매 이야기로 알 수 있는 고려 사회의 모습은 어느 것인가요?',ARRAY['SO5-2-u1-X32']::text[],false,'{"seq":13,"concept":"SO5-2-u1-C19","difficulty":2,"kind":"mc","stem":"누리 수첩 ⑰의 남매 이야기로 알 수 있는 고려 사회의 모습은 어느 것인가요?","options":[{"t":"아들딸이 재산을 똑같이 나누어 받았다","correct":true},{"t":"재산은 아들만 받았다","mis":"SO5-2-u1-X32"},{"t":"딸은 재산을 받을 수 없었다","mis":"SO5-2-u1-X32"},{"t":"재산은 모두 나라에 바쳤다","mis":"SO5-2-u1-X32"}],"explanation":["반씩 나누었어요.","아들딸이 같아요.","집안에서 같은 지위였어요."],"asset":{"type":"passage","lines":["⑮ 고려실 — 궁예를 몰아낸 왕이 고구려를 잇겠다며 나라 이름을 정했다.","⑯ 붉은 종이 합격증 — 시험을 보아 관리를 뽑았다는 증거라고 한다.","⑰ 남매가 재산을 반씩 나눈 이야기 그림이 걸려 있었다.","⑱ 등불 행렬 그림 — 오늘날 거리의 연등 행렬과 닮았다."],"title":"누리의 박물관 견학 수첩 ⑤(고려 사회실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#14','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C20',2,'mc','auto','누리 수첩 ⑲의 「말로 맞서 땅을 얻은 신하」가 얻은 땅은 어느 것인가요?',ARRAY['SO5-2-u1-X34']::text[],false,'{"seq":14,"concept":"SO5-2-u1-C20","difficulty":2,"kind":"mc","stem":"누리 수첩 ⑲의 「말로 맞서 땅을 얻은 신하」가 얻은 땅은 어느 것인가요?","options":[{"t":"강동 6주","correct":true},{"t":"한강 유역","mis":"SO5-2-u1-X34"},{"t":"강화도","mis":"SO5-2-u1-X34"},{"t":"귀주","mis":"SO5-2-u1-X34"}],"explanation":["서희의 담판이에요.","싸우지 않고 얻었어요.","강동 6주예요."],"asset":{"type":"passage","lines":["⑲ 외교 코너 — 말로 맞서 싸우지 않고 땅을 얻은 신하의 이야기","⑳ 항구 모형 — 예성강에 아라비아 상인의 배까지 떠 있었다.","㉑ 섬 지도 — 몽골군을 피해 수도를 옮긴 곳이라 한다.","㉒ 노비 문서를 태우는 승려 그림 — 모두 함께 성을 지켰다."],"title":"누리의 박물관 견학 수첩 ⑥(고려와 주변 나라실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#15','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C21',2,'mc','auto','누리 수첩 ㉑의 「몽골군을 피해 수도를 옮긴 곳」은 어디인가요?',ARRAY['SO5-2-u1-X36']::text[],false,'{"seq":15,"concept":"SO5-2-u1-C21","difficulty":2,"kind":"mc","stem":"누리 수첩 ㉑의 「몽골군을 피해 수도를 옮긴 곳」은 어디인가요?","options":[{"t":"강화도","correct":true},{"t":"벽란도","mis":"SO5-2-u1-X36"},{"t":"평양","mis":"SO5-2-u1-X36"},{"t":"경주","mis":"SO5-2-u1-X36"}],"explanation":["섬이에요.","몽골군이 건너기 어려웠어요.","강화도예요."],"asset":{"type":"passage","lines":["⑲ 외교 코너 — 말로 맞서 싸우지 않고 땅을 얻은 신하의 이야기","⑳ 항구 모형 — 예성강에 아라비아 상인의 배까지 떠 있었다.","㉑ 섬 지도 — 몽골군을 피해 수도를 옮긴 곳이라 한다.","㉒ 노비 문서를 태우는 승려 그림 — 모두 함께 성을 지켰다."],"title":"누리의 박물관 견학 수첩 ⑥(고려와 주변 나라실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#16','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C22',2,'mc','auto','누리 수첩 ㉓의 주전자를 만든 고려만의 기법은 어느 것인가요?',ARRAY['SO5-2-u1-X37']::text[],false,'{"seq":16,"concept":"SO5-2-u1-C22","difficulty":2,"kind":"mc","stem":"누리 수첩 ㉓의 주전자를 만든 고려만의 기법은 어느 것인가요?","options":[{"t":"상감 기법","correct":true},{"t":"빗살무늬 기법","mis":"SO5-2-u1-X37"},{"t":"금속 활자 기법","mis":"SO5-2-u1-X37"},{"t":"민무늬 기법","mis":"SO5-2-u1-X37"}],"explanation":["무늬를 파냈어요.","다른 색 흙을 메웠어요.","상감 기법이에요."],"asset":{"type":"passage","lines":["㉓ 푸른 주전자 — 무늬를 파내고 흰 흙·붉은 흙으로 메웠다.","㉔ 나무판 사진 — 몽골을 물리치기를 빌며 다시 새겼다고 한다.","㉕ 작은 쇠 글자들 — 다시 짜서 여러 책을 찍었다고 한다.","㉖ 솜이불과 무명옷 — 목화씨 몇 알에서 시작되었다고 한다."],"title":"누리의 박물관 견학 수첩 ⑦(고려 문화실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#17','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C6',3,'mc','auto','누리 수첩 ①~⑥을 차례로 볼 때 사람들의 생활이 달라진 흐름으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X08','SO5-2-u1-X10']::text[],false,'{"seq":17,"concept":"SO5-2-u1-C6","difficulty":3,"kind":"mc","stem":"누리 수첩 ①~⑥을 차례로 볼 때 사람들의 생활이 달라진 흐름으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옮겨 다니는 생활 → 강가에 머무는 생활 → 곡식이 남아 지배자가 생긴 생활","correct":true},{"t":"지배자가 다스리는 생활 → 옮겨 다니는 생활 → 강가에 머무는 생활","mis":"SO5-2-u1-X08"},{"t":"강가에 머무는 생활 → 옮겨 다니는 생활 → 나라를 세운 생활","mis":"SO5-2-u1-X08"},{"t":"처음부터 끝까지 똑같은 생활","mis":"SO5-2-u1-X10"}],"explanation":["구석기는 옮겨 다녀요.","신석기는 머물러요.","청동기에는 지배자가 생겨요."],"asset":{"type":"passage","lines":["④ 청동기실 — 반짝이는 검과 거울은 한 무덤에서만 나왔다고 한다.","⑤ 그 옆에는 반달 모양 돌칼과 무늬 없는 토기가 가득했다.","⑥ 바깥 마당 — 탁자처럼 생긴 거대한 돌무덤을 본떠 세워 두었다.","⑦ 벽 안내문 — 「사람을 다치게 하면 곡식으로 갚는다.」"],"title":"누리의 박물관 견학 수첩 ②(청동기·고조선실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#18','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C8',3,'mc','auto','누리 수첩 ⑦의 안내문으로 짐작할 수 있는 고조선 사회의 모습은 어느 것인가요?',ARRAY['SO5-2-u1-X13','SO5-2-u1-X15']::text[],false,'{"seq":18,"concept":"SO5-2-u1-C8","difficulty":3,"kind":"mc","stem":"누리 수첩 ⑦의 안내문으로 짐작할 수 있는 고조선 사회의 모습은 어느 것인가요?","options":[{"t":"농사를 짓고 곡식을 귀하게 여겼으며 남의 몸을 해치는 일을 벌했다","correct":true},{"t":"곡식을 전혀 기르지 않았다","mis":"SO5-2-u1-X13"},{"t":"다툼이 있어도 벌이 없었다","mis":"SO5-2-u1-X13"},{"t":"철 농기구로 농사를 지었다","mis":"SO5-2-u1-X15"}],"explanation":["곡식으로 갚아요.","곡식이 값어치가 있어요.","해치는 일을 벌했어요."],"asset":{"type":"passage","lines":["④ 청동기실 — 반짝이는 검과 거울은 한 무덤에서만 나왔다고 한다.","⑤ 그 옆에는 반달 모양 돌칼과 무늬 없는 토기가 가득했다.","⑥ 바깥 마당 — 탁자처럼 생긴 거대한 돌무덤을 본떠 세워 두었다.","⑦ 벽 안내문 — 「사람을 다치게 하면 곡식으로 갚는다.」"],"title":"누리의 박물관 견학 수첩 ②(청동기·고조선실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#19','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C10',3,'mc','auto','누리 수첩 ⑩의 한강 지도처럼 세 나라가 한강 유역을 번갈아 차지한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X17']::text[],false,'{"seq":19,"concept":"SO5-2-u1-C10","difficulty":3,"kind":"mc","stem":"누리 수첩 ⑩의 한강 지도처럼 세 나라가 한강 유역을 번갈아 차지한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"넓은 평야로 농사짓기 좋고 서해로 나가 중국과 오가기 좋은 곳이었기 때문에","correct":true},{"t":"산이 높아 숨기 좋았기 때문에","mis":"SO5-2-u1-X17"},{"t":"철이 전혀 나지 않았기 때문에","mis":"SO5-2-u1-X17"},{"t":"아무도 원하지 않는 땅이었기 때문에","mis":"SO5-2-u1-X17"}],"explanation":["넓은 평야예요.","서해로 나가요.","모두 원했어요."],"asset":{"type":"passage","lines":["⑧ 고대실 — 무덤 벽화 사진 속 주인은 크고 시중드는 사람은 작았다.","⑨ 철을 납작하게 편 덩이쇠와 말 탄 무사 모양 토기가 있었다.","⑩ 한강 지도 — 세 나라가 번갈아 차지한 땅에 색이 칠해져 있었다."],"title":"누리의 박물관 견학 수첩 ③(삼국·가야실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#20','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C15',3,'mc','auto','누리 수첩 ⑬과 ⑮를 함께 볼 때 발해와 고려의 공통점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X27','SO5-2-u1-X30']::text[],false,'{"seq":20,"concept":"SO5-2-u1-C15","difficulty":3,"kind":"mc","stem":"누리 수첩 ⑬과 ⑮를 함께 볼 때 발해와 고려의 공통점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 나라 모두 고구려를 이었다고 여겼다","correct":true},{"t":"두 나라 모두 신라를 이었다고 여겼다","mis":"SO5-2-u1-X27"},{"t":"두 나라 모두 가야를 이었다고 여겼다","mis":"SO5-2-u1-X30"},{"t":"두 나라는 같은 사람이 세웠다","mis":"SO5-2-u1-X27"}],"explanation":["발해는 고구려 문화를 이었어요.","고려는 이름에 고구려를 담았어요.","고구려 계승이 공통점이에요."],"asset":{"type":"passage","lines":["⑮ 고려실 — 궁예를 몰아낸 왕이 고구려를 잇겠다며 나라 이름을 정했다.","⑯ 붉은 종이 합격증 — 시험을 보아 관리를 뽑았다는 증거라고 한다.","⑰ 남매가 재산을 반씩 나눈 이야기 그림이 걸려 있었다.","⑱ 등불 행렬 그림 — 오늘날 거리의 연등 행렬과 닮았다."],"title":"누리의 박물관 견학 수첩 ⑤(고려 사회실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#21','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C18',3,'mc','auto','누리 수첩 ⑯의 합격증이 알려 주는 고려 초 정책의 결과로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X31']::text[],false,'{"seq":21,"concept":"SO5-2-u1-C18","difficulty":3,"kind":"mc","stem":"누리 수첩 ⑯의 합격증이 알려 주는 고려 초 정책의 결과로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실력 있는 관리를 나라가 직접 뽑아 호족의 힘이 약해졌다","correct":true},{"t":"호족이 관리를 마음대로 정했다","mis":"SO5-2-u1-X31"},{"t":"돈만 있으면 관리가 되었다","mis":"SO5-2-u1-X31"},{"t":"관리는 모두 노비 가운데서 뽑았다","mis":"SO5-2-u1-X31"}],"explanation":["시험으로 뽑았어요.","나라가 정했어요.","호족의 힘이 줄었어요."],"asset":{"type":"passage","lines":["⑮ 고려실 — 궁예를 몰아낸 왕이 고구려를 잇겠다며 나라 이름을 정했다.","⑯ 붉은 종이 합격증 — 시험을 보아 관리를 뽑았다는 증거라고 한다.","⑰ 남매가 재산을 반씩 나눈 이야기 그림이 걸려 있었다.","⑱ 등불 행렬 그림 — 오늘날 거리의 연등 행렬과 닮았다."],"title":"누리의 박물관 견학 수첩 ⑤(고려 사회실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#22','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C24',3,'mc','auto','누리 수첩 ⑧에서 누리 모둠이 「고인돌 세우기 대회」 기사를 빼기로 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X40','SO5-2-u1-X41']::text[],false,'{"seq":22,"concept":"SO5-2-u1-C24","difficulty":3,"kind":"mc","stem":"누리 수첩 ⑧에서 누리 모둠이 「고인돌 세우기 대회」 기사를 빼기로 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"고인돌은 청동기 시대 무덤이라 고려 신문의 내용과 맞지 않아서","correct":true},{"t":"고인돌은 고려 때 가장 많이 세워서","mis":"SO5-2-u1-X40"},{"t":"기사가 너무 짧아서","mis":"SO5-2-u1-X41"},{"t":"만화로 그려야 해서","mis":"SO5-2-u1-X41"}],"explanation":["고인돌은 청동기 시대예요.","고려와 맞지 않아요.","사실과 어긋나 뺐어요."],"asset":{"type":"passage","lines":["누리 모둠의 「고려 신문」 계획","사건 — 「붉은 합격증 받은 날」 · 인터뷰 — 「벽란도 상인에게 묻다」","광고 — 「상감 청자 주전자」 · 만화 — 「문익점과 목화 한 그루」","고칠 점 — 「고인돌 세우기 대회」 기사는 빼기로 했다."],"title":"누리의 박물관 견학 수첩 ⑧(우리 모둠 신문)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#23','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C1',4,'mc','auto','「유적과 유물로 살펴본 옛 사람들의 생활」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X08','SO5-2-u1-X42','SO5-2-u1-X02']::text[],false,'{"seq":23,"concept":"SO5-2-u1-C1","difficulty":4,"kind":"mc","stem":"「유적과 유물로 살펴본 옛 사람들의 생활」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"옮겨 다니던 사람들이 정착하고 나라를 세웠으며, 삼국·통일신라·발해를 거쳐 고려까지 저마다의 사회와 문화를 이루었고, 이를 유적·유물·기록으로 짐작한다","correct":true},{"t":"옛 사람들은 처음부터 고려 사람들처럼 살았다","mis":"SO5-2-u1-X08"},{"t":"나라 이름과 연도만 외우면 옛 생활을 모두 안다","mis":"SO5-2-u1-X42"},{"t":"선사 시대도 책을 읽으면 생활을 알 수 있다","mis":"SO5-2-u1-X02"}],"explanation":["생활이 달라져 왔어요.","나라와 문화가 이어졌어요.","자료로 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#24','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C4',4,'essay','teacher','누리 수첩 ①~③을 증거로 삼아 구석기 사람들과 신석기 사람들의 생활이 어떻게 달랐는지 도구·먹을거리·사는 곳 가운데 두 가지를 들어 쓰고, 그렇게 달라진 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u1-C4","difficulty":4,"kind":"essay","stem":"누리 수첩 ①~③을 증거로 삼아 구석기 사람들과 신석기 사람들의 생활이 어떻게 달랐는지 도구·먹을거리·사는 곳 가운데 두 가지를 들어 쓰고, 그렇게 달라진 까닭을 쓰세요.","answer_guide":{"answer":"예: 구석기 사람들은 ①처럼 깨뜨려 만든 뗀석기를 쓰고 동굴에서 지냈지만, 신석기 사람들은 간석기와 ②의 토기, 가락바퀴를 쓰고 ③처럼 강가에 움집을 지어 마을을 이루었다. 신석기 사람들은 물고기잡이 등으로 먹을 것을 꾸준히 구하고 토기에 보관할 수 있어 옮겨 다니지 않고 머물러 살게 되었다.","scoring_points":["두 시대를 두 가지 기준으로 견주었는가","수첩의 유물·유적을 증거로 들었는가","달라진 까닭(먹을 것을 꾸준히·보관)을 썼는가"]},"explanation":["도구와 사는 곳을 견주어요.","수첩을 증거로 들어요.","먹을 것을 꾸준히 구한 까닭을 써요."],"asset":{"type":"passage","lines":["① 첫 전시실 — 깨뜨려 만든 돌도끼 옆에 동굴 속 불 피운 자리 사진이 있었다.","② 다음 진열장 — 바닥이 뾰족한 무늬 그릇과 가운데 구멍 난 둥근 돌이 있었다.","③ 강가 마을 모형 — 땅을 파고 지은 집이 여러 채 모여 있었다."],"title":"누리의 박물관 견학 수첩 ①(선사실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_a#25','soc',5,2,'u1','','g5_2_soc_u1_review_a','unit_review','SO5-2-u1-C18',4,'essay','teacher','누리 수첩 ⑮~⑱을 보고 고려가 어떻게 세워졌고 어떤 사회였는지 건국·제도·여성·불교 가운데 세 가지를 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u1-C18","difficulty":4,"kind":"essay","stem":"누리 수첩 ⑮~⑱을 보고 고려가 어떻게 세워졌고 어떤 사회였는지 건국·제도·여성·불교 가운데 세 가지를 들어 쓰세요.","answer_guide":{"answer":"예: 고려는 궁예를 몰아낸 왕건이 고구려를 잇는다는 뜻으로 세웠다. ⑯의 붉은 합격증처럼 과거제로 실력 있는 관리를 뽑아 호족의 힘을 줄였다. ⑰처럼 아들딸이 재산을 똑같이 나누어 여성이 집안에서 남성과 같은 지위였고, ⑱처럼 연등회를 크게 열어 불교를 믿었다.","scoring_points":["건국을 썼는가","제도·여성·불교 가운데 두 가지를 더 썼는가","수첩의 자료와 이었는가"]},"explanation":["왕건과 고구려 계승이에요.","과거제와 여성의 지위예요.","연등회는 불교예요."],"asset":{"type":"passage","lines":["⑮ 고려실 — 궁예를 몰아낸 왕이 고구려를 잇겠다며 나라 이름을 정했다.","⑯ 붉은 종이 합격증 — 시험을 보아 관리를 뽑았다는 증거라고 한다.","⑰ 남매가 재산을 반씩 나눈 이야기 그림이 걸려 있었다.","⑱ 등불 행렬 그림 — 오늘날 거리의 연등 행렬과 닮았다."],"title":"누리의 박물관 견학 수첩 ⑤(고려 사회실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#1','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C1',1,'sa','auto','옛 사람들이 쓰던 도구나 그릇처럼 남겨진 물건을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u1-C1","difficulty":1,"kind":"sa","stem":"옛 사람들이 쓰던 도구나 그릇처럼 남겨진 물건을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["유물"],"explanation":["쓰던 물건이에요.","박물관 진열장에 있어요.","유물이에요."],"mis":"SO5-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#2','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C3',1,'mc','auto','누리 수첩 ②의 「가운데 구멍 난 둥근 돌」의 쓰임은 어느 것인가요?',ARRAY['SO5-2-u1-X06','SO5-2-u1-X09','SO5-2-u1-X08']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C3","difficulty":1,"kind":"mc","stem":"누리 수첩 ②의 「가운데 구멍 난 둥근 돌」의 쓰임은 어느 것인가요?","options":[{"t":"실을 뽑는 데 썼다","correct":true},{"t":"이삭을 자르는 데 썼다","mis":"SO5-2-u1-X06"},{"t":"제사를 지내는 데 썼다","mis":"SO5-2-u1-X09"},{"t":"글자를 찍는 데 썼다","mis":"SO5-2-u1-X08"}],"explanation":["가락바퀴예요.","막대를 끼워 돌려요.","실을 뽑았어요."],"asset":{"type":"passage","lines":["① 첫 전시실 — 깨뜨려 만든 돌도끼 옆에 동굴 속 불 피운 자리 사진이 있었다.","② 다음 진열장 — 바닥이 뾰족한 무늬 그릇과 가운데 구멍 난 둥근 돌이 있었다.","③ 강가 마을 모형 — 땅을 파고 지은 집이 여러 채 모여 있었다."],"title":"누리의 박물관 견학 수첩 ①(선사실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#3','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C5',1,'mc','auto','누리 수첩 ⑤의 반달 모양 돌칼은 무엇에 썼나요?',ARRAY['SO5-2-u1-X06','SO5-2-u1-X08']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C5","difficulty":1,"kind":"mc","stem":"누리 수첩 ⑤의 반달 모양 돌칼은 무엇에 썼나요?","options":[{"t":"벼 이삭을 거두는 데","correct":true},{"t":"실을 뽑는 데","mis":"SO5-2-u1-X06"},{"t":"물고기를 잡는 데","mis":"SO5-2-u1-X06"},{"t":"글자를 새기는 데","mis":"SO5-2-u1-X08"}],"explanation":["반달 돌칼이에요.","벼농사를 지었어요.","이삭을 거두었어요."],"asset":{"type":"passage","lines":["④ 청동기실 — 반짝이는 검과 거울은 한 무덤에서만 나왔다고 한다.","⑤ 그 옆에는 반달 모양 돌칼과 무늬 없는 토기가 가득했다.","⑥ 바깥 마당 — 탁자처럼 생긴 거대한 돌무덤을 본떠 세워 두었다.","⑦ 벽 안내문 — 「사람을 다치게 하면 곡식으로 갚는다.」"],"title":"누리의 박물관 견학 수첩 ②(청동기·고조선실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#4','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C8',1,'mc','auto','누리 수첩 ⑦의 벽 안내문은 고조선의 무엇을 옮긴 것인가요?',ARRAY['SO5-2-u1-X13']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C8","difficulty":1,"kind":"mc","stem":"누리 수첩 ⑦의 벽 안내문은 고조선의 무엇을 옮긴 것인가요?","options":[{"t":"8조법","correct":true},{"t":"훈요 10조","mis":"SO5-2-u1-X13"},{"t":"촌락 문서","mis":"SO5-2-u1-X13"},{"t":"과거제","mis":"SO5-2-u1-X13"}],"explanation":["곡식으로 갚게 했어요.","고조선의 법이에요.","8조법이에요."],"asset":{"type":"passage","lines":["④ 청동기실 — 반짝이는 검과 거울은 한 무덤에서만 나왔다고 한다.","⑤ 그 옆에는 반달 모양 돌칼과 무늬 없는 토기가 가득했다.","⑥ 바깥 마당 — 탁자처럼 생긴 거대한 돌무덤을 본떠 세워 두었다.","⑦ 벽 안내문 — 「사람을 다치게 하면 곡식으로 갚는다.」"],"title":"누리의 박물관 견학 수첩 ②(청동기·고조선실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#5','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C10',1,'mc','auto','수도를 평양으로 옮기고 한강 유역을 모두 차지한 고구려의 왕은 누구인가요?',ARRAY['SO5-2-u1-X16']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C10","difficulty":1,"kind":"mc","stem":"수도를 평양으로 옮기고 한강 유역을 모두 차지한 고구려의 왕은 누구인가요?","options":[{"t":"장수왕","correct":true},{"t":"진흥왕","mis":"SO5-2-u1-X16"},{"t":"근초고왕","mis":"SO5-2-u1-X16"},{"t":"왕건","mis":"SO5-2-u1-X16"}],"explanation":["고구려의 왕이에요.","평양으로 옮겼어요.","장수왕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#6','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C14',1,'mc','auto','통일신라 때 화강암을 쌓아 동굴처럼 만든 절은 어느 것인가요?',ARRAY['SO5-2-u1-X26']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C14","difficulty":1,"kind":"mc","stem":"통일신라 때 화강암을 쌓아 동굴처럼 만든 절은 어느 것인가요?","options":[{"t":"석굴암","correct":true},{"t":"해인사","mis":"SO5-2-u1-X26"},{"t":"정림사","mis":"SO5-2-u1-X26"},{"t":"벽란도","mis":"SO5-2-u1-X26"}],"explanation":["돌을 쌓았어요.","동굴처럼 생겼어요.","석굴암이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#7','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C15',1,'mc','auto','누리 수첩 ⑬의 「북쪽 나라」가 이어받았다고 밝힌 나라는 어느 것인가요?',ARRAY['SO5-2-u1-X27']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C15","difficulty":1,"kind":"mc","stem":"누리 수첩 ⑬의 「북쪽 나라」가 이어받았다고 밝힌 나라는 어느 것인가요?","options":[{"t":"고구려","correct":true},{"t":"신라","mis":"SO5-2-u1-X27"},{"t":"백제","mis":"SO5-2-u1-X27"},{"t":"당","mis":"SO5-2-u1-X27"}],"explanation":["기와와 온돌이 닮았어요.","고구려 출신이 세웠어요.","고구려를 이었어요."],"asset":{"type":"passage","lines":["⑪ 통일신라실 — 사람·말·뽕나무 수를 적은 마을 문서를 보았다.","⑫ 턱수염 짙은 돌사람 사진 — 먼 서쪽 사람의 얼굴이라 한다.","⑬ 북쪽 나라 코너 — 고구려와 꼭 닮은 꽃잎 무늬 기와와 온돌 집터 모형","⑭ 세 빛깔 향로 — 당의 도자기를 닮았다는 설명이 붙어 있었다."],"title":"누리의 박물관 견학 수첩 ④(통일신라·발해실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#8','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C18',1,'mc','auto','누리 수첩 ⑯의 「붉은 종이 합격증」과 관계있는 고려의 제도는 어느 것인가요?',ARRAY['SO5-2-u1-X31']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C18","difficulty":1,"kind":"mc","stem":"누리 수첩 ⑯의 「붉은 종이 합격증」과 관계있는 고려의 제도는 어느 것인가요?","options":[{"t":"과거제","correct":true},{"t":"8조법","mis":"SO5-2-u1-X31"},{"t":"신분제 폐지","mis":"SO5-2-u1-X31"},{"t":"화랑 제도","mis":"SO5-2-u1-X31"}],"explanation":["시험에 붙으면 받았어요.","홍패예요.","과거제예요."],"asset":{"type":"passage","lines":["⑮ 고려실 — 궁예를 몰아낸 왕이 고구려를 잇겠다며 나라 이름을 정했다.","⑯ 붉은 종이 합격증 — 시험을 보아 관리를 뽑았다는 증거라고 한다.","⑰ 남매가 재산을 반씩 나눈 이야기 그림이 걸려 있었다.","⑱ 등불 행렬 그림 — 오늘날 거리의 연등 행렬과 닮았다."],"title":"누리의 박물관 견학 수첩 ⑤(고려 사회실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#9','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C4',2,'mc','auto','신석기 사람들이 강가나 바닷가에 마을을 이룬 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X07']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C4","difficulty":2,"kind":"mc","stem":"신석기 사람들이 강가나 바닷가에 마을을 이룬 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"물고기잡이로 먹을 것을 꾸준히 구할 수 있어서","correct":true},{"t":"적을 피해 숨기 좋아서","mis":"SO5-2-u1-X07"},{"t":"청동이 많이 나서","mis":"SO5-2-u1-X07"},{"t":"동굴이 많아서","mis":"SO5-2-u1-X07"}],"explanation":["물가에는 물고기가 있어요.","먹을 것이 꾸준해요.","머물러 살 수 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#10','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C11',2,'mc','auto','삼국 시대 평민의 생활로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X19']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C11","difficulty":2,"kind":"mc","stem":"삼국 시대 평민의 생활로 알맞은 것은 어느 것인가요?","options":[{"t":"삼베옷을 입고 잡곡을 먹으며 초가집에 살았다","correct":true},{"t":"비단옷을 입고 쌀밥을 먹었다","mis":"SO5-2-u1-X19"},{"t":"기와집에 살며 노비를 거느렸다","mis":"SO5-2-u1-X19"},{"t":"나라의 중요한 일을 정했다","mis":"SO5-2-u1-X19"}],"explanation":["평민은 농사지었어요.","세금도 냈어요.","삼베·잡곡·초가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#11','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C12',2,'mc','auto','누리 수첩 ⑨의 말 탄 무사 모양 토기로 짐작할 수 있는 가야 사람들의 모습은 어느 것인가요?',ARRAY['SO5-2-u1-X22','SO5-2-u1-X08']::text[],false,'{"seq":11,"concept":"SO5-2-u1-C12","difficulty":2,"kind":"mc","stem":"누리 수첩 ⑨의 말 탄 무사 모양 토기로 짐작할 수 있는 가야 사람들의 모습은 어느 것인가요?","options":[{"t":"말을 타고 철로 만든 무기와 갑옷을 갖추어 싸웠다","correct":true},{"t":"말을 기르지 않았다","mis":"SO5-2-u1-X22"},{"t":"철을 쓸 줄 몰랐다","mis":"SO5-2-u1-X22"},{"t":"돌도끼만 들고 싸웠다","mis":"SO5-2-u1-X08"}],"explanation":["말을 탄 무사예요.","가야는 철이 많았어요.","무기와 갑옷을 갖추었어요."],"asset":{"type":"passage","lines":["⑧ 고대실 — 무덤 벽화 사진 속 주인은 크고 시중드는 사람은 작았다.","⑨ 철을 납작하게 편 덩이쇠와 말 탄 무사 모양 토기가 있었다.","⑩ 한강 지도 — 세 나라가 번갈아 차지한 땅에 색이 칠해져 있었다."],"title":"누리의 박물관 견학 수첩 ③(삼국·가야실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#12','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C14',2,'mc','auto','통일신라와 일본 사이의 교류로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X25']::text[],false,'{"seq":12,"concept":"SO5-2-u1-C14","difficulty":2,"kind":"mc","stem":"통일신라와 일본 사이의 교류로 알맞은 것은 어느 것인가요?","options":[{"t":"주로 물건을 사고팔며 오갔다","correct":true},{"t":"전혀 오가지 않았다","mis":"SO5-2-u1-X25"},{"t":"일본이 신라를 다스렸다","mis":"SO5-2-u1-X25"},{"t":"일본으로 유학생만 보냈다","mis":"SO5-2-u1-X25"}],"explanation":["일본과도 오갔어요.","주로 무역이었어요.","물건을 사고팔았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#13','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C19',2,'mc','auto','누리 수첩 ⑱의 등불 행렬 그림과 관계있는 고려의 행사는 어느 것인가요?',ARRAY['SO5-2-u1-X33']::text[],false,'{"seq":13,"concept":"SO5-2-u1-C19","difficulty":2,"kind":"mc","stem":"누리 수첩 ⑱의 등불 행렬 그림과 관계있는 고려의 행사는 어느 것인가요?","options":[{"t":"연등회","correct":true},{"t":"팔관회","mis":"SO5-2-u1-X33"},{"t":"과거 시험","mis":"SO5-2-u1-X33"},{"t":"제천 행사","mis":"SO5-2-u1-X33"}],"explanation":["등불을 밝혀요.","소원을 빌어요.","연등회예요."],"asset":{"type":"passage","lines":["⑮ 고려실 — 궁예를 몰아낸 왕이 고구려를 잇겠다며 나라 이름을 정했다.","⑯ 붉은 종이 합격증 — 시험을 보아 관리를 뽑았다는 증거라고 한다.","⑰ 남매가 재산을 반씩 나눈 이야기 그림이 걸려 있었다.","⑱ 등불 행렬 그림 — 오늘날 거리의 연등 행렬과 닮았다."],"title":"누리의 박물관 견학 수첩 ⑤(고려 사회실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#14','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C20',2,'mc','auto','누리 수첩 ⑳의 항구에 아라비아 상인이 온 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X35']::text[],false,'{"seq":14,"concept":"SO5-2-u1-C20","difficulty":2,"kind":"mc","stem":"누리 수첩 ⑳의 항구에 아라비아 상인이 온 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"고려가 아주 먼 나라와도 교류했다","correct":true},{"t":"고려는 이웃 나라와만 오갔다","mis":"SO5-2-u1-X35"},{"t":"고려는 바다를 쓰지 않았다","mis":"SO5-2-u1-X35"},{"t":"아라비아 상인은 고려를 다스렸다","mis":"SO5-2-u1-X35"}],"explanation":["아라비아는 아주 멀어요.","그 상인이 왔어요.","먼 나라와도 교류했어요."],"asset":{"type":"passage","lines":["⑲ 외교 코너 — 말로 맞서 싸우지 않고 땅을 얻은 신하의 이야기","⑳ 항구 모형 — 예성강에 아라비아 상인의 배까지 떠 있었다.","㉑ 섬 지도 — 몽골군을 피해 수도를 옮긴 곳이라 한다.","㉒ 노비 문서를 태우는 승려 그림 — 모두 함께 성을 지켰다."],"title":"누리의 박물관 견학 수첩 ⑥(고려와 주변 나라실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#15','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C21',2,'mc','auto','누리 수첩 ㉒의 그림으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X36']::text[],false,'{"seq":15,"concept":"SO5-2-u1-C21","difficulty":2,"kind":"mc","stem":"누리 수첩 ㉒의 그림으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"신분에 상관없이 모두 힘을 합쳐 몽골에 맞섰다","correct":true},{"t":"노비는 싸움에서 빠졌다","mis":"SO5-2-u1-X36"},{"t":"승려는 몽골 편에 섰다","mis":"SO5-2-u1-X36"},{"t":"높은 신분만 성을 지켰다","mis":"SO5-2-u1-X36"}],"explanation":["노비 문서를 태웠어요.","모두 함께 싸웠어요.","신분을 넘었어요."],"asset":{"type":"passage","lines":["⑲ 외교 코너 — 말로 맞서 싸우지 않고 땅을 얻은 신하의 이야기","⑳ 항구 모형 — 예성강에 아라비아 상인의 배까지 떠 있었다.","㉑ 섬 지도 — 몽골군을 피해 수도를 옮긴 곳이라 한다.","㉒ 노비 문서를 태우는 승려 그림 — 모두 함께 성을 지켰다."],"title":"누리의 박물관 견학 수첩 ⑥(고려와 주변 나라실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#16','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C23',2,'mc','auto','누리 수첩 ㉔의 나무판은 무엇인가요?',ARRAY['SO5-2-u1-X26']::text[],false,'{"seq":16,"concept":"SO5-2-u1-C23","difficulty":2,"kind":"mc","stem":"누리 수첩 ㉔의 나무판은 무엇인가요?","options":[{"t":"팔만대장경","correct":true},{"t":"신라 촌락 문서","mis":"SO5-2-u1-X26"},{"t":"훈요 10조","mis":"SO5-2-u1-X26"},{"t":"8조법","mis":"SO5-2-u1-X26"}],"explanation":["몽골을 물리치기를 빌었어요.","다시 새겼어요.","팔만대장경이에요."],"asset":{"type":"passage","lines":["㉓ 푸른 주전자 — 무늬를 파내고 흰 흙·붉은 흙으로 메웠다.","㉔ 나무판 사진 — 몽골을 물리치기를 빌며 다시 새겼다고 한다.","㉕ 작은 쇠 글자들 — 다시 짜서 여러 책을 찍었다고 한다.","㉖ 솜이불과 무명옷 — 목화씨 몇 알에서 시작되었다고 한다."],"title":"누리의 박물관 견학 수첩 ⑦(고려 문화실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#17','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C5',3,'mc','auto','누리 수첩 ④·⑤를 함께 볼 때 알 수 있는 청동기 시대의 모습은 어느 것인가요?',ARRAY['SO5-2-u1-X09']::text[],false,'{"seq":17,"concept":"SO5-2-u1-C5","difficulty":3,"kind":"mc","stem":"누리 수첩 ④·⑤를 함께 볼 때 알 수 있는 청동기 시대의 모습은 어느 것인가요?","options":[{"t":"귀한 청동기는 일부 지배자가 갖고, 늘 쓰는 도구와 그릇은 돌과 흙으로 만들었다","correct":true},{"t":"모든 사람이 청동 검과 거울을 가졌다","mis":"SO5-2-u1-X09"},{"t":"돌로 만든 도구는 모두 사라졌다","mis":"SO5-2-u1-X09"},{"t":"청동기는 농사에만 썼다","mis":"SO5-2-u1-X09"}],"explanation":["청동은 한 무덤에서만 나왔어요.","반달 돌칼과 토기는 가득했어요.","청동은 귀했어요."],"asset":{"type":"passage","lines":["④ 청동기실 — 반짝이는 검과 거울은 한 무덤에서만 나왔다고 한다.","⑤ 그 옆에는 반달 모양 돌칼과 무늬 없는 토기가 가득했다.","⑥ 바깥 마당 — 탁자처럼 생긴 거대한 돌무덤을 본떠 세워 두었다.","⑦ 벽 안내문 — 「사람을 다치게 하면 곡식으로 갚는다.」"],"title":"누리의 박물관 견학 수첩 ②(청동기·고조선실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#18','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C13',3,'mc','auto','누리 수첩 ⑪의 문서에 뽕나무까지 적힌 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X24']::text[],false,'{"seq":18,"concept":"SO5-2-u1-C13","difficulty":3,"kind":"mc","stem":"누리 수첩 ⑪의 문서에 뽕나무까지 적힌 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뽕나무는 비단과 이어지는 재산이라 세금을 걷는 데 필요했다","correct":true},{"t":"뽕나무로 배를 만들었기 때문에","mis":"SO5-2-u1-X24"},{"t":"뽕나무 수를 겨루는 놀이가 있었기 때문에","mis":"SO5-2-u1-X24"},{"t":"뽕나무는 쓸모가 없었기 때문에","mis":"SO5-2-u1-X24"}],"explanation":["뽕잎은 누에가 먹어요.","비단을 짤 수 있어요.","세금과 이어져요."],"asset":{"type":"passage","lines":["⑪ 통일신라실 — 사람·말·뽕나무 수를 적은 마을 문서를 보았다.","⑫ 턱수염 짙은 돌사람 사진 — 먼 서쪽 사람의 얼굴이라 한다.","⑬ 북쪽 나라 코너 — 고구려와 꼭 닮은 꽃잎 무늬 기와와 온돌 집터 모형","⑭ 세 빛깔 향로 — 당의 도자기를 닮았다는 설명이 붙어 있었다."],"title":"누리의 박물관 견학 수첩 ④(통일신라·발해실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#19','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C13',3,'mc','auto','신라가 당을 물리치고 삼국 통일을 이룬 것으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X23']::text[],false,'{"seq":19,"concept":"SO5-2-u1-C13","difficulty":3,"kind":"mc","stem":"신라가 당을 물리치고 삼국 통일을 이룬 것으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"신라는 큰 나라의 힘에 기대기만 하지 않고 스스로 한반도를 지키려 했다","correct":true},{"t":"신라는 끝까지 당의 뜻을 따랐다","mis":"SO5-2-u1-X23"},{"t":"당이 통일을 이루어 한반도를 다스렸다","mis":"SO5-2-u1-X23"},{"t":"고구려가 당을 물리쳤다","mis":"SO5-2-u1-X23"}],"explanation":["당이 한반도를 노렸어요.","신라가 맞서 싸웠어요.","스스로 지킨 통일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#20','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C17',3,'mc','auto','왕건이 발해 유민을 친척처럼 받아들인 까닭을 가장 잘 짐작한 것은 어느 것인가요?',ARRAY['SO5-2-u1-X30','SO5-2-u1-X34']::text[],false,'{"seq":20,"concept":"SO5-2-u1-C17","difficulty":3,"kind":"mc","stem":"왕건이 발해 유민을 친척처럼 받아들인 까닭을 가장 잘 짐작한 것은 어느 것인가요?","options":[{"t":"발해와 고려가 모두 고구려를 이은 같은 뿌리라고 여겼기 때문에","correct":true},{"t":"발해 유민이 모두 신라 사람이었기 때문에","mis":"SO5-2-u1-X30"},{"t":"발해 유민을 노비로 삼으려고","mis":"SO5-2-u1-X30"},{"t":"거란과 손잡으려고","mis":"SO5-2-u1-X34"}],"explanation":["발해는 고구려를 이었어요.","고려도 고구려를 이었어요.","같은 뿌리로 여겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#21','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C20',3,'mc','auto','누리 수첩 ⑲와 ⑳을 함께 볼 때 고려에 대해 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X35','SO5-2-u1-X34']::text[],false,'{"seq":21,"concept":"SO5-2-u1-C20","difficulty":3,"kind":"mc","stem":"누리 수첩 ⑲와 ⑳을 함께 볼 때 고려에 대해 알 수 있는 것은 어느 것인가요?","options":[{"t":"외교로 나라를 지키면서 바다를 통해 여러 나라와 활발히 교류했다","correct":true},{"t":"주변 나라와 싸우기만 하고 오가지 않았다","mis":"SO5-2-u1-X35"},{"t":"바다 밖 나라와는 오가지 않았다","mis":"SO5-2-u1-X35"},{"t":"외교도 교류도 하지 않았다","mis":"SO5-2-u1-X34"}],"explanation":["⑲는 외교예요.","⑳은 교류예요.","둘 다 했어요."],"asset":{"type":"passage","lines":["⑲ 외교 코너 — 말로 맞서 싸우지 않고 땅을 얻은 신하의 이야기","⑳ 항구 모형 — 예성강에 아라비아 상인의 배까지 떠 있었다.","㉑ 섬 지도 — 몽골군을 피해 수도를 옮긴 곳이라 한다.","㉒ 노비 문서를 태우는 승려 그림 — 모두 함께 성을 지켰다."],"title":"누리의 박물관 견학 수첩 ⑥(고려와 주변 나라실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#22','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C24',3,'mc','auto','누리 모둠의 기사 「벽란도 상인에게 묻다」는 어떤 기사 갈래인가요?',ARRAY['SO5-2-u1-X41']::text[],false,'{"seq":22,"concept":"SO5-2-u1-C24","difficulty":3,"kind":"mc","stem":"누리 모둠의 기사 「벽란도 상인에게 묻다」는 어떤 기사 갈래인가요?","options":[{"t":"인터뷰","correct":true},{"t":"광고","mis":"SO5-2-u1-X41"},{"t":"만화","mis":"SO5-2-u1-X41"},{"t":"사건","mis":"SO5-2-u1-X41"}],"explanation":["상인에게 물어요.","상인이 답해요.","인터뷰예요."],"asset":{"type":"passage","lines":["누리 모둠의 「고려 신문」 계획","사건 — 「붉은 합격증 받은 날」 · 인터뷰 — 「벽란도 상인에게 묻다」","광고 — 「상감 청자 주전자」 · 만화 — 「문익점과 목화 한 그루」","고칠 점 — 「고인돌 세우기 대회」 기사는 빼기로 했다."],"title":"누리의 박물관 견학 수첩 ⑧(우리 모둠 신문)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#23','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C6',4,'mc','auto','누리 수첩 ①~⑦을 걸으며 누리가 깨달은 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X08','SO5-2-u1-X10','SO5-2-u1-X25']::text[],false,'{"seq":23,"concept":"SO5-2-u1-C6","difficulty":4,"kind":"mc","stem":"누리 수첩 ①~⑦을 걸으며 누리가 깨달은 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"도구와 생활이 바뀔 때마다 사회의 모습도 바뀌어, 곡식이 남자 지배자와 나라가 생기고 나라마다 교류와 문화가 달라졌다","correct":true},{"t":"도구는 바뀌었지만 생활은 그대로였다","mis":"SO5-2-u1-X08"},{"t":"나라는 지배자 없이 저절로 생겼다","mis":"SO5-2-u1-X10"},{"t":"나라들은 서로 오가지 않고 따로 살았다","mis":"SO5-2-u1-X25"}],"explanation":["도구가 바뀌었어요.","사회가 바뀌었어요.","나라와 문화가 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#24','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C6',4,'essay','teacher','누리 수첩 ④~⑥을 보고 청동기 시대에 빈부의 차이와 지배자가 생겼다고 짐작할 수 있는 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u1-C6","difficulty":4,"kind":"essay","stem":"누리 수첩 ④~⑥을 보고 청동기 시대에 빈부의 차이와 지배자가 생겼다고 짐작할 수 있는 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: ④처럼 귀한 청동 검과 거울이 한 무덤에서만 나와 그 무덤 주인이 다른 사람보다 많은 재산과 힘을 가졌다고 짐작할 수 있다. ⑥의 고인돌은 아주 무거운 덮개돌을 옮기려면 많은 사람이 필요한데, 그 사람들을 모을 수 있는 지배자가 있었다는 증거이다.","scoring_points":["청동기가 한 무덤에서만 나온 것을 근거로 들었는가","고인돌과 많은 사람·지배자를 이었는가","빈부의 차이나 지배자를 결론으로 썼는가"]},"explanation":["④는 무덤 속 차이예요.","⑥은 고인돌이에요.","지배자가 있었어요."],"asset":{"type":"passage","lines":["④ 청동기실 — 반짝이는 검과 거울은 한 무덤에서만 나왔다고 한다.","⑤ 그 옆에는 반달 모양 돌칼과 무늬 없는 토기가 가득했다.","⑥ 바깥 마당 — 탁자처럼 생긴 거대한 돌무덤을 본떠 세워 두었다.","⑦ 벽 안내문 — 「사람을 다치게 하면 곡식으로 갚는다.」"],"title":"누리의 박물관 견학 수첩 ②(청동기·고조선실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_b#25','soc',5,2,'u1','','g5_2_soc_u1_review_b','unit_review','SO5-2-u1-C21',4,'essay','teacher','누리 수첩 ⑲~㉒를 보고 고려가 주변 나라와 어떻게 지냈는지 외교·교류·전쟁으로 나누어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u1-C21","difficulty":4,"kind":"essay","stem":"누리 수첩 ⑲~㉒를 보고 고려가 주변 나라와 어떻게 지냈는지 외교·교류·전쟁으로 나누어 쓰세요.","answer_guide":{"answer":"예: 외교 — 서희가 거란 장수와 담판해 싸우지 않고 강동 6주를 얻었다. 교류 — 개경 가까운 벽란도에 송·일본은 물론 아라비아 상인까지 와서 인삼·도자기를 사고팔았다. 전쟁 — 몽골이 쳐들어오자 수도를 강화도로 옮기고 승려와 노비까지 신분을 넘어 함께 싸웠지만 백성의 고통도 컸다.","scoring_points":["외교를 썼는가","교류를 썼는가","전쟁과 대응을 썼는가"]},"explanation":["외교는 서희예요.","교류는 벽란도예요.","전쟁은 몽골과 강화도예요."],"asset":{"type":"passage","lines":["⑲ 외교 코너 — 말로 맞서 싸우지 않고 땅을 얻은 신하의 이야기","⑳ 항구 모형 — 예성강에 아라비아 상인의 배까지 떠 있었다.","㉑ 섬 지도 — 몽골군을 피해 수도를 옮긴 곳이라 한다.","㉒ 노비 문서를 태우는 승려 그림 — 모두 함께 성을 지켰다."],"title":"누리의 박물관 견학 수첩 ⑥(고려와 주변 나라실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#1','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C1',1,'mc','auto','선사 시대 사람들의 생활을 알아낼 때 주로 쓰는 것은 어느 것인가요?',ARRAY['SO5-2-u1-X02']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C1","difficulty":1,"kind":"mc","stem":"선사 시대 사람들의 생활을 알아낼 때 주로 쓰는 것은 어느 것인가요?","options":[{"t":"유적과 유물","correct":true},{"t":"그때 쓴 일기","mis":"SO5-2-u1-X02"},{"t":"그때 만든 신문","mis":"SO5-2-u1-X02"},{"t":"그때 남긴 편지","mis":"SO5-2-u1-X02"}],"explanation":["문자 기록이 없어요.","남긴 흔적을 봐요.","유적과 유물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#2','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C3',1,'sa','auto','신석기 시대 사람들이 돌을 갈고 다듬어 만든 도구를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u1-C3","difficulty":1,"kind":"sa","stem":"신석기 시대 사람들이 돌을 갈고 다듬어 만든 도구를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["간석기"],"explanation":["돌을 갈아요.","매끄러워요.","간석기예요."],"mis":"SO5-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#3','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C5',1,'sa','auto','구리에 주석을 섞어 만든 금속을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u1-C5","difficulty":1,"kind":"sa","stem":"구리에 주석을 섞어 만든 금속을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["청동"],"explanation":["구리가 들어가요.","주석을 섞어요.","청동이에요."],"mis":"SO5-2-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#4','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C7',1,'mc','auto','단군왕검이 세운 고조선은 어떤 문화를 바탕으로 세워졌나요?',ARRAY['SO5-2-u1-X15']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C7","difficulty":1,"kind":"mc","stem":"단군왕검이 세운 고조선은 어떤 문화를 바탕으로 세워졌나요?","options":[{"t":"청동기 문화","correct":true},{"t":"철기 문화","mis":"SO5-2-u1-X15"},{"t":"구석기 문화","mis":"SO5-2-u1-X15"},{"t":"불교문화","mis":"SO5-2-u1-X15"}],"explanation":["비파형 동검이 대표 유물이에요.","청동으로 만들었어요.","청동기 문화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#5','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C12',1,'mc','auto','누리 수첩 ⑨의 덩이쇠를 화폐처럼 쓴 나라는 어느 것인가요?',ARRAY['SO5-2-u1-X22']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C12","difficulty":1,"kind":"mc","stem":"누리 수첩 ⑨의 덩이쇠를 화폐처럼 쓴 나라는 어느 것인가요?","options":[{"t":"가야","correct":true},{"t":"고조선","mis":"SO5-2-u1-X22"},{"t":"발해","mis":"SO5-2-u1-X22"},{"t":"고려","mis":"SO5-2-u1-X22"}],"explanation":["철이 많이 났어요.","덩이쇠를 화폐처럼 썼어요.","가야예요."],"asset":{"type":"passage","lines":["⑧ 고대실 — 무덤 벽화 사진 속 주인은 크고 시중드는 사람은 작았다.","⑨ 철을 납작하게 편 덩이쇠와 말 탄 무사 모양 토기가 있었다.","⑩ 한강 지도 — 세 나라가 번갈아 차지한 땅에 색이 칠해져 있었다."],"title":"누리의 박물관 견학 수첩 ③(삼국·가야실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#6','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C13',1,'mc','auto','신라가 삼국을 통일할 때 처음 손잡았다가 뒤에 물리친 나라는 어느 것인가요?',ARRAY['SO5-2-u1-X23']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C13","difficulty":1,"kind":"mc","stem":"신라가 삼국을 통일할 때 처음 손잡았다가 뒤에 물리친 나라는 어느 것인가요?","options":[{"t":"당","correct":true},{"t":"송","mis":"SO5-2-u1-X23"},{"t":"몽골","mis":"SO5-2-u1-X23"},{"t":"거란","mis":"SO5-2-u1-X23"}],"explanation":["중국의 나라예요.","처음엔 손잡았어요.","나중엔 물리쳤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#7','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C15',1,'sa','auto','당에서 발해를 「바다 동쪽의 번성한 나라」라는 뜻으로 부른 말을 쓰세요. 네 글자예요.','{}'::text[],false,'{"seq":7,"concept":"SO5-2-u1-C15","difficulty":1,"kind":"sa","stem":"당에서 발해를 「바다 동쪽의 번성한 나라」라는 뜻으로 부른 말을 쓰세요. 네 글자예요.","answer":["해동성국"],"explanation":["바다 동쪽이에요.","번성한 나라예요.","해동성국이에요."],"mis":"SO5-2-u1-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#8','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C17',1,'sa','auto','통일신라 말 지방에서 자란 힘센 세력을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO5-2-u1-C17","difficulty":1,"kind":"sa","stem":"통일신라 말 지방에서 자란 힘센 세력을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["호족"],"explanation":["지방의 세력이에요.","새 나라도 세웠어요.","호족이에요."],"mis":"SO5-2-u1-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#9','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C4',2,'ox','auto','신석기 사람들이 한곳에 머물게 된 데에는 먹을 것을 토기에 보관할 수 있게 된 것도 도움이 되었어요.',ARRAY['SO5-2-u1-X07']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C4","difficulty":2,"kind":"ox","stem":"신석기 사람들이 한곳에 머물게 된 데에는 먹을 것을 토기에 보관할 수 있게 된 것도 도움이 되었어요.","answer":"O","reason_options":[{"t":"남은 먹을 것을 보관하면 옮겨 다니지 않아도 되었기 때문에","correct":true},{"t":"토기는 들고 다니며 옮겨 다니기 위한 것이었기 때문에","mis":"SO5-2-u1-X07"}],"mis":"SO5-2-u1-X07","explanation":["토기에 담아 두어요.","먹을 것이 남아요.","옮겨 다니지 않아도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#10','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C11',2,'ox','auto','삼국 시대에는 신분에 따라 입는 옷과 사는 집이 달랐어요.',ARRAY['SO5-2-u1-X19']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C11","difficulty":2,"kind":"ox","stem":"삼국 시대에는 신분에 따라 입는 옷과 사는 집이 달랐어요.","answer":"O","reason_options":[{"t":"귀족은 비단옷·기와집, 평민은 삼베옷·초가집이었기 때문에","correct":true},{"t":"신분과 상관없이 모두 같은 옷을 입었기 때문에","mis":"SO5-2-u1-X19"}],"mis":"SO5-2-u1-X19","explanation":["귀족은 비단·기와예요.","평민은 삼베·초가예요.","신분에 따라 달랐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#11','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C12',2,'ox','auto','가야는 철을 다루는 기술이 뛰어나 무기와 갑옷을 다른 나라에 팔았어요.',ARRAY['SO5-2-u1-X22']::text[],false,'{"seq":11,"concept":"SO5-2-u1-C12","difficulty":2,"kind":"ox","stem":"가야는 철을 다루는 기술이 뛰어나 무기와 갑옷을 다른 나라에 팔았어요.","answer":"O","reason_options":[{"t":"철이 많이 나는 곳에 자리 잡아 철 기술이 발달했기 때문에","correct":true},{"t":"가야에는 철이 전혀 나지 않았기 때문에","mis":"SO5-2-u1-X22"}],"mis":"SO5-2-u1-X22","explanation":["철이 많이 났어요.","기술이 뛰어났어요.","무기와 갑옷을 팔았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#12','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C14',2,'ox','auto','통일신라의 승려 혜초는 인도와 서역을 여행하고 책을 남겼어요.',ARRAY['SO5-2-u1-X26']::text[],false,'{"seq":12,"concept":"SO5-2-u1-C14","difficulty":2,"kind":"ox","stem":"통일신라의 승려 혜초는 인도와 서역을 여행하고 책을 남겼어요.","answer":"O","reason_options":[{"t":"먼 곳까지 다녀와 보고 들은 것을 기록했기 때문에","correct":true},{"t":"혜초는 고려 때 사람이기 때문에","mis":"SO5-2-u1-X26"}],"mis":"SO5-2-u1-X26","explanation":["인도와 서역에 갔어요.","책을 남겼어요.","통일신라 승려예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#13','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C19',2,'ox','auto','고려 여성은 집안에서 남성과 같은 지위를 가졌지만 관리가 되는 것 같은 사회 활동은 자유롭지 않았어요.',ARRAY['SO5-2-u1-X32']::text[],false,'{"seq":13,"concept":"SO5-2-u1-C19","difficulty":2,"kind":"ox","stem":"고려 여성은 집안에서 남성과 같은 지위를 가졌지만 관리가 되는 것 같은 사회 활동은 자유롭지 않았어요.","answer":"O","reason_options":[{"t":"집안의 일과 나라의 일에서 여성의 자리가 달랐기 때문에","correct":true},{"t":"고려 여성은 관리도 자유롭게 되었기 때문에","mis":"SO5-2-u1-X32"}],"mis":"SO5-2-u1-X32","explanation":["집안에서는 같았어요.","사회 활동은 어려웠어요.","둘을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#14','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C20',2,'ox','auto','고려는 거란과 거리를 두고 송과는 좋은 사이를 이어 갔어요.',ARRAY['SO5-2-u1-X34']::text[],false,'{"seq":14,"concept":"SO5-2-u1-C20","difficulty":2,"kind":"ox","stem":"고려는 거란과 거리를 두고 송과는 좋은 사이를 이어 갔어요.","answer":"O","reason_options":[{"t":"발해를 무너뜨린 거란을 멀리하고 송과 가까이 지냈기 때문에","correct":true},{"t":"고려는 송을 무너뜨린 나라이기 때문에","mis":"SO5-2-u1-X34"}],"mis":"SO5-2-u1-X34","explanation":["거란은 발해를 무너뜨렸어요.","그래서 멀리했어요.","송과는 가까웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#15','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C21',2,'ox','auto','몽골과의 전쟁 뒤 두 나라는 서로의 음식과 풍습을 주고받기도 했어요.',ARRAY['SO5-2-u1-X36']::text[],false,'{"seq":15,"concept":"SO5-2-u1-C21","difficulty":2,"kind":"ox","stem":"몽골과의 전쟁 뒤 두 나라는 서로의 음식과 풍습을 주고받기도 했어요.","answer":"O","reason_options":[{"t":"전쟁 뒤 사람과 물건이 오가며 풍습이 전해졌기 때문에","correct":true},{"t":"전쟁 뒤 두 나라는 다시는 만나지 않았기 때문에","mis":"SO5-2-u1-X36"}],"mis":"SO5-2-u1-X36","explanation":["사람이 오갔어요.","설렁탕·족두리 이야기가 있어요.","풍습을 주고받았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#16','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C23',2,'mc','auto','누리 수첩 ㉕의 쇠 글자가 나무판보다 좋은 점은 어느 것인가요?',ARRAY['SO5-2-u1-X38']::text[],false,'{"seq":16,"concept":"SO5-2-u1-C23","difficulty":2,"kind":"mc","stem":"누리 수첩 ㉕의 쇠 글자가 나무판보다 좋은 점은 어느 것인가요?","options":[{"t":"글자를 다시 짜서 여러 책을 찍을 수 있다","correct":true},{"t":"한 가지 책만 찍을 수 있다","mis":"SO5-2-u1-X38"},{"t":"글자를 만들 필요가 없다","mis":"SO5-2-u1-X38"},{"t":"잘 휘고 갈라진다","mis":"SO5-2-u1-X38"}],"explanation":["글자가 하나씩이에요.","다시 짤 수 있어요.","여러 책을 찍어요."],"asset":{"type":"passage","lines":["㉓ 푸른 주전자 — 무늬를 파내고 흰 흙·붉은 흙으로 메웠다.","㉔ 나무판 사진 — 몽골을 물리치기를 빌며 다시 새겼다고 한다.","㉕ 작은 쇠 글자들 — 다시 짜서 여러 책을 찍었다고 한다.","㉖ 솜이불과 무명옷 — 목화씨 몇 알에서 시작되었다고 한다."],"title":"누리의 박물관 견학 수첩 ⑦(고려 문화실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#17','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C6',3,'ox','auto','누리 수첩 ④에서 청동 검과 거울이 한 무덤에서만 나온 것은 그 무덤 주인이 힘 있는 지배자였다는 증거가 될 수 있어요.',ARRAY['SO5-2-u1-X09']::text[],false,'{"seq":17,"concept":"SO5-2-u1-C6","difficulty":3,"kind":"ox","stem":"누리 수첩 ④에서 청동 검과 거울이 한 무덤에서만 나온 것은 그 무덤 주인이 힘 있는 지배자였다는 증거가 될 수 있어요.","answer":"O","reason_options":[{"t":"귀한 청동기를 가질 수 있는 사람은 재산과 힘을 가진 지배자였기 때문에","correct":true},{"t":"청동기는 누구나 흔히 갖던 물건이기 때문에","mis":"SO5-2-u1-X09"}],"mis":"SO5-2-u1-X09","explanation":["청동은 귀했어요.","한 무덤에만 있어요.","지배자의 무덤이에요."],"asset":{"type":"passage","lines":["④ 청동기실 — 반짝이는 검과 거울은 한 무덤에서만 나왔다고 한다.","⑤ 그 옆에는 반달 모양 돌칼과 무늬 없는 토기가 가득했다.","⑥ 바깥 마당 — 탁자처럼 생긴 거대한 돌무덤을 본떠 세워 두었다.","⑦ 벽 안내문 — 「사람을 다치게 하면 곡식으로 갚는다.」"],"title":"누리의 박물관 견학 수첩 ②(청동기·고조선실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#18','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C14',3,'ox','auto','누리 수첩 ⑫와 ⑭를 함께 보면 통일신라와 발해가 모두 바깥 세계와 오갔다는 것을 짐작할 수 있어요.',ARRAY['SO5-2-u1-X25']::text[],false,'{"seq":18,"concept":"SO5-2-u1-C14","difficulty":3,"kind":"ox","stem":"누리 수첩 ⑫와 ⑭를 함께 보면 통일신라와 발해가 모두 바깥 세계와 오갔다는 것을 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"서역 사람의 얼굴과 당의 도자기를 닮은 향로가 모두 교류의 흔적이기 때문에","correct":true},{"t":"두 유물 모두 그 나라 안에서만 쓰인 것이기 때문에","mis":"SO5-2-u1-X25"}],"mis":"SO5-2-u1-X25","explanation":["⑫는 서역이에요.","⑭는 당이에요.","모두 교류의 흔적이에요."],"asset":{"type":"passage","lines":["⑪ 통일신라실 — 사람·말·뽕나무 수를 적은 마을 문서를 보았다.","⑫ 턱수염 짙은 돌사람 사진 — 먼 서쪽 사람의 얼굴이라 한다.","⑬ 북쪽 나라 코너 — 고구려와 꼭 닮은 꽃잎 무늬 기와와 온돌 집터 모형","⑭ 세 빛깔 향로 — 당의 도자기를 닮았다는 설명이 붙어 있었다."],"title":"누리의 박물관 견학 수첩 ④(통일신라·발해실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#19','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C10',3,'ox','auto','한강 유역을 차지한 나라가 그때 가장 크게 발전한 것은 우연이 아니에요.',ARRAY['SO5-2-u1-X17']::text[],false,'{"seq":19,"concept":"SO5-2-u1-C10","difficulty":3,"kind":"ox","stem":"한강 유역을 차지한 나라가 그때 가장 크게 발전한 것은 우연이 아니에요.","answer":"O","reason_options":[{"t":"한강 유역은 농사와 교류에 좋아 나라를 키우는 바탕이 되었기 때문에","correct":true},{"t":"한강 유역은 쓸모없는 땅이었기 때문에","mis":"SO5-2-u1-X17"}],"mis":"SO5-2-u1-X17","explanation":["농사짓기 좋아요.","교류하기 좋아요.","나라를 키웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#20','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C17',3,'ox','auto','고려가 거란을 멀리한 것은 발해를 무너뜨린 거란에 대한 생각과 이어져요.',ARRAY['SO5-2-u1-X34']::text[],false,'{"seq":20,"concept":"SO5-2-u1-C17","difficulty":3,"kind":"ox","stem":"고려가 거란을 멀리한 것은 발해를 무너뜨린 거란에 대한 생각과 이어져요.","answer":"O","reason_options":[{"t":"같은 뿌리로 여긴 발해를 무너뜨린 나라라 경계했기 때문에","correct":true},{"t":"거란이 고려에 늘 좋은 선물만 주었기 때문에","mis":"SO5-2-u1-X34"}],"mis":"SO5-2-u1-X34","explanation":["거란이 발해를 무너뜨렸어요.","고려는 발해를 친척처럼 여겼어요.","그래서 멀리했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#21','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C21',3,'ox','auto','김윤후가 노비 문서를 불태운 것은 신분이 낮은 사람들도 나라를 지키는 데 함께하게 하려는 것이었어요.',ARRAY['SO5-2-u1-X36']::text[],false,'{"seq":21,"concept":"SO5-2-u1-C21","difficulty":3,"kind":"ox","stem":"김윤후가 노비 문서를 불태운 것은 신분이 낮은 사람들도 나라를 지키는 데 함께하게 하려는 것이었어요.","answer":"O","reason_options":[{"t":"신분에 상관없이 벼슬을 약속하자 모두 힘을 합쳤기 때문에","correct":true},{"t":"노비 문서가 너무 많아 버리려고 했기 때문에","mis":"SO5-2-u1-X36"}],"mis":"SO5-2-u1-X36","explanation":["벼슬을 약속했어요.","모두 힘을 합쳤어요.","함께 지키려 했어요."],"asset":{"type":"passage","lines":["⑲ 외교 코너 — 말로 맞서 싸우지 않고 땅을 얻은 신하의 이야기","⑳ 항구 모형 — 예성강에 아라비아 상인의 배까지 떠 있었다.","㉑ 섬 지도 — 몽골군을 피해 수도를 옮긴 곳이라 한다.","㉒ 노비 문서를 태우는 승려 그림 — 모두 함께 성을 지켰다."],"title":"누리의 박물관 견학 수첩 ⑥(고려와 주변 나라실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#22','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C22',3,'ox','auto','누리 모둠이 「상감 청자 주전자」를 광고 기사로 넣은 것은 고려 사람들이 쓰던 물건을 보여 주기에 알맞아요.',ARRAY['SO5-2-u1-X37']::text[],false,'{"seq":22,"concept":"SO5-2-u1-C22","difficulty":3,"kind":"ox","stem":"누리 모둠이 「상감 청자 주전자」를 광고 기사로 넣은 것은 고려 사람들이 쓰던 물건을 보여 주기에 알맞아요.","answer":"O","reason_options":[{"t":"상감 청자는 고려의 생활용품이고 광고는 그때 쓰던 물건을 보여 주기 때문에","correct":true},{"t":"상감 청자는 신석기 시대 그릇이기 때문에","mis":"SO5-2-u1-X37"}],"mis":"SO5-2-u1-X37","explanation":["청자는 고려 물건이에요.","광고는 물건을 보여 줘요.","알맞은 기사예요."],"asset":{"type":"passage","lines":["누리 모둠의 「고려 신문」 계획","사건 — 「붉은 합격증 받은 날」 · 인터뷰 — 「벽란도 상인에게 묻다」","광고 — 「상감 청자 주전자」 · 만화 — 「문익점과 목화 한 그루」","고칠 점 — 「고인돌 세우기 대회」 기사는 빼기로 했다."],"title":"누리의 박물관 견학 수첩 ⑧(우리 모둠 신문)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#23','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C17',4,'mc','auto','고조선·발해·고려를 이어 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO5-2-u1-X30','SO5-2-u1-X27']::text[],false,'{"seq":23,"concept":"SO5-2-u1-C17","difficulty":4,"kind":"mc","stem":"고조선·발해·고려를 이어 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"우리 역사의 나라들은 앞선 나라를 이어받았다고 여기며 스스로의 뿌리를 지키려 했다","correct":true},{"t":"나라들은 앞선 나라와 아무 관계가 없었다","mis":"SO5-2-u1-X30"},{"t":"모든 나라는 신라를 이었다고 여겼다","mis":"SO5-2-u1-X27"},{"t":"나라 이름에는 아무 뜻도 담지 않았다","mis":"SO5-2-u1-X30"}],"explanation":["발해는 고구려를 이었어요.","고려도 고구려를 이었어요.","뿌리를 지키려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#24','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C11',4,'essay','teacher','누리 수첩 ⑧·⑨를 보고 삼국과 가야 사람들의 생활 모습을 신분과 철 문화로 나누어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u1-C11","difficulty":4,"kind":"essay","stem":"누리 수첩 ⑧·⑨를 보고 삼국과 가야 사람들의 생활 모습을 신분과 철 문화로 나누어 쓰세요.","answer_guide":{"answer":"예: ⑧의 벽화에서 주인은 크게, 시중드는 사람은 작게 그려 신분에 따라 사람을 다르게 여겼다는 것을 알 수 있고, 귀족은 비단옷과 쌀밥, 평민은 삼베옷과 잡곡을 먹었다. ⑨의 덩이쇠와 말 탄 무사 토기로 가야는 철 기술이 뛰어나 덩이쇠를 화폐처럼 쓰고 철 무기와 갑옷을 갖추었다고 짐작한다.","scoring_points":["벽화로 신분 차이를 썼는가","신분에 따른 의식주를 썼는가","덩이쇠·토기로 가야의 철 문화를 썼는가"]},"explanation":["벽화는 신분이에요.","의식주가 달랐어요.","가야는 철의 나라예요."],"asset":{"type":"passage","lines":["⑧ 고대실 — 무덤 벽화 사진 속 주인은 크고 시중드는 사람은 작았다.","⑨ 철을 납작하게 편 덩이쇠와 말 탄 무사 모양 토기가 있었다.","⑩ 한강 지도 — 세 나라가 번갈아 차지한 땅에 색이 칠해져 있었다."],"title":"누리의 박물관 견학 수첩 ③(삼국·가야실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_c#25','soc',5,2,'u1','','g5_2_soc_u1_review_c','unit_review','SO5-2-u1-C23',4,'essay','teacher','누리 수첩 ㉓~㉖ 가운데 두 가지를 골라 그것이 무엇인지 쓰고, 그것으로 알 수 있는 고려 사람들의 생각이나 생활을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u1-C23","difficulty":4,"kind":"essay","stem":"누리 수첩 ㉓~㉖ 가운데 두 가지를 골라 그것이 무엇인지 쓰고, 그것으로 알 수 있는 고려 사람들의 생각이나 생활을 쓰세요.","answer_guide":{"answer":"예: ㉓은 상감 기법으로 만든 고려청자 주전자로, 고려 사람들이 받아들인 기술을 고려만의 것으로 발전시켰고 귀한 청자를 지배층이 썼다는 것을 알 수 있다. ㉖은 문익점이 가져온 목화씨에서 시작된 무명옷과 솜이불로, 백성이 겨울을 따뜻하게 나게 되어 생활이 바뀌었다는 것을 알 수 있다.","scoring_points":["두 가지를 골라 무엇인지 썼는가","각각 고려 사람들의 생각이나 생활과 이었는가","바르게 설명했는가"]},"explanation":["두 가지를 골라요.","무엇인지 써요.","생각이나 생활과 이어요."],"asset":{"type":"passage","lines":["㉓ 푸른 주전자 — 무늬를 파내고 흰 흙·붉은 흙으로 메웠다.","㉔ 나무판 사진 — 몽골을 물리치기를 빌며 다시 새겼다고 한다.","㉕ 작은 쇠 글자들 — 다시 짜서 여러 책을 찍었다고 한다.","㉖ 솜이불과 무명옷 — 목화씨 몇 알에서 시작되었다고 한다."],"title":"누리의 박물관 견학 수첩 ⑦(고려 문화실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#1','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C1',1,'ox','auto','선사 시대는 문자를 쓰기 전이라 글로 남은 기록이 없는 시대예요.',ARRAY['SO5-2-u1-X02']::text[],false,'{"seq":1,"concept":"SO5-2-u1-C1","difficulty":1,"kind":"ox","stem":"선사 시대는 문자를 쓰기 전이라 글로 남은 기록이 없는 시대예요.","answer":"O","reason_options":[{"t":"선사 시대의 기준은 문자 기록이 있는지이기 때문에","correct":true},{"t":"선사 시대에도 왕이 쓴 역사책이 많기 때문에","mis":"SO5-2-u1-X02"}],"mis":"SO5-2-u1-X02","explanation":["기준은 문자예요.","기록이 없어요.","선사 시대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#2','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C2',1,'mc','auto','구석기 사람들이 불을 피워 한 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-2-u1-X05']::text[],false,'{"seq":2,"concept":"SO5-2-u1-C2","difficulty":1,"kind":"mc","stem":"구석기 사람들이 불을 피워 한 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"곡식을 토기에 담아 끓였다","correct":true},{"t":"추위를 막았다","mis":"SO5-2-u1-X05"},{"t":"사나운 짐승을 쫓았다","mis":"SO5-2-u1-X05"},{"t":"고기를 익혀 먹었다","mis":"SO5-2-u1-X05"}],"explanation":["불은 따뜻하고 안전하게 했어요.","고기를 익혔어요.","토기와 곡식은 신석기 이후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#3','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C6',1,'ox','auto','청동기 시대에는 곡식이 남으면서 빈부의 차이가 생겼어요.',ARRAY['SO5-2-u1-X10']::text[],false,'{"seq":3,"concept":"SO5-2-u1-C6","difficulty":1,"kind":"ox","stem":"청동기 시대에는 곡식이 남으면서 빈부의 차이가 생겼어요.","answer":"O","reason_options":[{"t":"남은 곡식을 더 가진 사람과 덜 가진 사람이 생겼기 때문에","correct":true},{"t":"청동기 시대에는 곡식이 늘 모자랐기 때문에","mis":"SO5-2-u1-X10"}],"mis":"SO5-2-u1-X10","explanation":["곡식이 남았어요.","가진 것이 달라졌어요.","빈부의 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#4','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C8',1,'ox','auto','고조선의 문화 범위는 비파형 동검과 탁자식 고인돌이 발견된 곳으로 짐작해요.',ARRAY['SO5-2-u1-X14']::text[],false,'{"seq":4,"concept":"SO5-2-u1-C8","difficulty":1,"kind":"ox","stem":"고조선의 문화 범위는 비파형 동검과 탁자식 고인돌이 발견된 곳으로 짐작해요.","answer":"O","reason_options":[{"t":"고조선의 국경 기록이 없어 대표 유물·유적이 나온 곳을 살피기 때문에","correct":true},{"t":"고조선 사람들이 남긴 국경 지도가 있기 때문에","mis":"SO5-2-u1-X14"}],"mis":"SO5-2-u1-X14","explanation":["국경 기록이 없어요.","대표 유물을 찾아요.","나온 곳으로 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#5','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C9',1,'ox','auto','가야는 여러 나라가 모인 연맹이었어요.',ARRAY['SO5-2-u1-X18']::text[],false,'{"seq":5,"concept":"SO5-2-u1-C9","difficulty":1,"kind":"ox","stem":"가야는 여러 나라가 모인 연맹이었어요.","answer":"O","reason_options":[{"t":"낙동강 가의 여러 나라가 모여 이루었기 때문에","correct":true},{"t":"가야는 고구려의 한 지방이었기 때문에","mis":"SO5-2-u1-X18"}],"mis":"SO5-2-u1-X18","explanation":["낙동강 가에 있었어요.","여러 나라가 모였어요.","가야 연맹이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#6','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C14',1,'ox','auto','누리 수첩 ⑫의 돌사람은 통일신라가 서역과 교류했다는 것을 보여 줘요.',ARRAY['SO5-2-u1-X25']::text[],false,'{"seq":6,"concept":"SO5-2-u1-C14","difficulty":1,"kind":"ox","stem":"누리 수첩 ⑫의 돌사람은 통일신라가 서역과 교류했다는 것을 보여 줘요.","answer":"O","reason_options":[{"t":"먼 서쪽 사람의 얼굴을 새긴 것은 그들이 신라를 오갔다는 뜻이기 때문에","correct":true},{"t":"돌사람은 고구려 사람의 얼굴이기 때문에","mis":"SO5-2-u1-X25"}],"mis":"SO5-2-u1-X25","explanation":["턱수염이 짙어요.","서역 사람 얼굴이에요.","서역과 교류했어요."],"asset":{"type":"passage","lines":["⑪ 통일신라실 — 사람·말·뽕나무 수를 적은 마을 문서를 보았다.","⑫ 턱수염 짙은 돌사람 사진 — 먼 서쪽 사람의 얼굴이라 한다.","⑬ 북쪽 나라 코너 — 고구려와 꼭 닮은 꽃잎 무늬 기와와 온돌 집터 모형","⑭ 세 빛깔 향로 — 당의 도자기를 닮았다는 설명이 붙어 있었다."],"title":"누리의 박물관 견학 수첩 ④(통일신라·발해실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#7','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C15',1,'ox','auto','발해는 고구려의 옛 땅을 대부분 되찾았어요.',ARRAY['SO5-2-u1-X27']::text[],false,'{"seq":7,"concept":"SO5-2-u1-C15","difficulty":1,"kind":"ox","stem":"발해는 고구려의 옛 땅을 대부분 되찾았어요.","answer":"O","reason_options":[{"t":"고구려가 무너진 뒤 그 북쪽 땅에 세워져 넓게 되찾았기 때문에","correct":true},{"t":"발해는 한반도 남쪽 끝에 있었기 때문에","mis":"SO5-2-u1-X27"}],"mis":"SO5-2-u1-X27","explanation":["고구려가 무너졌어요.","그 땅에 발해가 섰어요.","옛 땅을 대부분 되찾았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#8','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C17',1,'ox','auto','고려는 후삼국을 통일한 나라예요.',ARRAY['SO5-2-u1-X29']::text[],false,'{"seq":8,"concept":"SO5-2-u1-C17","difficulty":1,"kind":"ox","stem":"고려는 후삼국을 통일한 나라예요.","answer":"O","reason_options":[{"t":"신라의 항복을 받고 후백제를 물리쳤기 때문에","correct":true},{"t":"고려는 후삼국 가운데 하나로 끝까지 나뉘어 있었기 때문에","mis":"SO5-2-u1-X29"}],"mis":"SO5-2-u1-X29","explanation":["신라가 항복했어요.","후백제를 물리쳤어요.","고려가 통일했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#9','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C4',2,'error','auto','선사 시대 사람들이 사는 곳을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X07','SO5-2-u1-X04']::text[],false,'{"seq":9,"concept":"SO5-2-u1-C4","difficulty":2,"kind":"error","stem":"선사 시대 사람들이 사는 곳을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"루아 — 「구석기 사람들은 강가에 움집 마을을 이루었어.」","correct":true,"mis_target":"SO5-2-u1-X07"},{"t":"정후 — 「구석기 사람들은 막집·동굴에서 지냈어.」","mis":"SO5-2-u1-X04"},{"t":"해나 — 「신석기 사람들은 움집을 지었어.」","mis":"SO5-2-u1-X07"}],"explanation":["구석기는 옮겨 다녔어요.","움집 마을은 신석기예요.","루아의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#10','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C11',2,'error','auto','삼국 시대 신분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X19']::text[],false,'{"seq":10,"concept":"SO5-2-u1-C11","difficulty":2,"kind":"error","stem":"삼국 시대 신분을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"마루 — 「천민이 토지를 가장 많이 가지고 나라 일을 정했어.」","correct":true,"mis_target":"SO5-2-u1-X19"},{"t":"아린 — 「귀족은 토지와 노비가 많았어.」","mis":"SO5-2-u1-X19"},{"t":"주노 — 「평민은 농사짓고 세금을 냈어.」","mis":"SO5-2-u1-X19"}],"explanation":["토지가 많은 건 귀족이에요.","천민은 대부분 노비예요.","마루의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#11','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C12',2,'error','auto','삼국의 불교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X21']::text[],false,'{"seq":11,"concept":"SO5-2-u1-C12","difficulty":2,"kind":"error","stem":"삼국의 불교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태경 — 「불교를 받아들이자 왕의 힘이 약해지고 나라가 흩어졌어.」","correct":true,"mis_target":"SO5-2-u1-X21"},{"t":"수안 — 「불교를 받아들여 절과 탑을 지었어.」","mis":"SO5-2-u1-X21"},{"t":"유진 — 「신라에서는 귀족의 반대가 있었어.」","mis":"SO5-2-u1-X21"}],"explanation":["불교로 마음이 모였어요.","왕의 힘이 세졌어요.","태경의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#12','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C16',2,'error','auto','발해의 교류를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X25']::text[],false,'{"seq":12,"concept":"SO5-2-u1-C16","difficulty":2,"kind":"error","stem":"발해의 교류를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하온 — 「발해는 이웃 나라에 물건을 팔지 않고 사기만 했어.」","correct":true,"mis_target":"SO5-2-u1-X25"},{"t":"이찬 — 「발해는 당·일본과 교류했어.」","mis":"SO5-2-u1-X25"},{"t":"보라 — 「말과 짐승 가죽, 인삼을 이웃 나라에 팔았어.」","mis":"SO5-2-u1-X25"}],"explanation":["발해도 물건을 팔았어요.","말·가죽·인삼이에요.","하온의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#13','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C19',2,'error','auto','고려의 불교 행사를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X33']::text[],false,'{"seq":13,"concept":"SO5-2-u1-C19","difficulty":2,"kind":"error","stem":"고려의 불교 행사를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지환 — 「팔관회는 해마다 초에 등불을 밝힌 행사야.」","correct":true,"mis_target":"SO5-2-u1-X33"},{"t":"나연 — 「연등회는 오늘날 연등 행렬로 이어져.」","mis":"SO5-2-u1-X33"},{"t":"은결 — 「팔관회는 11월에 온 세상의 평안을 빌었어.」","mis":"SO5-2-u1-X33"}],"explanation":["등불은 연등회예요.","팔관회는 11월이에요.","지환이 바꾸어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#14','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C20',2,'error','auto','고려와 거란을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X34']::text[],false,'{"seq":14,"concept":"SO5-2-u1-C20","difficulty":2,"kind":"error","stem":"고려와 거란을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수인 — 「강감찬은 말로 맞서 강동 6주를 얻었어.」","correct":true,"mis_target":"SO5-2-u1-X34"},{"t":"태하 — 「강감찬은 귀주에서 거란군을 크게 물리쳤어.」","mis":"SO5-2-u1-X34"},{"t":"민서 — 「거란은 세 번 쳐들어왔어.」","mis":"SO5-2-u1-X34"}],"explanation":["강동 6주는 서희예요.","강감찬은 귀주 대첩이에요.","수인이 바꾸어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#15','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C21',2,'error','auto','몽골과의 전쟁을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X36']::text[],false,'{"seq":15,"concept":"SO5-2-u1-C21","difficulty":2,"kind":"error","stem":"몽골과의 전쟁을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하빈 — 「고려가 강화도로 옮긴 건 섬에 금이 많아서야.」","correct":true,"mis_target":"SO5-2-u1-X36"},{"t":"서진 — 「몽골군은 말을 타서 바다를 건너기 어려웠어.」","mis":"SO5-2-u1-X36"},{"t":"아준 — 「전쟁이 길어져 백성이 큰 고통을 겪었어.」","mis":"SO5-2-u1-X36"}],"explanation":["금 때문이 아니에요.","바다가 몽골군을 막았어요.","하빈의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#16','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C23',2,'error','auto','목화와 무명옷을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X39']::text[],false,'{"seq":16,"concept":"SO5-2-u1-C23","difficulty":2,"kind":"error","stem":"목화와 무명옷을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라임 — 「목화는 고려가 세워질 때부터 온 나라에 있었어.」","correct":true,"mis_target":"SO5-2-u1-X39"},{"t":"도해 — 「문익점이 목화씨를 가져와 길렀어.」","mis":"SO5-2-u1-X39"},{"t":"소은 — 「무명옷 덕분에 백성의 겨울이 따뜻해졌어.」","mis":"SO5-2-u1-X39"}],"explanation":["목화씨는 문익점이 가져왔어요.","처음부터 있던 게 아니에요.","라임의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉓ 푸른 주전자 — 무늬를 파내고 흰 흙·붉은 흙으로 메웠다.","㉔ 나무판 사진 — 몽골을 물리치기를 빌며 다시 새겼다고 한다.","㉕ 작은 쇠 글자들 — 다시 짜서 여러 책을 찍었다고 한다.","㉖ 솜이불과 무명옷 — 목화씨 몇 알에서 시작되었다고 한다."],"title":"누리의 박물관 견학 수첩 ⑦(고려 문화실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#17','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C3',3,'error','auto','누리 수첩 ①~③을 보고 친구들이 짐작했어요. 알맞지 않게 짐작한 친구는 누구인가요?',ARRAY['SO5-2-u1-X08','SO5-2-u1-X05','SO5-2-u1-X07']::text[],false,'{"seq":17,"concept":"SO5-2-u1-C3","difficulty":3,"kind":"error","stem":"누리 수첩 ①~③을 보고 친구들이 짐작했어요. 알맞지 않게 짐작한 친구는 누구인가요?","options":[{"t":"하늘 — 「②의 무늬 그릇은 구석기 사람들이 옮겨 다니며 들고 다닌 거야.」","correct":true,"mis_target":"SO5-2-u1-X08"},{"t":"우진 — 「①을 보면 불을 피워 동굴에서 지냈나 봐.」","mis":"SO5-2-u1-X05"},{"t":"다솔 — 「③을 보면 신석기 사람들이 마을을 이루었어.」","mis":"SO5-2-u1-X07"}],"explanation":["무늬 그릇은 신석기 토기예요.","보관하려고 만들었어요.","하늘의 짐작이 알맞지 않아요."],"asset":{"type":"passage","lines":["① 첫 전시실 — 깨뜨려 만든 돌도끼 옆에 동굴 속 불 피운 자리 사진이 있었다.","② 다음 진열장 — 바닥이 뾰족한 무늬 그릇과 가운데 구멍 난 둥근 돌이 있었다.","③ 강가 마을 모형 — 땅을 파고 지은 집이 여러 채 모여 있었다."],"title":"누리의 박물관 견학 수첩 ①(선사실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#18','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C8',3,'error','auto','유물로 옛 생활을 짐작하는 방법을 두고 친구들이 말했어요. 가장 알맞지 않은 친구는 누구인가요?',ARRAY['SO5-2-u1-X42','SO5-2-u1-X14']::text[],false,'{"seq":18,"concept":"SO5-2-u1-C8","difficulty":3,"kind":"error","stem":"유물로 옛 생활을 짐작하는 방법을 두고 친구들이 말했어요. 가장 알맞지 않은 친구는 누구인가요?","options":[{"t":"세온 — 「유물은 이름이랑 만든 연도만 외우면 충분해.」","correct":true,"mis_target":"SO5-2-u1-X42"},{"t":"하경 — 「유물이 나온 곳을 이어 보면 문화가 퍼진 범위를 짐작할 수 있어.」","mis":"SO5-2-u1-X14"},{"t":"준성 — 「유물의 쓰임을 생각하면 생활을 짐작할 수 있어.」","mis":"SO5-2-u1-X42"}],"explanation":["이름과 연도만으론 부족해요.","쓰임과 나온 곳을 살펴요.","세온의 말이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#19','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C13',3,'error','auto','삼국 통일 뒤 신라를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X23','SO5-2-u1-X24']::text[],false,'{"seq":19,"concept":"SO5-2-u1-C13","difficulty":3,"kind":"error","stem":"삼국 통일 뒤 신라를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이든 — 「신라는 통일 뒤 고구려의 북쪽 땅까지 모두 다스렸어.」","correct":true,"mis_target":"SO5-2-u1-X23"},{"t":"채아 — 「통일 뒤 넓어진 땅을 다스리려고 제도를 정비했어.」","mis":"SO5-2-u1-X24"},{"t":"무진 — 「신라 촌락 문서로 마을을 살피고 세금을 걷었어.」","mis":"SO5-2-u1-X24"}],"explanation":["북쪽 땅은 되찾지 못했어요.","그곳엔 발해가 섰어요.","이든의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#20','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C15',3,'error','auto','고구려를 이은 나라들을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u1-X28','SO5-2-u1-X30']::text[],false,'{"seq":20,"concept":"SO5-2-u1-C15","difficulty":3,"kind":"error","stem":"고구려를 이은 나라들을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예온 — 「발해 기와가 고구려와 닮은 건 우연이라서 아무 뜻이 없어.」","correct":true,"mis_target":"SO5-2-u1-X28"},{"t":"서하 — 「일본도 발해 사신을 고려 사신이라 적었어.」","mis":"SO5-2-u1-X28"},{"t":"지오 — 「서경을 중히 여기라는 가르침도 고구려 계승과 이어져.」","mis":"SO5-2-u1-X30"}],"explanation":["닮은 문화는 증거예요.","계승을 보여 줘요.","예온의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#21','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C19',3,'error','auto','고려 사회를 두고 친구들이 짐작했어요. 알맞지 않게 짐작한 친구는 누구인가요?',ARRAY['SO5-2-u1-X32','SO5-2-u1-X33','SO5-2-u1-X31']::text[],false,'{"seq":21,"concept":"SO5-2-u1-C19","difficulty":3,"kind":"error","stem":"고려 사회를 두고 친구들이 짐작했어요. 알맞지 않게 짐작한 친구는 누구인가요?","options":[{"t":"태라 — 「⑰을 보면 고려에서는 딸이 재산을 하나도 받지 못했어.」","correct":true,"mis_target":"SO5-2-u1-X32"},{"t":"윤아 — 「⑱을 보면 고려 사람들은 등불을 밝혀 소원을 빌었어.」","mis":"SO5-2-u1-X33"},{"t":"라현 — 「⑯을 보면 시험으로 관리를 뽑았어.」","mis":"SO5-2-u1-X31"}],"explanation":["남매가 반씩 나눴어요.","딸도 재산을 받았어요.","태라의 짐작이 알맞지 않아요."],"asset":{"type":"passage","lines":["⑮ 고려실 — 궁예를 몰아낸 왕이 고구려를 잇겠다며 나라 이름을 정했다.","⑯ 붉은 종이 합격증 — 시험을 보아 관리를 뽑았다는 증거라고 한다.","⑰ 남매가 재산을 반씩 나눈 이야기 그림이 걸려 있었다.","⑱ 등불 행렬 그림 — 오늘날 거리의 연등 행렬과 닮았다."],"title":"누리의 박물관 견학 수첩 ⑤(고려 사회실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#22','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C24',3,'error','auto','누리 모둠이 기사를 더하자고 했어요. 알맞지 않은 의견은 누구의 것인가요?',ARRAY['SO5-2-u1-X40','SO5-2-u1-X41']::text[],false,'{"seq":22,"concept":"SO5-2-u1-C24","difficulty":3,"kind":"error","stem":"누리 모둠이 기사를 더하자고 했어요. 알맞지 않은 의견은 누구의 것인가요?","options":[{"t":"한별 — 「고려 신문에 「발해, 해동성국이라 불리다」를 머리기사로 넣자.」","correct":true,"mis_target":"SO5-2-u1-X40"},{"t":"누리 — 「서희의 담판을 사건 기사로 더하자.」","mis":"SO5-2-u1-X41"},{"t":"찬우 — 「팔만대장경을 새긴 사람 인터뷰를 넣자.」","mis":"SO5-2-u1-X41"}],"explanation":["해동성국은 발해 이야기예요.","고려 신문의 머리기사로 맞지 않아요.","한별의 의견이 알맞지 않아요."],"asset":{"type":"passage","lines":["누리 모둠의 「고려 신문」 계획","사건 — 「붉은 합격증 받은 날」 · 인터뷰 — 「벽란도 상인에게 묻다」","광고 — 「상감 청자 주전자」 · 만화 — 「문익점과 목화 한 그루」","고칠 점 — 「고인돌 세우기 대회」 기사는 빼기로 했다."],"title":"누리의 박물관 견학 수첩 ⑧(우리 모둠 신문)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#23','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C23',4,'mc','auto','고려의 문화유산(청자·대장경·활자·목화)을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO5-2-u1-X37','SO5-2-u1-X39','SO5-2-u1-X42']::text[],false,'{"seq":23,"concept":"SO5-2-u1-C23","difficulty":4,"kind":"mc","stem":"고려의 문화유산(청자·대장경·활자·목화)을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"고려 사람들은 받아들인 기술을 자기 것으로 발전시키고, 어려움 속에서도 마음을 모으며 생활을 바꾸어 갔다","correct":true},{"t":"고려 문화는 모두 다른 나라 것을 그대로 가져왔다","mis":"SO5-2-u1-X37"},{"t":"고려 문화는 지배층하고만 관계있다","mis":"SO5-2-u1-X39"},{"t":"문화유산의 이름만 외우면 된다","mis":"SO5-2-u1-X42"}],"explanation":["상감 기법은 고려만의 것이에요.","대장경은 마음을 모았어요.","목화는 백성의 생활을 바꿨어요."],"asset":{"type":"passage","lines":["㉓ 푸른 주전자 — 무늬를 파내고 흰 흙·붉은 흙으로 메웠다.","㉔ 나무판 사진 — 몽골을 물리치기를 빌며 다시 새겼다고 한다.","㉕ 작은 쇠 글자들 — 다시 짜서 여러 책을 찍었다고 한다.","㉖ 솜이불과 무명옷 — 목화씨 몇 알에서 시작되었다고 한다."],"title":"누리의 박물관 견학 수첩 ⑦(고려 문화실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#24','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C15',4,'essay','teacher','누리 수첩 ⑪~⑭를 보고 통일신라와 발해가 각각 어떤 나라였는지 제도·교류·계승 가운데 두 가지를 들어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u1-C15","difficulty":4,"kind":"essay","stem":"누리 수첩 ⑪~⑭를 보고 통일신라와 발해가 각각 어떤 나라였는지 제도·교류·계승 가운데 두 가지를 들어 쓰세요.","answer_guide":{"answer":"예: 통일신라는 ⑪의 촌락 문서처럼 넓어진 땅을 다스리려고 마을을 꼼꼼히 살펴 세금을 걷었고, ⑫의 돌사람처럼 먼 서역과도 교류했다. 발해는 ⑬의 꽃잎 무늬 기와와 온돌처럼 고구려를 이은 나라였고, ⑭의 향로처럼 당과 교류했다.","scoring_points":["통일신라를 두 가지로 썼는가","발해를 두 가지로 썼는가","수첩의 자료를 근거로 들었는가"]},"explanation":["통일신라는 제도와 교류예요.","발해는 계승과 교류예요.","수첩을 근거로 들어요."],"asset":{"type":"passage","lines":["⑪ 통일신라실 — 사람·말·뽕나무 수를 적은 마을 문서를 보았다.","⑫ 턱수염 짙은 돌사람 사진 — 먼 서쪽 사람의 얼굴이라 한다.","⑬ 북쪽 나라 코너 — 고구려와 꼭 닮은 꽃잎 무늬 기와와 온돌 집터 모형","⑭ 세 빛깔 향로 — 당의 도자기를 닮았다는 설명이 붙어 있었다."],"title":"누리의 박물관 견학 수첩 ④(통일신라·발해실)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u1_review_d#25','soc',5,2,'u1','','g5_2_soc_u1_review_d','unit_review','SO5-2-u1-C24',4,'essay','teacher','누리 모둠의 「고려 신문」 계획(⑧)에 기사 하나를 더한다고 생각하고, 기사 갈래와 제목, 한두 줄 내용을 쓴 뒤 그 내용이 사실에 맞는지 어떤 자료로 확인할지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u1-C24","difficulty":4,"kind":"essay","stem":"누리 모둠의 「고려 신문」 계획(⑧)에 기사 하나를 더한다고 생각하고, 기사 갈래와 제목, 한두 줄 내용을 쓴 뒤 그 내용이 사실에 맞는지 어떤 자료로 확인할지 쓰세요.","answer_guide":{"answer":"예: 갈래 — 사건. 제목 — 「강감찬, 귀주에서 거란군을 크게 물리치다」. 내용 — 세 번째로 쳐들어온 거란군을 강감찬이 귀주에서 크게 이겨 나라를 지켰다. 교과서의 역사 기록과 박물관 누리집 자료로 고려 때 일이 맞는지 확인하겠다.","scoring_points":["기사 갈래와 제목을 썼는가","고려에 맞는 사실을 내용으로 썼는가","확인할 자료를 썼는가"]},"explanation":["갈래와 제목을 정해요.","고려에 맞는 사실을 써요.","자료로 확인해요."],"asset":{"type":"passage","lines":["누리 모둠의 「고려 신문」 계획","사건 — 「붉은 합격증 받은 날」 · 인터뷰 — 「벽란도 상인에게 묻다」","광고 — 「상감 청자 주전자」 · 만화 — 「문익점과 목화 한 그루」","고칠 점 — 「고인돌 세우기 대회」 기사는 빼기로 했다."],"title":"누리의 박물관 견학 수첩 ⑧(우리 모둠 신문)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
